def _runtime_provider_id(kind: str, identity: str) -> str:
    return f"{str(kind or 'provider').strip()}:{str(identity or 'unknown').strip()}"


def _provider_witness_ref(witness: Optional[dict[str, Any]]) -> str:
    if not isinstance(witness, dict):
        return ""
    provider_id = str(witness.get("provider_id") or "").strip()
    generation = witness.get("generation")
    if not provider_id or not isinstance(generation, int) or generation < 0:
        return ""
    return f"{provider_id}@{generation}"


def _observe_runtime_provider(
    *,
    provider_id: str,
    interface_key: str,
    health: str = "unknown",
    metadata: Optional[dict[str, Any]] = None,
    capacity: int = 1,
) -> Optional[dict[str, Any]]:
    """Publish a process-local provider witness without owning its transport."""

    normalized_id = str(provider_id or "").strip()
    if not normalized_id:
        return None
    with _RUNTIME_PROVIDER_LOCK:
        current = _RUNTIME_PROVIDER_CATALOG.get(normalized_id)
        if current is not None and current.status.value == "draining":
            # A draining generation remains the witness for turns that still
            # reference it. Re-observation must not overwrite its inflight
            # count or silently create a replacement under the same identity.
            record = current
        elif current is None or current.status.value == "removed":
            record = _RUNTIME_PROVIDER_CATALOG.register(
                provider_id=normalized_id,
                interface_key=str(interface_key or "provider").strip(),
                version=str((metadata or {}).get("version") or "unknown"),
                health=str(health or "unknown"),
                capacity=max(1, int(capacity)),
                metadata=dict(metadata or {}),
            )
        else:
            record = _RUNTIME_PROVIDER_CATALOG.update_health(
                normalized_id,
                str(health or current.health),
            )
        return {
            "provider_id": record.provider_id,
            "interface_key": record.interface_key,
            "version": record.version,
            "generation": record.generation,
            "health": record.health,
            "status": record.status.value,
        }


def _runtime_event_kwargs(event: dict[str, Any]) -> dict[str, Any]:
    runtime = event.get("runtime")
    if not isinstance(runtime, dict):
        return {}
    return {
        "component_id": runtime.get("component_id") or "",
        "parent_component_id": runtime.get("parent_component_id") or "",
        "provider_refs": runtime.get("provider_refs") or (),
        "dependency_state": runtime.get("dependency_state") or {},
        "lifecycle_state": runtime.get("lifecycle_state") or "",
        "effect_scope_id": runtime.get("effect_scope_id") or "",
        "plan_node_id": runtime.get("plan_node_id") or "",
        "artifact_refs": runtime.get("artifact_refs") or (),
        "contract_revision": runtime.get("contract_revision") or "",
        "policy_snapshot_hash": runtime.get("policy_snapshot_hash") or "",
    }


def _refresh_mcp_provider_catalog(capability_hints: Optional[list[str]] = None) -> None:
    """Mirror selected MCP readiness into the live provider catalog."""

    try:
        backend = _backend_api()
        snapshots = backend.get_mcp_availability()
        hints = {str(item).strip().lower() for item in capability_hints or [] if str(item).strip()}
        for snapshot in snapshots:
            name = str(getattr(snapshot, "name", "") or "").strip()
            if not name:
                continue
            state = str(getattr(snapshot, "state", "") or "").strip().lower()
            live = bool(getattr(snapshot, "live", False))
            health = "healthy" if live or state in {"ready", "connected"} else state or "unknown"
            if hints and name.lower() not in hints and not any(name.lower() in hint for hint in hints):
                continue
            _observe_runtime_provider(
                provider_id=_runtime_provider_id("mcp", name),
                interface_key=f"mcp:{name}",
                health=health,
                metadata={
                    "mcp_name": name,
                    "registered_tools": list(getattr(snapshot, "registered_tools", ()) or ())[:100],
                },
            )
    except Exception:
        logger.debug("MCP provider catalog refresh unavailable", exc_info=True)


def _backend_api():
    from hermes_cli import collaboration_plugin_backend

    return collaboration_plugin_backend


def _account_generation_for_owner(owner_id: str) -> str:
    normalized = str(owner_id or "").strip()
    if normalized == LOCAL_OWNER_ID:
        return "local-owner-generation"
    if not normalized:
        raise RuntimeError("authenticated owner generation is required")
    try:
        return _backend_api().MobileDeviceStore().account_generation(
            normalized,
            create=True,
        )
    except PermissionError as exc:
        raise HTTPException(
            status_code=410,
            detail="Account deletion is in progress",
        ) from exc


def _account_generation_for_request(request: Request, owner_id: str) -> str:
    """Validate the authenticated generation against the current account."""

    live_generation = _account_generation_for_owner(owner_id)
    authenticated_generation = account_generation_from_request(request)
    principal = getattr(getattr(request, "state", None), "token_principal", None)
    if (
        getattr(principal, "provider", "") == "owner-mobile"
        and authenticated_generation != live_generation
    ):
        raise HTTPException(status_code=410, detail="Account generation is no longer active")
    if authenticated_generation not in {"legacy", live_generation}:
        raise HTTPException(status_code=410, detail="Account generation is no longer active")
    return live_generation


def _require_owner(request: Request) -> str:
    """Return the authenticated owner id or raise 401.

    The dashboard's global middleware normally handles this, but plugin
    endpoints that trigger LLM work or expose profile metadata must not rely
    on a single middleware layer.  This helper is fail-closed: it only accepts
    a verified dashboard session/principal, or the legacy loopback session
    token when the server is bound to a loopback address and auth is disabled.
    """
    state = getattr(request, "state", None)
    if getattr(state, "session", None) is not None:
        return owner_id_from_request(request)
    principal = getattr(state, "token_principal", None)
    if principal is not None:
        return owner_id_from_request(request)
    if getattr(getattr(request, "app", None), "state", None) is not None:
        auth_required = bool(
            getattr(request.app.state, "auth_required", False)
        )
    else:
        auth_required = False
    if auth_required:
        raise HTTPException(status_code=401, detail="Unauthorized")
    # Loopback / legacy mode: the legacy auth middleware has already checked
    # the ephemeral _SESSION_TOKEN before reaching an /api route.  Belt-and-
    # braces: verify it here as well when the web_server module is available.
    try:
        from hermes_cli.web_server import _has_valid_session_token

        if _has_valid_session_token(request):
            return owner_id_from_request(request)
    except Exception:
        # In standalone plugin tests there is no web_server module; only the
        # explicit session/principal paths above are trusted.
        pass
    raise HTTPException(status_code=401, detail="Unauthorized")


def _rate_limit_key(request: Request, fallback: str) -> str:
    """Best-effort per-owner/per-connector key, falling back to client IP."""
    state = getattr(request, "state", None)
    if getattr(state, "session", None) is not None:
        return f"owner:{owner_id_from_request(request)}"
    principal = getattr(state, "token_principal", None)
    if principal is not None:
        return f"principal:{str(getattr(principal, 'principal', '') or '')}"
    client = request.client
    if client is not None and getattr(client, "host", ""):
        return f"ip:{client.host}"
    return fallback


async def _enforce_route_body_size(request: Request) -> None:
    """Reject oversized /route JSON before FastAPI buffers it into memory."""
    content_length = request.headers.get("content-length")
    if content_length:
        try:
            length = int(content_length)
        except (TypeError, ValueError):
            raise HTTPException(status_code=411, detail="Length Required") from None
        if length > _ROUTE_BODY_MAX_BYTES:
            raise HTTPException(
                status_code=413,
                detail=f"Request body exceeds {_ROUTE_BODY_MAX_BYTES} bytes",
            )
    body = await request.body()
    if len(body) > _ROUTE_BODY_MAX_BYTES:
        raise HTTPException(
            status_code=413,
            detail=f"Request body exceeds {_ROUTE_BODY_MAX_BYTES} bytes",
        )


def _account_generation_for_conversation(conversation: dict[str, Any]) -> str:
    """Return the boundary captured when the conversation was created."""

    generation = str(conversation.get("account_generation") or "").strip()
    return generation or "legacy"


def _hosted_event_account_generation(conversation: dict[str, Any]) -> str:
    """Return a hosted conversation's captured generation without a DB hit.

    Live hosted projections are emitted once per model delta. Looking up the
    account generation through ``MobileDeviceStore`` in that hot path opens a
    SQLite connection for every reasoning token; under the mobile API this
    serialized the event callback and could leave a completed gateway turn
    appearing to spin for tens of seconds. New conversations always carry
    their generation, while the fallback preserves compatibility for legacy
    in-memory/local records that predate the field.
    """

    captured = str(conversation.get("account_generation") or "").strip()
    if captured:
        return captured
    return _account_generation_for_owner(
        str(conversation.get("owner_id") or LOCAL_OWNER_ID)
    )


async def _run_mobile_write_approval_recovery_loop(stop: asyncio.Event) -> None:
    while not stop.is_set():
        try:
            await asyncio.wait_for(
                stop.wait(),
                timeout=max(
                    0.01, float(_WRITE_APPROVAL_RECOVERY_INTERVAL_SECONDS)
                ),
            )
            return
        except asyncio.TimeoutError:
            pass
        try:
            await asyncio.to_thread(_recover_all_mobile_write_approvals)
        except Exception:
            logging.getLogger(__name__).exception(
                "Failed to recover mobile write approvals"
            )


def _purge_expired_tool_output_artifacts() -> dict[str, int]:
    return EncryptedToolArtifactStore(Path(get_hermes_home())).purge_expired()


async def _run_tool_artifact_cleanup_loop(stop: asyncio.Event) -> None:
    while not stop.is_set():
        try:
            await asyncio.wait_for(
                stop.wait(), timeout=_TOOL_ARTIFACT_CLEANUP_INTERVAL_SECONDS
            )
            return
        except asyncio.TimeoutError:
            pass
        try:
            await asyncio.to_thread(_purge_expired_tool_output_artifacts)
        except Exception:
            logging.getLogger(__name__).exception(
                "Failed to purge expired encrypted tool output artifacts"
            )


@asynccontextmanager
async def collaboration_dashboard_lifespan(_app):
    """Resume persisted work as soon as the dashboard process starts."""
    try:
        state = load_single_state()
        conversations = state.get("conversations") or []
        changed = False
        for conversation in conversations:
            changed = reconcile_stale_hosted_turns(conversation) or changed
            changed = reconcile_orphaned_local_role_owners(conversation) or changed
        if changed:
            save_single_state(state)
        resume_unfinished_hosted_workflows(conversations)
    except Exception:
        logging.getLogger(__name__).exception(
            "Failed to resume collaboration hosted workflows during startup"
        )
    try:
        await asyncio.to_thread(_recover_all_mobile_write_approvals)
    except Exception:
        logging.getLogger(__name__).exception(
            "Failed to recover mobile write approvals during startup"
        )
    try:
        await asyncio.to_thread(_purge_expired_tool_output_artifacts)
    except Exception:
        logging.getLogger(__name__).exception(
            "Failed to purge expired encrypted tool output artifacts during startup"
        )
    recovery_stop = asyncio.Event()
    recovery_task = asyncio.create_task(
        _run_mobile_write_approval_recovery_loop(recovery_stop)
    )
    artifact_cleanup_task = asyncio.create_task(
        _run_tool_artifact_cleanup_loop(recovery_stop)
    )
    try:
        yield
    finally:
        recovery_stop.set()
        await asyncio.gather(
            recovery_task, artifact_cleanup_task, return_exceptions=True
        )


async def _enforce_active_account_generation(request: Request) -> None:
    """Router-wide stale-generation fence (P1-15).

    Owner-mobile bearer tokens carry the generation they were minted for.
    Routes that resolve records by owner alone previously let a token from a
    previous account era act on the re-registered account's live records.
    Enforcing principal-generation == live-generation here, for every route
    on this router, closes that uniformly; cookie sessions ("legacy") and
    connector-token requests (no mobile principal) are unaffected, exactly
    matching the per-route `_account_generation_for_request` semantics.
    """

    principal = getattr(getattr(request, "state", None), "token_principal", None)
    if getattr(principal, "provider", "") != "owner-mobile":
        return
    owner_id = owner_id_from_request(request)
    if not owner_id:
        return
    live_generation = _account_generation_for_owner(owner_id)
    if account_generation_from_request(request) != live_generation:
        raise HTTPException(status_code=410, detail="Account generation is no longer active")


router = APIRouter(
    lifespan=collaboration_dashboard_lifespan,
    dependencies=[Depends(_enforce_active_account_generation)],
)


class _AccountStateLock:
    """Always acquire the account fence before collaboration state."""

    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._local = threading.local()

    def __enter__(self):
        guard = _backend_api().account_lifecycle_commit_guard()
        guard.__enter__()
        try:
            self._lock.acquire()
        except BaseException:
            guard.__exit__(*sys.exc_info())
            raise
        stack = getattr(self._local, "guards", None)
        if stack is None:
            stack = []
            self._local.guards = stack
        stack.append(guard)
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        guard = self._local.guards.pop()
        self._lock.release()
        return guard.__exit__(exc_type, exc_value, traceback)


_STATE_LOCK = _AccountStateLock()
_HOSTED_THREADS_LOCK = threading.Lock()
_HOSTED_THREADS: dict[str, threading.Thread] = {}
_HOSTED_ROUTING_THREADS_LOCK = threading.Lock()
_HOSTED_ROUTING_THREADS: dict[str, threading.Thread] = {}
_HOSTED_EXECUTION_GENERATION = threading.local()
_COLLABORATION_DELETION_WRITE = threading.local()
_STATE_THREAD_LOCAL = threading.local()
# The hosted event stream and turn workers are separate threads, so the
# thread-local fast path above cannot prevent them from reparsing the same
# multi-megabyte document.  Keep one normalized single-store result keyed by
# the atomic file's mtime/size fingerprint.  Writers invalidate it before an
# atomic replace; an external writer is still detected by the fingerprint.
_SINGLE_STATE_CACHE_LOCK = threading.RLock()
_SINGLE_STATE_CACHE: dict[
    tuple[str, bool], tuple[tuple[int, int], dict[str, Any]]
] = {}
_ACCOUNT_DELETION_TOMBSTONES_KEY = "account_deletion_tombstones"
_HOSTED_CONVERSATION_LOCKS_LOCK = threading.Lock()


class _ConversationExecutionLock:
    """A lock plus the number of callers holding or waiting for it."""

    __slots__ = ("lock", "users")

    def __init__(self) -> None:
        self.lock = threading.Lock()
        self.users = 0


_HOSTED_CONVERSATION_LOCKS: dict[str, _ConversationExecutionLock] = {}
_MOBILE_NOTIFICATION_DISPATCH_CONDITION = threading.Condition()
_MOBILE_NOTIFICATION_DISPATCH_THREAD: Optional[threading.Thread] = None
# kind ∈ {"completion", "awaiting"}: which persisted notification field to
# deliver and how to build the push payload.
_MOBILE_NOTIFICATION_PENDING: dict[str, tuple[str, str, int, str]] = {}
# Conversation SSE presence: active hosted-events watchers per conversation.
# While the user watches the turn live, loud pushes are suppressed; the
# moment the stream drops (app backgrounded or killed) the dispatcher is
# kicked and the pending notification fires within seconds.
_CONVERSATION_SSE_PRESENCE: dict[str, int] = {}
_CONVERSATION_SSE_PRESENCE_LOCK = threading.Lock()
# Suppressed-online notifications re-check at this cadence while a watcher
# stays connected.
_NOTIFICATION_ONLINE_RECHECK_MS = 5_000
_HOSTED_UPDATE_CONDITION = threading.Condition()
_HOSTED_UPDATE_REVISION = 0
_HOSTED_UPDATE_REVISIONS: dict[str, int] = {}
# A hosted turn can produce a user-visible lifecycle event while the durable
# single-conversation document is still being atomically rewritten.  Keep the
# latest conversation projection outside the account-state lock so the SSE
# reader can publish that event without waiting for a multi-megabyte JSON
# write.  Snapshots are immutable after publication and are replaced on the
# next state save.
_HOSTED_LIVE_STATE_LOCK = threading.RLock()
_HOSTED_LIVE_CONVERSATIONS: dict[str, dict[str, Any]] = {}
_HOSTED_CANCEL_STATE_LOCK = threading.Lock()
_SUBAGENT_CONTROL_LOCK = threading.Lock()
_HOSTED_CANCEL_SIGNALS: set[tuple[str, str]] = set()
_HOSTED_CANCEL_CACHE: dict[tuple[str, str], tuple[float, bool]] = {}
_HOSTED_CANCEL_CACHE_SECONDS = 0.75
# A plain chat turn has no tool boundary at which an intervention can be
# applied. Polling the full account-state JSON on every streamed reasoning
# delta nevertheless made the model callback wait on disk I/O. Keep the
# intervention path responsive while bounding that hot-path poll to 4 Hz.
_HOSTED_INTERVENTION_POLL_SECONDS = 0.25
_HOSTED_TERMINAL_STATUSES = {"completed", "failed", "cancelled"}
_MOBILE_NOTIFICATION_TERMINAL_STATUSES = {
    "delivered",
    "no_recipients",
    "permanent_failure",
}
_HOSTED_TRANSIENT_RETRIES = 1
_HOSTED_CHAT_API_ATTEMPTS = 5
_HOSTED_CHAT_API_RETRY_DELAY_SECONDS = 15
_HOSTED_CHAT_MODEL_BUDGET_SECONDS = 120
def _hosted_chat_timeout_seconds() -> int:
    """Per-turn hosted chat timeout, configurable via env; 0 = unlimited."""
    raw = os.environ.get("HERMES_HOSTED_CHAT_TIMEOUT_SECONDS", "").strip()
    if raw:
        try:
            value = int(raw)
            if value >= 0:
                return value
        except (TypeError, ValueError):
            pass
    return 10 * 60


def _hosted_chat_lease_ms() -> int:
    """Lease length for the chat execution owner; unbounded when unlimited."""
    if _HOSTED_CHAT_TIMEOUT_SECONDS == 0:
        return 10 * 365 * 24 * 3600 * 1000
    return (_HOSTED_CHAT_TIMEOUT_SECONDS + 60) * 1000


_HOSTED_CHAT_TIMEOUT_SECONDS = _hosted_chat_timeout_seconds()
# Remote connector roles (supervisor checks, manager handoff, worker/reviewer)
# must not wait forever for a claimed-but-stalled remote run. This is a
# liveness threshold: if the remote run's persisted state stops advancing for
# this many seconds, the server seals it as failed so iOS receives a terminal
# event. It is not a total runtime cap.
_HOSTED_REMOTE_ROLE_STALL_SECONDS = 300
_HOSTED_STDERR_TAIL_CHARS = 64 * 1024
_HOSTED_REWORK_LIMIT = 2
# Hosted SSE readers consume the live in-memory snapshot immediately.  The
# durable document is a recovery/checkpoint store, so lifecycle chatter should
# not rewrite the multi-megabyte account JSON for every protocol event.
_HOSTED_EVENT_FLUSH_SECONDS = 1.5
_STATE_STORE_PREVIOUS_UNSET = object()


def _publish_live_conversations(state: dict[str, Any]) -> set[str]:
    """Publish immutable hosted conversation snapshots before durable I/O."""

    snapshots: dict[str, dict[str, Any]] = {}
    for item in state.get("conversations") or []:
        if not isinstance(item, dict):
            continue
        conversation_id = str(item.get("id") or "").strip()
        if not conversation_id:
            continue
        snapshots[conversation_id] = deepcopy(item)
    with _HOSTED_LIVE_STATE_LOCK:
        _HOSTED_LIVE_CONVERSATIONS.clear()
        _HOSTED_LIVE_CONVERSATIONS.update(snapshots)
    return set(snapshots)


def _live_conversation_snapshot(
    conversation_id: str,
    owner_id: str,
) -> Optional[dict[str, Any]]:
    """Return a published snapshot that is safe for this account to read."""

    normalized_id = str(conversation_id or "").strip()
    normalized_owner = str(owner_id or "").strip()
    with _HOSTED_LIVE_STATE_LOCK:
        snapshot = _HOSTED_LIVE_CONVERSATIONS.get(normalized_id)
        if snapshot is None:
            return None
        snapshot_owner = str(snapshot.get("owner_id") or "").strip()
        # A live projection is not the legacy-owner claim path.  Ownerless
        # snapshots must go through the durable compatibility gate below; an
        # arbitrary caller who knows a conversation id must not read them.
        if not snapshot_owner or snapshot_owner != normalized_owner:
            return None
        if snapshot.get("delete_requested"):
            return None
        return snapshot


def _publish_live_hosted_role_projection(
    conversation_id: str,
    turn_id: str,
    *,
    patch: Optional[dict[str, Any]] = None,
    message: Optional[dict[str, Any]] = None,
    protocol_events: Optional[list[dict[str, Any]]] = None,
) -> None:
    """Publish a small hosted-chat projection without touching durable state.

    The durable collaboration document is intentionally written at accepted,
    checkpoint, and terminal boundaries.  A chat first-token event must not
    wait for that multi-megabyte atomic write before the SSE reader can render
    the lifecycle.  This copy is replaced by the next durable save and is not
    used for recovery.
    """

    normalized_conversation_id = str(conversation_id or "").strip()
    normalized_turn_id = str(turn_id or "").strip()
    if not normalized_conversation_id or not normalized_turn_id:
        return
    with _HOSTED_LIVE_STATE_LOCK:
        current = _HOSTED_LIVE_CONVERSATIONS.get(normalized_conversation_id)
        if not isinstance(current, dict):
            return
        # Token cadence must not deepcopy the whole account conversation. Keep
        # published snapshots immutable by copying only the branches touched
        # by this projection; history, attachments and unrelated turns remain
        # shared read-only values.
        conversation = dict(current)
        current_turns = current.get("hosted_turns")
        if not isinstance(current_turns, dict):
            return
        current_run = current_turns.get(normalized_turn_id)
        if not isinstance(current_run, dict):
            return
        turns = dict(current_turns)
        run = deepcopy(current_run)
        turns[normalized_turn_id] = run
        conversation["hosted_turns"] = turns
        for key, value in (patch or {}).items():
            if key == "role_events" and isinstance(value, dict):
                role_events = run.setdefault("role_events", {})
                if not isinstance(role_events, dict):
                    role_events = {}
                    run["role_events"] = role_events
                role_events.update(deepcopy(value))
            elif key == "participants" and isinstance(value, list):
                existing = run.setdefault("participants", [])
                if not isinstance(existing, list):
                    existing = []
                    run["participants"] = existing
                known = {
                    str(item.get("member_id") or item.get("id") or "")
                    for item in existing
                    if isinstance(item, dict)
                }
                for item in value:
                    if not isinstance(item, dict):
                        continue
                    member_key = str(item.get("member_id") or item.get("id") or "")
                    if member_key and member_key in known:
                        continue
                    existing.append(deepcopy(item))
                    if member_key:
                        known.add(member_key)
            else:
                run[key] = deepcopy(value)
        now = int(time.time() * 1000)
        run["updated_at"] = now
        conversation["updated_at"] = now

        if isinstance(message, dict):
            incoming = deepcopy(message)
            incoming_meta = dict(incoming.get("meta") or {})
            incoming_meta.setdefault("runtime_turn_id", normalized_turn_id)
            incoming["meta"] = incoming_meta
            message_key = str(incoming_meta.get("message_key") or "")
            current_messages = current.get("messages")
            messages = list(current_messages) if isinstance(current_messages, list) else []
            conversation["messages"] = messages
            existing_index: Optional[int] = None
            for index, item in enumerate(messages):
                if not isinstance(item, dict):
                    continue
                item_meta = item.get("meta")
                if not isinstance(item_meta, dict):
                    continue
                if str(item_meta.get("runtime_turn_id") or "") != normalized_turn_id:
                    continue
                if message_key and str(item_meta.get("message_key") or "") != message_key:
                    continue
                existing_index = index
                break
            if existing_index is None:
                incoming.setdefault("id", f"live_{uuid.uuid4().hex[:14]}")
                incoming.setdefault("created_at", now)
                incoming["updated_at"] = now
                _project_native_message(incoming)
                messages.append(incoming)
            else:
                existing = messages[existing_index]
                incoming["id"] = existing.get("id")
                incoming.setdefault("created_at", existing.get("created_at") or now)
                incoming["updated_at"] = now
                _project_native_message(incoming)
                messages[existing_index] = incoming
        if protocol_events:
            conversation["hosted_events"] = list(current.get("hosted_events") or [])
            conversation["hosted_event_sequences"] = dict(
                current.get("hosted_event_sequences") or {}
            )
            conversation["hosted_event_terminals"] = dict(
                current.get("hosted_event_terminals") or {}
            )
            for key in (
                "session_entries",
                "session_entry_sequences",
                "session_entry_terminals",
                "_hosted_event_persistence_pending",
            ):
                value = current.get(key)
                if isinstance(value, list):
                    conversation[key] = list(value)
                elif isinstance(value, dict):
                    conversation[key] = dict(value)
        account_generation = _hosted_event_account_generation(conversation)
        for protocol_event in protocol_events or []:
            if not isinstance(protocol_event, dict):
                continue
            append_hosted_event(
                conversation,
                conversation_id=normalized_conversation_id,
                turn_id=normalized_turn_id,
                role_stage=str(protocol_event.get("role_stage") or "chat"),
                event_type=str(
                    protocol_event.get("event_type") or "message.delta"
                ),
                payload=(
                    protocol_event.get("payload")
                    if isinstance(protocol_event.get("payload"), dict)
                    else {}
                ),
                entity_id=str(protocol_event.get("entity_id") or ""),
                idempotency_key=str(
                    protocol_event.get("idempotency_key") or ""
                ),
                occurred_at=int(protocol_event.get("occurred_at") or now),
                account_generation=account_generation,
                **_runtime_event_kwargs(protocol_event),
                # The live projection is cloned together with its current
                # sequence and terminal indexes. Rebuilding those indexes and
                # rescanning every retained idempotency key on each token makes
                # long conversations progressively slower.
                assume_current_indexes=True,
            )
        _HOSTED_LIVE_CONVERSATIONS[normalized_conversation_id] = conversation
    _notify_hosted_update(normalized_conversation_id)


def _single_state_cache_key(
    target: Path,
    dispatch_persistence_hooks: bool,
) -> tuple[str, bool] | None:
    if target.name != "single.json":
        return None
    return (os.path.abspath(os.fspath(target)), bool(dispatch_persistence_hooks))


def _single_state_fingerprint(target: Path) -> tuple[int, int] | None:
    try:
        stat = target.stat()
    except OSError:
        return None
    return (int(stat.st_mtime_ns), int(stat.st_size))


def _invalidate_single_state_cache(target: Path) -> None:
    """Invalidate primary/backup cache entries when a state file is written."""

    primary = Path(os.path.abspath(os.fspath(target)))
    if primary.name.endswith(".bak"):
        primary = primary.with_name(primary.name[:-4])
    backup = primary.with_name(f"{primary.name}.bak")
    paths = {str(primary), str(backup)}
    with _SINGLE_STATE_CACHE_LOCK:
        for key in tuple(_SINGLE_STATE_CACHE):
            if key[0] in paths:
                _SINGLE_STATE_CACHE.pop(key, None)
