_ACCOUNT_FILE_MIGRATION_VERSION = "conversation-files-v1"

# Application-layer abuse protection.  nginx remains a first line of defence;
# these bounds protect the Python process when a deployment is reached
# directly, behind a misconfigured proxy, or on a loopback bind.
_ROUTE_BODY_MAX_BYTES = 256 * 1024
_ROUTE_RATE_LIMIT = 30
_ROUTE_RATE_WINDOW_SECONDS = 60
_CONNECTOR_RATE_LIMIT = 120
_CONNECTOR_RATE_WINDOW_SECONDS = 60
_SSE_MAX_CONNECTIONS_PER_CONNECTOR = 4
_SSE_MAX_IDLE_SECONDS = 6 * 60 * 60


class _SlidingWindowRateLimiter:
    """Small in-process sliding-window limiter.

    This is a defence-in-depth layer for a single Python process.  Multi-worker
    deployments should also enforce the same limits in nginx/API gateway; the
    in-process bucket prevents a direct-to-server client from exhausting model
    budget or connector worker threads even when the proxy is absent.
    """

    # A caller can create an arbitrary number of owner/IP/connector keys.  A
    # plain dict with no bound would therefore turn this defence into a small
    # memory-exhaustion surface on a long-running public deployment.  Keep a
    # generous cap and evict expired/oldest buckets only when it is reached;
    # normal traffic never pays an O(n) cleanup cost.
    _MAX_KEYS = 8_192

    def __init__(self, max_events: int, window_seconds: float) -> None:
        self.max_events = max(1, int(max_events))
        self.window_seconds = max(0.1, float(window_seconds))
        self._hits: dict[str, deque[float]] = defaultdict(deque)
        self._lock = threading.Lock()

    def _bound_keys_locked(self, now: float) -> None:
        if len(self._hits) < self._MAX_KEYS:
            return
        cutoff = now - self.window_seconds
        expired = [
            key
            for key, bucket in self._hits.items()
            if not bucket or bucket[-1] <= cutoff
        ]
        for key in expired:
            self._hits.pop(key, None)
        if len(self._hits) < self._MAX_KEYS:
            return
        # All remaining buckets have a live hit. Evict the least-recently-hit
        # key so a burst of unique addresses cannot grow the process forever.
        oldest_key = min(
            self._hits,
            key=lambda key: self._hits[key][-1] if self._hits[key] else float("-inf"),
        )
        self._hits.pop(oldest_key, None)

    def allow(self, key: str, *, cost: int = 1) -> bool:
        if cost < 1:
            cost = 1
        now = time.monotonic()
        with self._lock:
            normalized_key = str(key or "")
            if normalized_key not in self._hits:
                self._bound_keys_locked(now)
            bucket = self._hits[normalized_key]
            while bucket and bucket[0] <= now - self.window_seconds:
                bucket.popleft()
            if len(bucket) + cost > self.max_events:
                return False
            for _ in range(cost):
                bucket.append(now)
            return True

    def reset(self, key: str) -> None:
        with self._lock:
            self._hits.pop(str(key or ""), None)


_ROUTE_RATE_LIMITER = _SlidingWindowRateLimiter(
    _ROUTE_RATE_LIMIT,
    _ROUTE_RATE_WINDOW_SECONDS,
)
_CONNECTOR_RATE_LIMITER = _SlidingWindowRateLimiter(
    _CONNECTOR_RATE_LIMIT,
    _CONNECTOR_RATE_WINDOW_SECONDS,
)


def append_hosted_event(
    conversation: dict[str, Any],
    **kwargs: Any,
):
    """Append a canonical event and its durable session-history projection."""

    # Legacy profile projections carry the optional runtime envelope as one
    # nested field. The protocol authority accepts the typed fields at its
    # boundary, so normalize the envelope here and preserve old producers.
    runtime = kwargs.pop("runtime", None)
    if isinstance(runtime, dict):
        for key, value in _runtime_event_kwargs({"runtime": runtime}).items():
            kwargs.setdefault(key, value)
    result = _append_hosted_event_protocol(conversation, **kwargs)
    if not result.appended:
        return result
    event_type = str(kwargs.get("event_type") or "").strip().lower()
    if not (
        event_type.startswith("intervention.")
        or event_type in {
            "role.handoff",
            "role.rework_requested",
            "turn.completed",
            "turn.failed",
            "turn.cancelled",
        }
    ):
        return result
    payload = (
        dict(kwargs.get("payload"))
        if isinstance(kwargs.get("payload"), dict)
        else {}
    )
    entity_id = str(
        kwargs.get("entity_id")
        or payload.get("entity_id")
        or kwargs.get("turn_id")
        or ""
    ).strip()
    event_key = str(
        (result.event if isinstance(result.event, dict) else {}).get(
            "idempotency_key"
        )
        or kwargs.get("idempotency_key")
        or f"{event_type}:{entity_id}"
    )
    occurred_at = int(
        (result.event if isinstance(result.event, dict) else {}).get("occurred_at")
        or kwargs.get("occurred_at")
        or time.time() * 1000
    )
    if event_type.startswith("intervention."):
        entry_type = "intervention"
    elif event_type in {"role.handoff", "role.rework_requested"}:
        entry_type = (
            "collaboration_lift"
            if str(payload.get("action") or "") == "collaboration_lift"
            else "role_handoff"
        )
    else:
        entry_type = "terminal_state"
        payload.setdefault("status", event_type.removeprefix("turn."))
    append_session_entry(
        conversation,
        entry_type=entry_type,
        idempotency_key=f"hosted-event:{event_key}",
        payload={
            **payload,
            "event_type": event_type,
            "entity_id": entity_id,
            "turn_id": str(kwargs.get("turn_id") or ""),
            "role_stage": str(kwargs.get("role_stage") or "chat"),
        },
        occurred_at=occurred_at,
    )
    return result


def _append_attachment_session_entries(
    conversation: dict[str, Any],
    *,
    turn_id: str,
    role_stage: str,
    attachments: Any,
    direction: str,
    occurred_at: int,
) -> None:
    for raw in attachments if isinstance(attachments, list) else []:
        item = dict(raw) if isinstance(raw, dict) else {"id": str(raw or "")}
        attachment_id = str(item.get("id") or item.get("file_id") or "").strip()
        if not attachment_id:
            continue
        try:
            attachment_size = max(0, int(item.get("size") or 0))
        except (TypeError, ValueError, OverflowError):
            attachment_size = 0
        append_session_entry(
            conversation,
            entry_type="attachment",
            idempotency_key=(
                f"attachment:{turn_id}:{direction}:{attachment_id}"
            ),
            payload={
                "attachment_id": attachment_id,
                "turn_id": str(turn_id or ""),
                "role_stage": str(role_stage or "chat"),
                "direction": str(direction or "input"),
                "name": str(item.get("name") or item.get("filename") or "")[:240],
                "mime_type": str(item.get("mime_type") or "")[:120],
                "sha256": str(item.get("sha256") or "")[:64],
                "size": attachment_size,
            },
            occurred_at=occurred_at,
        )


def _append_canonical_turn_terminal(
    conversation: dict[str, Any],
    *,
    conversation_id: str,
    turn_id: str,
    run: dict[str, Any],
    occurred_at: int,
) -> None:
    status = str(run.get("status") or "").strip().lower()
    if status not in _HOSTED_TERMINAL_STATUSES:
        return
    for message in conversation.get("messages") or []:
        if not isinstance(message, dict):
            continue
        meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
        message_key = str(meta.get("message_key") or "")
        if (
            str(meta.get("runtime_turn_id") or "").strip() != turn_id
            and not message_key.startswith(f"{turn_id}:")
        ):
            continue
        message_id = str(message.get("id") or "").strip()
        if not message_id:
            continue
        message_status = str(message.get("status") or status).strip().lower()
        if message_status not in _HOSTED_TERMINAL_STATUSES:
            message_status = status
        append_message_stream_entries(
            conversation,
            message_id=message_id,
            previous_content=str(message.get("content") or ""),
            current_content=str(message.get("content") or ""),
            status=message_status,
            role=str(message.get("role") or "assistant"),
            name=str(message.get("name") or ""),
            kind=str(message.get("kind") or "message"),
            turn_id=turn_id,
            role_stage=str(meta.get("role_stage") or "chat"),
            occurred_at=occurred_at,
        )
        _append_attachment_session_entries(
            conversation,
            turn_id=turn_id,
            role_stage=str(meta.get("role_stage") or "chat"),
            attachments=meta.get("attachments"),
            direction="output",
            occurred_at=occurred_at,
        )
    event_type = f"turn.{status}"
    append_hosted_event(
        conversation,
        conversation_id=conversation_id,
        turn_id=turn_id,
        role_stage="turn",
        event_type=event_type,
        entity_id=turn_id,
        idempotency_key=f"turn:{turn_id}:{event_type}",
        account_generation=_account_generation_for_owner(
            str(conversation.get("owner_id") or LOCAL_OWNER_ID)
        ),
        payload={
            "entity_id": turn_id,
            "status": status,
            "stage": str(run.get("stage") or status),
            "error": str(run.get("error") or "")[:4000],
            "terminal_commit_id": str(run.get("terminal_commit_id") or ""),
        },
        occurred_at=occurred_at,
    )


class _HostedTurnCancelled(RuntimeError):
    """Interrupt a running profile child after its durable turn is cancelled."""


class _HostedRoleIntervention(RuntimeError):
    """Pause one role at an event boundary so a targeted control can run first."""

    def __init__(self, intervention: dict[str, Any]):
        super().__init__("Hosted role intervention requested")
        self.intervention = dict(intervention)

