def _configured_connector_token() -> str:
    """Read the connector credential without persisting or logging it."""

    value = os.environ.get("HERMES_COLLABORATION_CONNECTOR_TOKEN", "").strip()
    if value:
        return value
    path = os.environ.get("HERMES_COLLABORATION_CONNECTOR_TOKEN_FILE", "").strip()
    candidates = [path] if path else []
    candidates.append("/etc/hermes-mobile/connector_token")
    candidates.append("/etc/hermes-agent/collaboration-connector-token")
    for candidate in candidates:
        if not candidate:
            continue
        try:
            value = Path(candidate).read_text(encoding="utf-8").strip()
        except (OSError, UnicodeError):
            continue
        if value:
            return value
    return ""


def _connector_token_values(value: Any) -> tuple[list[str], dict[str, Any]]:
    """Normalise one connector credential entry into accepted tokens + metadata.

    Supported shapes for ``HERMES_COLLABORATION_CONNECTOR_TOKENS`` /
    ``..._TOKENS_FILE`` values:

    * ``"current-token"`` — legacy simple string.
    * ``["current-token", "previous-token"]`` — dual-secret rotation window.
    * ``{"token": "...", "previous_token": "...", "expires_at": "..."}`` —
      explicit rotation record.
    """
    if isinstance(value, str):
        token = str(value).strip()
        return ([token] if token else [], {})
    if isinstance(value, list):
        tokens = [
            str(item).strip()
            for item in value
            if isinstance(item, str) and str(item).strip()
        ]
        return tokens, {}
    if isinstance(value, dict):
        current = str(
            value.get("token")
            or value.get("current")
            or value.get("current_token")
            or ""
        ).strip()
        previous = str(
            value.get("previous")
            or value.get("previous_token")
            or value.get("old_token")
            or ""
        ).strip()
        tokens = [token for token in (current, previous) if token]
        # expires_at applies to the whole rotation record: past that moment
        # neither secret authenticates anymore, regardless of string match.
        expiry = _parse_connector_token_expiry(value.get("expires_at"))
        if expiry is not None and time.time() >= expiry:
            tokens = []
        metadata = {str(key): item for key, item in value.items() if key not in {"token", "current", "current_token", "previous", "previous_token", "old_token", "expires_at"}}
        return tokens, metadata
    return [], {}


def _parse_connector_token_expiry(value: Any) -> Optional[float]:
    """Parse an expires_at field as epoch seconds or an ISO-8601 timestamp."""

    if value is None:
        return None
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return float(value)
    text = str(value).strip()
    if not text:
        return None
    if re.fullmatch(r"-?\d+(?:\.\d+)?", text):
        return float(text)
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.timestamp()


def _configured_connector_token_records() -> dict[str, dict[str, Any]]:
    """Return connector credentials plus rotation metadata by device id."""
    records: dict[str, dict[str, Any]] = {}
    legacy = _configured_connector_token()
    if legacy:
        records["dbb3-primary"] = {"tokens": [legacy], "metadata": {}}
    raw = os.environ.get("HERMES_COLLABORATION_CONNECTOR_TOKENS", "").strip()
    map_file = os.environ.get(
        "HERMES_COLLABORATION_CONNECTOR_TOKENS_FILE",
        "",
    ).strip()
    if map_file:
        try:
            raw = Path(map_file).read_text(encoding="utf-8").strip()
        except (OSError, UnicodeError):
            raw = ""
    if raw:
        try:
            parsed = json.loads(raw)
        except (TypeError, ValueError):
            parsed = {}
        if isinstance(parsed, dict):
            for connector_id, value in parsed.items():
                normalized_id = str(connector_id or "").strip()[:128]
                tokens, metadata = _connector_token_values(value)
                if normalized_id and tokens:
                    records[normalized_id] = {"tokens": tokens, "metadata": metadata}
    return records


def _configured_connector_tokens() -> dict[str, str]:
    """Return the current connector credential keyed by immutable device id.

    The original single-token deployment remains supported, but that token is
    deliberately bound only to DBB3. Additional devices use the JSON secret
    map so presenting a valid token never lets a caller choose its identity.
    """

    return {
        connector_id: record["tokens"][0]
        for connector_id, record in _configured_connector_token_records().items()
    }


def _connector_bearer(request: Request) -> str:
    authorization = str(request.headers.get("authorization") or "")
    scheme, separator, token = authorization.partition(" ")
    return token.strip() if separator and scheme.lower() == "bearer" else ""


def _connector_identity(request: Request) -> str:
    supplied = _connector_bearer(request)
    claimed = str(request.headers.get("x-connector-id") or "").strip()[:128]
    if not supplied or not claimed:
        return ""
    records = _configured_connector_token_records()
    matches: set[str] = set()
    for connector_id, record in records.items():
        expected_tokens = record.get("tokens") or []
        if any(
            token and hmac.compare_digest(supplied, token)
            for token in expected_tokens
        ):
            matches.add(str(connector_id))

    # Backwards compatibility with tests/older deployments that only expose
    # the flat current-token map.  In normal production configuration this is
    # derived from ``records`` and adds no extra entries.  We still collect all
    # matches rather than checking only the claimed id: a token accidentally
    # assigned to two devices must fail closed instead of allowing the caller
    # to select either device with X-Connector-ID.
    for connector_id, expected in _configured_connector_tokens().items():
        if expected and hmac.compare_digest(supplied, expected):
            matches.add(str(connector_id))
    if len(matches) != 1 or claimed not in matches:
        return ""
    return claimed


def _connector_authorized(request: Request) -> bool:
    return bool(_connector_identity(request))


def _require_connector(request: Request) -> str:
    if not _configured_connector_tokens():
        raise HTTPException(status_code=503, detail="Connector credential is not configured")
    connector_id = _connector_identity(request)
    if not connector_id:
        raise HTTPException(status_code=401, detail="Unauthorized")
    return connector_id


def _rate_limit_connector(request: Request, connector_id: str, action: str) -> None:
    """Per-connector application-layer rate limit for hosted endpoints."""
    _record_connector_metric(connector_id, action)
    if not _CONNECTOR_RATE_LIMITER.allow(
        f"connector:{connector_id}:{action}",
        cost=2 if action in {"pull", "cancellations/pull", "artifacts"} else 1,
    ):
        raise HTTPException(status_code=429, detail="Too Many Requests")


def _register_connector_token_auth() -> None:
    """Register the connector prefix with the dashboard bearer seam.

    The plugin still checks the credential in each handler. Registration lets
    service callers bypass the interactive cookie gate on a public dashboard.
    """

    try:
        from hermes_cli.dashboard_auth import (
            DashboardAuthProvider,
            LoginStart,
            Session,
            TokenPrincipal,
            get_provider,
            register_provider,
        )
        from hermes_cli.dashboard_auth.token_auth import register_optional_token_prefix
    except Exception:
        return

    class _ConnectorTokenProvider(DashboardAuthProvider):
        name = "collaboration-connector"
        display_name = "Collaboration Connector"
        supports_session = False
        supports_token = True

        def verify_token(self, *, token: str) -> Optional[TokenPrincipal]:
            matches: list[str] = []
            seen: set[str] = set()
            for connector_id, record in _configured_connector_token_records().items():
                expected_tokens = record.get("tokens") or []
                for expected in expected_tokens:
                    if (
                        expected
                        and token
                        and hmac.compare_digest(token, expected)
                        and connector_id not in seen
                    ):
                        matches.append(connector_id)
                        seen.add(connector_id)
            # Backwards compatibility: a flat current-token map may be the only
            # configured source (or the only source tests override).
            for connector_id, expected in _configured_connector_tokens().items():
                if (
                    expected
                    and token
                    and hmac.compare_digest(token, expected)
                    and connector_id not in seen
                ):
                    matches.append(connector_id)
                    seen.add(connector_id)
            if len(matches) != 1:
                return None
            return TokenPrincipal(
                principal=matches[0],
                provider=self.name,
                scopes=("collaboration:connector",),
            )

        def start_login(self, *, redirect_uri: str) -> LoginStart:
            raise NotImplementedError("connector credentials are non-interactive")

        def complete_login(self, *, code: str, state: str, code_verifier: str, redirect_uri: str) -> Session:
            raise NotImplementedError("connector credentials are non-interactive")

        def verify_session(self, *, access_token: str) -> Optional[Session]:
            return None

        def refresh_session(self, *, refresh_token: str) -> Session:
            raise NotImplementedError("connector credentials are non-interactive")

        def revoke_session(self, *, refresh_token: str) -> None:
            return None

    try:
        if get_provider("collaboration-connector") is None:
            register_provider(_ConnectorTokenProvider())
        register_optional_token_prefix(
            "/api/plugins/collaboration/connector",
            required_scope="collaboration:connector",
        )
    except Exception:
        logging.getLogger(__name__).debug(
            "Collaboration connector token seam registration skipped",
            exc_info=True,
        )


_register_connector_token_auth()


def state_path() -> Path:
    return Path(get_hermes_home()) / "collaboration" / "rooms.json"


def single_state_path() -> Path:
    return Path(get_hermes_home()) / "collaboration" / "single.json"


def safe_attachment_name(filename: str) -> str:
    name = Path(str(filename or "").replace("\x00", "")).name.strip()
    if name in {"", ".", ".."}:
        raise ValueError("附件文件名无效")
    return name


_CONVERSATION_ID_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,249}")
_WINDOWS_RESERVED_COMPONENTS = frozenset(
    {"CON", "PRN", "AUX", "NUL"}
    | {f"COM{index}" for index in range(1, 10)}
    | {f"LPT{index}" for index in range(1, 10)}
)


def _safe_conversation_id(conversation_id: str) -> str:
    """Return an id that is safe to use as one filesystem path component."""

    raw = str(conversation_id or "")
    normalized = raw.strip()
    windows_stem = normalized.split(".", 1)[0].upper()
    if (
        not normalized
        or normalized != raw
        or not _CONVERSATION_ID_RE.fullmatch(normalized)
        or normalized in {".", ".."}
        or normalized[-1] in ". "
        or windows_stem in _WINDOWS_RESERVED_COMPONENTS
    ):
        raise ValueError("Invalid conversation_id")
    return normalized


def _contained_storage_path(root: Path, *components: str) -> Path:
    """Resolve a storage child and reject component or external-symlink escapes."""

    resolved_root = Path(root).resolve()
    target = resolved_root.joinpath(*components).resolve()
    if target == resolved_root or not target.is_relative_to(resolved_root):
        raise ValueError("Storage path escapes its root")
    return target


def conversation_files_root(conversation_id: str) -> Path:
    normalized = _safe_conversation_id(conversation_id)
    base = Path(get_hermes_home()) / "collaboration" / "files"
    return _contained_storage_path(base, normalized)


def _conversation_file_dir(conversation_id: str, bucket: str) -> Path:
    if bucket not in _ATTACHMENT_BUCKETS:
        raise HTTPException(status_code=404, detail="附件目录不存在")
    root = conversation_files_root(conversation_id)
    target = _contained_storage_path(root, bucket)
    target.mkdir(parents=True, exist_ok=True)
    return target


def _hosted_turn_output_dir(conversation_id: str, turn_id: str) -> Path:
    normalized_turn_id = str(turn_id or "").strip()
    if not normalized_turn_id:
        raise ValueError("turn_id is required")
    turn_key = hashlib.sha256(normalized_turn_id.encode("utf-8")).hexdigest()[:32]
    output_root = _conversation_file_dir(conversation_id, "outputs")
    turns_root = _contained_storage_path(output_root, "turns")
    target = _contained_storage_path(turns_root, turn_key)
    target.mkdir(parents=True, exist_ok=True)
    return target


def _hosted_output_paths(
    conversation_id: str,
    run: dict[str, Any],
) -> tuple[Path, Path]:
    output_root = _conversation_file_dir(conversation_id, "outputs").resolve()
    configured = str(run.get("output_dir") or "").strip()
    output_dir = Path(configured).resolve() if configured else output_root
    if not output_dir.is_relative_to(output_root):
        raise RuntimeError("Hosted output directory escapes the conversation output root")
    output_dir.mkdir(parents=True, exist_ok=True)
    return output_root, output_dir


def _output_file_signatures(directory: Path) -> dict[str, str]:
    """Hash a stable output snapshot so adjacent turns cannot share artifacts."""

    if not directory.exists():
        return {}
    resolved_root = directory.resolve(strict=True)
    signatures: dict[str, str] = {}
    for candidate in sorted(directory.rglob("*")):
        if (
            candidate.is_symlink()
            or not candidate.is_file()
            or (candidate.name.startswith(".") and candidate.name.endswith(".upload"))
        ):
            continue
        before = candidate.stat()
        resolved = candidate.resolve(strict=True)
        if not resolved.is_relative_to(resolved_root):
            continue
        digest = hashlib.sha256()
        with resolved.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        after = candidate.stat()
        if before.st_size != after.st_size or before.st_mtime_ns != after.st_mtime_ns:
            raise OSError(f"Output changed while its turn baseline was captured: {candidate}")
        signatures[resolved.relative_to(resolved_root).as_posix()] = digest.hexdigest()
    return signatures


def _ensure_hosted_output_baseline(
    conversation_id: str,
    run: dict[str, Any],
) -> None:
    if not _coerce_flag(run.get("artifact_required")) or "output_baseline" in run:
        return
    _output_root, output_dir = _hosted_output_paths(conversation_id, run)
    run["output_baseline"] = _output_file_signatures(output_dir)
    run["output_baseline_captured_at"] = int(time.time() * 1000)


def _sha256_path(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while chunk := handle.read(256 * 1024):
            digest.update(chunk)
    return digest.hexdigest()


def _attachment_upload_contract(request: Request) -> tuple[int | None, str]:
    declared_length = request.headers.get("content-length")
    expected_bytes: int | None = None
    if declared_length is not None:
        normalized_length = declared_length.strip()
        if not normalized_length.isdigit():
            raise HTTPException(status_code=422, detail="Invalid Content-Length")
        expected_bytes = int(normalized_length)
        if expected_bytes > _MAX_ATTACHMENT_BYTES:
            raise HTTPException(status_code=413, detail="Attachment exceeds 64 MB")
    expected_sha = str(request.headers.get("x-content-sha256") or "").strip().lower()
    if expected_sha and not re.fullmatch(r"[a-f0-9]{64}", expected_sha):
        raise HTTPException(status_code=422, detail="X-Content-SHA256 must be a SHA-256 hex digest")
    return expected_bytes, expected_sha


def _attachment_record(
    conversation_id: str,
    bucket: str,
    path: Path,
) -> dict[str, Any]:
    stat = path.stat()
    relative_path = path.relative_to(_conversation_file_dir(conversation_id, bucket))
    mime_type = mimetypes.guess_type(path.name)[0] or "application/octet-stream"
    encoded_relative = "/".join(
        quote(part, safe="")
        for part in relative_path.parts
    )
    return {
        "id": f"{bucket}:{relative_path.as_posix()}",
        "name": path.name,
        "bucket": bucket,
        "relative_path": relative_path.as_posix(),
        "size": stat.st_size,
        "mime_type": mime_type,
        "sha256": _sha256_path(path),
        "updated_at": int(stat.st_mtime * 1000),
        "download_url": (
            "/api/plugins/collaboration/single/conversations/"
            f"{conversation_id}/attachments/{bucket}/{encoded_relative}"
        ),
    }


def _list_conversation_attachments(conversation_id: str) -> list[dict[str, Any]]:
    # Hosted workflows call this function while preparing their final report.
    # Once a conversation has an authenticated owner, publish outputs into the
    # durable account library before exposing them to that report. Legacy
    # unowned conversations retain the original directory-backed response.
    try:
        with _STATE_LOCK:
            state = load_single_state()
            conversation = next(
                (
                    item
                    for item in state.get("conversations") or []
                    if item.get("id") == conversation_id
                ),
                None,
            )
            owner_id = (
                str(conversation.get("owner_id") or "").strip()
                if isinstance(conversation, dict)
                else ""
            )
        if owner_id and isinstance(conversation, dict):
            account_generation = _account_generation_for_conversation(conversation)
            try:
                _sync_conversation_files(
                    owner_id,
                    conversation,
                    account_generation=account_generation,
                )
            except Exception:
                logging.getLogger(__name__).exception(
                    "Failed to publish conversation files into account library"
                )
            return _conversation_library_attachments(
                owner_id,
                conversation_id,
                account_generation=account_generation,
            )
    except Exception:
        logging.getLogger(__name__).exception(
            "Failed to resolve conversation file ownership"
        )

    attachments: list[dict[str, Any]] = []
    for bucket in sorted(_ATTACHMENT_BUCKETS):
        root = _conversation_file_dir(conversation_id, bucket)
        for path in sorted(root.rglob("*")):
            if path.is_file():
                attachments.append(
                    _attachment_record(conversation_id, bucket, path)
                )
    return attachments


def _hosted_turn_output_attachments(
    conversation_id: str,
    turn_id: str,
    started_at: int,
) -> list[dict[str, Any]]:
    """Publish and return outputs owned by exactly one hosted turn."""

    del started_at  # Timestamp proximity is not proof that a turn created a file.
    normalized_turn_id = str(turn_id or "").strip()
    if not normalized_turn_id:
        return []
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(normalized_turn_id)
        if not isinstance(run, dict):
            return []
        run_snapshot = dict(run)
        owner_id = str(conversation.get("owner_id") or LOCAL_OWNER_ID).strip()
        account_generation = str(
            run.get("account_generation")
            or conversation.get("account_generation")
            or ""
        ).strip()
        if not account_generation:
            return []
        profile = next(
            (
                str(item).strip()
                for item in run.get("profiles") or []
                if str(item).strip()
            ),
            str(conversation.get("profile") or "default").strip() or "default",
        )

    output_root, output_dir = _hosted_output_paths(conversation_id, run_snapshot)
    baseline = run_snapshot.get("output_baseline")
    library = _file_library()
    if isinstance(baseline, dict):
        normalized_baseline = {
            str(relative): str(digest)
            for relative, digest in baseline.items()
            if str(relative) and re.fullmatch(r"[0-9a-f]{64}", str(digest))
        }
        if len(normalized_baseline) == len(baseline):
            current = _output_file_signatures(output_dir)
            origin_root = f"conversation:{conversation_id}:outputs"
            output_relative = output_dir.relative_to(output_root).as_posix()
            origin_prefix = (
                f"{origin_root}:{output_relative}"
                if output_relative != "."
                else origin_root
            )
            if not normalized_baseline:
                library.sync_directory(
                    owner_id,
                    output_dir,
                    account_generation=account_generation,
                    source="model_output",
                    conversation_id=conversation_id,
                    turn_id=normalized_turn_id,
                    profile=profile,
                    origin_prefix=origin_prefix,
                    strict=True,
                )
            else:
                for relative, digest in current.items():
                    if normalized_baseline.get(relative) == digest:
                        continue
                    candidate = (output_dir / relative).resolve(strict=True)
                    if not candidate.is_relative_to(output_dir):
                        continue
                    record = library.ingest_file(
                        owner_id,
                        candidate,
                        account_generation=account_generation,
                        name=candidate.name,
                        source="model_output",
                        conversation_id=conversation_id,
                        turn_id=normalized_turn_id,
                        profile=profile,
                        origin_key=f"{origin_prefix}:{relative}",
                        allowed_roots=[output_dir],
                        restore_deleted=False,
                    )
                    if record is not None and str(record.get("sha256") or "") != digest:
                        raise OSError(f"Output changed while it was indexed: {candidate}")

    attachments: list[dict[str, Any]] = []
    offset = 0
    while True:
        page, total = library.list_files(
            owner_id,
            account_generation=account_generation,
            source="model_output",
            status="available",
            conversation_id=conversation_id,
            turn_id=normalized_turn_id,
            limit=200,
            offset=offset,
        )
        attachments.extend(_library_attachment(record) for record in page)
        offset += len(page)
        if not page or offset >= total:
            break
    return attachments


class StateStoreError(RuntimeError):
    """Raised when a collaboration state store needs operator recovery."""


class CollaborationAccountDeletionInProgress(HTTPException):
    def __init__(self) -> None:
        super().__init__(status_code=410, detail="Account deletion is in progress")


def _account_deletion_tombstones(data: Any) -> dict[str, dict[str, dict[str, int]]]:
    if not isinstance(data, dict):
        return {}
    source = data.get(_ACCOUNT_DELETION_TOMBSTONES_KEY)
    if not isinstance(source, dict):
        return {}
    normalized: dict[str, dict[str, dict[str, int]]] = {}
    for owner_id, generations in source.items():
        owner = str(owner_id or "").strip().lower()
        if not owner or not isinstance(generations, dict):
            continue
        retained: dict[str, dict[str, int]] = {}
        for account_generation, metadata in generations.items():
            generation = str(account_generation or "").strip()
            if not generation:
                continue
            deleted_at = 0
            if isinstance(metadata, dict):
                try:
                    deleted_at = max(0, int(metadata.get("deleted_at") or 0))
                except (TypeError, ValueError):
                    deleted_at = 0
            retained[generation] = {"deleted_at": deleted_at}
        if retained:
            normalized[owner] = retained
    return normalized


def _record_account_deletion_intent(
    state: dict[str, Any],
    owner_id: str,
    account_generation: str,
    *,
    deleted_at: int,
) -> None:
    tombstones = _account_deletion_tombstones(state)
    owner = str(owner_id or "").strip().lower()
    generation = str(account_generation or "").strip()
    if not owner or not generation:
        raise ValueError("owner_id and account_generation are required")
    tombstones.setdefault(owner, {})[generation] = {
        "deleted_at": max(0, int(deleted_at)),
    }
    state[_ACCOUNT_DELETION_TOMBSTONES_KEY] = tombstones
    drop_account_persistence_hook_work(
        state,
        owner_id=owner,
        account_generation=generation,
    )


def _merge_account_deletion_tombstones(
    destination: dict[str, Any],
    source: dict[str, Any],
) -> dict[str, dict[str, dict[str, int]]]:
    merged = _account_deletion_tombstones(destination)
    for owner, generations in _account_deletion_tombstones(source).items():
        merged.setdefault(owner, {}).update(generations)
    if merged:
        destination[_ACCOUNT_DELETION_TOMBSTONES_KEY] = merged
    return merged


def _merge_authoritative_account_deletion_intents(
    state: dict[str, Any],
    collection_key: str,
) -> None:
    """Merge intelligence deletion intents before an account-owned commit."""

    account_scopes = {
        (
            str(record.get("owner_id") or "").strip().lower(),
            str(record.get("account_generation") or "").strip(),
        )
        for record in state.get(collection_key) or []
        if isinstance(record, dict)
        and str(record.get("owner_id") or "").strip()
        and str(record.get("owner_id") or "").strip().lower()
        != str(LOCAL_OWNER_ID).strip().lower()
    }
    if not account_scopes:
        return
    backend = _backend_api()
    configured = str(backend.load_ios_intelligence_config().database_path or "").strip()
    root = Path(get_hermes_home())
    database_path = Path(configured).expanduser() if configured else root
    if not database_path.is_absolute():
        database_path = root / database_path
    resolved_key = str(database_path.resolve())
    with _ACCOUNT_DELETION_STORE_LOCK:
        deletion_store = _ACCOUNT_DELETION_STORES.get(resolved_key)
        if deletion_store is None:
            deletion_store = backend.IOSIntelligenceStore(database_path)
            _ACCOUNT_DELETION_STORES[resolved_key] = deletion_store
    for owner, record_generation in account_scopes:
        intent = deletion_store.account_deletion_status(
            owner,
            record_generation,
        )
        if not intent:
            continue
        generation = str(intent.get("account_generation") or "").strip()
        if not generation:
            # A legacy/malformed deletion intent blocks every generation.
            generation = "*"
        deleted_at = int(intent.get("requested_at") or intent.get("updated_at") or 0)
        tombstones = _account_deletion_tombstones(state)
        tombstones.setdefault(owner, {})[generation] = {"deleted_at": deleted_at}
        state[_ACCOUNT_DELETION_TOMBSTONES_KEY] = tombstones


def _assert_no_tombstoned_state_mutation(
    current: dict[str, Any],
    incoming: dict[str, Any],
    collection_key: str,
) -> None:
    tombstones = _merge_account_deletion_tombstones(incoming, current)
    if not tombstones:
        return
    current_by_id = {
        str(record.get("id") or ""): record
        for record in current.get(collection_key) or []
        if isinstance(record, dict) and str(record.get("id") or "")
    }
    for record in incoming.get(collection_key) or []:
        if not isinstance(record, dict):
            continue
        owner = str(record.get("owner_id") or "").strip().lower()
        if not owner or owner == str(LOCAL_OWNER_ID).strip().lower():
            continue
        generations = tombstones.get(owner) or {}
        generation = str(record.get("account_generation") or "").strip()
        is_deleted = (
            "*" in generations
            or (generation in generations if generation else bool(generations))
        )
        if not is_deleted:
            continue
        existing = current_by_id.get(str(record.get("id") or ""))
        if existing != record:
            raise CollaborationAccountDeletionInProgress()


@contextmanager
def _collaboration_deletion_write():
    previous = bool(getattr(_COLLABORATION_DELETION_WRITE, "active", False))
    _COLLABORATION_DELETION_WRITE.active = True
    try:
        yield
    finally:
        _COLLABORATION_DELETION_WRITE.active = previous


def _state_backup_path(target: Path) -> Path:
    return target.with_name(f"{target.name}.bak")


def _state_quarantine_paths(target: Path) -> list[Path]:
    return sorted(target.parent.glob(f"{target.name}.corrupt.*"))


def _state_path_present(target: Path) -> bool:
    try:
        target.lstat()
    except FileNotFoundError:
        return False
    return True


def _validate_state_document(
    data: Any,
    collection_key: str,
    source: Path,
) -> dict[str, Any]:
    if not isinstance(data, dict):
        raise ValueError(f"{source} must contain a JSON object")
    collection = data.get(collection_key)
    if not isinstance(collection, list):
        raise ValueError(f"{source} must contain a {collection_key!r} list")
    return data


def _read_state_document(target: Path, collection_key: str) -> dict[str, Any]:
    raw = target.read_text(encoding="utf-8")
    return _validate_state_document(json.loads(raw), collection_key, target)


def _fsync_parent_directory(target: Path) -> None:
    if os.name == "nt":
        return
    try:
        descriptor = os.open(target.parent, os.O_RDONLY)
    except OSError:
        return
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def _atomic_write_state_document(target: Path, data: dict[str, Any]) -> None:
    _invalidate_single_state_cache(target)
    # This is a machine-owned recovery document. Compact encoding cuts both
    # fsync latency and storage without weakening the atomic-write contract.
    payload = json.dumps(data, ensure_ascii=False, separators=(",", ":")) + "\n"
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = target.with_name(
        f".{target.name}.{os.getpid()}.{threading.get_ident()}.{uuid.uuid4().hex}.tmp"
    )
    try:
        with temporary.open("x", encoding="utf-8", newline="\n") as handle:
            try:
                os.chmod(temporary, 0o600)
            except OSError:
                pass
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, target)
        _fsync_parent_directory(target)
    finally:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass


def _atomic_snapshot_state_document(source: Path, target: Path) -> bool:
    """Atomically retain the current document without rewriting its bytes.

    State saves replace ``source`` with a new inode.  A hard link made before
    that replace therefore remains an immutable copy of the last committed
    document, which is exactly the recovery contract for ``*.bak``.  Some
    filesystems do not support links; callers fall back to serialization in
    that case.
    """

    _invalidate_single_state_cache(target)
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = target.with_name(
        f".{target.name}.{os.getpid()}.{threading.get_ident()}.{uuid.uuid4().hex}.tmp"
    )
    try:
        os.link(source, temporary)
        os.replace(temporary, target)
        _fsync_parent_directory(target)
        return True
    except OSError:
        return False
    finally:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass


def _deliver_and_persist_hosted_event_hook_outbox(
    target: Path,
    state: dict[str, Any],
    collection_key: str,
) -> dict[str, Any]:
    """Deliver committed callbacks and persist their ACK without rollback."""

    outcome = dispatch_persisted_hosted_event_hooks(
        state,
        store_path=str(target),
    )
    # Dispatch also performs deletion-boundary garbage collection.  Persist
    # that change even when no callback was attempted (for example, an empty
    # registry recovering a tombstoned account).
    if not outcome.attempted_event_ids and outcome.state == state:
        return state
    _validate_state_document(outcome.state, collection_key, target)
    try:
        # The backup intentionally retains the pre-ACK outbox. If the ACK target
        # is lost or damaged, recovery redelivers with the same idempotency key.
        _atomic_write_state_document(_state_backup_path(target), state)
        _atomic_write_state_document(target, outcome.state)
    except Exception:
        logging.getLogger(__name__).exception(
            "Could not persist hosted-event hook ACK for %s; delivery will retry",
            target,
        )
        return state
    return outcome.state


def _quarantine_state_file(target: Path) -> Path:
    quarantine = target.with_name(
        f"{target.name}.corrupt.{time.time_ns()}.{uuid.uuid4().hex[:8]}"
    )
    try:
        os.replace(target, quarantine)
        try:
            quarantine.chmod(0o600, follow_symlinks=False)
        except (NotImplementedError, OSError):
            pass
        _fsync_parent_directory(target)
    except OSError as exc:
        raise StateStoreError(
            f"Could not isolate unreadable collaboration state {target}: {exc}"
        ) from exc
    return quarantine


def _restore_state_backup(
    target: Path,
    collection_key: str,
    *,
    primary_error: BaseException | None = None,
    quarantine: Path | None = None,
) -> dict[str, Any]:
    backup = _state_backup_path(target)
    try:
        data = _read_state_document(backup, collection_key)
    except FileNotFoundError as backup_error:
        detail = f"; corrupt data preserved at {quarantine}" if quarantine else ""
        raise StateStoreError(
            f"Collaboration state {target} is unreadable and has no valid backup{detail}"
        ) from (primary_error or backup_error)
    except (OSError, UnicodeError, ValueError, TypeError) as backup_error:
        backup_quarantine = _quarantine_state_file(backup)
        detail = f"; corrupt data preserved at {quarantine}" if quarantine else ""
        raise StateStoreError(
            f"Collaboration state {target} and its backup are unreadable{detail}; "
            f"backup preserved at {backup_quarantine}"
        ) from backup_error
    try:
        _atomic_write_state_document(target, data)
    except OSError as restore_error:
        raise StateStoreError(
            f"Could not restore collaboration state {target} from {backup}"
        ) from restore_error
    logging.getLogger(__name__).error(
        "Recovered collaboration state %s from %s; damaged primary is at %s",
        target,
        backup,
        quarantine or "<missing>",
    )
    return data


def _load_state_store(
    target: Path,
    collection_key: str,
    *,
    dispatch_persistence_hooks: bool = True,
) -> dict[str, Any]:
    # Recovery can persist an outbox ACK, so readers share the same critical
    # section as writers rather than allowing a stale read to overwrite a newer
    # conversation document.
    with _backend_api().account_lifecycle_commit_guard():
        with _STATE_LOCK:
            result = _load_state_store_locked(
                target,
                collection_key,
                dispatch_persistence_hooks=dispatch_persistence_hooks,
            )
    return result


def _load_state_store_locked(
    target: Path,
    collection_key: str,
    *,
    dispatch_persistence_hooks: bool = True,
) -> dict[str, Any]:
    try:
        data = _read_state_document(target, collection_key)
        if dispatch_persistence_hooks:
            return _deliver_and_persist_hosted_event_hook_outbox(
                target,
                data,
                collection_key,
            )
        return data
    except FileNotFoundError:
        pass
    except (OSError, UnicodeError, ValueError, TypeError) as primary_error:
        quarantine = _quarantine_state_file(target)
        restored = _restore_state_backup(
            target,
            collection_key,
            primary_error=primary_error,
            quarantine=quarantine,
        )
        if dispatch_persistence_hooks:
            return _deliver_and_persist_hosted_event_hook_outbox(
                target,
                restored,
                collection_key,
            )
        return restored

    if _state_path_present(_state_backup_path(target)):
        restored = _restore_state_backup(target, collection_key)
        if dispatch_persistence_hooks:
            return _deliver_and_persist_hosted_event_hook_outbox(
                target,
                restored,
                collection_key,
            )
        return restored
    quarantines = _state_quarantine_paths(target)
    if quarantines:
        raise StateStoreError(
            f"Collaboration state {target} is awaiting recovery; "
            f"preserved data: {quarantines[-1]}"
        )
    return {collection_key: []}


def _save_state_store(
    target: Path,
    state: dict[str, Any],
    collection_key: str,
    *,
    previous_state: Any = _STATE_STORE_PREVIOUS_UNSET,
) -> None:
    if previous_state is _STATE_STORE_PREVIOUS_UNSET:
        previous: dict[str, Any] | None = None
        if (
            _state_path_present(target)
            or _state_path_present(_state_backup_path(target))
            or _state_quarantine_paths(target)
        ):
            previous = _load_state_store(
                target,
                collection_key,
                dispatch_persistence_hooks=not bool(
                    getattr(_COLLABORATION_DELETION_WRITE, "active", False)
                ),
            )
    else:
        previous = previous_state
    if previous is not None:
        # A stale in-memory writer may still carry a staged callback that a
        # recovery reader already delivered. Merge durable receipts before
        # promoting pending work so an ACK cannot be resurrected.
        preserve_persistence_hook_outbox(previous, state)
    persisted_state = state_with_persistence_hook_outbox(state)
    _validate_state_document(persisted_state, collection_key, target)

    # Keep the last known-good document in a separately atomic file. On first
    # creation the backup is written first, so a crash cannot leave an empty
    # store with no recovery source.
    backup_state: dict[str, Any]
    can_snapshot_previous = False
    if previous is None:
        backup_state = persisted_state
        # ``save_single_state``'s fast path deliberately avoids reparsing the
        # document it just loaded.  When a committed primary already exists,
        # retain that inode as the backup instead of serializing the new state
        # twice.  Deletion-tombstone writes leave the fast path above.
        can_snapshot_previous = _state_path_present(target)
    else:
        # A deletion intent may have been added to the incoming state after
        # the previous document was read.  Carry that tombstone into the
        # backup before filtering its hook outbox, otherwise recovery from the
        # backup could resurrect a delivery for the deleted generation.
        backup_state = deepcopy(previous)
        _merge_account_deletion_tombstones(backup_state, persisted_state)
        backup_state = state_with_persistence_hook_outbox(backup_state)
        can_snapshot_previous = (
            _state_path_present(target)
            and _account_deletion_tombstones(backup_state)
            == _account_deletion_tombstones(previous)
        )
    backup_target = _state_backup_path(target)
    if not (
        can_snapshot_previous
        and _atomic_snapshot_state_document(target, backup_target)
    ):
        _atomic_write_state_document(backup_target, backup_state)
    _atomic_write_state_document(target, persisted_state)
    try:
        committed_state = _deliver_and_persist_hosted_event_hook_outbox(
            target,
            persisted_state,
            collection_key,
        )
        state.clear()
        state.update(deepcopy(committed_state))
    except Exception:
        # The target write is already authoritative. Persistence observers are
        # fail-open and must never turn a committed state transition into a
        # caller-visible save failure.
        logging.getLogger(__name__).exception(
            "Post-persistence hosted-event observer failed for %s",
            target,
        )


def load_state(
    path: Optional[Path] = None,
    *,
    dispatch_persistence_hooks: bool = True,
) -> dict[str, Any]:
    target = path or state_path()
    data = _load_state_store(
        target,
        "rooms",
        dispatch_persistence_hooks=dispatch_persistence_hooks,
    )
    result = {"rooms": data["rooms"]}
    for room in result["rooms"]:
        if not isinstance(room, dict):
            continue
        if not isinstance(room.get("mailbox"), list):
            room["mailbox"] = []
        if not isinstance(room.get("dependencies"), list):
            room["dependencies"] = []
    tombstones = _account_deletion_tombstones(data)
    if tombstones:
        result[_ACCOUNT_DELETION_TOMBSTONES_KEY] = tombstones
    preserve_persistence_hook_outbox(data, result)
    return result


def load_single_state(
    path: Optional[Path] = None,
    *,
    dispatch_persistence_hooks: bool = True,
) -> dict[str, Any]:
    target = Path(path) if path is not None else single_state_path()
    cache_key = _single_state_cache_key(target, dispatch_persistence_hooks)
    if cache_key is not None:
        # Check the cache while holding the same account/state fence used by
        # writers.  This prevents an atomic replace from racing a cache hit
        # and returning the previous document after a committed turn update.
        with _STATE_LOCK:
            fingerprint = _single_state_fingerprint(target)
            if fingerprint is not None:
                with _SINGLE_STATE_CACHE_LOCK:
                    cached = _SINGLE_STATE_CACHE.get(cache_key)
                if cached is not None and cached[0] == fingerprint:
                    # Persistence-enabled callers mutate the returned state
                    # before saving it.  Return a private snapshot so that a
                    # staged mutation cannot silently rewrite the cache's
                    # view of the last committed document.  The event stream
                    # is read-only and can share its normalized snapshot.
                    result = (
                        deepcopy(cached[1])
                        if dispatch_persistence_hooks
                        else cached[1]
                    )
                    if path is None:
                        _STATE_THREAD_LOCAL.last_single_state = result
                    return result
    data = _load_state_store(
        target,
        "conversations",
        dispatch_persistence_hooks=dispatch_persistence_hooks,
    )
    normalized_conversations = data["conversations"]
    for conversation in normalized_conversations:
        if not isinstance(conversation, dict):
            continue
        messages = conversation.get("messages")
        if isinstance(messages, list):
            conversation["messages"] = normalize_stored_conversation_messages(
                messages
            )
        if not isinstance(conversation.get("hosted_turns"), dict):
            conversation["hosted_turns"] = {}
        if not isinstance(conversation.get("hosted_events"), list):
            conversation["hosted_events"] = []
        if not isinstance(conversation.get("hosted_event_sequences"), dict):
            conversation["hosted_event_sequences"] = {}
        if not isinstance(conversation.get("hosted_event_terminals"), dict):
            conversation["hosted_event_terminals"] = {}
        normalize_session_entries(conversation)
        try:
            conversation["event_cursor"] = max(
                0,
                int(conversation.get("event_cursor") or 0),
            )
        except (TypeError, ValueError):
            conversation["event_cursor"] = 0
        retained_hosted_events = [
            item
            for item in conversation.get("hosted_events") or []
            if isinstance(item, dict)
        ]
        try:
            conversation["hosted_event_cursor"] = max(
                max(
                    (
                        int(item.get("cursor") or 0)
                        for item in retained_hosted_events
                    ),
                    default=0,
                ),
                int(conversation.get("hosted_event_cursor") or 0),
            )
        except (TypeError, ValueError):
            conversation["hosted_event_cursor"] = 0
    result = {"conversations": normalized_conversations}
    tombstones = _account_deletion_tombstones(data)
    if tombstones:
        result[_ACCOUNT_DELETION_TOMBSTONES_KEY] = tombstones
    preserve_persistence_hook_outbox(data, result)
    if cache_key is not None:
        fingerprint = _single_state_fingerprint(target)
        if fingerprint is not None:
            with _SINGLE_STATE_CACHE_LOCK:
                _SINGLE_STATE_CACHE[cache_key] = (
                    fingerprint,
                    deepcopy(result)
                    if dispatch_persistence_hooks
                    else result,
                )
    # Most hosted writers read, mutate, and save this exact object while the
    # account lock is held.  Remember that identity so save_single_state can
    # avoid reparsing the same multi-megabyte document on the hot path.
    if path is None:
        _STATE_THREAD_LOCAL.last_single_state = result
    return result


def _load_single_state_for_event_stream() -> dict[str, Any]:
    """Read the event source without running persistence observers."""

    try:
        return load_single_state(dispatch_persistence_hooks=False)
    except TypeError:
        # A few lightweight tests replace load_single_state with a zero-arg
        # lambda; retain that test seam while keeping production reads cheap.
        return load_single_state()


def summarize_task_title(content: str) -> str:
    text = re.sub(r"\s+", " ", str(content or "")).strip()
    if not text:
        return "新对话"
    text = text.split("本会话交付文件目录：", 1)[0].strip()
    reply_match = re.search(
        r"(?:^|[，,。；;])\s*只回复\s*[：:]?\s*([A-Za-z0-9][A-Za-z0-9_. -]{1,40})",
        text,
    )
    if reply_match:
        return reply_match.group(1).strip()[:_MAX_CONVERSATION_TITLE_CHARS]
    clauses = [
        clause.strip(" ：:，,。；;！？!?\"'`()[]{}")
        for clause in re.split(r"[\n，,。；;！？!?:：]+", text)
        if clause.strip()
    ] or [text]
    action_weights = {
        "修复": 10,
        "优化": 10,
        "部署": 10,
        "配置": 10,
        "创建": 10,
        "生成": 10,
        "安装": 9,
        "更新": 9,
        "删除": 9,
        "验收": 9,
        "验证": 8,
        "测试": 8,
        "继续": 8,
        "接着": 8,
        "检查": 7,
        "总结": 7,
        "整理": 7,
        "说明": 7,
        "解释": 7,
        "精炼": 7,
        "运行": 5,
        "调用": 4,
        "完成": 2,
    }
    topic_markers = (
        "Hermes",
        "hermes",
        "DBB3",
        "dbb3",
        "本地电脑",
        "iOS",
        "ios",
        "后台托管",
        "会话",
        "标题",
        "看板",
        "网络",
        "输入框",
        "定时任务",
        "自我进化",
        "terminal",
    )
    negative_markers = ("不要", "不调用", "无需", "禁止", "只回复")
    focused_clauses = [
        clause
        for clause in clauses
        if not any(marker in clause for marker in negative_markers)
    ]
    if focused_clauses:
        clauses = focused_clauses

    def score(clause: str) -> tuple[int, int]:
        value = sum(weight for marker, weight in action_weights.items() if marker in clause)
        value += sum(2 for marker in topic_markers if marker in clause)
        if any(marker in clause for marker in negative_markers):
            value -= 20
        return value, -len(clause)

    title = max(clauses, key=score)
    title = re.sub(
        r"^(?:请用[一二三四五六七八九十\d]+句话|请(?:你)?|麻烦(?:你)?|帮我|你(?:去|帮我)|我(?:希望|想要|要)|能不能|可以)+",
        "",
        title,
    ).strip()
    title = re.sub(r"(?:已)?完成$", "", title).strip()
    if not title:
        title = clauses[0]
    if len(title) > _MAX_CONVERSATION_TITLE_CHARS:
        title = title[: _MAX_CONVERSATION_TITLE_CHARS - 1].rstrip() + "…"
    return title or "新对话"


def compact_conversation_title(conversation: dict[str, Any]) -> bool:
    current = str(conversation.get("title") or "").strip()
    poor_title = any(
        marker in current
        for marker in ("不要", "不调用", "无需", "禁止", "只回复")
    ) or current.startswith("回复 ")
    if len(current) <= _MAX_CONVERSATION_TITLE_CHARS and not poor_title:
        return False
    first_user_message = next(
        (
            str(message.get("content") or "").strip()
            for message in conversation.get("messages") or []
            if message.get("role") == "user" and message.get("content")
        ),
        current,
    )
    compacted = summarize_task_title(first_user_message)
    if compacted == current:
        return False
    conversation["title"] = compacted
    return True


def save_state(state: dict[str, Any], path: Optional[Path] = None) -> None:
    target = path or state_path()
    with _backend_api().account_lifecycle_commit_guard():
        with _STATE_LOCK:
            previous_state: Any = _STATE_STORE_PREVIOUS_UNSET
            if not bool(getattr(_COLLABORATION_DELETION_WRITE, "active", False)):
                current = (
                    _load_state_store(target, "rooms")
                    if _state_path_present(target)
                    else {"rooms": []}
                )
                if path is None:
                    # The single-conversation store is the deletion-intent
                    # authority. Group-room writes must observe the same fence
                    # before mobile authentication is revoked.
                    _merge_account_deletion_tombstones(current, load_single_state())
                _merge_authoritative_account_deletion_intents(state, "rooms")
                _assert_no_tombstoned_state_mutation(current, state, "rooms")
                if _state_path_present(target):
                    previous_state = current
            _save_state_store(
                target,
                state,
                "rooms",
                previous_state=previous_state,
            )


_MAX_HOSTED_EVENTS_PER_CONVERSATION = 200
_MAX_HOSTED_TURNS_PER_CONVERSATION = 20
_MAX_HOSTED_MESSAGES_PER_CONVERSATION = 40
_MAX_HOSTED_SESSION_ENTRIES_PER_CONVERSATION = 40
_MAX_ROLE_EVENTS_PER_TURN = 10
_MAX_SUPERVISOR_CHECKS_PER_TURN = 5
_MAX_REMOTE_ACTIVITIES_PER_RUN = 30
_MAX_ACTIVITY_FIELD_CHARS = 4000
_MAX_MESSAGE_CONTENT_CHARS = 8000
_MAX_ROLE_EVENT_ACTIVITY_CHARS = 4000
_MAX_SUPERVISOR_EVIDENCE_CHARS = 4000
# Conversations whose hosted turns are all terminal and which have been
# idle for this long are archived out of the hot single.json document into
# per-conversation archive files. Restoring one is a lazy, locked read.
# 10 minutes: every terminal test/one-shot conversation leaves the hot
# document quickly, keeping the every-write round-trip cheap; access is
# invisible to callers because _conversation_by_id restores on demand.
_ARCHIVE_IDLE_AGE_SECONDS = 600
_ARCHIVE_RESTORE_GRACE_SECONDS = 3600


def _conversation_history_path(conversation_id: str) -> Optional[Path]:
    """Return the sidecar used to retain history beyond the hot-state cap."""

    try:
        normalized = _safe_conversation_id(conversation_id)
        root = conversation_files_root(normalized)
        return _contained_storage_path(root, "history.json")
    except ValueError:
        return None


def _conversation_history_meta_path(conversation_id: str) -> Optional[Path]:
    target = _conversation_history_path(conversation_id)
    if target is None:
        return None
    try:
        return _contained_storage_path(target.parent, "history.meta.json")
    except ValueError:
        return None


def _history_item_key(item: Any, index: int) -> str:
    if isinstance(item, dict):
        for field in (
            "id",
            "entry_id",
            "message_id",
            "cursor",
            "sequence",
            "request_id",
        ):
            value = str(item.get(field) or "").strip()
            if value:
                return f"{field}:{value}"
    try:
        encoded = json.dumps(item, ensure_ascii=False, sort_keys=True, default=str)
    except (TypeError, ValueError):
        encoded = repr(item)
    return f"value:{hashlib.sha256(encoded.encode('utf-8')).hexdigest()}:{index}"


def _merge_history_items(
    existing: Any,
    incoming: Any,
) -> list[dict[str, Any]]:
    """Merge hot-state updates into an append-only full-history sidecar."""

    merged: list[dict[str, Any]] = []
    positions: dict[str, int] = {}
    for source in (existing, incoming):
        if not isinstance(source, list):
            continue
        for index, item in enumerate(source):
            if not isinstance(item, dict):
                continue
            value = deepcopy(item)
            key = _history_item_key(value, index)
            previous = positions.get(key)
            if previous is None:
                positions[key] = len(merged)
                merged.append(value)
            else:
                merged[previous] = value
    return merged


def _read_conversation_history(conversation_id: str) -> dict[str, Any]:
    target = _conversation_history_path(conversation_id)
    if target is None:
        return {}
    try:
        value = json.loads(target.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, ValueError):
        return {}
    return value if isinstance(value, dict) else {}


def _read_conversation_history_meta(conversation_id: str) -> dict[str, Any]:
    target = _conversation_history_meta_path(conversation_id)
    if target is None:
        return {}
    try:
        value = json.loads(target.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, ValueError):
        return {}
    return value if isinstance(value, dict) else {}


def _history_matches_conversation(
    history: dict[str, Any],
    conversation: dict[str, Any],
) -> bool:
    if not history:
        return False
    expected_id = str(conversation.get("id") or "").strip()
    stored_id = str(history.get("conversation_id") or "").strip()
    if expected_id and stored_id != expected_id:
        return False
    if history.get("version") not in (None, 1):
        return False
    for field in ("owner_id", "account_generation"):
        expected = str(conversation.get(field) or "").strip()
        stored = str(history.get(field) or "").strip()
        # A missing identity on an old sidecar is not proof that it belongs to
        # the current account.  Refuse to hydrate it rather than risking a
        # cross-account or cross-generation transcript leak.
        if stored != expected:
            return False
    return True


def _atomic_write_json_file(target: Path, document: Any) -> None:
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = target.with_name(
        f".{target.name}.{os.getpid()}.{threading.get_ident()}.{uuid.uuid4().hex}.tmp"
    )
    try:
        with temporary.open("x", encoding="utf-8", newline="\n") as handle:
            try:
                os.chmod(temporary, 0o600)
            except OSError:
                pass
            handle.write(json.dumps(document, ensure_ascii=False, separators=(",", ":")))
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, target)
        _fsync_parent_directory(target)
    finally:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass


def _write_conversation_history(
    conversation: dict[str, Any],
    *,
    existing: Optional[dict[str, Any]] = None,
) -> None:
    conversation_id = str(conversation.get("id") or "").strip()
    target = _conversation_history_path(conversation_id)
    if target is None:
        # This path is reached before hot-state trimming.  Silently returning
        # would make the subsequent trim destroy the only copy of history.
        raise ValueError("invalid conversation id for history sidecar")
    previous = existing if existing is not None else _read_conversation_history(conversation_id)
    if previous and not _history_matches_conversation(previous, conversation):
        previous = {}
    incoming_messages = [
        _sanitize_history_message(deepcopy(item))
        for item in conversation.get("messages") or []
        if isinstance(item, dict)
    ]
    messages = _merge_history_items(previous.get("messages"), incoming_messages)
    session_entries = _merge_history_items(
        previous.get("session_entries"),
        conversation.get("session_entries"),
    )
    if not messages and not session_entries:
        return
    document = {
        "version": 1,
        "conversation_id": conversation_id,
        "owner_id": conversation.get("owner_id", previous.get("owner_id", "")),
        "account_generation": conversation.get(
            "account_generation",
            previous.get("account_generation", ""),
        ),
        "messages": messages,
        "session_entries": session_entries,
        "message_count": len(messages),
        "last_message": deepcopy(messages[-1]) if messages else None,
        "session_entry_count": len(session_entries),
        "updated_at": max(
            _nonnegative_int(conversation.get("updated_at")),
            _nonnegative_int(previous.get("updated_at")),
        ),
    }
    conversation["history_message_count"] = document["message_count"]
    conversation["history_last_message"] = document["last_message"]
    conversation["history_session_entry_count"] = document["session_entry_count"]
    existing_meta = _read_conversation_history_meta(conversation_id)
    if (
        previous.get("messages") == messages
        and previous.get("session_entries") == session_entries
        and previous.get("message_count") == document["message_count"]
        and previous.get("last_message") == document["last_message"]
        and previous.get("session_entry_count") == document["session_entry_count"]
        and previous.get("owner_id") == document["owner_id"]
        and previous.get("account_generation") == document["account_generation"]
        and existing_meta.get("message_count") == document["message_count"]
        and existing_meta.get("last_message") == document["last_message"]
        and existing_meta.get("session_entry_count") == document["session_entry_count"]
        and existing_meta.get("owner_id") == document["owner_id"]
        and existing_meta.get("account_generation") == document["account_generation"]
    ):
        return
    _atomic_write_json_file(target, document)
    meta_target = _conversation_history_meta_path(conversation_id)
    if meta_target is not None:
        _atomic_write_json_file(meta_target, {
            "version": 1,
            "conversation_id": conversation_id,
            "owner_id": document["owner_id"],
            "account_generation": document["account_generation"],
            "message_count": document["message_count"],
            "last_message": document["last_message"],
            "session_entry_count": document["session_entry_count"],
        })


def _rewrite_conversation_history_messages(
    conversation_id: str,
    rewrite: Callable[[list[dict[str, Any]]], list[dict[str, Any]]],
) -> None:
    """Apply an explicit chat-message delete/rollback to the full sidecar."""

    history = _read_conversation_history(conversation_id)
    if not history or not isinstance(history.get("messages"), list):
        return
    current = [deepcopy(item) for item in history["messages"] if isinstance(item, dict)]
    messages = [
        _sanitize_history_message(deepcopy(item))
        for item in rewrite(current)
        if isinstance(item, dict)
    ]
    if messages == current:
        return
    history["messages"] = messages
    history["message_count"] = len(messages)
    history["last_message"] = deepcopy(messages[-1]) if messages else None
    target = _conversation_history_path(conversation_id)
    meta_target = _conversation_history_meta_path(conversation_id)
    if target is None or meta_target is None:
        return
    _atomic_write_json_file(target, history)
    _atomic_write_json_file(meta_target, {
        "version": 1,
        "conversation_id": conversation_id,
        "owner_id": history.get("owner_id", ""),
        "account_generation": history.get("account_generation", ""),
        "message_count": history["message_count"],
        "last_message": history["last_message"],
        "session_entry_count": int(history.get("session_entry_count") or 0),
    })


def _persist_conversation_histories(state: dict[str, Any]) -> None:
    """Persist complete transcripts before trimming the hot single-state file."""

    for conversation in state.get("conversations") or []:
        if not isinstance(conversation, dict):
            continue
        messages = conversation.get("messages")
        entries = conversation.get("session_entries")
        if not isinstance(messages, list) and not isinstance(entries, list):
            continue
        conversation_id = str(conversation.get("id") or "").strip()
        if not conversation_id:
            continue
        previous = _read_conversation_history(conversation_id)
        # Avoid touching disk for the common short-conversation case until a
        # transcript actually exceeds the hot-state bound or already exists.
        if (
            not previous
            and len(messages or []) <= _MAX_HOSTED_MESSAGES_PER_CONVERSATION
            and len(entries or []) <= _MAX_HOSTED_SESSION_ENTRIES_PER_CONVERSATION
        ):
            continue
        # Do not trim this conversation if its full-history sidecar cannot be
        # committed. Raising keeps the previous hot state and deletion intent
        # durable, instead of silently destroying the only older messages.
        _write_conversation_history(conversation, existing=previous)


def _hydrate_conversation_history(conversation: dict[str, Any]) -> dict[str, Any]:
    """Merge a retained sidecar into one hot conversation on detailed reads."""

    history = _read_conversation_history(str(conversation.get("id") or ""))
    if not _history_matches_conversation(history, conversation):
        return conversation
    messages = _merge_history_items(history.get("messages"), conversation.get("messages"))
    entries = _merge_history_items(
        history.get("session_entries"),
        conversation.get("session_entries"),
    )
    if messages:
        conversation["messages"] = messages
    if entries:
        conversation["session_entries"] = entries
    if history.get("message_count") is not None:
        # The merged list is authoritative.  Never let a corrupt/stale count
        # manufacture an endless pagination tail.
        conversation["history_message_count"] = len(messages)
        conversation["history_last_message"] = (
            deepcopy(messages[-1]) if messages else None
        )
    if history.get("session_entry_count") is not None:
        conversation["history_session_entry_count"] = len(entries)
    conversation["history_complete"] = True
    return conversation


def _conversation_history_summary(
    conversation: dict[str, Any],
) -> tuple[int, Optional[dict[str, Any]]]:
    """Read the bounded index metadata without expanding the transcript."""

    messages = conversation.get("messages")
    count = max(
        len(messages) if isinstance(messages, list) else 0,
        _nonnegative_int(conversation.get("history_message_count")),
        _nonnegative_int(conversation.get("message_count"))
        if conversation.get("archived")
        else 0,
    )
    last = conversation.get("history_last_message")
    if not isinstance(last, dict):
        last = messages[-1] if isinstance(messages, list) and messages else None
    # A complete internal summary is safe to use without touching disk.  At
    # the hot-state cap, however, an older sidecar may exist without these
    # fields; fall through so index polling can discover its full count.
    if (
        isinstance(last, dict)
        and "history_message_count" in conversation
        and (len(messages or []) < _MAX_HOSTED_MESSAGES_PER_CONVERSATION)
    ):
        return count, last
    # Read the tiny metadata sidecar during index polling. Older installs may
    # not have it yet, so fall back to the full document once and promote it.
    conversation_id = str(conversation.get("id") or "")
    history = _read_conversation_history_meta(conversation_id)
    if not history:
        history = _read_conversation_history(conversation_id)
    if history and not _history_matches_conversation(history, conversation):
        history = {}
    if history:
        history_count = _nonnegative_int(history.get("message_count"))
        count = max(count, history_count)
        candidate = history.get("last_message")
        if isinstance(candidate, dict) and history_count >= len(messages or []):
            last = candidate
        conversation["history_message_count"] = count
        conversation["history_last_message"] = deepcopy(last) if last else None
    return count, last if isinstance(last, dict) else None


def _archive_root() -> Path:
    return Path(get_hermes_home()) / "collaboration" / "archive"


def _conversation_archive_path(conversation_id: str) -> Optional[Path]:
    try:
        normalized = _safe_conversation_id(conversation_id)
    except ValueError:
        return None
    try:
        return _contained_storage_path(_archive_root(), f"{normalized}.json")
    except ValueError:
        return None


def _conversation_terminal(conversation: dict[str, Any]) -> bool:
    turns = conversation.get("hosted_turns")
    if not isinstance(turns, dict):
        return True
    if not turns:
        return True
    return all(
        isinstance(turn, dict)
        and str(turn.get("status") or "").strip().lower()
        in _HOSTED_TERMINAL_STATUSES
        for turn in turns.values()
    )


def _archive_completed_conversations(state: dict[str, Any]) -> None:
    """Move long-idle terminal conversations out of the hot state document.

    The single.json document is read, deep-copied and rewritten on every
    hosted mutation; unbounded per-conversation history (messages, hosted
    events, role events, remote-run activities) made every round-trip take
    tens of seconds. Terminal conversations that have been idle for over
    ``_ARCHIVE_IDLE_AGE_SECONDS`` are written to
    ``collaboration/archive/<id>.json`` and replaced in the hot document by
    a small index placeholder. Accessing one lazily restores it (see
    ``_conversation_by_id``), so archiving is invisible to callers.
    """
    now = int(time.time() * 1000)
    root = _archive_root()
    conversations = state.get("conversations")
    if not isinstance(conversations, list):
        return
    for index, conversation in enumerate(conversations):
        if not isinstance(conversation, dict):
            continue
        if conversation.get("archived"):
            continue
        # A deletion tombstone is a durable operation, not an idle transcript.
        # Never replace it with an archive placeholder that omits the intent.
        if conversation.get("delete_requested"):
            continue
        if conversation.get(_PENDING_PERSISTENCE_HOOKS):
            # Post-persistence observers are staged on this conversation and
            # must be promoted into the root durable outbox on this save.
            # Archiving now would strand the pending delivery in the archive
            # file where nothing dispatches it.
            continue
        if not _conversation_terminal(conversation):
            continue
        restored_at = int(conversation.get("restored_from_archive_at") or 0)
        if restored_at and now - restored_at < _ARCHIVE_RESTORE_GRACE_SECONDS * 1000:
            continue
        updated_at = int(conversation.get("updated_at") or conversation.get("created_at") or 0)
        if updated_at and now - updated_at < _ARCHIVE_IDLE_AGE_SECONDS * 1000:
            continue
        conversation_id = str(conversation.get("id") or "")
        target = _conversation_archive_path(conversation_id)
        if target is None:
            continue
        try:
            root.mkdir(parents=True, exist_ok=True)
            _atomic_write_json_file(target, conversation)
        except (OSError, UnicodeError, ValueError):
            continue
        message_count, last_message = _conversation_history_summary(conversation)
        placeholder = {
            "id": conversation_id,
            "title": conversation.get("title", ""),
            "owner_id": conversation.get("owner_id", ""),
            "account_generation": conversation.get("account_generation", ""),
            "profile": conversation.get("profile", "default"),
            "source": conversation.get("source", ""),
            "room_id": conversation.get("room_id", ""),
            "created_at": conversation.get("created_at", 0),
            "updated_at": conversation.get("updated_at", 0),
            # Keep an index preview so mobile history can decide that the row
            # is incomplete and fetch detail before lazy restoration.
            "messages": [deepcopy(last_message)] if last_message else [],
            "message_count": message_count,
            "archived": True,
            "archived_at": now,
        }
        conversations[index] = placeholder


def _restore_archived_conversation(
    state: dict[str, Any],
    conversation_id: str,
) -> Optional[dict[str, Any]]:
    placeholder = next(
        (
            item
            for item in state.get("conversations") or []
            if isinstance(item, dict)
            and item.get("id") == conversation_id
            and item.get("archived")
        ),
        None,
    )
    # An archive file without its hot-state placeholder is orphaned.  Do not
    # resurrect it into a newly-created conversation by ID alone.
    if not isinstance(placeholder, dict):
        return None
    target = _conversation_archive_path(conversation_id)
    if target is None:
        return None
    try:
        restored = json.loads(target.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, ValueError):
        return None
    if not isinstance(restored, dict):
        return None
    if str(restored.get("id") or "").strip() != str(conversation_id).strip():
        return None
    for field in ("owner_id", "account_generation"):
        expected = str(placeholder.get(field) or "").strip()
        stored = str(restored.get(field) or "").strip()
        if stored != expected:
            return None
    restored["restored_from_archive_at"] = int(time.time() * 1000)
    restored.pop("archived", None)
    conversations = state.get("conversations")
    if isinstance(conversations, list):
        for index, conversation in enumerate(conversations):
            if (
                isinstance(conversation, dict)
                and conversation.get("id") == conversation_id
            ):
                conversations[index] = restored
                break
        else:
            conversations.append(restored)
    return restored


def _sanitize_history_activities(value: Any) -> list[Any] | Any:
    if not isinstance(value, list):
        return value
    activities = value[-_MAX_REMOTE_ACTIVITIES_PER_RUN:]
    for activity in activities:
        if not isinstance(activity, dict):
            continue
        for field in ("output", "detail", "input", "summary"):
            field_value = activity.get(field)
            if isinstance(field_value, str) and len(field_value) > _MAX_ACTIVITY_FIELD_CHARS:
                activity[field] = field_value[:_MAX_ACTIVITY_FIELD_CHARS]
    return activities


def _sanitize_history_message(message: dict[str, Any]) -> dict[str, Any]:
    """Apply the hot-state field bounds without dropping the message row."""

    for field in ("content", "display_result", "summary"):
        value = message.get(field)
        if isinstance(value, str) and len(value) > _MAX_MESSAGE_CONTENT_CHARS:
            message[field] = value[:_MAX_MESSAGE_CONTENT_CHARS]
    activities = _sanitize_history_activities(message.get("activities"))
    if isinstance(activities, list):
        message["activities"] = activities
    meta = message.get("meta")
    if isinstance(meta, dict):
        for field in ("display_result", "content"):
            value = meta.get(field)
            if isinstance(value, str) and len(value) > _MAX_MESSAGE_CONTENT_CHARS:
                meta[field] = value[:_MAX_MESSAGE_CONTENT_CHARS]
        meta_activities = _sanitize_history_activities(meta.get("activities"))
        if isinstance(meta_activities, list):
            meta["activities"] = meta_activities
    return message


def _trim_hosted_state(state: dict[str, Any]) -> None:
    """Bound the append-only event/turn history so every state round-trip
    (deepcopy + JSON write) stays cheap; a runaway hosted_events list made
    the dashboard burn a core on deepcopy and stalled first-token latency."""
    for conversation in state.get("conversations") or []:
        if not isinstance(conversation, dict):
            continue
        events = conversation.get("hosted_events")
        if isinstance(events, list) and len(events) > _MAX_HOSTED_EVENTS_PER_CONVERSATION:
            conversation["hosted_events"] = events[-_MAX_HOSTED_EVENTS_PER_CONVERSATION:]
        messages = conversation.get("messages")
        if isinstance(messages, list) and len(messages) > _MAX_HOSTED_MESSAGES_PER_CONVERSATION:
            conversation["messages"] = messages[-_MAX_HOSTED_MESSAGES_PER_CONVERSATION:]
        if isinstance(messages, list):
            for message in messages:
                if isinstance(message, dict):
                    _sanitize_history_message(message)
        session_entries = conversation.get("session_entries")
        if (
            isinstance(session_entries, list)
            and len(session_entries) > _MAX_HOSTED_SESSION_ENTRIES_PER_CONVERSATION
        ):
            conversation["session_entries"] = session_entries[
                -_MAX_HOSTED_SESSION_ENTRIES_PER_CONVERSATION:
            ]
        turns = conversation.get("hosted_turns")
        if isinstance(turns, dict) and len(turns) > _MAX_HOSTED_TURNS_PER_CONVERSATION:
            ordered = sorted(
                turns.items(),
                key=lambda item: (
                    (item[1].get("created_at") or 0)
                    if isinstance(item[1], dict)
                    else 0
                ),
            )
            for turn_id, _turn in ordered[: len(turns) - _MAX_HOSTED_TURNS_PER_CONVERSATION]:
                turns.pop(turn_id, None)
        turns = conversation.get("hosted_turns")
        if isinstance(turns, dict):
            for _turn_id, turn in turns.items():
                if not isinstance(turn, dict):
                    continue
                role_events = turn.get("role_events")
                if isinstance(role_events, dict) and len(role_events) > _MAX_ROLE_EVENTS_PER_TURN:
                    ordered_events = sorted(
                        role_events.items(),
                        key=lambda item: (
                            (item[1].get("updated_at") or 0)
                            if isinstance(item[1], dict)
                            else 0
                        ),
                    )
                    for event_id, _event in ordered_events[
                        : len(role_events) - _MAX_ROLE_EVENTS_PER_TURN
                    ]:
                        role_events.pop(event_id, None)
                if isinstance(role_events, dict):
                    for _event_id, event in role_events.items():
                        if not isinstance(event, dict):
                            continue
                        event_activities = event.get("activities")
                        if isinstance(event_activities, list):
                            if len(event_activities) > _MAX_REMOTE_ACTIVITIES_PER_RUN:
                                event_activities = event_activities[
                                    -_MAX_REMOTE_ACTIVITIES_PER_RUN:
                                ]
                                event["activities"] = event_activities
                            for activity in event_activities:
                                if not isinstance(activity, dict):
                                    continue
                                for field in ("output", "detail", "input", "summary"):
                                    value = activity.get(field)
                                    if (
                                        isinstance(value, str)
                                        and len(value) > _MAX_ROLE_EVENT_ACTIVITY_CHARS
                                    ):
                                        activity[field] = value[
                                            :_MAX_ROLE_EVENT_ACTIVITY_CHARS
                                        ]
                        content_value = event.get("content")
                        if (
                            isinstance(content_value, str)
                            and len(content_value) > _MAX_MESSAGE_CONTENT_CHARS
                        ):
                            event["content"] = content_value[:_MAX_MESSAGE_CONTENT_CHARS]
                supervisor_checks = turn.get("supervisor_checks")
                if (
                    isinstance(supervisor_checks, dict)
                    and len(supervisor_checks) > _MAX_SUPERVISOR_CHECKS_PER_TURN
                ):
                    ordered_checks = sorted(supervisor_checks.keys())
                    for check_id in ordered_checks[
                        : len(supervisor_checks) - _MAX_SUPERVISOR_CHECKS_PER_TURN
                    ]:
                        supervisor_checks.pop(check_id, None)
                if isinstance(supervisor_checks, dict):
                    for _check_id, check in supervisor_checks.items():
                        if not isinstance(check, dict):
                            continue
                        for field in ("result", "display_result", "evidence"):
                            value = check.get(field)
                            if (
                                isinstance(value, str)
                                and len(value) > _MAX_SUPERVISOR_EVIDENCE_CHARS
                            ):
                                check[field] = value[:_MAX_SUPERVISOR_EVIDENCE_CHARS]
                        check_activities = check.get("activities")
                        if isinstance(check_activities, list):
                            if len(check_activities) > _MAX_REMOTE_ACTIVITIES_PER_RUN:
                                check_activities = check_activities[
                                    -_MAX_REMOTE_ACTIVITIES_PER_RUN:
                                ]
                                check["activities"] = check_activities
                            for activity in check_activities:
                                if not isinstance(activity, dict):
                                    continue
                                for field in ("output", "detail", "input", "summary"):
                                    value = activity.get(field)
                                    if (
                                        isinstance(value, str)
                                        and len(value) > _MAX_ROLE_EVENT_ACTIVITY_CHARS
                                    ):
                                        activity[field] = value[
                                            :_MAX_ROLE_EVENT_ACTIVITY_CHARS
                                        ]
                remote_runs = turn.get("remote_runs")
                if isinstance(remote_runs, dict):
                    for _stage, run in remote_runs.items():
                        if not isinstance(run, dict):
                            continue
                        activities = run.get("activities")
                        if isinstance(activities, list):
                            if len(activities) > _MAX_REMOTE_ACTIVITIES_PER_RUN:
                                activities = activities[-_MAX_REMOTE_ACTIVITIES_PER_RUN:]
                                run["activities"] = activities
                            for activity in activities:
                                if not isinstance(activity, dict):
                                    continue
                                for field in ("output", "detail", "input", "summary"):
                                    value = activity.get(field)
                                    if (
                                        isinstance(value, str)
                                        and len(value) > _MAX_ACTIVITY_FIELD_CHARS
                                    ):
                                        activity[field] = value[
                                            :_MAX_ACTIVITY_FIELD_CHARS
                                        ]


def save_single_state(state: dict[str, Any], path: Optional[Path] = None) -> None:
    if path is None:
        # Preserve the complete transcript before the compact hot-state
        # projection is archived/truncated for fast request round-trips.
        _persist_conversation_histories(state)
    _archive_completed_conversations(state)
    _trim_hosted_state(state)
    target = path or single_state_path()
    with _backend_api().account_lifecycle_commit_guard():
        with _STATE_LOCK:
            previous_state: Any = _STATE_STORE_PREVIOUS_UNSET
            fast_loaded_state = (
                path is None
                and getattr(_STATE_THREAD_LOCAL, "last_single_state", None) is state
            )
            if not bool(getattr(_COLLABORATION_DELETION_WRITE, "active", False)):
                if fast_loaded_state:
                    # The caller owns the same object returned by the guarded
                    # load above, so no other in-process writer can have
                    # changed the document.  The new state is validated and
                    # written atomically below; reparsing it here only adds a
                    # second JSON parse and normalization pass.
                    _merge_authoritative_account_deletion_intents(
                        state,
                        "conversations",
                    )
                    # A deletion tombstone changes the conflict contract:
                    # this state may be a staged copy from before the
                    # deletion boundary.  Re-read the committed document in
                    # that rare path so a late request cannot append a
                    # tombstoned account back into the store.
                    if _account_deletion_tombstones(state):
                        current = _load_state_store(
                            target,
                            "conversations",
                            dispatch_persistence_hooks=False,
                        )
                        _assert_no_tombstoned_state_mutation(
                            current,
                            state,
                            "conversations",
                        )
                        previous_state = current
                    else:
                        previous_state = None
                else:
                    current = (
                        _load_state_store(target, "conversations")
                        if _state_path_present(target)
                        else {"conversations": []}
                    )
                    _merge_authoritative_account_deletion_intents(
                        state,
                        "conversations",
                    )
                    _assert_no_tombstoned_state_mutation(current, state, "conversations")
                    if _state_path_present(target):
                        previous_state = current
            if path is None:
                # Make lifecycle updates visible to the SSE stream before the
                # large atomic JSON write.  The snapshot is immutable and the
                # subsequent durable commit remains the source of truth for
                # restart/replay.
                live_conversation_ids = _publish_live_conversations(state)
                for conversation_id in live_conversation_ids:
                    _notify_hosted_update(conversation_id)
            _save_state_store(
                target,
                state,
                "conversations",
                previous_state=previous_state,
            )
            if path is None:
                _STATE_THREAD_LOCAL.last_single_state = None


def begin_owner_account_deletion(
    owner_id: str,
    *,
    account_generation: str,
) -> dict[str, Any]:
    """Persist the collaboration write fence without starting heavy cleanup."""

    normalized_owner = str(owner_id or "").strip()
    normalized_generation = str(account_generation or "").strip()
    if not normalized_owner:
        raise ValueError("owner_id is required")
    if not normalized_generation or "\x00" in normalized_generation:
        raise ValueError("account_generation is required")
    now = int(time.time() * 1000)
    with _STATE_LOCK:
        # Do not dispatch the pre-deletion outbox while the deletion intent is
        # still being assembled.  The tombstone and outbox purge must become
        # visible in one guarded state commit before any recovery reader can
        # attempt a callback.
        state = load_single_state(dispatch_persistence_hooks=False)
        _record_account_deletion_intent(
            state,
            normalized_owner,
            normalized_generation,
            deleted_at=now,
        )
        with _collaboration_deletion_write():
            save_single_state(state)
    return {
        "owner_id": normalized_owner,
        "account_generation": normalized_generation,
        "state": "pending",
        "requested_at": now,
    }


def delete_owner_account_data(
    owner_id: str,
    *,
    account_generation: str,
) -> dict[str, Any]:
    """Idempotently remove all collaboration data for an account."""

    normalized_owner = str(owner_id or "").strip()
    normalized_generation = str(account_generation or "").strip()
    if not normalized_owner:
        raise ValueError("owner_id is required")
    if not normalized_generation or "\x00" in normalized_generation:
        raise ValueError("account_generation is required")
    runtime_sessions: list[tuple[str, str]] = []
    conversation_ids: list[str] = []
    now = int(time.time() * 1000)

    begin_owner_account_deletion(
        normalized_owner,
        account_generation=normalized_generation,
    )
    with _STATE_LOCK:
        state = load_single_state()
        owned: list[dict[str, Any]] = []
        for conversation in state.get("conversations") or []:
            if not isinstance(conversation, dict):
                continue
            existing_owner = str(conversation.get("owner_id") or "").strip()
            if existing_owner != normalized_owner and not _legacy_owner_claim_allowed(
                existing_owner,
                normalized_owner,
            ):
                continue
            stored_generation = str(
                conversation.get("account_generation") or ""
            ).strip()
            if stored_generation and stored_generation != normalized_generation:
                continue
            owned.append(conversation)
            conversation_ids.append(str(conversation.get("id") or ""))
            runtime_sessions.extend(
                (str(profile), str(session_id))
                for profile, session_id in (conversation.get("runtime_sessions") or {}).items()
                if str(session_id or "").strip()
            )
            conversation["delete_requested"] = True
            conversation["delete_requested_at"] = now
            for run in (conversation.get("hosted_turns") or {}).values():
                if isinstance(run, dict):
                    run["cancel_requested"] = True
                    run["cancel_requested_at"] = now
        with _collaboration_deletion_write():
            save_single_state(state)

    # Delete external/runtime state before dropping the only persisted list of
    # identifiers. A failure leaves the conversation tombstones for retry.
    for profile, session_id in runtime_sessions:
        if not _delete_runtime_session(profile, session_id):
            raise OSError(
                f"unable to remove runtime session {profile}:{session_id}"
            )
    for conversation_id in conversation_ids:
        if not conversation_id:
            continue
        history_target = _conversation_history_path(conversation_id)
        if history_target is None:
            raise ValueError("invalid conversation id in account deletion")
        root = history_target.parent
        if root.exists():
            shutil.rmtree(root)

    # Archived conversations live outside single.json and therefore are not
    # covered by the conversation file root above.  Read each candidate before
    # unlinking it so an account deletion cannot remove another owner's or
    # another generation's archive.  Known archive rows with unreadable
    # metadata fail closed and leave the account tombstone for a retry.
    known_archive_names = {
        f"{conversation_id}.json"
        for conversation_id in conversation_ids
        if conversation_id
    }
    archive_root = _archive_root()
    if archive_root.exists():
        for archive_target in archive_root.glob("*.json"):
            try:
                document = json.loads(archive_target.read_text(encoding="utf-8"))
            except (OSError, UnicodeError, ValueError) as exc:
                if archive_target.name in known_archive_names:
                    raise OSError(
                        f"unable to validate archived conversation {archive_target.name}"
                    ) from exc
                continue
            if not isinstance(document, dict):
                continue
            if (
                str(document.get("owner_id") or "").strip() != normalized_owner
                or str(document.get("account_generation") or "").strip()
                != normalized_generation
            ):
                continue
            archive_target.unlink()
            if archive_target.exists():
                raise OSError(
                    f"unable to remove archived conversation {archive_target.name}"
                )

    with _STATE_LOCK:
        state = load_single_state()
        for conversation in state.get("conversations") or []:
            if not isinstance(conversation, dict):
                continue
            if (
                str(conversation.get("owner_id") or "").strip() == normalized_owner
                or _legacy_owner_claim_allowed(
                    str(conversation.get("owner_id") or "").strip(),
                    normalized_owner,
                )
            ) and (
                not str(conversation.get("account_generation") or "").strip()
                or str(conversation.get("account_generation") or "").strip()
                    == normalized_generation
            ):
                _record_deletion_tombstone(state, conversation)
        state["conversations"] = [
            conversation
            for conversation in state.get("conversations") or []
            if not (
                isinstance(conversation, dict)
                and (
                    str(conversation.get("owner_id") or "").strip() == normalized_owner
                    or _legacy_owner_claim_allowed(
                        str(conversation.get("owner_id") or "").strip(),
                        normalized_owner,
                    )
                )
                and (
                    not str(conversation.get("account_generation") or "").strip()
                    or str(conversation.get("account_generation") or "").strip()
                    == normalized_generation
                )
            )
        ]
        with _collaboration_deletion_write():
            save_single_state(state)

        room_state = load_state()
        _record_account_deletion_intent(
            room_state,
            normalized_owner,
            normalized_generation,
            deleted_at=now,
        )
        removed_rooms = 0
        kept_rooms: list[dict[str, Any]] = []
        for room in room_state.get("rooms") or []:
            if not isinstance(room, dict):
                continue
            room_owner = str(room.get("owner_id") or "").strip()
            room_generation = str(room.get("account_generation") or "").strip()
            if (
                room_owner == normalized_owner
                or _legacy_owner_claim_allowed(room_owner, normalized_owner)
            ) and (
                not room_generation or room_generation == normalized_generation
            ):
                removed_rooms += 1
                continue
            # The deleted account may still live inside rooms owned by OTHER
            # accounts (joined via invite): scrub its membership, typing
            # presence, and direct mailbox traffic so a same-id re-registration
            # can never resurrect the old era's membership.
            members = [
                member
                for member in (room.get("members") or [])
                if not (
                    isinstance(member, dict)
                    and str(member.get("user_id") or "").strip() == normalized_owner
                )
            ]
            if len(members) != len(room.get("members") or []):
                room["members"] = members
            typing = room.get("typing") if isinstance(room.get("typing"), dict) else {}
            if typing.pop(normalized_owner, None) is not None:
                room["typing"] = typing
            mailbox = room.get("mailbox")
            if isinstance(mailbox, list):
                room["mailbox"] = [
                    item
                    for item in mailbox
                    if not (
                        isinstance(item, dict)
                        and normalized_owner in {
                            str(item.get("sender_id") or "").strip(),
                            str(item.get("recipient_id") or "").strip(),
                        }
                    )
                ]
            kept_rooms.append(room)
        room_state["rooms"] = kept_rooms
        with _collaboration_deletion_write():
            save_state(room_state)

    # Terminate live hosted state for every removed conversation: gateway
    # session leases, and any queued completion pushes. Persisted tombstones
    # already request cancellation; this releases the in-memory footprint so
    # nothing from the deleted era keeps running in the background.
    for conversation_id in conversation_ids:
        if not conversation_id:
            continue
        try:
            release_hosted_gateway_conversation(
                conversation_id,
                owner_id=normalized_owner,
                account_generation=normalized_generation,
            )
        except Exception:
            # Release is best-effort; the persisted deletion tombstone stays
            # authoritative for any straggler discovered by a later retry.
            logger.exception(
                "hosted gateway release failed during account deletion for %s",
                conversation_id,
            )
        _notify_hosted_update(conversation_id)

    return {
        "conversations": len(conversation_ids),
        "rooms": removed_rooms,
        "runtime_sessions": len(runtime_sessions),
        "files": _file_library().delete_owner(
            normalized_owner,
            account_generation=normalized_generation,
        ),
        "tool_output_artifacts": EncryptedToolArtifactStore(
            Path(get_hermes_home())
        ).delete_owner(
            normalized_owner,
            account_generation=normalized_generation,
        ),
        "managed_resources": _backend_api().delete_owner_managed_resources(
            normalized_owner,
            account_generation=normalized_generation,
        ),
    }


def create_room_record(
    name: str,
    profiles: list[str],
    owner_id: str = LOCAL_OWNER_ID,
    account_generation: str = "local-owner-generation",
) -> dict[str, Any]:
    now = int(time.time() * 1000)
    return {
        "id": f"room_{uuid.uuid4().hex[:12]}",
        "name": name.strip() or "新群聊",
        "profiles": list(dict.fromkeys(p.strip() for p in profiles if p.strip())),
        "owner_id": str(owner_id or LOCAL_OWNER_ID).strip() or LOCAL_OWNER_ID,
        "account_generation": str(account_generation or "").strip()
        or "local-owner-generation",
        "messages": [],
        "mailbox": [],
        "dependencies": [],
        "created_at": now,
        "updated_at": now,
    }


def create_single_conversation(
    profile: str,
    title: str = "新对话",
) -> dict[str, Any]:
    now = int(time.time() * 1000)
    return {
        "id": f"chat_{uuid.uuid4().hex[:12]}",
        "title": title.strip() or "新对话",
        "profile": profile.strip() or "default",
        "runtime_sessions": {},
        "runtime_runs": {},
        "hosted_turns": {},
        "hosted_events": [],
        "hosted_event_sequences": {},
        "hosted_event_terminals": {},
        "event_cursor": 0,
        "hosted_event_cursor": 0,
        "hosted_event_min_cursor": 1,
        "session_entries": [],
        "session_entry_cursor": 0,
        "session_entry_leaf_id": "",
        "pending_turn_cancellations": {},
        "messages": [],
        "created_at": now,
        "updated_at": now,
    }


def create_adopted_single_conversation(
    profile: str,
    session_id: str,
    title: str,
    messages: list[dict[str, Any]],
) -> dict[str, Any]:
    conversation = create_single_conversation(profile, title)
    set_conversation_runtime_session(conversation, profile, session_id)
    pending_assistant: list[dict[str, Any]] = []

    def flush_assistant_turn() -> None:
        if not pending_assistant:
            return
        content = next(
            (
                text
                for text in reversed(
                    [_message_content_text(item) for item in pending_assistant]
                )
                if text
            ),
            "",
        )
        activities = build_runtime_activity_timeline(pending_assistant)
        source = next(
            (
                item
                for item in reversed(pending_assistant)
                if str(item.get("role") or "").lower() == "assistant"
            ),
            pending_assistant[-1],
        )
        source_meta = source.get("meta")
        meta = dict(source_meta) if isinstance(source_meta, dict) else {}
        runtime_message_ids = [
            int(item["id"])
            for item in pending_assistant
            if isinstance(item.get("id"), int) or str(item.get("id") or "").isdigit()
        ]
        meta["runtime_session_id"] = session_id
        if runtime_message_ids:
            meta["runtime_message_id"] = max(runtime_message_ids)
        if activities:
            meta["activities"] = activities
        if content or activities:
            message = _append_message(
                conversation,
                role="assistant",
                name=str(source.get("name") or profile).strip() or profile,
                content=content,
                status=str(source.get("status") or "completed"),
                kind="message",
                meta=meta,
            )
            timestamp = source.get("timestamp")
            if isinstance(timestamp, (int, float)) and timestamp > 0:
                message["created_at"] = int(timestamp * 1000)
        pending_assistant.clear()

    for source in messages:
        role = str(source.get("role") or "assistant").strip().lower()
        if role == "user":
            flush_assistant_turn()
            content = _message_content_text(source)
            if not content:
                continue
            message = _append_message(
                conversation,
                role="user",
                name="user",
                content=content,
                status=str(source.get("status") or "completed"),
                kind="message",
                meta={
                    **(
                        source.get("meta")
                        if isinstance(source.get("meta"), dict)
                        else {}
                    ),
                    "runtime_session_id": session_id,
                    **(
                        {"runtime_message_id": int(source["id"])}
                        if isinstance(source.get("id"), int)
                        or str(source.get("id") or "").isdigit()
                        else {}
                    ),
                },
            )
            timestamp = source.get("timestamp")
            if isinstance(timestamp, (int, float)) and timestamp > 0:
                message["created_at"] = int(timestamp * 1000)
        elif role in {"assistant", "tool"}:
            pending_assistant.append(source)
    flush_assistant_turn()
    if conversation["messages"]:
        conversation["updated_at"] = max(
            message["created_at"]
            for message in conversation["messages"]
        )
    return conversation


def set_conversation_runtime_session(
    conversation: dict[str, Any],
    profile: str,
    session_id: str,
) -> dict[str, str]:
    profile_name = profile.strip() or "default"
    runtime_sessions = conversation.get("runtime_sessions")
    if not isinstance(runtime_sessions, dict):
        runtime_sessions = {}
        conversation["runtime_sessions"] = runtime_sessions
    normalized_session_id = session_id.strip()
    if normalized_session_id:
        runtime_sessions[profile_name] = normalized_session_id
    else:
        runtime_sessions.pop(profile_name, None)
    conversation["updated_at"] = int(time.time() * 1000)
    return runtime_sessions


def mark_conversation_runtime_run(
    conversation: dict[str, Any],
    profile: str,
    session_id: str,
    *,
    turn_id: str = "",
    baseline_message_count: int = 0,
    started_at: Optional[int] = None,
) -> dict[str, Any]:
    """Register a gateway-owned turn before its prompt is submitted.

    The record lets the dashboard process recover a completed answer from the
    profile's persistent SessionDB even when iOS has discarded the WebView.
    """
    profile_name = profile.strip() or "default"
    normalized_session_id = session_id.strip()
    set_conversation_runtime_session(
        conversation,
        profile_name,
        normalized_session_id,
    )
    runtime_runs = conversation.get("runtime_runs")
    if not isinstance(runtime_runs, dict):
        runtime_runs = {}
        conversation["runtime_runs"] = runtime_runs
    now = int(time.time() * 1000) if started_at is None else int(started_at)
    runtime_runs[profile_name] = {
        "session_id": normalized_session_id,
        "turn_id": str(turn_id).strip(),
        "status": "running",
        "baseline_message_count": max(0, int(baseline_message_count or 0)),
        "started_at": now,
        "updated_at": now,
    }
    conversation["updated_at"] = now
    return runtime_runs[profile_name]


def _load_runtime_messages(profile: str, session_id: str) -> list[dict[str, Any]]:
    from hermes_state import SessionDB

    db_path = _backend_api().get_profile_dir(profile) / "state.db"
    if not db_path.exists():
        return []
    db = SessionDB(db_path=db_path, read_only=True)
    try:
        resolved = db.resolve_session_id(session_id)
        if not resolved:
            return []
        resolved = db.resolve_resume_session_id(resolved)
        return db.get_messages(resolved)
    finally:
        db.close()


def _runtime_session_boundary(
    profile: str,
    session_id: str,
    *,
    after_message_id: int = 0,
) -> dict[str, Any]:
    """Return exact active-message boundaries from the authoritative SessionDB."""

    from hermes_state import SessionDB

    normalized = str(session_id or "").strip()
    if not normalized:
        return {"session_id": "", "user_message_id": None, "tip_message_id": None}
    db_path = _backend_api().get_profile_dir(profile.strip() or "default") / "state.db"
    if not db_path.exists():
        return {"session_id": "", "user_message_id": None, "tip_message_id": None}
    db = SessionDB(db_path=db_path, read_only=True)
    try:
        resolved = db.resolve_resume_session_id(normalized) or db.resolve_session_id(normalized)
        if not resolved:
            return {"session_id": "", "user_message_id": None, "tip_message_id": None}
        messages = [
            item
            for item in db.get_messages(str(resolved))
            if int(item.get("id") or 0) > max(0, int(after_message_id or 0))
            and _coerce_flag(item.get("active", 1), default=True)
        ]
        user_message = next(
            (
                item
                for item in messages
                if str(item.get("role") or "").strip().lower() == "user"
            ),
            None,
        )
        return {
            "session_id": str(resolved),
            "user_message_id": (
                int(user_message["id"]) if user_message is not None else None
            ),
            "tip_message_id": int(messages[-1]["id"]) if messages else None,
        }
    finally:
        db.close()


def _delete_runtime_session(profile: str, session_id: str) -> bool:
    from hermes_state import SessionDB

    normalized_session_id = session_id.strip()
    if not normalized_session_id:
        # The caller only persists non-empty ids. Treat an empty value as an
        # already-complete cleanup so a malformed legacy row cannot strand a
        # deletion tombstone forever.
        return True
    db_path = _backend_api().get_profile_dir(profile.strip() or "default") / "state.db"
    if not db_path.exists():
        # The profile database may have been removed by an independent
        # account/profile cleanup. There is no runtime state left to delete.
        return True
    db = SessionDB(db_path=db_path)
    try:
        resolved = db.resolve_session_id(normalized_session_id)
        if not resolved:
            # Deletion is idempotent: a previous retry may already have
            # removed the session.
            return True
        return bool(db.delete_session(resolved))
    finally:
        db.close()


def _message_content_text(message: dict[str, Any]) -> str:
    content = message.get("content")
    if isinstance(content, str):
        return content.strip()
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, str):
                parts.append(item)
            elif isinstance(item, dict):
                text = item.get("text")
                if not isinstance(text, str):
                    text = item.get("content")
                if isinstance(text, str):
                    parts.append(text)
        return "\n".join(part.strip() for part in parts if part.strip()).strip()
    if isinstance(content, dict):
        for key in ("text", "content", "output", "result"):
            value = content.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        try:
            return json.dumps(content, ensure_ascii=False, indent=2)
        except (TypeError, ValueError):
            return ""
    return ""


_REDACTED_VALUE = "[REDACTED]"
_SENSITIVE_ACTIVITY_KEYS = {
    "authorization",
    "proxy_authorization",
    "cookie",
    "set_cookie",
    "api_key",
    "apikey",
    "access_token",
    "refresh_token",
    "auth_token",
    "session_token",
    "token",
    "password",
    "passwd",
    "secret",
    "credential",
    "credentials",
    "private_key",
}
_INLINE_BEARER_RE = re.compile(r"(?i)\b(Bearer)\s+[A-Za-z0-9._~+/=-]{8,}")
_INLINE_SECRET_RE = re.compile(
    r"(?i)\b(Authorization|Proxy-Authorization|Cookie|Set-Cookie|"
    r"X-Api-Key|Api-Key|API[_ -]?Key|Access[_ -]?Token|Refresh[_ -]?Token|"
    r"Password|Passwd|Secret|Credential)\b\s*[:=]\s*(\"[^\"]*\"|'[^']*'|[^\s,;]+)"
)
_INLINE_ENV_SECRET_RE = re.compile(
    r"(?i)(?<![A-Za-z0-9_])((?:[A-Za-z][A-Za-z0-9_]*_)?(?:"
    r"API_KEY|APIKEY|ACCESS_TOKEN|REFRESH_TOKEN|AUTH_TOKEN|SESSION_TOKEN|TOKEN|"
    r"PASSWORD|PASSWD|SECRET|CREDENTIAL|CREDENTIALS|PRIVATE_KEY))"
    r"\s*[:=]\s*(\"[^\"]*\"|'[^']*'|[^\s,;]+)"
)


def _sensitive_activity_key(value: Any) -> bool:
    normalized = re.sub(r"[^a-z0-9]+", "_", str(value or "").lower()).strip("_")
    return normalized in _SENSITIVE_ACTIVITY_KEYS or any(
        normalized.endswith(suffix)
        for suffix in (
            "_api_key",
            "_access_token",
            "_refresh_token",
            "_auth_token",
            "_session_token",
            "_password",
            "_passwd",
            "_secret",
            "_credential",
            "_credentials",
            "_private_key",
        )
    )


def _redact_sensitive(value: Any) -> Any:
    if isinstance(value, dict):
        return {
            str(key): (
                _REDACTED_VALUE
                if _sensitive_activity_key(key)
                else _redact_sensitive(item)
            )
            for key, item in value.items()
        }
    if isinstance(value, (list, tuple)):
        return [_redact_sensitive(item) for item in value]
    if not isinstance(value, str):
        return value
    stripped = value.strip()
    if stripped.startswith(("{", "[")) and stripped.endswith(("}", "]")):
        try:
            parsed = json.loads(stripped)
        except (TypeError, ValueError):
            parsed = None
        if isinstance(parsed, (dict, list)):
            return json.dumps(
                _redact_sensitive(parsed),
                ensure_ascii=False,
                separators=(",", ":"),
            )
    redacted = _INLINE_BEARER_RE.sub(r"\1 [REDACTED]", value)
    redacted = _INLINE_SECRET_RE.sub(r"\1: [REDACTED]", redacted)
    return _INLINE_ENV_SECRET_RE.sub(r"\1: [REDACTED]", redacted)


def _structured_text(value: Any) -> str:
    value = _redact_sensitive(value)
    if value is None:
        return ""
    if isinstance(value, str):
        return value.strip()
    if isinstance(value, (dict, list)):
        try:
            return json.dumps(value, ensure_ascii=False, indent=2)
        except (TypeError, ValueError):
            return str(value).strip()
    return str(value).strip()


def sanitize_runtime_error(error: Any) -> str:
    """Return one short user-facing error without HTML, secrets, or retry noise."""
    text = _structured_text(error)
    lowered = text.lower()
    status_match = re.search(r"(?:http\s*)?(4\d\d|5\d\d)", lowered)
    status = status_match.group(1) if status_match else ""
    if status == "401":
        return "模型服务拒绝了 API 密钥（HTTP 401）。"
    if status == "403":
        return "模型服务拒绝访问（HTTP 403），请检查密钥权限。"
    if status == "404":
        return "模型或接口路径不存在（HTTP 404）。"
    if status == "429" or "rate limit" in lowered:
        return "模型服务请求过多（HTTP 429），已保留当前进度。"
    if status in {"500", "502", "503", "504", "520", "522", "524"} or any(
        marker in lowered
        for marker in ("bad gateway", "cloudflare", "origin web server", "upstream")
    ):
        visible_status = status or "502"
        return f"模型服务暂时繁忙（HTTP {visible_status}），已保留当前进度。"
    if status in {"401", "403"} or any(
        marker in lowered
        for marker in ("unauthorized", "invalid api key", "authentication failed")
    ):
        visible_status = status or "401"
        return f"模型认证失败（HTTP {visible_status}），请检查 API 密钥。"
    if any(
        marker in lowered
        for marker in (
            "no model configured",
            "model is not configured",
            "missing model configuration",
            "api key is not configured",
            "missing api key",
            "no api key",
        )
    ):
        return "尚未配置可用模型或模型凭据。"
    if any(
        marker in lowered
        for marker in (
            "timed out",
            "timeout",
            "connection reset",
            "connection aborted",
            "connection refused",
            "network is unreachable",
            "name or service not known",
            "temporary failure in name resolution",
            "nodename nor servname provided",
            "no route to host",
            "offline",
        )
    ):
        return "模型服务连接超时，已保留当前进度。"
    without_html = re.sub(r"<[^>]+>", " ", text)
    without_html = re.sub(r"\s+", " ", without_html).strip()
    return (without_html or "Hermes 执行失败")[:400]


def runtime_error_code(error: Any) -> str:
    text = _structured_text(error).lower()
    status_match = re.search(r"(?:http\s*)?(4\d\d|5\d\d)", text)
    if status_match:
        return f"http_{status_match.group(1)}"
    if "timed out" in text or "timeout" in text:
        return "model_timeout"
    if "empty stream" in text or "empty response" in text:
        return "model_empty_response"
    return "model_request_failed"


def _is_transient_runtime_error(error: Any) -> bool:
    """Classify failures that can recover after model/network reconfiguration."""
    text = _structured_text(error).lower()
    return bool(
        re.search(r"(?:http\s*)?(401|403|429|500|502|503|504|520|522|524)", text)
        or any(
            marker in text
            for marker in (
                "bad gateway",
                "cloudflare",
                "timed out",
                "timeout",
                "connection reset",
                "connection aborted",
                "connection refused",
                "network is unreachable",
                "name or service not known",
                "temporary failure in name resolution",
                "nodename nor servname provided",
                "no route to host",
                "offline",
                "temporarily unavailable",
                "unauthorized",
                "invalid api key",
                "authentication failed",
                "no model configured",
                "model is not configured",
                "missing model configuration",
                "api key is not configured",
                "missing api key",
                "no api key",
            )
        )
    )


def _reasoning_text(message: dict[str, Any]) -> str:
    for key in ("reasoning_content", "reasoning", "thinking"):
        text = _structured_text(message.get(key))
        if text:
            return text
    meta = message.get("meta")
    if isinstance(meta, dict):
        return _structured_text(meta.get("reasoning"))
    return ""


def _reasoning_repeats_final(reasoning: Any, final_content: Any) -> bool:
    reasoning_text = re.sub(r"\s+", " ", _structured_text(reasoning)).strip()
    final_text = re.sub(r"\s+", " ", _structured_text(final_content)).strip()
    if not reasoning_text or not final_text:
        return False
    if reasoning_text == final_text:
        return True
    minimum_prefix = 8
    return (
        len(reasoning_text) >= minimum_prefix
        and final_text.startswith(reasoning_text)
    ) or (
        len(final_text) >= minimum_prefix
        and reasoning_text.startswith(final_text)
    )


def _tool_category(name: str) -> str:
    lowered = name.strip().lower()
    if lowered.startswith("mcp__") or lowered.startswith("mcp_"):
        return "mcp"
    if "skill" in lowered:
        return "skill"
    if any(marker in lowered for marker in ("web_search", "search_web", "browse", "browser")):
        return "web"
    if any(marker in lowered for marker in ("terminal", "shell", "command", "exec", "bash", "powershell")):
        return "command"
    if any(marker in lowered for marker in ("read_file", "write_file", "patch", "filesystem", "glob", "search_files")):
        return "file"
    if any(marker in lowered for marker in ("delegate", "subagent", "spawn_agent")):
        return "subagent"
    return "other"


def _timestamp_ms(message: dict[str, Any]) -> Optional[int]:
    value = message.get("timestamp")
    if not isinstance(value, (int, float)) or value <= 0:
        return None
    return int(value if value > 10_000_000_000 else value * 1000)


def build_runtime_activity_timeline(
    messages: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Rebuild reasoning phases and tool calls from SessionDB messages."""
    activities: list[dict[str, Any]] = []
    tools_by_id: dict[str, dict[str, Any]] = {}
    sequence = 0
    previous_timestamp: Optional[int] = None

    for message in messages:
        role = str(message.get("role") or "").lower()
        message_timestamp = _timestamp_ms(message)
        if role == "assistant":
            reasoning = _reasoning_text(message)
            final_content = _message_content_text(message)
            if reasoning and not _reasoning_repeats_final(reasoning, final_content):
                sequence += 1
                activity = {
                    "id": f"reasoning-{sequence}",
                    "kind": "reasoning",
                    "category": "reasoning",
                    "name": "模型思考",
                    "input": "",
                    "output": reasoning,
                    "status": "completed",
                    "started_at": previous_timestamp,
                    "ended_at": message_timestamp,
                }
                if (
                    previous_timestamp is not None
                    and message_timestamp is not None
                    and message_timestamp >= previous_timestamp
                ):
                    activity["duration_ms"] = message_timestamp - previous_timestamp
                activities.append(activity)
            tool_calls = message.get("tool_calls")
            for call in (tool_calls if isinstance(tool_calls, list) else []):
                if not isinstance(call, dict):
                    continue
                function = call.get("function")
                function = function if isinstance(function, dict) else {}
                sequence += 1
                tool_id = str(call.get("id") or f"tool-{sequence}")
                name = str(function.get("name") or call.get("name") or "tool")
                activity = {
                    "id": tool_id,
                    "kind": "tool",
                    "category": _tool_category(name),
                    "name": name,
                    "input": _structured_text(
                        function.get("arguments", call.get("arguments"))
                    ),
                    "output": "",
                    "status": "running",
                    "started_at": message_timestamp,
                    "ended_at": None,
                }
                activities.append(activity)
                tools_by_id[tool_id] = activity
        elif role == "tool":
            tool_id = str(
                message.get("tool_call_id")
                or message.get("id")
                or ""
            )
            activity = tools_by_id.get(tool_id)
            if activity is None:
                sequence += 1
                name = str(message.get("name") or "tool")
                activity = {
                    "id": tool_id or f"tool-result-{sequence}",
                    "kind": "tool",
                    "category": _tool_category(name),
                    "name": name,
                    "input": "",
                    "output": "",
                    "status": "running",
                    "started_at": None,
                    "ended_at": None,
                }
                activities.append(activity)
            output = _message_content_text(message)
            activity["output"] = output
            execution_envelope = message.get("_tool_execution")
            if isinstance(execution_envelope, dict):
                activity["call_id"] = str(execution_envelope.get("call_id") or tool_id)
                activity["parent_call_id"] = str(execution_envelope.get("parent_call_id") or "")
                presentation_meta = execution_envelope.get("presentation_meta")
                if isinstance(presentation_meta, dict):
                    activity["presentation_meta"] = _redact_sensitive(presentation_meta)
            activity["status"] = (
                "failed"
                if message.get("error") or str(message.get("status") or "").lower() in {"error", "failed"}
                else "completed"
            )
            activity["ended_at"] = message_timestamp
            if activity.get("started_at") and activity.get("ended_at"):
                activity["duration_ms"] = max(
                    0,
                    activity["ended_at"] - activity["started_at"],
                )

        if message_timestamp is not None:
            previous_timestamp = message_timestamp

    return activities


def normalize_stored_conversation_messages(
    messages: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Fold legacy standalone tool rows into their assistant response."""
    normalized: list[dict[str, Any]] = []
    for source in messages:
        if not isinstance(source, dict):
            continue
        role = str(source.get("role") or "assistant").lower()
        if role != "tool":
            message = dict(source)
            content = _message_content_text(message)
            if content or not message.get("content"):
                message["content"] = content
            normalized.append(message)
            continue

        target = next(
            (
                item
                for item in reversed(normalized)
                if str(item.get("role") or "").lower() == "assistant"
            ),
            None,
        )
        if target is None:
            target = {
                "id": f"recovered-tool-{uuid.uuid4().hex[:10]}",
                "role": "assistant",
                "name": str(source.get("name") or "default"),
                "content": "",
                "status": str(source.get("status") or "completed"),
                "kind": "message",
                "created_at": source.get("created_at") or int(time.time() * 1000),
                "meta": {},
            }
            normalized.append(target)
        meta = target.get("meta")
        meta = dict(meta) if isinstance(meta, dict) else {}
        activities = meta.get("activities")
        activities = list(activities) if isinstance(activities, list) else []
        activities.extend(build_runtime_activity_timeline([source]))
        meta["activities"] = activities
        target["meta"] = meta
    return normalized


def _runtime_assistant_turns(
    messages: list[dict[str, Any]],
) -> list[tuple[str, dict[str, Any], list[dict[str, Any]]]]:
    turns: list[tuple[str, dict[str, Any], list[dict[str, Any]]]] = []
    pending: list[dict[str, Any]] = []

    def flush() -> None:
        if not pending:
            return
        assistants = [
            item
            for item in pending
            if str(item.get("role") or "").lower() == "assistant"
        ]
        source = assistants[-1] if assistants else pending[-1]
        content = next(
            (
                text
                for text in reversed(
                    [_message_content_text(item) for item in assistants]
                )
                if text
            ),
            "",
        )
        if content:
            turns.append((content, source, list(pending)))
        pending.clear()

    for message in messages:
        role = str(message.get("role") or "assistant").lower()
        if role == "user":
            flush()
        elif role in {"assistant", "tool"}:
            pending.append(message)
    flush()
    return turns


def reconcile_conversation_mapped_sessions(
    conversation: dict[str, Any],
    *,
    loader: Callable[[str, str], list[dict[str, Any]]] = _load_runtime_messages,
) -> bool:
    """Backfill assistant turns lost by legacy session-level replacement."""
    runtime_sessions = conversation.get("runtime_sessions")
    if not isinstance(runtime_sessions, dict):
        return False
    runtime_runs = conversation.get("runtime_runs")
    runtime_runs = runtime_runs if isinstance(runtime_runs, dict) else {}
    sync_counts = conversation.get("runtime_sync_counts")
    if not isinstance(sync_counts, dict):
        sync_counts = {}
        conversation["runtime_sync_counts"] = sync_counts

    changed = False
    for profile, raw_session_id in runtime_sessions.items():
        session_id = str(raw_session_id or "").strip()
        if not session_id:
            continue
        active_run = runtime_runs.get(profile)
        if (
            isinstance(active_run, dict)
            and active_run.get("status") == "running"
            and active_run.get("session_id") == session_id
        ):
            continue
        try:
            runtime_messages = loader(str(profile), session_id)
        except Exception:
            continue
        sync_key = f"{profile}:{session_id}"
        if sync_counts.get(sync_key) == len(runtime_messages):
            continue

        existing_counts: Counter[str] = Counter()
        for message in conversation.get("messages") or []:
            if str(message.get("role") or "").lower() != "assistant":
                continue
            meta = message.get("meta")
            meta = meta if isinstance(meta, dict) else {}
            belongs_to_session = meta.get("runtime_session_id") == session_id
            belongs_to_profile = (
                not meta.get("runtime_session_id")
                and str(message.get("name") or "") == str(profile)
            )
            content = _message_content_text(message)
            if content and (belongs_to_session or belongs_to_profile):
                existing_counts[content] += 1

        matched_counts: Counter[str] = Counter()
        for ordinal, (content, source, turn_messages) in enumerate(
            _runtime_assistant_turns(runtime_messages),
            start=1,
        ):
            if matched_counts[content] < existing_counts[content]:
                matched_counts[content] += 1
                continue
            recovered = _append_message(
                conversation,
                role="assistant",
                name=str(profile),
                content=content,
                status="completed",
                meta={
                    "runtime_session_id": session_id,
                    "runtime_turn_id": f"recovered:{session_id}:{ordinal}",
                    "runtime_recovered": True,
                    "activities": build_runtime_activity_timeline(turn_messages),
                },
            )
            timestamp = _timestamp_ms(source)
            if timestamp:
                recovered["created_at"] = timestamp
            changed = True

        sync_counts[sync_key] = len(runtime_messages)
        changed = True

    if changed:
        conversation["messages"] = sorted(
            conversation.get("messages") or [],
            key=lambda message: int(message.get("created_at") or 0),
        )
        if conversation["messages"]:
            conversation["updated_at"] = max(
                int(message.get("created_at") or 0)
                for message in conversation["messages"]
            )
    return changed


def reconcile_conversation_runtime_results(
    conversation: dict[str, Any],
    *,
    loader: Callable[[str, str], list[dict[str, Any]]] = _load_runtime_messages,
    now_ms: Optional[int] = None,
) -> bool:
    """Persist completed detached turns back into their original conversation."""
    runtime_runs = conversation.get("runtime_runs")
    if not isinstance(runtime_runs, dict):
        return False
    changed = False
    now = int(time.time() * 1000) if now_ms is None else int(now_ms)
    for profile, run in runtime_runs.items():
        if not isinstance(run, dict) or run.get("status") != "running":
            continue
        run_updated_at = int(run.get("updated_at") or run.get("started_at") or 0)
        stale = run_updated_at <= 0 or now - run_updated_at >= _RUNTIME_RUN_STALE_AFTER_MS
        session_id = str(run.get("session_id") or "").strip()
        if not session_id:
            if stale:
                run.update({
                    "status": "failed",
                    "error": "Runtime result was unavailable after the recovery window",
                    "completed_at": now,
                    "updated_at": now,
                })
                conversation["updated_at"] = now
                changed = True
            continue
        try:
            messages = loader(str(profile), session_id)
        except Exception:
            if stale:
                run.update({
                    "status": "failed",
                    "error": "Runtime session could not be recovered",
                    "completed_at": now,
                    "updated_at": now,
                })
                conversation["updated_at"] = now
                changed = True
            continue
        baseline = max(0, int(run.get("baseline_message_count") or 0))
        candidates = [
            (_message_content_text(message), message)
            for message in messages[baseline:]
            if str(message.get("role") or "").lower() == "assistant"
        ]
        final_text = next(
            (text for text, _message in reversed(candidates) if text),
            "",
        )
        if not final_text:
            if stale:
                run.update({
                    "status": "failed",
                    "error": "Runtime result was unavailable after the recovery window",
                    "completed_at": now,
                    "updated_at": now,
                })
                conversation["updated_at"] = now
                changed = True
            continue
        existing = next(
            (
                message
                for message in conversation.get("messages") or []
                if isinstance(message.get("meta"), dict)
                and (
                    message["meta"].get("runtime_turn_id") == run.get("turn_id")
                    if run.get("turn_id")
                    else message["meta"].get("runtime_session_id") == session_id
                )
            ),
            None,
        )
        if existing is None:
            activities = build_runtime_activity_timeline(messages[baseline:])
            recovered = _append_message(
                conversation,
                role="assistant",
                name=str(profile),
                content=final_text,
                status="completed",
                meta={
                    "runtime_session_id": session_id,
                    "runtime_turn_id": str(run.get("turn_id") or ""),
                    "recovered": True,
                    "activities": activities,
                },
            )
            recovered["created_at"] = now
        run["status"] = "completed"
        run["completed_at"] = now
        run["updated_at"] = now
        conversation["updated_at"] = now
        changed = True
    return changed


def reconcile_stale_hosted_turns(
    conversation: dict[str, Any],
    *,
    now_ms: Optional[int] = None,
) -> bool:
    """Close persisted hosted work that outlived its recovery window."""

    hosted_turns = conversation.get("hosted_turns")
    if not isinstance(hosted_turns, dict):
        return False
    now = int(time.time() * 1000) if now_ms is None else int(now_ms)
    changed = False
    for stored_turn_id, run in hosted_turns.items():
        if not isinstance(run, dict):
            continue
        if str(run.get("status") or "queued") not in {"queued", "running"}:
            continue
        updated_at = int(
            run.get("updated_at") or run.get("started_at") or run.get("created_at") or 0
        )
        if updated_at > 0 and now - updated_at < _HOSTED_TURN_STALE_AFTER_MS:
            continue
        run.update({
            "status": "failed",
            "stage": "failed",
            "error": "Hosted task expired before recovery completed",
            "completed_at": now,
            "updated_at": now,
        })
        run.setdefault("terminal_commit_id", f"terminal_{uuid.uuid4().hex}")
        run.setdefault("terminal_committed_at", now)
        turn_id = str(run.get("turn_id") or stored_turn_id).strip()
        for key in ("role_events", "remote_runs"):
            states = run.get(key)
            if not isinstance(states, dict):
                continue
            for state in states.values():
                if not isinstance(state, dict):
                    continue
                if str(state.get("status") or "") in {
                    "pending", "queued", "running", "starting", "streaming"
                }:
                    state["status"] = "failed"
                    state["completed_at"] = now
                    state["updated_at"] = now
        for message in conversation.get("messages") or []:
            if not isinstance(message, dict):
                continue
            meta = message.get("meta")
            meta = meta if isinstance(meta, dict) else {}
            message_key = str(meta.get("message_key") or "")
            if (
                str(meta.get("runtime_turn_id") or "").strip() != turn_id
                and not message_key.startswith(f"{turn_id}:")
            ):
                continue
            if str(message.get("status") or "") not in {
                "pending", "queued", "running", "starting", "streaming"
            }:
                continue
            message["status"] = "failed"
            message["completed_at"] = now
            message["updated_at"] = now
            meta["phase"] = "failed"
            message["meta"] = meta
            activity_lists = []
            if isinstance(message.get("activities"), list):
                activity_lists.append(message["activities"])
            if isinstance(meta.get("activities"), list):
                activity_lists.append(meta["activities"])
            seen_activity_lists: set[int] = set()
            for activities in activity_lists:
                if id(activities) in seen_activity_lists:
                    continue
                seen_activity_lists.add(id(activities))
                for activity in activities:
                    if not isinstance(activity, dict):
                        continue
                    if str(activity.get("status") or "") in {
                        "pending", "queued", "running", "starting", "streaming"
                    }:
                        activity["status"] = "failed"
                        activity["completed_at"] = now
                        activity["updated_at"] = now
        _append_canonical_turn_terminal(
            conversation,
            conversation_id=str(conversation.get("id") or "conversation"),
            turn_id=turn_id,
            run=run,
            occurred_at=now,
        )
        conversation["updated_at"] = now
        changed = True
    return changed


def reconcile_orphaned_local_role_owners(
    conversation: dict[str, Any],
    *,
    now_ms: Optional[int] = None,
) -> bool:
    """Release process-local role claims after this dashboard process starts.

    Local role owners represent threads and child processes from the previous
    dashboard process. They cannot survive a restart, even when their durable
    lease has time remaining. Remote owners are stable connector run IDs and
    must remain claimed so the new process can reattach to the same queue item.
    """

    hosted_turns = conversation.get("hosted_turns")
    if not isinstance(hosted_turns, dict):
        return False
    now = int(time.time() * 1000) if now_ms is None else int(now_ms)
    changed = False
    for run in hosted_turns.values():
        if not isinstance(run, dict):
            continue
        if str(run.get("status") or "queued") not in {"queued", "running"}:
            continue
        run_changed = False
        active_roles = run.get("active_roles")
        if isinstance(active_roles, dict):
            orphaned_stages = [
                str(stage)
                for stage, active in active_roles.items()
                if isinstance(active, dict)
                and str(
                    active.get("execution")
                    or ("remote" if active.get("remote_run_id") else "local")
                )
                == "local"
            ]
            for stage in orphaned_stages:
                active_roles.pop(stage, None)
                changed = True
                run_changed = True
        for intervention in run.get("interventions") or []:
            if not isinstance(intervention, dict):
                continue
            owner = str(intervention.get("execution_owner") or "")
            if (
                str(intervention.get("status") or "") != "processing"
                or owner.startswith("remote:")
            ):
                continue
            intervention["lease_expires_at"] = 0
            intervention["recovery_released_at"] = now
            intervention["updated_at"] = now
            changed = True
            run_changed = True
        if run_changed:
            run["updated_at"] = now
            conversation["updated_at"] = now
    return changed


def available_profiles() -> list[dict[str, Any]]:
    return [
        {
            "name": profile.name,
            "description": profile.description or "",
            "model": profile.model or "",
            "provider": profile.provider or "",
            "gateway_running": bool(profile.gateway_running),
        }
        for profile in list_profiles()
    ]


_WORKER_TARGETS = ("dbb3", "pc")
_WORKER_TARGET_PROFILES = {
    "dbb3": "dbb3-worker",
    "pc": "pc-worker",
}
_DBB3_MANAGER_PROFILE = "dbb3-manager"
_HERMES_MANAGER_NAME = "Hermes Manager"
_HERMES_MANAGER_LABEL = "Hermes 调度员"
_HERMES_SUPERVISOR_NAME = "Hermes Supervisor"
_HERMES_SUPERVISOR_LABEL = "Hermes 监督者"
_REMOTE_RUN_PROFILES = frozenset(
    {
        _DBB3_MANAGER_PROFILE,
        "dbb3-worker",
        "pc-worker",
        "reviewer",
        "default",
    }
)
_MANAGER_DIFFICULTIES = {"low", "medium", "high", "critical"}
_MANAGER_HANDOFF_FIELDS = (
    "task_goal",
    "plan",
    "worker_results",
    "review_verdict",
    "rework_history",
    "artifacts",
    "failures",
    "suggested_conclusion",
)


def _target_marker_pattern(markers: tuple[str, ...]) -> str:
    patterns: list[str] = []
    for marker in markers:
        if re.fullmatch(r"[a-z0-9 ]+", marker):
            words = r"\s+".join(re.escape(part) for part in marker.split())
            patterns.append(rf"(?<![a-z0-9]){words}(?![a-z0-9])")
        else:
            patterns.append(re.escape(marker))
    return "(?:" + "|".join(patterns) + ")"


def _target_constraints(content: str) -> dict[str, list[str]]:
    """Extract deterministic worker placement constraints from user wording."""
    text = re.sub(r"\s+", " ", str(content or "").strip().lower())
    marker_groups = {
        "dbb3": _DBB3_MARKERS,
        "pc": _PC_MARKERS,
    }
    mentioned: set[str] = set()
    excluded: set[str] = set()
    only: set[str] = set()
    for target, markers in marker_groups.items():
        target_pattern = _target_marker_pattern(markers)
        if re.search(target_pattern, text):
            mentioned.add(target)
        negative_patterns = (
            rf"(?:\bdo\s+not\b|\bdon['’]?t\b|\bdont\b|\bnot\b|\bnever\b|\bwithout\b|"
            rf"\bavoid\b|\bexclude\b)[^\n.!?,;。！？，；]{{0,64}}?{target_pattern}",
            rf"{target_pattern}[^\n.!?,;。！？，；]{{0,40}}?(?:\bmust\s+not\b|\bshould\s+not\b|"
            rf"\bdo\s+not\b|\bdon['’]?t\b|\bexcluded\b|\bdisabled\b)",
            rf"(?:不要|别|不应|无需|不用|不在|排除|避免)(?:在|用|使用|让|安排|运行|执行|部署|派到|交给)?"
            rf"[^,;，。；！？\n]{{0,24}}?{target_pattern}",
            rf"{target_pattern}[^,;，。；！？\n]{{0,20}}?(?:不要|别用|不运行|不执行|排除|禁用)",
        )
        if any(re.search(pattern, text) for pattern in negative_patterns):
            excluded.add(target)
        only_patterns = (
            rf"(?:\bonly\b|\bexclusively\b)[^\n.!?,;。！？，；]{{0,48}}?{target_pattern}",
            rf"{target_pattern}[^\n.!?,;。！？，；]{{0,24}}?(?:\bonly\b|\bexclusively\b)",
            rf"(?:只|仅)(?:在|用|使用|让|安排|运行|执行|部署|交给)?[^,;，。；！？\n]{{0,24}}?{target_pattern}",
            rf"{target_pattern}[^,;，。；！？\n]{{0,12}}?(?:专用|即可|就行)",
        )
        if any(re.search(pattern, text) for pattern in only_patterns):
            only.add(target)

    if only:
        excluded.update(set(_WORKER_TARGETS) - only)
        mentioned.update(only)
    included = mentioned - excluded
    return {
        "included": [target for target in _WORKER_TARGETS if target in included],
        "excluded": [target for target in _WORKER_TARGETS if target in excluded],
        "only": [target for target in _WORKER_TARGETS if target in only],
    }


def _constrained_worker_profiles(
    content: str,
    *,
    profiles: Optional[list[str]] = None,
    targets: Optional[list[str]] = None,
) -> tuple[list[str], dict[str, list[str]]]:
    constraints = _target_constraints(content)
    selected_targets: list[str] = []
    for profile in profiles or []:
        normalized = str(profile).strip().lower()
        if normalized in _WORKER_TARGET_PROFILES.values():
            target = normalized.removesuffix("-worker")
            if target not in selected_targets:
                selected_targets.append(target)
    for target in targets or []:
        normalized = str(target).strip().lower()
        if normalized in _WORKER_TARGETS and normalized not in selected_targets:
            selected_targets.append(normalized)

    excluded = set(constraints["excluded"])
    only = set(constraints["only"])
    if only:
        selected_targets = [target for target in _WORKER_TARGETS if target in only]
    else:
        selected_targets = [target for target in selected_targets if target not in excluded]
        for target in constraints["included"]:
            if target not in selected_targets:
                selected_targets.append(target)
        if not selected_targets and excluded:
            selected_targets = [
                target for target in _WORKER_TARGETS if target not in excluded
            ]
    if not selected_targets and excluded.issuperset(_WORKER_TARGETS):
        return [], constraints
    if not selected_targets:
        selected_targets = ["dbb3"]
    return [
        _WORKER_TARGET_PROFILES[target]
        for target in selected_targets
        if target in _WORKER_TARGET_PROFILES
    ], constraints


def _work_profiles(lowered: str) -> list[str]:
    worker_profiles, _constraints = _constrained_worker_profiles(lowered)
    return ["default", *worker_profiles, "reviewer"]


def _contains_intent_marker(text: str, marker: str) -> bool:
    if re.fullmatch(r"[a-z0-9 ]+", marker):
        words = r"\s+".join(re.escape(part) for part in marker.split())
        return bool(re.search(rf"(?<![a-z0-9]){words}(?![a-z0-9])", text))
    return marker in text


def requires_artifact_delivery(content: str) -> bool:
    """Return true only when the user explicitly asks for a file deliverable."""
    lowered = re.sub(r"\s+", " ", str(content or "").strip().lower())
    for clause in re.split(r"[\n.!?;。！？；]+", lowered):
        has_concrete_artifact = any(
            _contains_intent_marker(clause, marker)
            for marker in (*_DIRECT_ARTIFACT_MARKERS, *_ARTIFACT_NOUN_MARKERS)
        )
        has_ambiguous_report = any(
            _contains_intent_marker(clause, marker)
            for marker in _AMBIGUOUS_ARTIFACT_NOUN_MARKERS
        )
        if not has_concrete_artifact and not has_ambiguous_report:
            continue
        for marker in _ARTIFACT_ACTION_MARKERS:
            if (
                has_ambiguous_report
                and not has_concrete_artifact
                and marker not in _ARTIFACT_TRANSFER_ACTION_MARKERS
            ):
                continue
            pattern = _target_marker_pattern((marker,))
            for match in re.finditer(pattern, clause):
                prefix = clause[max(0, match.start() - 64):match.start()]
                english_negated = re.search(
                    r"(?:\bdo\s+not\b|\bdon['’]?t\b|\bdont\b|\bnever\b|"
                    r"\bwithout\b|\bavoid\b)[^.;。！？；]{0,64}$",
                    prefix,
                )
                chinese_negated = re.search(
                    r"(?:不要|别|无需|不用|避免)[^.;。！？；]{0,40}$",
                    prefix,
                )
                if english_negated is None and chinese_negated is None:
                    return True
    return False


def collaboration_role(profile: str) -> str:
    normalized = str(profile or "").strip().lower()
    if normalized == "supervisor" or "supervis" in normalized or "监督" in normalized:
        return "supervisor"
    if normalized == "reviewer" or "review" in normalized:
        return "reviewer"
    if normalized.endswith("worker") or "worker" in normalized:
        return "worker"
    return "reporter"


def collaboration_execution_order(profiles: list[str]) -> list[str]:
    """Order supervisors, workers, reviewers, then exactly one final reporter."""
    selected = list(dict.fromkeys(str(item).strip() for item in profiles if str(item).strip()))
    if not selected:
        return []
    reporter = next(
        (item for item in selected if collaboration_role(item) == "reporter"),
        selected[0],
    )
    workers = [
        item
        for item in selected
        if item != reporter and collaboration_role(item) == "worker"
    ]
    reviewers = [
        item
        for item in selected
        if item != reporter and collaboration_role(item) == "reviewer"
    ]
    supervisors = [
        item
        for item in selected
        if item != reporter and collaboration_role(item) == "supervisor"
    ]
    return [*supervisors, *workers, *reviewers, reporter]


# Execution node per hosted member Profile; the parity contract exposes it so
# native clients can label where each team member actually runs.
_HOSTED_MEMBER_NODES = {
    _DBB3_MANAGER_PROFILE: "dbb3",
    "dbb3-worker": "dbb3",
    "pc-worker": "wsl",
    "reviewer": "dbb3",
    "supervisor": "dbb3",
    "default": "main",
}
_HOSTED_MEMBER_DISPLAY_NAMES = {
    _DBB3_MANAGER_PROFILE: _HERMES_MANAGER_LABEL,
    "dbb3-worker": "DBB3 执行员",
    "pc-worker": "PC/WSL 执行员",
    "reviewer": "Hermes 审阅员",
    "supervisor": _HERMES_SUPERVISOR_LABEL,
    "default": "Hermes 汇报员",
}


def hosted_member_role(profile: str, role_stage: str = "") -> str:
    """Roster role of one hosted member: manager/worker/reviewer/reporter/supervisor."""

    normalized = str(profile or "").strip().lower()
    if normalized in {_DBB3_MANAGER_PROFILE, "dispatcher", "manager"}:
        return "manager"
    base_stage = str(role_stage or "").strip().lower().split(":", 1)[0].split(".", 1)[0]
    if base_stage.startswith("manager") or base_stage in {"dispatch", "workflow"}:
        return "manager"
    if base_stage in {"worker", "reviewer", "supervisor", "reporter"}:
        return base_stage
    return collaboration_role(normalized)


def hosted_member_id(profile: str, role_stage: str = "") -> str:
    """Canonical member id; every manager/dispatcher alias collapses to dbb3-manager."""

    if hosted_member_role(profile, role_stage) == "manager":
        return _DBB3_MANAGER_PROFILE
    return str(profile or "").strip() or "default"


def hosted_participant_descriptor(
    profile: str,
    *,
    role_stage: str = "",
    node: str = "",
) -> dict[str, Any]:
    """Stable identity card one team member contributes to the group-chat roster."""

    member_id = hosted_member_id(profile, role_stage)
    return {
        "id": member_id,
        "role": hosted_member_role(member_id, role_stage),
        "display_name": _HOSTED_MEMBER_DISPLAY_NAMES.get(member_id, member_id),
        "node": str(node or "").strip() or _HOSTED_MEMBER_NODES.get(member_id, "main"),
        "avatar_seed": f"hermes-member-{member_id}",
    }


def _merge_hosted_participants(run: dict[str, Any], members: Any) -> bool:
    """Append newly dispatched members; identity fields stay write-once."""

    participants = run.get("participants")
    if not isinstance(participants, list):
        participants = []
        run["participants"] = participants
    by_id = {
        str(item.get("id") or ""): item
        for item in participants
        if isinstance(item, dict)
    }
    changed = False
    now = int(time.time() * 1000)
    for member in members if isinstance(members, list) else []:
        if not isinstance(member, dict):
            continue
        member_id = str(member.get("id") or "").strip()
        if not member_id:
            continue
        existing = by_id.get(member_id)
        if existing is None:
            entry = {**member, "joined_at": int(member.get("joined_at") or now)}
            participants.append(entry)
            by_id[member_id] = entry
            changed = True
            continue
        for key, value in member.items():
            if key == "joined_at" or value in (None, ""):
                continue
            if not existing.get(key):
                existing[key] = value
                changed = True
    return changed


def _conversation_participants(conversation: dict[str, Any]) -> list[dict[str, Any]]:
    """Union of hosted team members across turns; the first identity wins."""

    merged: dict[str, dict[str, Any]] = {}
    for run in (conversation.get("hosted_turns") or {}).values():
        if not isinstance(run, dict):
            continue
        for member in run.get("participants") or []:
            if not isinstance(member, dict):
                continue
            member_id = str(member.get("id") or "")
            if member_id and member_id not in merged:
                merged[member_id] = dict(member)
    return list(merged.values())


def hosted_progress_protocol(role_name: str) -> str:
    """Static user-visible progress contract shared by every hosted role."""

    return "\n".join(
        (
            f"【{role_name} 过程回报协议】",
            "收到任务、上游交接、用户干预、附件或工具返回后，先在内部核对目标、边界、完成标准、已知事实、证据缺口和下一项可验证动作；不得只回复“收到”“正在处理”或复述任务。",
            "首次实质执行前，先发一条不超过两句的定向更新：第一句概括你对本角色任务和当前证据的理解，第二句说明马上要验证或完成什么；不得把计划、假设或预计结果写成已经完成。",
            "后续回报采用“信息增量事件 + 静默时长”双触发，不限于大里程碑。以下任一变化都应在下一个安全边界更新：得到会改变结论或计划的新证据；作出有取舍的决定；进入新阶段或发生交接；风险、权限或依赖发生变化；出现新的错误类别、重试策略、阻断或返工；完成一项验收；生成、修改或验证用户交付物。",
            "若一组连续操作服务于同一个小目标，先连续完成这组操作，再用一次更新合并说明证据和结论；只有工具名称、命令次数、百分比或“仍在运行”发生变化，不算信息增量。",
            "若同一阶段持续较久且没有上述事件，提供低频心跳：说明已经验证到哪里、当前在处理什么、还缺什么。预计少于五分钟的短步骤不单独心跳；长任务从上次可见更新起五到十五分钟内至少更新一次，阻断或需要用户决定时立即更新。",
            "每次更新优先控制在两句，复杂阻断最多三句；至少包含一项已验证事实和一项当前动作、下一步或影响。失败时给出最后一次有代表性的错误、已尝试的策略及剩余影响，不逐次堆叠相同错误。",
            "不要逐条广播每次思考、每个工具调用、重复读取、普通重试或微小步骤；连续重试只在错误类别、处置策略、是否需要外部输入或最终结果改变时更新。不得为了满足频率虚构进度，也不得用过程回报代替实际执行。",
            "内部推理、工具参数、命令和原始输出进入可折叠活动明细；正文只给用户可验证的工程结论、决策理由和必要风险，不披露隐藏思维链。",
            "进入角色交接前再发一条两句左右的收束更新：已完成/未完成、关键证据或产物、风险，以及接收角色下一步必须核验的事项；交接数据与用户可见更新必须一致。",
            "Hermes 原有的工具选择、Skill/MCP 使用、超时和失败恢复策略保持不变；本协议只约束可见过程回报的时机、密度、真实性和交接质量。",
        )
    )


def hosted_role_delivery_contract(role_name: str) -> str:
    """Evidence and handoff contract specialized for one hosted role."""

    normalized = str(role_name or "").strip().lower()
    if "manager" in normalized or "调度" in normalized or "dispatcher" in normalized:
        rules = (
            "调度员的更新必须说明任务边界、拆分或路由发生了什么变化，以及每个子任务的负责人、依赖和可验证验收标准；不能只说“已经派发”。",
            "派发前检查目标是否完整覆盖、步骤是否可并行、产物归属是否唯一；返工时明确退回哪一项、依据什么证据、由谁修正。",
            "结构化交接必须保留原始目标、计划版本、Worker 证据、审阅结论、返工记录、产物路径与哈希、失败和未完成项，不得把推测补成事实。",
        )
    elif "review" in normalized or "审阅" in normalized:
        rules = (
            "审阅员的更新必须指明正在核对的验收标准、采用的独立证据以及当前 PASS/REWORK 倾向；不能只复述 Worker 的结论。",
            "发现缺陷时说明复现条件、影响、严重度和最小整改要求；退回必须可执行，复审必须逐项对应上轮意见。",
            "没有证据覆盖的场景标为未验证，不得因主路径通过而推断异常、并发、离线、恢复或权限场景也通过。",
        )
    elif "report" in normalized or "汇报" in normalized:
        rules = (
            "汇报员只消费已经持久化并经审阅的结构化交接，不重新执行任务、不调用工具补洞，也不依据常识补写缺失结果。",
            "最终答案按已完成、失败、未完成/待决定、关键证据与产物组织；只有具备来源、执行结果和审阅结论的事项才能写成完成。",
            "交接相互矛盾或证据不足时保留冲突并明确标注，不得选择更乐观的版本；面向用户的结论必须可追溯到交接字段。",
        )
    elif "supervis" in normalized or "监督" in normalized:
        rules = (
            "监督者在计划形成、首次派发、每次角色交接、返工、阻断和最终汇报前进行检查；连续执行期间按新进展抽查，不等待任务结束才监督。",
            "监督更新只报告发现、证据、整改对象和复核结果；没有新增问题时不重复发“监督正常”，但不得因此停止检查。",
            "监督者不得替代调度、执行、审阅或汇报；其产物是可验证的纠偏指令和对整改是否落实的复核记录。",
        )
    else:
        rules = (
            "Worker 的更新必须把实际动作与证据绑定：说明验证了什么、观察到什么、这对任务结论有何影响，以及下一组操作是什么。",
            "修改、部署或生成产物后必须给出可复核位置、版本/哈希或测试结果；失败不得包装为完成，尚未运行的测试必须标为未验证。",
            "交接审阅员时提交完成项、命令/测试证据摘要、产物、异常路径、残余风险和明确未完成项，不替审阅员宣布通过。",
        )
    return "\n".join((f"【{role_name} 角色交付契约】", *rules))


def mention_priority_protocol(role_name: str) -> str:
    """Return the mandatory targeted-intervention semantics for one role."""

    return "\n".join(
        (
            f"【{role_name} @ 干预协议】",
            f"当用户、监督者或其他成员使用 @{role_name}（含等价角色名）定向发言时，该内容是高优先级控制消息。",
            "除不可中断的原子操作外，立即暂停新工具调用；在当前不可中断操作结束后的第一个安全边界，先直接回复该 @ 消息，并说明接受、拒绝或需要澄清的原因及其对计划的影响。",
            "回应后把有效要求、优先级和受影响步骤写入持久计划，再恢复执行；不得忽略、延迟到最终汇报、继续排队旧工具，或由未被 @ 的成员代答。",
            "若 @ 指令与用户原始目标、权限或已验证事实冲突，明确指出冲突并等待可执行决策，不得静默改变任务边界。",
        )
    )


def supervisor_role_prompt() -> str:
    """Define the independent supervisor's duties and bounded authority."""

    return "\n".join(
        (
            "【Hermes 监督者职责与权限】",
            "群聊拉起即开始监督，持续检查调度员、Worker、审阅员和汇报员；在计划形成、派发、角色交接、返工、阻断和最终汇报前必须检查，连续执行期间根据新增证据抽查。监督者不替任何成员执行其主体工作，也不直接生成最终答案。",
            "检查调度员是否完整理解目标和边界、合理拆分、明确依赖与验收标准、选择合适节点并处理遗漏。",
            "检查 Worker 是否真实执行、保留证据、遵守范围、没有偏离目标或用进度话术替代工作。",
            "检查审阅员是否独立复核、覆盖异常/并发/离线等必要场景、给出可复现证据，并对不合格结果明确退回。",
            "检查汇报员是否只基于已验证交接，准确区分完成、失败、未完成和风险，不遗漏返工记录、产物及哈希。",
            "发现偏离、偷懒、遗漏或证据不足时，立即用“@准确成员名：已观察到的事实；违反的职责边界；必须整改的动作；完成时需提交的验收证据”发出定向整改，并在后续安全边界复核是否落实。",
            "同时监督过程回报是否存在长时间沉默、无信息增量刷屏、只报计划不报证据或失败后不说明影响；违反时必须 @对应成员要求按过程回报协议整改。",
            "监督结论必须可验证；没有问题时简短写明检查范围和通过依据，不制造无意义返工。",
            hosted_role_delivery_contract(_HERMES_SUPERVISOR_LABEL),
        )
    )


_MENTION_TARGET_ALIASES = {
    "dispatcher": (
        "Hermes 调度员",
        "调度员",
        "Hermes Manager",
        "Manager",
    ),
    "worker": (
        "Hermes Worker",
        "Worker",
        "DBB3 执行员",
        "PC/WSL 执行员",
        "dbb3-worker",
        "pc-worker",
    ),
    "reviewer": (
        "Hermes 审阅员",
        "审阅员",
        "Hermes Reviewer",
        "Reviewer",
    ),
    "reporter": (
        "Hermes 汇报员",
        "汇报员",
        "Hermes Reporter",
        "Reporter",
    ),
    "supervisor": (
        "Hermes 监督者",
        "监督者",
        "Hermes Supervisor",
        "Supervisor",
    ),
}


def mentioned_collaboration_roles(content: str) -> list[str]:
    """Resolve explicit @ role mentions without treating ordinary prose as control."""

    normalized = re.sub(r"\s+", " ", str(content or "")).strip().lower()
    found: list[str] = []
    for role, aliases in _MENTION_TARGET_ALIASES.items():
        if any(f"@{alias.lower()}" in normalized for alias in aliases):
            found.append(role)
    return found


def hosted_intervention_context(
    conversation_id: str,
    turn_id: str,
    *,
    role_stage: str,
) -> str:
    """Return durable control messages relevant to the next role boundary."""

    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        interventions = (
            run.get("interventions")
            if isinstance(run, dict) and isinstance(run.get("interventions"), list)
            else []
        )
        snapshot = [dict(item) for item in interventions if isinstance(item, dict)]
    if not snapshot:
        return ""
    base_role = str(role_stage or "").split(":", 1)[0]
    lines = [
        "【任务进行中的持久化 @ 干预】",
        "以下控制消息属于当前托管任务。pending/processing 且被点名的成员必须按 @ 干预协议优先回应；completed 只用于核对落实情况，不得重复回复。",
    ]
    for item in snapshot[-50:]:
        targets = [str(value) for value in item.get("targets") or [] if str(value)]
        target_note = "、".join(targets) or "未识别"
        intervention_status = str(item.get("status") or "pending")
        relevance = (
            "当前角色被点名"
            if base_role in targets and intervention_status in _INTERVENTION_ACTIVE_STATUSES
            else "已处理，供复核"
            if intervention_status == "completed"
            else "供流程监督核对"
        )
        lines.append(
            f"- [{relevance}; status={intervention_status}; targets={target_note}] "
            f"{str(item.get('content') or '').strip()}"
        )
    return "\n".join(lines)


_INTERVENTION_ACTIVE_STATUSES = {"pending", "processing"}


def _hosted_stage_target_role(role_stage: str, profile: str = "") -> str:
    """Map a concrete hosted phase to the member name used by @ controls."""

    normalized = str(role_stage or "").strip().lower()
    base = normalized.split(":", 1)[0]
    if base == "worker":
        return "worker"
    if base == "reviewer":
        return "reviewer"
    if base == "reporter" or normalized.startswith("report"):
        return "reporter"
    if base == "supervisor" or normalized.startswith("supervis"):
        return "supervisor"
    if base == "dispatcher" or normalized.startswith(("dispatch", "manager")):
        return "dispatcher"
    return collaboration_role(profile)


def _mentioned_collaboration_profiles(content: str) -> list[str]:
    """Preserve exact worker targeting when the user names a concrete lane."""

    normalized = re.sub(r"\s+", " ", str(content or "")).strip().lower()
    aliases = {
        "dbb3-worker": ("dbb3-worker", "dbb3 执行员"),
        "pc-worker": ("pc-worker", "pc/wsl 执行员", "pc 执行员", "wsl 执行员"),
    }
    return [
        profile
        for profile, names in aliases.items()
        if any(f"@{name}" in normalized for name in names)
    ]


def _intervention_matches_role(
    intervention: dict[str, Any],
    *,
    role_stage: str,
    profile: str,
) -> bool:
    target_role = _hosted_stage_target_role(role_stage, profile)
    targets = {str(item) for item in intervention.get("targets") or [] if str(item)}
    if target_role not in targets:
        return False
    target_profiles = {
        str(item) for item in intervention.get("target_profiles") or [] if str(item)
    }
    role_profiles = {
        item for item in target_profiles if collaboration_role(item) == target_role
    }
    return not role_profiles or str(profile or "") in role_profiles


def _intervention_delivery_key(
    intervention: dict[str, Any],
    *,
    role_stage: str,
    profile: str,
) -> str:
    target_profiles = {
        str(item) for item in intervention.get("target_profiles") or [] if str(item)
    }
    if str(profile or "") in target_profiles:
        return f"profile:{profile}"
    return f"role:{_hosted_stage_target_role(role_stage, profile)}"


def _intervention_expected_delivery_keys(
    intervention: dict[str, Any],
) -> set[str]:
    targets = {str(item) for item in intervention.get("targets") or [] if str(item)}
    target_profiles = {
        str(item) for item in intervention.get("target_profiles") or [] if str(item)
    }
    keys = {f"profile:{profile}" for profile in target_profiles}
    covered_roles = {collaboration_role(profile) for profile in target_profiles}
    keys.update(f"role:{role}" for role in targets if role not in covered_roles)
    return keys


def _intervention_delivery_claim(
    intervention: dict[str, Any],
    *,
    role_stage: str,
    profile: str,
) -> tuple[str, dict[str, Any]]:
    key = _intervention_delivery_key(
        intervention,
        role_stage=role_stage,
        profile=profile,
    )
    claims = intervention.get("delivery_claims")
    if not isinstance(claims, dict):
        claims = {}
        intervention["delivery_claims"] = claims
    claim = claims.get(key)
    if not isinstance(claim, dict):
        claim = {"status": "pending"}
        claims[key] = claim
    return key, claim


def _hosted_role_checkpoint(
    *,
    role_stage: str,
    profile: str,
    execution: str,
    role_state: Optional[dict[str, Any]] = None,
    remote_run: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    """Create the bounded durable checkpoint carried into a resumed role."""

    source = remote_run if isinstance(remote_run, dict) else role_state or {}
    checkpoint = {
        "role_stage": str(role_stage or ""),
        "profile": str(profile or ""),
        "execution": str(execution or "local"),
        "status": str(source.get("status") or "running"),
        "content": str(
            source.get("result") or source.get("summary") or source.get("content") or ""
        )[-12000:],
        "activities": [
            _redact_sensitive(dict(item))
            for item in (source.get("activities") or [])[-50:]
            if isinstance(item, dict)
        ],
        "runtime_session_id": str(
            source.get("runtime_session_id") or source.get("session_id") or ""
        )[:512],
        "checkpoint_cursor": int(source.get("checkpoint_cursor") or 0),
        "captured_at": int(time.time() * 1000),
    }
    remote_run_id = str(source.get("id") or source.get("remote_run_id") or "")
    if remote_run_id:
        checkpoint["remote_run_id"] = remote_run_id[:512]
    return checkpoint


def _activate_hosted_role(
    conversation_id: str,
    turn_id: str,
    *,
    role_stage: str,
    profile: str,
    execution: str,
    remote_run_id: str = "",
    execution_owner: str = "",
    lease_ms: int = 120_000,
) -> bool:
    """Publish the currently interruptible local/remote role lane."""

    now = int(time.time() * 1000)
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict) or run.get("status") in _HOSTED_TERMINAL_STATUSES:
            return False
        active_roles = run.get("active_roles")
        if not isinstance(active_roles, dict):
            active_roles = {}
            run["active_roles"] = active_roles
        previous = active_roles.get(role_stage)
        owner = str(execution_owner or remote_run_id or uuid.uuid4().hex)
        if (
            isinstance(previous, dict)
            and str(previous.get("status") or "running") == "running"
            and int(previous.get("lease_expires_at") or 0) > now
            and str(previous.get("execution_owner") or "") != owner
        ):
            return False
        active_roles[role_stage] = {
            "role_stage": role_stage,
            "target_role": _hosted_stage_target_role(role_stage, profile),
            "profile": profile,
            "execution": execution,
            "remote_run_id": str(remote_run_id or ""),
            "status": "running",
            "execution_owner": owner,
            "lease_expires_at": now + max(1_000, int(lease_ms)),
            "started_at": int(previous.get("started_at") or now)
            if isinstance(previous, dict)
            else now,
            "updated_at": now,
        }
        run["updated_at"] = now
        conversation["updated_at"] = now
        save_single_state(state)
    _notify_hosted_update(conversation_id)
    return True


def _clear_hosted_active_role(
    conversation_id: str,
    turn_id: str,
    *,
    role_stage: str,
    remote_run_id: str = "",
    execution_owner: str = "",
) -> None:
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        active_roles = run.get("active_roles") if isinstance(run, dict) else None
        current = active_roles.get(role_stage) if isinstance(active_roles, dict) else None
        if not isinstance(current, dict):
            return
        expected_remote_id = str(remote_run_id or "")
        if expected_remote_id and str(current.get("remote_run_id") or "") != expected_remote_id:
            return
        expected_owner = str(execution_owner or "")
        if expected_owner and str(current.get("execution_owner") or "") != expected_owner:
            return
        active_roles.pop(role_stage, None)
        now = int(time.time() * 1000)
        run["updated_at"] = now
        conversation["updated_at"] = now
        save_single_state(state)
    _notify_hosted_update(conversation_id)


def _renew_hosted_active_role(
    conversation_id: str,
    turn_id: str,
    *,
    role_stage: str,
    execution_owner: str,
    lease_ms: int = 120_000,
) -> bool:
    """CAS-renew one role lane only while this coordinator still owns it."""

    now = int(time.time() * 1000)
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict) or run.get("status") in _HOSTED_TERMINAL_STATUSES:
            return False
        active_roles = run.get("active_roles")
        current = active_roles.get(role_stage) if isinstance(active_roles, dict) else None
        if (
            not isinstance(current, dict)
            or str(current.get("status") or "running") != "running"
            or str(current.get("execution_owner") or "") != execution_owner
        ):
            return False
        current["lease_expires_at"] = now + max(1_000, int(lease_ms))
        current["updated_at"] = now
        run["updated_at"] = now
        conversation["updated_at"] = now
        save_single_state(state)
    return True


def _pending_hosted_role_intervention(
    conversation_id: str,
    turn_id: str,
    *,
    role_stage: str,
    profile: str,
    include_processing: bool = False,
    deliveries: Optional[set[str]] = None,
) -> Optional[dict[str, Any]]:
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            return None
        for item in run.get("interventions") or []:
            if not isinstance(item, dict) or not _intervention_matches_role(
                item,
                role_stage=role_stage,
                profile=profile,
            ):
                continue
            if deliveries is not None and str(
                item.get("delivery") or "steer"
            ) not in deliveries:
                continue
            if str(item.get("queue_mode") or "one_at_a_time") == "all_at_once":
                delivery_key, claim = _intervention_delivery_claim(
                    item,
                    role_stage=role_stage,
                    profile=profile,
                )
                status = str(claim.get("status") or "pending")
                if status == "pending" or (include_processing and status == "processing"):
                    return {**dict(item), **dict(claim), "delivery_key": delivery_key}
                continue
            status = str(item.get("status") or "pending")
            if status == "pending" or (
                include_processing
                and status == "processing"
                and str(item.get("active_role_stage") or "") == role_stage
                and str(item.get("active_profile") or "") == profile
            ):
                return dict(item)
        return None


def _hosted_intervention_by_id(
    conversation_id: str,
    turn_id: str,
    intervention_id: str,
) -> Optional[dict[str, Any]]:
    wanted = str(intervention_id or "")
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            return None
        return next(
            (
                dict(item)
                for item in run.get("interventions") or []
                if isinstance(item, dict) and str(item.get("id") or "") == wanted
            ),
            None,
        )


def _claim_hosted_role_intervention(
    conversation_id: str,
    turn_id: str,
    *,
    role_stage: str,
    profile: str,
    checkpoint: dict[str, Any],
    intervention_id: str = "",
    execution_owner: str = "",
    lease_ms: int = 120_000,
    deliveries: Optional[set[str]] = None,
) -> Optional[dict[str, Any]]:
    """Atomically move one matching @ control from pending to processing."""

    wanted = str(intervention_id or "")
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            return None
        intervention = next(
            (
                item
                for item in run.get("interventions") or []
                if isinstance(item, dict)
                and (not wanted or str(item.get("id") or "") == wanted)
                and str(item.get("status") or "pending") in {
                    "pending",
                    "processing",
                }
                and _intervention_matches_role(
                    item,
                    role_stage=role_stage,
                    profile=profile,
                )
                and (
                    deliveries is None
                    or str(item.get("delivery") or "steer") in deliveries
                )
            ),
            None,
        )
        if not isinstance(intervention, dict):
            return None
        now = int(time.time() * 1000)
        owner = str(execution_owner or "")
        if not owner:
            return None
        all_at_once = str(
            intervention.get("queue_mode") or "one_at_a_time"
        ) == "all_at_once"
        delivery_key = ""
        claim_state = intervention
        if all_at_once:
            delivery_key, claim_state = _intervention_delivery_claim(
                intervention,
                role_stage=role_stage,
                profile=profile,
            )
        current_status = str(claim_state.get("status") or "pending")
        if current_status == "completed":
            return None
        current_owner = str(claim_state.get("execution_owner") or "")
        lease_expires_at = int(claim_state.get("lease_expires_at") or 0)
        if current_status == "processing":
            if current_owner == owner and lease_expires_at > now:
                claim_state["lease_expires_at"] = now + max(1_000, int(lease_ms))
                intervention["updated_at"] = now
                save_single_state(state)
                return {
                    **dict(intervention),
                    **dict(claim_state),
                    **({"delivery_key": delivery_key} if delivery_key else {}),
                }
            if lease_expires_at > now:
                return None
        claim_token = uuid.uuid4().hex
        persisted_checkpoint = claim_state.get("checkpoint")
        claim_state.update(
            {
                "status": "processing",
                "claim_token": claim_token,
                "execution_owner": owner,
                "lease_expires_at": now + max(1_000, int(lease_ms)),
                "claimed_at": now,
                "active_role_stage": role_stage,
                "active_profile": profile,
                "checkpoint": (
                    dict(persisted_checkpoint)
                    if current_status == "processing"
                    and isinstance(persisted_checkpoint, dict)
                    else _redact_sensitive(dict(checkpoint))
                ),
                "updated_at": now,
            }
        )
        if current_status == "processing":
            claim_state["reclaimed_at"] = now
        if all_at_once:
            intervention["status"] = "processing"
            intervention["updated_at"] = now
        run["updated_at"] = now
        conversation["updated_at"] = now
        append_hosted_event(
            conversation,
            conversation_id=conversation_id,
            turn_id=turn_id,
            role_stage=role_stage,
            event_type="intervention.claimed",
            entity_id=str(intervention.get("id") or ""),
            idempotency_key=(
                f"intervention:{intervention.get('id')}:claimed:{claim_token}"
            ),
            account_generation=_account_generation_for_owner(
                str(conversation.get("owner_id") or LOCAL_OWNER_ID)
            ),
            payload={
                "entity_id": str(intervention.get("id") or ""),
                "delivery": str(intervention.get("delivery") or "steer"),
                "queue_mode": str(
                    intervention.get("queue_mode") or "one_at_a_time"
                ),
                "profile": profile,
                "role_stage": role_stage,
                "delivery_key": delivery_key,
            },
            occurred_at=now,
        )
        save_single_state(state)
        claimed = {
            **dict(intervention),
            **dict(claim_state),
            **({"delivery_key": delivery_key} if delivery_key else {}),
        }
    _notify_hosted_update(conversation_id)
    return claimed


def _complete_hosted_role_intervention(
    conversation_id: str,
    turn_id: str,
    *,
    intervention_id: str,
    claim_token: str,
    execution_owner: str,
    role_stage: str,
    role_label: str,
    profile: str,
    reply: str,
    checkpoint: dict[str, Any],
    resume_role_stage: str = "",
) -> dict[str, Any]:
    """Persist the targeted member's reply before the original role resumes."""

    clean_reply = str(reply or "").strip() or "已收到定向干预，已在检查点暂停并更新执行计划。"
    now = int(time.time() * 1000)
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            raise RuntimeError("托管任务记录不存在")
        intervention = next(
            (
                item
                for item in run.get("interventions") or []
                if isinstance(item, dict)
                and str(item.get("id") or "") == str(intervention_id or "")
            ),
            None,
        )
        if not isinstance(intervention, dict):
            raise RuntimeError("托管干预记录不存在")
        if str(run.get("status") or "") in _HOSTED_TERMINAL_STATUSES or _coerce_flag(
            run.get("cancel_requested")
        ):
            raise RuntimeError("托管任务已结束，拒绝迟到的干预回复")
        all_at_once = str(
            intervention.get("queue_mode") or "one_at_a_time"
        ) == "all_at_once"
        delivery_key = ""
        claim_state = intervention
        if all_at_once:
            delivery_key, claim_state = _intervention_delivery_claim(
                intervention,
                role_stage=role_stage,
                profile=profile,
            )
        if str(claim_state.get("status") or "") != "processing":
            raise RuntimeError("托管干预不在可完成状态")
        if not hmac.compare_digest(
            str(claim_state.get("claim_token") or ""),
            str(claim_token or ""),
        ):
            raise RuntimeError("托管干预 claim_token 不匹配")
        if (
            str(claim_state.get("active_role_stage") or "") != role_stage
            or str(claim_state.get("active_profile") or "") != profile
            or str(claim_state.get("execution_owner") or "")
            != str(execution_owner or "")
        ):
            raise RuntimeError("托管干预角色所有者不匹配")
        claim_state.update(
            {
                "status": "completed",
                "reply": clean_reply,
                "checkpoint": _redact_sensitive(dict(checkpoint)),
                "replied_at": int(claim_state.get("replied_at") or now),
                "completed_at": int(claim_state.get("completed_at") or now),
                "resume_role_stage": str(resume_role_stage or ""),
                "updated_at": now,
            }
        )
        if all_at_once:
            expected = _intervention_expected_delivery_keys(intervention)
            claims = intervention.get("delivery_claims")
            completed_keys = {
                str(key)
                for key, value in (claims.items() if isinstance(claims, dict) else [])
                if isinstance(value, dict) and str(value.get("status") or "") == "completed"
            }
            intervention["status"] = (
                "completed" if expected and expected.issubset(completed_keys) else "processing"
            )
            intervention["updated_at"] = now
            if intervention["status"] == "completed":
                intervention["completed_at"] = now
        message_suffix = f":{delivery_key}" if delivery_key else ""
        message_key = f"{turn_id}:intervention:{intervention_id}{message_suffix}:reply"
        existing = next(
            (
                item
                for item in conversation.get("messages") or []
                if isinstance(item, dict)
                and str((item.get("meta") or {}).get("message_key") or "") == message_key
            ),
            None,
        )
        message_meta = {
            "runtime_turn_id": turn_id,
            "role_stage": f"{role_stage}:intervention",
            "base_role_stage": _hosted_stage_target_role(role_stage, profile),
            "phase": "completed",
            "message_key": message_key,
            "role_label": role_label,
            "profile": profile,
            "intervention_reply": True,
            "intervention_id": intervention_id,
            "checkpoint": _redact_sensitive(dict(checkpoint)),
            "final_report": False,
        }
        if existing is None:
            existing = _append_message(
                conversation,
                role="assistant",
                name=profile,
                content=clean_reply,
                status="completed",
                kind="message",
                meta=message_meta,
            )
        else:
            existing.update(
                {
                    "content": clean_reply,
                    "status": "completed",
                    "meta": {**(existing.get("meta") or {}), **message_meta},
                    "updated_at": now,
                }
            )
            _project_native_message(existing)
        run["updated_at"] = now
        conversation["updated_at"] = now
        append_hosted_event(
            conversation,
            conversation_id=conversation_id,
            turn_id=turn_id,
            role_stage=role_stage,
            event_type="intervention.replied",
            entity_id=f"{intervention_id}{message_suffix}",
            idempotency_key=f"intervention:{intervention_id}{message_suffix}:replied",
            account_generation=_account_generation_for_owner(
                str(conversation.get("owner_id") or LOCAL_OWNER_ID)
            ),
            payload={
                "entity_id": intervention_id,
                "profile": profile,
                "role_stage": role_stage,
                "reply": clean_reply,
                "delivery_key": delivery_key,
            },
            occurred_at=now,
        )
        append_hosted_event(
            conversation,
            conversation_id=conversation_id,
            turn_id=turn_id,
            role_stage=role_stage,
            event_type="intervention.completed",
            entity_id=f"{intervention_id}{message_suffix}",
            idempotency_key=f"intervention:{intervention_id}{message_suffix}:completed",
            account_generation=_account_generation_for_owner(
                str(conversation.get("owner_id") or LOCAL_OWNER_ID)
            ),
            payload={
                "entity_id": intervention_id,
                "profile": profile,
                "role_stage": role_stage,
                "status": "completed",
                "delivery_key": delivery_key,
            },
            occurred_at=now,
        )
        save_single_state(state)
        completed = {
            **dict(intervention),
            **dict(claim_state),
            **({"delivery_key": delivery_key} if delivery_key else {}),
        }
    _notify_hosted_update(conversation_id)
    return completed


def _refresh_claimed_intervention_checkpoint(
    conversation_id: str,
    turn_id: str,
    *,
    intervention_id: str,
    claim_token: str,
    execution_owner: str,
    role_stage: str,
    profile: str,
    checkpoint: dict[str, Any],
) -> Optional[dict[str, Any]]:
    """Advance a claimed checkpoint without changing its owner or token."""

    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict) or str(run.get("status") or "") in _HOSTED_TERMINAL_STATUSES:
            return None
        intervention = next(
            (
                item
                for item in run.get("interventions") or []
                if isinstance(item, dict)
                and str(item.get("id") or "") == str(intervention_id or "")
            ),
            None,
        )
        if not isinstance(intervention, dict):
            return None
        delivery_key = ""
        claim_state = intervention
        if str(intervention.get("queue_mode") or "one_at_a_time") == "all_at_once":
            delivery_key, claim_state = _intervention_delivery_claim(
                intervention,
                role_stage=role_stage,
                profile=profile,
            )
        if (
            str(claim_state.get("status") or "") != "processing"
            or str(claim_state.get("active_role_stage") or "") != role_stage
            or str(claim_state.get("active_profile") or "") != profile
            or str(claim_state.get("execution_owner") or "")
            != str(execution_owner or "")
            or not hmac.compare_digest(
                str(claim_state.get("claim_token") or ""),
                str(claim_token or ""),
            )
        ):
            return None
        now = int(time.time() * 1000)
        claim_state["checkpoint"] = _redact_sensitive(dict(checkpoint))
        claim_state["updated_at"] = now
        intervention["updated_at"] = now
        run["updated_at"] = now
        conversation["updated_at"] = now
        save_single_state(state)
        refreshed = {
            **dict(intervention),
            **dict(claim_state),
            **({"delivery_key": delivery_key} if delivery_key else {}),
        }
    _notify_hosted_update(conversation_id)
    return refreshed


def _hosted_intervention_reply_prompt(
    *,
    role_label: str,
    intervention: dict[str, Any],
    checkpoint: dict[str, Any],
) -> str:
    return "\n".join(
        (
            f"你是 {role_label}。当前执行已在安全边界暂停。",
            "先处理下面的 @ 定向干预；此回复优先于原任务，不调用新工具，不继续原步骤。",
            "用一到两句直接说明接受、拒绝或需要澄清的原因，以及它对后续计划的影响。",
            f"干预消息：{str(intervention.get('content') or '').strip()}",
            "暂停检查点：",
            json.dumps(checkpoint, ensure_ascii=False, default=str),
        )
    )


def _hosted_intervention_resume_prompt(
    original_prompt: str,
    *,
    intervention: dict[str, Any],
    checkpoint: dict[str, Any],
    reply: str,
) -> str:
    return "\n\n".join(
        (
            str(original_prompt or "").strip(),
            "\n".join(
                (
                    "【从 @ 干预检查点恢复】",
                    f"已优先回复：{str(reply or '').strip()}",
                    f"有效干预：{str(intervention.get('content') or '').strip()}",
                    "从下方持久化检查点继续；不得重复已经完成的动作。先把有效要求写入计划，再执行下一项安全动作。",
                    json.dumps(checkpoint, ensure_ascii=False, default=str),
                )
            ),
        )
    )


def _json_object_from_model_text(value: Any) -> dict[str, Any]:
    """Extract one JSON object without accepting trailing prose as data."""

    text = str(value or "").strip()
    if text.startswith("```"):
        text = re.sub(r"^```(?:json)?\s*", "", text, flags=re.IGNORECASE)
        text = re.sub(r"\s*```$", "", text)
    decoder = json.JSONDecoder()
    for index, character in enumerate(text):
        if character != "{":
            continue
        try:
            parsed, _end = decoder.raw_decode(text[index:])
        except (TypeError, ValueError):
            continue
        if isinstance(parsed, dict):
            return parsed
    return {}


def _normalize_manager_plan(
    result: Any,
    *,
    content: str,
    fallback_workers: list[str],
) -> dict[str, Any]:
    """Validate DBB3 Manager output before it can control remote placement."""

    parsed = (
        dict(result)
        if isinstance(result, dict)
        else _json_object_from_model_text(result)
    )
    difficulty = str(parsed.get("difficulty") or "medium").strip().lower()
    if difficulty not in _MANAGER_DIFFICULTIES:
        difficulty = "medium"
    requested = [
        str(item).strip().lower()
        for item in parsed.get("workers") or []
        if str(item).strip().lower() in set(_WORKER_TARGET_PROFILES.values())
    ]
    requested_targets = [profile.removesuffix("-worker") for profile in requested]
    worker_profiles, constraints = _constrained_worker_profiles(
        content,
        profiles=requested or fallback_workers,
        targets=requested_targets,
    )
    if not worker_profiles:
        raise RuntimeError(f"{_HERMES_MANAGER_NAME} did not leave an eligible execution worker")

    raw_steps = parsed.get("plan") if isinstance(parsed.get("plan"), list) else []
    steps: list[dict[str, Any]] = []
    for index, item in enumerate(raw_steps[:24], start=1):
        if not isinstance(item, dict):
            continue
        assignee = str(item.get("assignee") or "").strip().lower()
        if assignee not in worker_profiles:
            assignee = worker_profiles[min(index - 1, len(worker_profiles) - 1)]
        objective = str(item.get("objective") or item.get("title") or "").strip()
        if not objective:
            continue
        steps.append(
            {
                "id": str(item.get("id") or f"step-{index}").strip()[:80],
                "title": str(item.get("title") or objective).strip()[:180],
                "objective": objective[:8000],
                "assignee": assignee,
                "depends_on": [
                    str(value).strip()[:80]
                    for value in item.get("depends_on") or []
                    if str(value).strip()
                ][:24],
                # A2A reference_task_ids style: upstream task ids this step
                # needs as context (summaries injected, full text on demand).
                "context_refs": [
                    str(value).strip()[:128]
                    for value in item.get("context_refs") or []
                    if str(value).strip()
                ][:16],
                # MetaGPT/OpenHands-style artifact handoff contract.
                "input_artifacts": [
                    str(value).strip()[:500]
                    for value in item.get("input_artifacts") or []
                    if str(value).strip()
                ][:16],
                "output_artifacts": [
                    str(value).strip()[:500]
                    for value in item.get("output_artifacts") or []
                    if str(value).strip()
                ][:16],
            }
        )
    if not steps:
        steps = [
            {
                "id": f"step-{index}",
                "title": f"{profile} execution",
                "objective": content[:8000],
                "assignee": profile,
                "depends_on": [],
            }
            for index, profile in enumerate(worker_profiles, start=1)
        ]

    reviewer_target = str(parsed.get("reviewer_target") or "dbb3").strip().lower()
    if reviewer_target not in {"dbb3", "pc", "spark"}:
        reviewer_target = "dbb3"
    if reviewer_target in {"pc", "spark"} and reviewer_target in set(constraints.get("excluded") or []):
        reviewer_target = "dbb3"
    acceptance_criteria = [
        str(item).strip()[:2000]
        for item in parsed.get("acceptance_criteria") or []
        if str(item).strip()
    ][:32]
    context_variables = (
        dict(parsed.get("context_variables"))
        if isinstance(parsed.get("context_variables"), dict)
        else None
    )
    for step in steps:
        # A2A reference_task_ids style: upstream task ids this step needs as
        # context (full text pulled on demand, summaries injected).
        step["context_refs"] = [
            str(value).strip()[:128]
            for value in step.get("context_refs") or []
            if str(value).strip()
        ][:16]
        # MetaGPT/OpenHands-style artifact handoff contract.
        step["input_artifacts"] = [
            str(value).strip()[:500]
            for value in step.get("input_artifacts") or []
            if str(value).strip()
        ][:16]
        step["output_artifacts"] = [
            str(value).strip()[:500]
            for value in step.get("output_artifacts") or []
            if str(value).strip()
        ][:16]
    return {
        "version": 3,
        "difficulty": difficulty,
        "reason": str(parsed.get("reason") or f"{_HERMES_MANAGER_NAME} selected a bounded execution plan.").strip()[:1000],
        "workers": worker_profiles,
        "reviewer_target": reviewer_target,
        "approach": str(parsed.get("approach") or "").strip()[:12000],
        "task_requirements": str(parsed.get("task_requirements") or "").strip()[:12000],
        "acceptance_criteria": acceptance_criteria,
        "test_plan": str(parsed.get("test_plan") or "").strip()[:12000],
        "flow": [
            str(item).strip()[:2000]
            for item in parsed.get("flow") or []
            if str(item).strip()
        ][:48],
        "context_variables": context_variables,
        "plan": steps,
        "constraints": constraints,
    }


def _parse_slash_directive(content: str) -> tuple[str, str, str]:
    """Detect a leading /plan or /goal directive in a user message.

    Returns (directive, argument, content): directive is "" when the message
    has no directive; content is the argument when one was supplied, else the
    original message. /plan asks the manager to investigate and produce a
    plan without dispatching workers; /goal sets the user's goal as the
    highest-priority objective for the turn.
    """
    stripped = str(content or "").strip()
    match = re.match(r"^/(plan|goal)\b[ \t]*([\s\S]*)", stripped, re.IGNORECASE)
    if not match:
        return "", "", stripped
    directive = match.group(1).lower()
    argument = match.group(2).strip()
    return directive, argument, argument or stripped


def _manager_plan_prompt(
    *,
    content: str,
    fallback_workers: list[str],
    attachment_context: str,
    artifact_required: bool,
    goal_override: str = "",
    plan_only: bool = False,
) -> str:
    directive_lines: list[str] = []
    if plan_only:
        directive_lines.append(
            "用户使用了 /plan 指令：本轮**只做调查与方案制定**。"
            "输出完整方案后直接结束，绝不派发执行节点、绝不调用任务板创建执行任务；"
            "方案本身就是最终交付物，写得更详尽一些。"
        )
    if goal_override:
        directive_lines.append(
            "用户刚刚通过 /goal 明确了目标（最高优先级，任务内容如与其冲突以目标为准）："
            f"{goal_override}"
        )
    return "\n".join(
        item
        for item in (
            "你是 Hermes Manager（调度员/规划者），是整个 agent team 的调度中枢。",
            *directive_lines,
            "你的职责：完整理解用户任务 → 收集一切必要信息和问题（可以调用工具，"
            "也可以调用 delegate_task 派调查子代理去核实环境、统计、检索、验证文件/服务/数据）"
            "→ 输出一份可执行的完整方案。你不亲手执行任务，也不向用户生成最终答案。",
            "调查自主判断：任务信息不足或需要核实外部状态时，先派 1-2 个 leaf 调查子代理收集信息，"
            "每个子代理用 name 给一个中文职业名（如“资料调查员”“环境核查员”），"
            "并用 expected_output 写明要交付什么、acceptance_criteria 写明验收条件"
            "（inherit_turns 保持 0，子代理用全新上下文）；"
            "把调查结论写进方案；信息已经足够时直接规划，不要为简单任务增加无谓延迟。"
            "调查子代理运行期间，用 subagent_list 查看其进展；"
            "发现方向偏离时用 subagent_send(subagent_id=..., text=...) 发送调整指令，"
            "发现子代理卡死时用 subagent_kill(subagent_id=...) 终止并重新派出，"
            "不需要等它结束。",
            "方向或需求确实不清楚、必须由用户拍板时，用 kanban_block(kind=\"needs_input\") "
            "提问，reason 用“问题 + 选项：A. ... B. ... C. ...”格式，"
            "让用户在手机上直接点选（也可自定义回答）；能自行判断的不要打扰用户。",
            "方案必须包含以下全部要素（写入最终 JSON，不要省略）：",
            "  - approach：整体方案与思路（如何完成任务、各阶段做什么）；",
            "  - task_requirements：任务要求（把用户任务的每一条可验证要求逐条列出）；",
            "  - acceptance_criteria：验收标准（每条可验证、可检查的通过条件）；",
            "  - test_plan：测试方案（如何验证每个交付物/每项功能，含具体验证动作）；",
            "  - flow：流程方案（按执行顺序的完整流程步骤）。",
            "  - plan：Todo List（按实际执行顺序列出可验证、可独立完成的步骤，title 简短明确，"
            "每步 objective 写明目标、做法与验收要点，assignee 为具体 worker，depends_on 表达依赖）。",
            "  - plan 每步可选携带：context_refs（本步骤需要引用的上游任务 id 列表，worker 按需拉全文）、"
            "input_artifacts（本步骤消费的上游产物，如 \"upstream/report.md\"）、"
            "output_artifacts（本步骤必须产出的交付物路径）。"
            "  - context_variables（可选）：跨步骤共享的小型结构化状态对象（如 {\"target_host\":\"dbb3\",\"mode\":\"verify\"}），"
            "随任务链传给每个 worker，不要放对话历史里。",
            "多步骤任务不得压缩成一个泛化的“执行任务”；每完成一个步骤，服务端会依据真实 Worker、"
            "审阅与汇报状态更新勾选。示例：用户要求「建目录、写文件、运行、用 todo 跟踪、总结」，"
            "则 plan 至少包含 5 个步骤（建目录 → 写文件 → 运行验证 → 更新 todo → 总结），"
            "禁止把多个要求合并成单个执行节点。",
            "按任务真实需要选择一个或两个 Worker，不得使用其他节点，不得省略验收。",
            hosted_progress_protocol(_HERMES_MANAGER_LABEL),
            hosted_role_delivery_contract(_HERMES_MANAGER_LABEL),
            mention_priority_protocol(_HERMES_MANAGER_LABEL),
            "可用执行节点有 dbb3-worker 与 pc-worker；默认审阅节点是 DBB3，必要时可选择 PC。",
            f"服务器路由建议：{', '.join(fallback_workers)}",
            f"是否要求交付文件：{'yes' if artifact_required else 'no'}",
            "最终交接输出一个 JSON 对象且不要附加解释；过程回报通过运行事件发送，不得混入最终 JSON。结构必须为：",
            '{"difficulty":"low|medium|high|critical","reason":"...","workers":["dbb3-worker"],'
            '"reviewer_target":"dbb3|pc","approach":"整体方案","task_requirements":"任务要求逐条",'
            '"acceptance_criteria":["验收标准1","验收标准2"],"test_plan":"测试方案",'
            '"flow":["流程步骤1","流程步骤2"],"context_variables":{"k":"v"},'
            '"plan":[{"id":"step-1","title":"...","objective":"...","assignee":"dbb3-worker|pc-worker",'
            '"depends_on":[],"context_refs":["t_xxx"],"input_artifacts":["path"],"output_artifacts":["path"]}]}',
            "plan 是用户右滑后看到的 Todo List；approach/task_requirements/acceptance_criteria/"
            "test_plan/flow 会写入看板任务并随任务链传给每个 Worker。",
            f"用户任务：\n{content}",
            attachment_context,
        )
        if item
    )


def _render_manager_plan_report(
    manager_plan: dict[str, Any],
    content: str,
    argument: str,
) -> str:
    """Render the structured manager plan as the final /plan answer."""

    sections: list[str] = []
    sections.append(f"# 执行方案：{argument or summarize_task_title(content)}")
    difficulty = str(manager_plan.get("difficulty") or "").strip()
    reason = str(manager_plan.get("reason") or "").strip()
    if difficulty or reason:
        head = f"难度：{difficulty or '未标注'}"
        if reason:
            head += f"（{reason}）"
        sections.append(head)
    approach = str(manager_plan.get("approach") or "").strip()
    if approach:
        sections.append(f"## 整体方案\n\n{approach}")
    requirements = str(manager_plan.get("task_requirements") or "").strip()
    if requirements:
        sections.append(f"## 任务要求\n\n{requirements}")
    acceptance = manager_plan.get("acceptance_criteria")
    if isinstance(acceptance, list) and acceptance:
        sections.append(
            "## 验收标准\n\n"
            + "\n".join(
                f"- {item}" for item in acceptance if str(item).strip()
            )
        )
    elif str(acceptance or "").strip():
        sections.append(f"## 验收标准\n\n{acceptance}")
    test_plan = str(manager_plan.get("test_plan") or "").strip()
    if test_plan:
        sections.append(f"## 测试方案\n\n{test_plan}")
    flow = manager_plan.get("flow")
    if isinstance(flow, list) and flow:
        sections.append(
            "## 流程\n\n"
            + "\n".join(
                f"{index}. {item}"
                for index, item in enumerate(flow, 1)
                if str(item).strip()
            )
        )
    plan_steps = manager_plan.get("plan")
    if isinstance(plan_steps, list) and plan_steps:
        lines: list[str] = []
        for step in plan_steps:
            if not isinstance(step, dict):
                continue
            label = str(step.get("title") or step.get("id") or "步骤")
            assignee = str(step.get("assignee") or "").strip()
            lines.append(f"- {label}" + (f"（{assignee}）" if assignee else ""))
            objective = str(step.get("objective") or "").strip()
            if objective:
                lines.append(f"  - {objective}")
        sections.append("## 执行步骤\n\n" + "\n".join(lines))
    return "\n\n".join(sections)


def _hosted_manager_plan_todo_snapshot(
    manager_plan: dict[str, Any],
    *,
    stage: str,
    worker_statuses: Optional[dict[str, str]] = None,
    reviewer_status: str = "",
    reviewer_result: str = "",
    reporter_status: str = "",
    final_status: str = "",
) -> dict[str, Any]:
    """Project the model-authored manager plan onto one durable Todo snapshot."""

    normalized_stage = str(stage or "").strip().lower()
    normalized_final = str(final_status or "").strip().lower()
    worker_states = {
        str(profile): str(status or "").strip().lower()
        for profile, status in (worker_statuses or {}).items()
        if str(profile).strip()
    }
    terminal = normalized_final in _HOSTED_TERMINAL_STATUSES
    todos: list[dict[str, str]] = []
    for index, raw_step in enumerate(manager_plan.get("plan") or [], start=1):
        if not isinstance(raw_step, dict):
            continue
        step_id = str(raw_step.get("id") or f"step-{index}").strip()[:80]
        content = str(
            raw_step.get("title")
            or raw_step.get("objective")
            or f"Step {index}"
        ).strip()[:500]
        assignee = str(raw_step.get("assignee") or "").strip()
        worker_status = worker_states.get(assignee, "")
        if normalized_final == "completed" or worker_status == "completed":
            item_status = "completed"
        elif worker_status in {"cancelled", "failed", "blocked"}:
            item_status = "cancelled"
        elif terminal:
            item_status = "cancelled"
        else:
            item_status = "pending"
        todos.append(
            {
                "id": step_id,
                "content": content,
                "status": item_status,
            }
        )

    reviewer_verdict = (
        _hosted_reviewer_verdict(reviewer_result)
        if str(reviewer_result or "").strip()
        else "unknown"
    )
    normalized_reviewer = str(reviewer_status or "").strip().lower()
    review_completed = (
        normalized_final == "completed"
        or (normalized_reviewer == "completed" and reviewer_verdict == "pass")
    )
    review_cancelled = (
        not review_completed
        and (
            normalized_reviewer in {"cancelled", "failed", "blocked"}
            or terminal
        )
    )
    todos.append(
        {
            "id": "workflow-review",
            "content": "验收执行结果",
            "status": (
                "completed"
                if review_completed
                else "cancelled" if review_cancelled else "pending"
            ),
        }
    )

    normalized_reporter = str(reporter_status or "").strip().lower()
    report_completed = normalized_final == "completed"
    report_cancelled = (
        not report_completed
        and (
            normalized_reporter in {"cancelled", "failed", "blocked"}
            or terminal
        )
    )
    todos.append(
        {
            "id": "workflow-report",
            "content": "整理并汇报结果",
            "status": (
                "completed"
                if report_completed
                else "cancelled" if report_cancelled else "pending"
            ),
        }
    )

    if not terminal and not any(item["status"] == "in_progress" for item in todos):
        preferred_ids: list[str] = []
        if normalized_stage in {"manager_handoff", "reporting"}:
            preferred_ids.extend(("workflow-report", "workflow-review"))
        elif normalized_stage == "reviewing":
            preferred_ids.extend(("workflow-review", "workflow-report"))
        preferred_ids.extend(
            item["id"]
            for item in todos
            if item["id"] not in {"workflow-review", "workflow-report"}
        )
        preferred_ids.extend(("workflow-review", "workflow-report"))
        for item_id in preferred_ids:
            candidate = next(
                (
                    item
                    for item in todos
                    if item["id"] == item_id and item["status"] == "pending"
                ),
                None,
            )
            if candidate is not None:
                candidate["status"] = "in_progress"
                break

    completed = sum(item["status"] == "completed" for item in todos)
    return {
        "todos": todos,
        "summary": {
            "completed": completed,
            "total": len(todos),
        },
    }


def _persist_hosted_plan_snapshot(
    conversation_id: str,
    turn_id: str,
    manager_plan: dict[str, Any],
    *,
    stage: str,
    worker_statuses: Optional[dict[str, str]] = None,
    reviewer_status: str = "",
    reviewer_result: str = "",
    reporter_status: str = "",
    final_status: str = "",
) -> dict[str, Any]:
    """Persist one canonical Todo activity without adding a second plan bubble."""

    snapshot = _hosted_manager_plan_todo_snapshot(
        manager_plan,
        stage=stage,
        worker_statuses=worker_statuses,
        reviewer_status=reviewer_status,
        reviewer_result=reviewer_result,
        reporter_status=reporter_status,
        final_status=final_status,
    )
    now = int(time.time() * 1000)
    activity_id = f"{turn_id}:manager-plan:todo"
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            raise RuntimeError("托管任务记录不存在")
        started_at = int(run.get("todo_started_at") or now)
        run["todo_started_at"] = started_at
        run["todo_snapshot"] = snapshot
        run["todo_updated_at"] = now
        run["updated_at"] = now
        conversation["updated_at"] = now
        payload = json.dumps(snapshot, ensure_ascii=False, separators=(",", ":"))
        activity = {
            "id": activity_id,
            "kind": "tool",
            "category": "planning",
            "name": "todo",
            "tool_name": "todo",
            "input": payload,
            "output": payload,
            "status": "completed",
            "summary": (
                f"Plan {snapshot['summary']['completed']}/"
                f"{snapshot['summary']['total']}"
            ),
            "started_at": started_at,
            "ended_at": now,
            "completed_at": now,
            "duration_ms": max(0, now - started_at),
        }

        messages = conversation.get("messages") or []
        target = next(
            (
                message
                for message in reversed(messages)
                if isinstance(message, dict)
                and isinstance(message.get("meta"), dict)
                and str(message["meta"].get("runtime_turn_id") or "") == turn_id
                and any(
                    isinstance(item, dict) and str(item.get("id") or "") == activity_id
                    for item in message["meta"].get("activities") or []
                )
            ),
            None,
        )
        if target is None:
            target = next(
                (
                    message
                    for message in reversed(messages)
                    if isinstance(message, dict)
                    and isinstance(message.get("meta"), dict)
                    and str(message["meta"].get("runtime_turn_id") or "") == turn_id
                    and str(message["meta"].get("role_stage") or "").startswith(
                        "manager_planning"
                    )
                ),
                None,
            )
        plan_count = max(0, int(snapshot["summary"]["total"]) - 2)
        if target is None:
            target = _append_message(
                conversation,
                role="assistant",
                name=_DBB3_MANAGER_PROFILE,
                content=f"已生成 {plan_count} 项执行计划，正在按顺序推进。",
                status="completed",
                kind="message",
                meta={
                    "runtime_turn_id": turn_id,
                    "role_stage": "manager_planning",
                    "base_role_stage": "manager_planning",
                    "phase": "completed",
                    "message_key": f"{turn_id}:manager_planning:completed",
                    "role_label": f"{_HERMES_MANAGER_LABEL} · 规划",
                    "profile": _DBB3_MANAGER_PROFILE,
                    "collapse_activities": True,
                    "final_report": False,
                    "activities": [activity],
                    "completed_at": now,
                },
            )
        else:
            meta = dict(target.get("meta") or {})
            activities = [
                dict(item)
                for item in meta.get("activities") or []
                if isinstance(item, dict)
                and str(item.get("id") or "") != activity_id
            ]
            activities.append(activity)
            meta.update(
                {
                    "runtime_turn_id": turn_id,
                    "role_stage": "manager_planning",
                    "base_role_stage": "manager_planning",
                    "phase": "completed",
                    "message_key": f"{turn_id}:manager_planning:completed",
                    "role_label": f"{_HERMES_MANAGER_LABEL} · 规划",
                    "profile": _DBB3_MANAGER_PROFILE,
                    "collapse_activities": True,
                    "final_report": False,
                    "activities": activities,
                    "completed_at": now,
                }
            )
            target.update(
                {
                    "content": f"已生成 {plan_count} 项执行计划，正在按顺序推进。",
                    "status": "completed",
                    "meta": meta,
                    "updated_at": now,
                }
            )
            _project_native_message(target)
        save_single_state(state)
    _notify_hosted_update(conversation_id)
    return snapshot


def _normalize_manager_handoff(
    result: Any,
    *,
    task_goal: str,
    plan: dict[str, Any],
    worker_results: dict[str, str],
    review_verdict: str,
    rework_history: list[dict[str, Any]],
    artifacts: list[dict[str, Any]],
    failures: list[str],
) -> dict[str, Any]:
    parsed = (
        dict(result)
        if isinstance(result, dict)
        else _json_object_from_model_text(result)
    )
    authoritative = {
        "task_goal": str(task_goal).strip(),
        "plan": list(plan.get("plan") or []),
        "worker_results": dict(worker_results),
        "review_verdict": str(review_verdict).strip(),
        "rework_history": list(rework_history),
        "artifacts": list(artifacts),
        "failures": list(failures),
    }
    ignored_conflicts = sorted(
        key
        for key, value in authoritative.items()
        if key in parsed and parsed.get(key) != value
    )
    handoff = {
        "version": 1,
        **authoritative,
        "suggested_conclusion": str(
            parsed.get("suggested_conclusion") or ""
        ).strip()[:4000],
        "ignored_manager_conflicts": ignored_conflicts,
    }
    for field in _MANAGER_HANDOFF_FIELDS:
        if field not in handoff:
            raise RuntimeError(f"{_HERMES_MANAGER_NAME} handoff is missing {field}")
    return handoff


def _rule_based_user_intent(content: str) -> dict[str, Any]:
    text = content.strip()
    lowered = text.lower()
    title = summarize_task_title(text)
    matched = [marker for marker in _WORK_MARKERS if marker in lowered]
    complex_matches = [
        marker for marker in _COMPLEX_WORK_MARKERS if marker in lowered
    ]
    device_matches = [
        marker
        for marker in (*_PC_MARKERS, *_DBB3_MARKERS)
        if marker in lowered
    ]
    multi_step_count = sum(
        lowered.count(marker) for marker in _MULTI_STEP_MARKERS
    )
    explicit_role_count = sum(
        1 for marker in _EXPLICIT_WORKFLOW_ROLE_MARKERS if marker in lowered
    )
    explicit_workflow = (
        (
            explicit_role_count >= 2
            or any(marker in lowered for marker in _EXPLICIT_WORKFLOW_PHRASES)
        )
        and any(marker in lowered for marker in _WORKFLOW_EXECUTION_MARKERS)
    )
    explanatory = any(marker in lowered for marker in _EXPLANATION_MARKERS)
    imperative = any(
        marker in lowered
        for marker in ("帮我", "请你", "直接", "现在", "完成", "执行", "go ahead")
    )
    hard_work = explicit_workflow or (
        any(marker in lowered for marker in _HARD_WORK_MARKERS)
        and (imperative or not explanatory)
    )
    explicit_chat = any(marker in lowered for marker in _SIMPLE_CHAT_MARKERS)
    single_turn_tools = any(
        marker in lowered for marker in _SINGLE_TURN_TOOL_MARKERS
    )
    ambiguous_delegation = any(
        marker in lowered for marker in _AMBIGUOUS_DELEGATION_MARKERS
    )
    trivial_chat = bool(text) and len(text) <= 16 and bool(
        re.fullmatch(r"[\d０-９\s.,，。!?！？、+-]+", text)
    )
    plain_chat = (
        not hard_work
        and len(text) <= 80
        and not matched
        and not complex_matches
        and not device_matches
        and multi_step_count == 0
        and explicit_role_count == 0
        and not single_turn_tools
        and not ambiguous_delegation
        and not requires_artifact_delivery(text)
    )
    hard_chat = (
        not hard_work
        and len(text) <= 80
        and (explicit_chat or trivial_chat or plain_chat or single_turn_tools)
    )
    score = min(6, len(complex_matches) * 2)
    score += min(3, len(device_matches) * 2)
    score += min(3, multi_step_count)
    score += 1 if matched else 0
    score += 2 if len(text) >= 80 else 0
    if explicit_workflow:
        score = max(score, 4)
    if hard_work:
        score = max(score, 4)
    if explicit_chat and len(text) < 30:
        score -= 3

    if score < 4:
        if explicit_chat or trivial_chat or plain_chat or single_turn_tools:
            confidence = 0.96
        elif not matched and len(text) <= 12:
            confidence = 0.62
        elif score <= 0:
            confidence = 0.82
        else:
            confidence = 0.68
        if trivial_chat:
            rationale_code = "rule.trivial_chat"
        elif explicit_chat:
            rationale_code = "rule.explicit_chat"
        elif single_turn_tools:
            rationale_code = "rule.single_turn_tools"
        elif hard_chat:
            rationale_code = "rule.plain_chat"
        else:
            rationale_code = "rule.ambiguous_chat_fallback"
        return {
            "mode": "chat",
            "label": "简单任务",
            "title": title,
            "reason": "当前请求可由一个 Hermes 直接回答或完成，不需要创建群聊工作流。",
            "confidence": confidence,
            "source": "rules",
            "profiles": ["default"],
            "artifact_required": requires_artifact_delivery(text),
            "lock_level": "hard_chat" if hard_chat else "ambiguous",
            "needs_tools": single_turn_tools,
            "capability_hints": [],
            "rationale_codes": [rationale_code],
        }

    profiles = _work_profiles(lowered)
    return {
        "mode": "work",
        "label": "群聊 + 工作流",
        "title": title,
        "reason": "检测到多步骤、设备操作、代码修改或交付要求，将创建工作流并启动多 Profile 协作。",
        "confidence": 0.95 if score >= 7 else 0.86,
        "source": "rules",
        "profiles": profiles,
        "targets": [
            profile.removesuffix("-worker")
            for profile in profiles
            if profile in _WORKER_TARGET_PROFILES.values()
        ],
        "target_constraints": _target_constraints(lowered),
        "artifact_required": requires_artifact_delivery(text),
        "lock_level": "hard_work" if hard_work else "ambiguous",
        "capability_hints": [],
        "rationale_codes": [
            "rule.explicit_work" if hard_work else "rule.ambiguous_work_fallback"
        ],
    }


def classify_intent_with_model(content: str) -> Optional[dict[str, Any]]:
    """Ask the configured auxiliary model only for ambiguous routing cases."""
    from agent.auxiliary_client import call_llm, extract_content_or_reasoning

    response = call_llm(
        task="intent_routing",
        messages=[
            {
                "role": "system",
                "content": (
                    "你是 Hermes 任务路由器。判断用户请求应走 simple 还是 workflow。"
                    "simple 表示普通聊天、问答、总结、搜索或一个 Hermes 可直接完成的单步任务；"
                    "workflow 表示多步骤执行、设备协作、修改代码、部署、测试、生成交付文件或长期任务。"
                    "只输出 JSON：{\"mode\":\"chat|work\",\"confidence\":0到1,"
                    "\"reason\":\"一句中文理由\"}。"
                ),
            },
            {"role": "user", "content": content.strip()},
        ],
        temperature=0,
        max_tokens=160,
        timeout=15,
    )
    raw = extract_content_or_reasoning(response)
    match = re.search(r"\{.*\}", raw, flags=re.DOTALL)
    if not match:
        return None
    parsed = json.loads(match.group(0))
    mode = str(parsed.get("mode") or "").strip().lower()
    if mode not in {"chat", "work"}:
        return None
    return {
        "mode": mode,
        "confidence": max(
            0.0,
            min(1.0, float(parsed.get("confidence") or 0.75)),
        ),
        "reason": str(
            parsed.get("reason") or "模型根据任务复杂度完成判断。"
        )[:180],
    }


def classify_intent_with_context_model(
    content: str,
    *,
    recent_messages: Optional[list[dict[str, Any]]] = None,
    attachments: Optional[list[dict[str, Any]]] = None,
    adjudicate: bool = False,
) -> Optional[dict[str, Any]]:
    """Model-first structured routing for native hosted conversations."""
    from agent.auxiliary_client import call_llm, extract_content_or_reasoning

    context = {
        "current_message": str(content or "").strip()[:12_000],
        "recent_messages": [
            {
                "role": str(item.get("role") or ""),
                "content": str(item.get("content") or "")[:2_000],
            }
            for item in (recent_messages or [])[-12:]
            if isinstance(item, dict)
        ],
        "attachments": [
            {
                "name": str(item.get("name") or item.get("filename") or "")[:240],
                "mime_type": str(item.get("mime_type") or item.get("type") or "")[:120],
                "source": str(item.get("source") or "user")[:40],
            }
            for item in (attachments or [])[:32]
            if isinstance(item, dict)
        ],
    }
    system = (
        "Classify this Hermes conversation turn from semantics and context. "
        "chat is ordinary conversation, explanation, translation, summary, search, or read-only analysis that one "
        "Hermes can answer. work is concrete development/operations, tool execution, state mutation, deployment, "
        "multi-step execution, or creating a deliverable. An uploaded file is normally input, not a requested output. "
        "Repository edits do not imply a downloadable artifact. Resolve references such as continue or send that file "
        "from recent_messages. Select targets from dbb3 and pc (Windows/WSL/local computer). "
        "Return JSON only: {mode:'chat|work',needs_execution:boolean,needs_tools:boolean,mutates_state:boolean,"
        "targets:[],profiles:[],artifact:{decision:'required|optional|none',types:[],"
        "producer_targets:[],producer_profiles:[],reason:string},"
        "confidence:0..1,reason:string}. Work profiles are dbb3-worker and pc-worker."
    )
    if adjudicate:
        system += " This is a second adjudication for a low-confidence first result; resolve the boundary explicitly."
    response = call_llm(
        task="intent_routing",
        messages=[
            {"role": "system", "content": system},
            {"role": "user", "content": json.dumps(context, ensure_ascii=False)},
        ],
        temperature=0,
        max_tokens=900,
        timeout=30,
    )
    raw = extract_content_or_reasoning(response)
    match = re.search(r"\{.*\}", raw, flags=re.DOTALL)
    if not match:
        return None
    parsed = json.loads(match.group(0))
    mode = str(parsed.get("mode") or "").strip().lower()
    if mode not in {"chat", "work"}:
        return None
    targets = []
    for value in parsed.get("targets") or []:
        normalized = str(value).strip().lower()
        if normalized in {"server", "remote", "linux"}:
            normalized = "dbb3"
        elif normalized in {"windows", "wsl", "local"}:
            normalized = "pc"
        if normalized in {"dbb3", "pc"} and normalized not in targets:
            targets.append(normalized)
    profiles = [
        str(value).strip().lower()
        for value in parsed.get("profiles") or []
        if str(value).strip().lower() in {"dbb3-worker", "pc-worker"}
    ]
    if mode == "work" and not profiles:
        profiles = [f"{target}-worker" for target in targets] or ["dbb3-worker"]
    artifact = parsed.get("artifact") if isinstance(parsed.get("artifact"), dict) else {}
    artifact_decision = str(artifact.get("decision") or "none").strip().lower()
    if artifact_decision not in {"required", "optional", "none"}:
        artifact_decision = "none"
    return {
        "mode": mode,
        "needs_execution": _coerce_flag(
            parsed.get("needs_execution"), default=mode == "work"
        ),
        "needs_tools": _coerce_flag(
            parsed.get("needs_tools"), default=mode == "work"
        ),
        "mutates_state": _coerce_flag(
            parsed.get("mutates_state"), default=mode == "work"
        ),
        "targets": targets,
        "profiles": profiles,
        "artifact": {
            "decision": artifact_decision,
            "types": [str(value).strip().lower() for value in artifact.get("types") or [] if str(value).strip()],
            "producer_targets": [
                str(value).strip().lower()
                for value in artifact.get("producer_targets") or []
                if str(value).strip().lower() in {"dbb3", "pc"}
            ],
            "producer_profiles": [
                str(value).strip().lower()
                for value in artifact.get("producer_profiles") or []
                if str(value).strip().lower() in {"dbb3-worker", "pc-worker"}
            ],
            "reason": str(artifact.get("reason") or "")[:500],
        },
        "confidence": max(0.0, min(1.0, float(parsed.get("confidence") or 0.0))),
        "reason": str(parsed.get("reason") or "Model semantic routing")[:500],
    }


def _runtime_has_usable_credentials(runtime: dict[str, Any]) -> bool:
    api_key = runtime.get("api_key")
    if callable(api_key):
        return True
    if str(api_key or "").strip():
        return True
    pool = runtime.get("credential_pool")
    if pool is None:
        return False
    try:
        return bool(pool.has_credentials())
    except (AttributeError, RuntimeError, TypeError, ValueError):
        return False


def _profile_runtime_readiness(
    profile: str,
    model: str,
    provider: str,
) -> dict[str, Any]:
    """Resolve the same credential path used by the hosted child process."""

    from hermes_runtime.config import load_config
    from hermes_cli.moa_config import resolve_moa_preset
    from hermes_cli.profiles import resolve_profile_env
    from hermes_constants import reset_hermes_home_override, set_hermes_home_override

    try:
        from hermes_cli.runtime_provider import resolve_runtime_provider
    except ModuleNotFoundError:
        return {
            "ready": False,
            "retryable": False,
            "code": _SERVER_RUNTIME_INCOMPLETE_CODE,
            "message": _SERVER_RUNTIME_INCOMPLETE_MESSAGE,
        }

    token = set_hermes_home_override(resolve_profile_env(profile))
    try:
        config = load_config()
        slots = [{"provider": provider, "model": model}]
        if provider.lower() == "moa":
            preset = resolve_moa_preset(config.get("moa") or {}, model)
            slots = [
                *list(preset.get("reference_models") or []),
                dict(preset.get("aggregator") or {}),
            ]
        for slot in slots:
            slot_provider = str(slot.get("provider") or "").strip()
            slot_model = str(slot.get("model") or "").strip()
            if not slot_provider or not slot_model:
                return {
                    "ready": False,
                    "code": _MODEL_NOT_CONFIGURED_CODE,
                    "message": _MODEL_NOT_CONFIGURED_MESSAGE,
                }
            try:
                runtime = resolve_runtime_provider(
                    requested=slot_provider,
                    target_model=slot_model,
                )
            except Exception:
                return {
                    "ready": False,
                    "code": "model_credentials_missing",
                    "message": _MODEL_NOT_CONFIGURED_MESSAGE,
                }
            if not _runtime_has_usable_credentials(runtime):
                return {
                    "ready": False,
                    "code": "model_credentials_missing",
                    "message": _MODEL_NOT_CONFIGURED_MESSAGE,
                }
    finally:
        reset_hermes_home_override(token)
    return {"ready": True, "code": "ready", "message": ""}


def profile_model_readiness(profile: str) -> dict[str, Any]:
    """Return whether one hosted-chat profile can reach its selected model."""

    normalized = str(profile or "default").strip() or "default"
    record = next(
        (
            item
            for item in available_profiles()
            if str(item.get("name") or "").strip() == normalized
        ),
        None,
    )
    if record is None:
        return {
            "ready": False,
            "code": "profile_not_found",
            "message": "Hermes Profile 不存在。",
            "profile": normalized,
        }
    model = str(record.get("model") or "").strip()
    if not model:
        return {
            "ready": False,
            "code": _MODEL_NOT_CONFIGURED_CODE,
            "message": _MODEL_NOT_CONFIGURED_MESSAGE,
            "profile": normalized,
        }
    readiness = _profile_runtime_readiness(
        normalized,
        model,
        str(record.get("provider") or "").strip(),
    )
    return {
        **readiness,
        "profile": normalized,
        "model": model,
        "provider": str(record.get("provider") or "").strip(),
    }


def _fail_hosted_turn_preflight(
    conversation: dict[str, Any],
    run: dict[str, Any],
    readiness: dict[str, Any],
) -> None:
    """Persist one idempotent terminal error without a running placeholder."""

    turn_id = str(run.get("turn_id") or "").strip()
    profile = str(readiness.get("profile") or "default").strip() or "default"
    error = str(readiness.get("message") or _MODEL_NOT_CONFIGURED_MESSAGE).strip()
    code = str(readiness.get("code") or _MODEL_NOT_CONFIGURED_CODE).strip()
    now = int(time.time() * 1000)
    run.update(
        {
            "status": "failed",
            "stage": "failed",
            "error": error,
            "error_code": code,
            "retryable": False,
            "completed_at": now,
            "updated_at": now,
        }
    )
    run.setdefault("terminal_commit_id", f"terminal_{uuid.uuid4().hex}")
    run.setdefault("terminal_committed_at", now)
    message_key = f"{turn_id}:chat:preflight-failed"
    messages = conversation.setdefault("messages", [])
    existing = next(
        (
            item
            for item in messages
            if isinstance(item, dict)
            and str((item.get("meta") or {}).get("message_key") or "") == message_key
        ),
        None,
    )
    payload = {
        "role": "assistant",
        "name": profile,
        "content": error,
        "status": "failed",
        "kind": "message",
        "meta": {
            "role_stage": "chat",
            "base_role_stage": "chat",
            "phase": "failed",
            "message_key": message_key,
            "role_label": "Hermes",
            "profile": profile,
            "error_code": code,
            "retryable": False,
            "completed_at": now,
        },
    }
    if existing is None:
        message = _append_message(conversation, **payload)
    else:
        existing.update(payload)
        existing["updated_at"] = now
        message = existing
    _project_native_message(message)
    _append_canonical_turn_terminal(
        conversation,
        conversation_id=str(conversation.get("id") or "conversation"),
        turn_id=turn_id,
        run=run,
        occurred_at=now,
    )
    conversation["updated_at"] = now


def _hosted_model_wait_state(
    previous: Any,
    *,
    attempt: int,
    now: int,
    thinking: bool = False,
) -> dict[str, Any]:
    state = dict(previous) if isinstance(previous, dict) else {}
    state.update(
        {
            "content": "",
            "status": "streaming",
            "actual_model": "",
            "actual_provider": "",
            "runtime_session_id": str(state.get("runtime_session_id") or ""),
            "started_at": int(state.get("started_at") or now),
            "first_token_at": 0,
            "milestone_count": 0,
            "milestone_content": "",
            "request_accepted": False,
            "request_accepted_at": 0,
        }
    )
    status_text = (
        "正在思考"
        if thinking
        else f"正在重新连接 ({attempt}/{_HOSTED_CHAT_API_ATTEMPTS})"
    )
    state["activities"] = [
        {
            "id": f"model-readiness-{attempt if not thinking else 'ready'}",
            "kind": "status",
            "category": "other",
            "name": "运行状态",
            "output": status_text,
            "status": "completed",
            "started_at": now,
            "ended_at": now,
            "duration_ms": 0,
        }
    ]
    return state


def _wait_for_hosted_chat_model(
    conversation_id: str,
    turn_id: str,
    profile: str,
    *,
    retry_delay_seconds: float = _HOSTED_CHAT_API_RETRY_DELAY_SECONDS,
    sleeper: Callable[[float], None] = time.sleep,
) -> bool:
    """Persist and resume the five-attempt model-readiness state machine."""

    while True:
        if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
            return False
        with _STATE_LOCK:
            state = load_single_state()
            conversation = _conversation_by_id(state, conversation_id)
            run = (conversation.get("hosted_turns") or {}).get(turn_id)
            if not isinstance(run, dict) or run.get("status") in _HOSTED_TERMINAL_STATUSES:
                return False
            attempt = max(0, int(run.get("model_readiness_attempt") or 0))
            next_attempt_at = max(0, int(run.get("model_readiness_next_attempt_at") or 0))
            deadline_at = int(run.get("model_retry_deadline_at") or 0)
            previous = (run.get("role_events") or {}).get("chat")
        now_ms = int(time.time() * 1000)
        if deadline_at and now_ms >= deadline_at:
            with _STATE_LOCK:
                state = load_single_state()
                conversation = _conversation_by_id(state, conversation_id)
                run = (conversation.get("hosted_turns") or {}).get(turn_id)
                if isinstance(run, dict) and run.get("status") not in _HOSTED_TERMINAL_STATUSES:
                    _fail_hosted_turn_preflight(
                        conversation,
                        run,
                        {
                            "profile": profile,
                            "code": "model_connection_deadline_exceeded",
                            "message": "模型连接在 120 秒预算内未恢复，请重试。",
                        },
                    )
                    save_single_state(state)
            _notify_hosted_update(conversation_id)
            return False
        if next_attempt_at > now_ms:
            wait_seconds = max(0.0, (next_attempt_at - now_ms) / 1000)
            if deadline_at:
                wait_seconds = min(
                    wait_seconds,
                    max(0.0, (deadline_at - now_ms) / 1000),
                )
            sleeper(min(1.0, wait_seconds))
            continue

        readiness = profile_model_readiness(profile)
        checked_at = int(time.time() * 1000)
        if readiness.get("ready") and (not deadline_at or checked_at < deadline_at):
            ready_state = _hosted_model_wait_state(
                previous,
                attempt=attempt,
                now=now_ms,
                thinking=True,
            )
            _persist_hosted_turn(
                conversation_id,
                turn_id,
                patch={
                    "model_readiness_next_attempt_at": 0,
                    "model_readiness_recovered_at": checked_at,
                    "model_retry_attempt": attempt,
                },
            )
            _persist_hosted_role_state(
                conversation_id,
                turn_id,
                profile=profile,
                role_stage="chat",
                role_label="Hermes",
                state=ready_state,
                content_fallback="",
            )
            return True

        if readiness.get("retryable") is False:
            with _STATE_LOCK:
                state = load_single_state()
                conversation = _conversation_by_id(state, conversation_id)
                run = (conversation.get("hosted_turns") or {}).get(turn_id)
                if not isinstance(run, dict) or run.get("status") in _HOSTED_TERMINAL_STATUSES:
                    return False
                _fail_hosted_turn_preflight(conversation, run, readiness)
                save_single_state(state)
            _notify_hosted_update(conversation_id)
            return False

        attempt += 1
        retry_state = _hosted_model_wait_state(
            previous,
            attempt=attempt,
            now=now_ms,
        )
        remaining_ms = max(0, deadline_at - checked_at) if deadline_at else 0
        retry_delay_ms = int(max(0.0, retry_delay_seconds) * 1000)
        next_attempt_at = (
            0
            if attempt >= _HOSTED_CHAT_API_ATTEMPTS or (deadline_at and remaining_ms <= 0)
            else checked_at + min(retry_delay_ms, remaining_ms or retry_delay_ms)
        )
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "model_readiness_attempt": attempt,
                "model_retry_attempt": attempt,
                "model_readiness_next_attempt_at": next_attempt_at,
                "model_retry_last_error": str(readiness.get("code") or "model_unavailable"),
            },
        )
        _persist_hosted_role_state(
            conversation_id,
            turn_id,
            profile=profile,
            role_stage="chat",
            role_label="Hermes",
            state=retry_state,
            content_fallback="",
        )
        if attempt >= _HOSTED_CHAT_API_ATTEMPTS or (deadline_at and checked_at >= deadline_at):
            with _STATE_LOCK:
                state = load_single_state()
                conversation = _conversation_by_id(state, conversation_id)
                run = (conversation.get("hosted_turns") or {}).get(turn_id)
                if not isinstance(run, dict) or run.get("status") in _HOSTED_TERMINAL_STATUSES:
                    return False
                _fail_hosted_turn_preflight(conversation, run, readiness)
                save_single_state(state)
            _notify_hosted_update(conversation_id)
            return False


def _requires_local_ios_mcp(content: str) -> bool:
    lowered = str(content or "").strip().lower()
    explicit_mcp = "mcp" in lowered
    device_context = any(
        marker in lowered
        for marker in (
            "iphone",
            "apple watch",
            "ios",
            "\u6211\u7684",
            "\u6211\u73b0\u5728",
            "\u624b\u673a",
            "\u624b\u8868",
        )
    )
    managed_domain = any(
        marker in lowered
        for marker in (
            "location",
            "trajectory",
            "places",
            "motion",
            "qweather",
            "weather",
            "health",
            "sleep",
            "heart",
            "oxygen",
            "calendar",
            "reminder",
            "screen time",
            "\u4f4d\u7f6e",
            "\u5730\u5740",
            "\u8f68\u8ff9",
            "\u5730\u70b9",
            "\u8fd0\u52a8",
            "\u5929\u6c14",
            "\u5065\u5eb7",
            "\u7761\u7720",
            "\u5fc3\u7387",
            "\u8840\u6c27",
            "\u65e5\u5386",
            "\u63d0\u9192",
            "\u5c4f\u5e55\u4f7f\u7528",
            "\u7535\u91cf",
        )
    )
    return managed_domain and (explicit_mcp or device_context)


def _ios_capability_hints(content: str) -> list[str]:
    """Return advisory device capabilities without changing chat/work mode."""

    lowered = str(content or "").strip().lower()
    domains = {
        "ios.location": ("location", "trajectory", "places", "位置", "地址", "轨迹", "地点"),
        "ios.weather": ("qweather", "weather", "天气"),
        "ios.health": ("health", "sleep", "heart", "oxygen", "健康", "睡眠", "心率", "血氧"),
        "ios.calendar": ("calendar", "reminder", "日历", "提醒"),
        "ios.screen_time": ("screen time", "屏幕使用"),
        "ios.motion": ("motion", "运动"),
        "ios.power": ("battery", "电量"),
    }
    return [
        capability
        for capability, markers in domains.items()
        if any(marker in lowered for marker in markers)
    ] if _requires_local_ios_mcp(content) else []


def classify_user_intent(
    content: str,
    *,
    model_classifier: Optional[Callable[[str], Optional[dict[str, Any]]]] = None,
) -> dict[str, Any]:
    routed = _rule_based_user_intent(content)
    capability_hints = _ios_capability_hints(content)
    if capability_hints:
        routed["capability_hints"] = capability_hints
        routed["rationale_codes"] = [
            *list(routed.get("rationale_codes") or []),
            "capability.ios_mcp",
        ]
        routed["needs_tools"] = True
    rule_decision = {
        key: deepcopy(routed.get(key))
        for key in (
            "mode",
            "confidence",
            "lock_level",
            "profiles",
            "targets",
            "rationale_codes",
        )
        if key in routed
    }
    routed["rule_decision"] = rule_decision
    if str(routed.get("lock_level") or "") in {"hard_chat", "hard_work"}:
        return routed
    if model_classifier is None:
        return routed
    try:
        model_result = model_classifier(content.strip())
    except Exception:
        logging.getLogger(__name__).warning(
            "Intent routing model failed; using deterministic fallback",
            exc_info=True,
        )
        return routed
    if not isinstance(model_result, dict):
        logging.getLogger(__name__).warning(
            "Intent routing model returned %s instead of an object; using deterministic fallback",
            type(model_result).__name__,
        )
        return routed
    mode = str(model_result.get("mode") or "").strip().lower()
    if mode not in {"chat", "work"}:
        logging.getLogger(__name__).warning(
            "Intent routing model returned invalid mode %r; using deterministic fallback",
            mode,
        )
        return routed
    try:
        model_confidence = max(
            0.0,
            min(1.0, float(model_result.get("confidence") or 0.0)),
        )
    except (TypeError, ValueError):
        model_confidence = 0.0
    if model_confidence < 0.70:
        try:
            second = model_classifier(content.strip())
        except Exception:
            second = None
        if isinstance(second, dict):
            try:
                second_confidence = max(
                    0.0,
                    min(1.0, float(second.get("confidence") or 0.0)),
                )
            except (TypeError, ValueError):
                second_confidence = 0.0
            second_mode = str(second.get("mode") or "").strip().lower()
            if second_mode in {"chat", "work"} and second_confidence > model_confidence:
                model_result = second
                model_confidence = second_confidence
                mode = second_mode
    model_profiles = [
        str(item).strip()
        for item in model_result.get("profiles") or []
        if str(item).strip()
    ]
    artifact = (
        dict(model_result.get("artifact"))
        if isinstance(model_result.get("artifact"), dict)
        else {
            "decision": "required"
            if _coerce_flag(routed.get("artifact_required"))
            else "none",
            "types": [],
            "reason": "",
        }
    )
    artifact_decision = str(artifact.get("decision") or "none").strip().lower()
    if artifact_decision not in {"required", "optional", "none"}:
        artifact_decision = "none"
    worker_profiles, target_constraints = _constrained_worker_profiles(
        content,
        profiles=model_profiles,
        targets=list(model_result.get("targets") or []),
    )
    selected_profiles = (
        ["default"]
        if mode == "chat"
        else ["default", *worker_profiles, "reviewer"]
    )
    routed.update(
        {
            "mode": mode,
            "label": "群聊 + 工作流" if mode == "work" else "简单任务",
            "reason": str(
                model_result.get("reason") or "模型根据任务复杂度完成判断。"
            )[:180],
            "confidence": model_confidence,
            "source": "model",
            "profiles": selected_profiles,
            "targets": [
                profile.removesuffix("-worker") for profile in worker_profiles
            ],
            "target_constraints": target_constraints,
            "needs_execution": _coerce_flag(
                model_result.get("needs_execution"), default=mode == "work"
            ),
            "needs_tools": _coerce_flag(
                model_result.get("needs_tools"), default=mode == "work"
            ),
            "mutates_state": _coerce_flag(
                model_result.get("mutates_state"), default=mode == "work"
            ),
            "artifact": {**artifact, "decision": artifact_decision},
            "artifact_required": artifact_decision == "required",
            "lock_level": "ambiguous",
            "capability_hints": capability_hints,
            "rationale_codes": [
                *list(routed.get("rationale_codes") or []),
                "model.ambiguous_resolution",
            ],
            "rule_decision": rule_decision,
            "model_decision": {
                "mode": mode,
                "confidence": model_confidence,
                "profiles": list(model_profiles),
                "targets": list(model_result.get("targets") or []),
            },
            "routing_conflict": bool(rule_decision.get("mode") != mode),
        }
    )
    return routed


def _message_line(message: dict[str, Any]) -> str:
    name = str(message.get("name") or message.get("role") or "成员").strip()
    content = str(message.get("content") or "").strip()
    return f"{name}: {content}"


def build_group_prompt(
    room: dict[str, Any],
    profile: str,
    user_message: str,
    *,
    artifact_required: bool = False,
) -> str:
    history = room.get("messages") if isinstance(room.get("messages"), list) else []
    recent = "\n".join(_message_line(item) for item in history[-_PROMPT_HISTORY:])
    members = "、".join(str(item) for item in room.get("profiles") or [])
    role = collaboration_role(profile)
    role_instruction = {
        "worker": (
            "你是执行者。只负责实际执行、调用工具并提交证据、结果和遗留问题；"
            "不要向用户做最终总结，也不要替审阅者下结论。"
            "任务含可并行子步骤或需要独立调查时，可用 delegate_task 派 leaf 子代理"
            "并行执行（并发数量由你根据任务和节点资源自行判断），"
            "每个子代理用 name 给中文职业名，用 expected_output 写明交付物、"
            "acceptance_criteria 写明验收条件（inherit_turns 保持 0、"
            "context_variables 仅在需要跨子代理共享小状态时传递）；"
            "运行中用 subagent_list 查看进展、subagent_send 调整方向、"
            "subagent_kill 终止卡死的子代理并重新派出；"
            "子代理结果必须汇总进你的交接证据。"
            "方向或需求必须由用户拍板时用 kanban_block(kind=\"needs_input\") 提问，"
            "reason 用“问题 + 选项：A. ... B. ...”格式；能自行判断的不要打扰用户。"
        ),
        "reviewer": (
            "你是审阅者。基于执行者已经提交的结果做验收、风险检查和通过/退回判断；"
            "不要重复执行者的工作，不要向用户做最终总结。"
        ),
        "supervisor": supervisor_role_prompt(),
        "reporter": (
            "你是唯一最终汇报者。综合执行者和审阅者的信息，向用户给出一次清晰的最终结论、"
            "完成状态、关键证据、问题和下一步；不要重新执行已经完成的工作。"
        ),
    }[role]
    if artifact_required:
        artifact_instruction = (
            "用户明确要求文件交付。只有执行者可以创建所需的最终文件；审阅者只核验，"
            "最终汇报者只引用执行者产物，不得重复生成同一文件。"
        )
    else:
        artifact_instruction = (
            "本任务没有文件交付要求。不得创建或上传交付文件，直接在会话中报告文字结果。"
        )
    return (
        "你正在 Hermes 官方 WebUI 的多智能体群聊中。\n"
        f"群聊名称：{room.get('name') or '群聊'}\n"
        f"当前身份：{profile}\n"
        f"参与 Profiles：{members}\n"
        f"{role_instruction}\n"
        f"{artifact_instruction}\n"
        f"{hosted_progress_protocol(profile)}\n"
        f"{hosted_role_delivery_contract(role)}\n"
        f"{mention_priority_protocol(profile)}\n"
        "请使用简体中文，避免机械重复其他成员。\n\n"
        f"最近讨论：\n{recent or '暂无'}\n\n"
        f"用户的新消息：\n{user_message.strip()}"
    )


def build_single_prompt(
    conversation: dict[str, Any],
    profile: str,
    user_message: str,
    *,
    include_projected_history: bool = True,
    exclude_message_id: str = "",
) -> str:
    history = (
        conversation.get("messages")
        if isinstance(conversation.get("messages"), list)
        else []
    )
    excluded_id = str(exclude_message_id or "").strip()
    if excluded_id:
        history = [
            item
            for item in history
            if not (
                isinstance(item, dict)
                and str(item.get("id") or "").strip() == excluded_id
            )
        ]
    recent = (
        "\n".join(_message_line(item) for item in history[-_PROMPT_HISTORY:])
        if include_projected_history
        else ""
    )
    planning_guidance = (
        "Planning behavior: for a request with 3 or more actionable steps, or multiple "
        "tasks, call the todo tool before execution. Keep exactly one item in_progress "
        "and update the list immediately after each step. Do not create a todo list for "
        "ordinary single-step chat."
    )
    return (
        f"{planning_guidance}\n\n"
        "你正在 Hermes 官方 WebUI 单聊中。\n"
        f"当前 Hermes Profile：{profile}\n"
        "请使用简体中文直接回答并执行用户请求。你仍可使用该 Profile 已配置的"
        "模型、Skill、MCP、记忆和工具。回复应清晰说明结果、关键过程与错误。\n\n"
        f"最近对话：\n{recent or '暂无'}\n\n"
        f"用户的新消息：\n{user_message.strip()}"
    )


def consume_profile_event_stream(
    lines: Any,
    event_callback: Optional[Callable[[dict[str, Any]], None]] = None,
) -> str:
    """Consume the profile runner's JSONL protocol without parsing display logs."""
    final_response = ""
    for raw_line in lines:
        line = str(raw_line or "").strip()
        if not line:
            continue
        try:
            event = json.loads(line)
        except (TypeError, ValueError):
            continue
        if not isinstance(event, dict) or not isinstance(event.get("type"), str):
            continue
        payload = event.get("payload")
        if not isinstance(payload, dict):
            event["payload"] = {}
            payload = event["payload"]
        if event_callback is not None:
            event_callback(event)
        if event["type"] == "message.complete":
            final_response = _structured_text(payload.get("text"))
            if str(payload.get("status") or "").lower() == "error":
                raise RuntimeError(
                    sanitize_runtime_error(final_response or "Hermes 执行失败")
                )
        elif event["type"] == "error":
            raise RuntimeError(sanitize_runtime_error(payload.get("message")))
    return final_response


_PROFILE_RETRY_STATUS_RE = re.compile(r"\((\d+)\s*/\s*(\d+)\)")
_PROFILE_TERMINAL_STATUS_MARKERS = (
    "api failed after",
    "rate limited after",
    "non-retryable error",
    "max retries",
)


def _profile_status_event(kind: Any, text: Any) -> Optional[dict[str, Any]]:
    """Normalize agent lifecycle callbacks for the hosted event protocol."""

    status_text = str(text or kind or "").strip()
    if not status_text:
        return None
    retry_match = _PROFILE_RETRY_STATUS_RE.search(status_text)
    if retry_match and (
        "重连" in status_text
        or "retry" in status_text.lower()
        or "reconnect" in status_text.lower()
    ):
        try:
            attempt_offset = max(
                0, int(os.environ.get("HERMES_API_RETRY_ATTEMPT_OFFSET", "0") or 0)
            )
        except (TypeError, ValueError):
            attempt_offset = 0
        return {
            "type": "connection.retry",
            "payload": {
                "attempt": min(
                    _HOSTED_CHAT_API_ATTEMPTS,
                    attempt_offset + int(retry_match.group(1)),
                ),
                "max_attempts": _HOSTED_CHAT_API_ATTEMPTS,
            },
        }
    lowered = status_text.lower()
    if status_text.startswith("❌") or any(
        marker in lowered for marker in _PROFILE_TERMINAL_STATUS_MARKERS
    ):
        # message.complete is the single persisted terminal error. Emitting the
        # lifecycle summary too creates a duplicate error row in the activity
        # fold and briefly races the final assistant message in the client.
        return None
    return {
        "type": "status.update",
        "payload": {"status": str(kind or ""), "text": status_text},
    }


def _legacy_profile_turn(
    profile: str,
    prompt: str,
    *,
    runner: Callable[..., Any],
    hermes_bin: str,
    kanban_task_id: Optional[str] = None,
) -> str:
    command = [
        hermes_bin,
        "-p",
        profile,
        "chat",
        "-Q",
        "-q",
        prompt,
        "--source",
        "dashboard-group",
        "--max-turns",
        "45",
    ]
    env = {**os.environ, "HOME": os.environ.get("HOME", "/home/hermes")}
    if kanban_task_id:
        env["HERMES_KANBAN_TASK"] = kanban_task_id
    else:
        env.pop("HERMES_KANBAN_TASK", None)
    result = runner(
        command,
        shell=False,
        capture_output=True,
        text=True,
        timeout=600,
        env=env,
    )
    if result.returncode != 0:
        error = result.stderr or result.stdout or "Hermes profile execution failed"
        raise RuntimeError(sanitize_runtime_error(error))
    response = (result.stdout or "").strip()
    if not response:
        raise RuntimeError("Hermes profile returned an empty response")
    return response


def _hosted_runtime_home(
    profile: str,
    artifact_context: Optional[dict[str, Any]] = None,
) -> str:
    from hermes_cli.profiles import resolve_profile_env

    runtime_home = str(resolve_profile_env(profile))
    runtime_owner = str((artifact_context or {}).get("owner_id") or "").strip()
    runtime_generation = str(
        (artifact_context or {}).get("account_generation") or ""
    ).strip()
    if runtime_owner and runtime_owner != LOCAL_OWNER_ID:
        try:
            runtime_home = str(
                _backend_api().managed_account_runtime_home(
                    runtime_owner,
                    runtime_generation,
                    profile,
                    base_profile_home=Path(runtime_home),
                )
            )
        except PermissionError as exc:
            raise RuntimeError("stale hosted turn account generation") from exc
    return runtime_home


_HOSTED_PREWARM_LOCK = threading.Lock()
_HOSTED_PREWARM_INFLIGHT: set[tuple[str, str, str, str, bool]] = set()


def _prewarm_hosted_chat(
    conversation: dict[str, Any],
    *,
    allow_tools: bool = True,
) -> None:
    """Start the official Hermes 0.20 gateway while the user is reading or typing."""

    owner_id = str(conversation.get("owner_id") or LOCAL_OWNER_ID).strip()
    account_generation = str(conversation.get("account_generation") or "").strip()
    conversation_id = str(conversation.get("id") or "").strip()
    profile = str(conversation.get("profile") or "default").strip() or "default"
    if not conversation_id or not account_generation or conversation.get("delete_requested"):
        return
    key = (owner_id, account_generation, conversation_id, profile, bool(allow_tools))
    with _HOSTED_PREWARM_LOCK:
        if key in _HOSTED_PREWARM_INFLIGHT:
            return
        _HOSTED_PREWARM_INFLIGHT.add(key)

    runtime_session_id = str(
        (conversation.get("runtime_sessions") or {}).get(profile) or ""
    ).strip()

    def _run() -> None:
        try:
            artifact_context = {
                "owner_id": owner_id,
                "account_generation": account_generation,
            }
            prewarm_hosted_gateway(
                runtime_home=_hosted_runtime_home(profile, artifact_context),
                owner_id=owner_id,
                account_generation=account_generation,
                conversation_id=conversation_id,
                profile=profile,
                artifact_root=str(get_hermes_home()),
                import_root=_RUNTIME_IMPORT_ROOT,
                requested_session_id=runtime_session_id,
                allow_tools=allow_tools,
                extra_env={
                    "HERMES_API_MAX_RETRIES": str(_HOSTED_CHAT_API_ATTEMPTS),
                    "HERMES_API_RETRY_CLIENT_ERRORS": "1",
                    "HERMES_API_RETRY_DELAY_SECONDS": str(
                        _HOSTED_CHAT_API_RETRY_DELAY_SECONDS
                    ),
                    "HERMES_API_RETRY_STATUS_LIVE": "1",
                },
            )
        except Exception:
            logging.getLogger(__name__).warning(
                "Hermes 0.20 hosted chat pre-warm failed for %s",
                conversation_id,
                exc_info=True,
            )
        finally:
            with _HOSTED_PREWARM_LOCK:
                _HOSTED_PREWARM_INFLIGHT.discard(key)

    threading.Thread(
        target=_run,
        name=f"hermes-prewarm-{conversation_id[-12:]}",
        daemon=True,
    ).start()


def _hosted_conversation_prewarm_allows_tools(
    conversation: dict[str, Any],
) -> bool:
    """Keep existing work conversations fully capable while opening chat fast.

    A newly-created single conversation has no message that can require an
    MCP tool, so its background session can skip discovery.  Once a
    conversation contains an explicit work/tool turn, retain the normal
    capability-rich prewarm when the user reopens it.
    """

    hosted_turns = conversation.get("hosted_turns")
    if isinstance(hosted_turns, dict):
        for run in hosted_turns.values():
            if isinstance(run, dict) and _hosted_turn_allows_tools(run):
                return True
    messages = conversation.get("messages")
    if isinstance(messages, list):
        for message in messages:
            if not isinstance(message, dict):
                continue
            meta = message.get("meta")
            if isinstance(meta, dict) and (
                _coerce_flag(meta.get("artifact_required"))
                or any(str(item).strip() for item in meta.get("attachments") or [])
            ):
                return True
    return False


def run_profile_turn(
    profile: str,
    prompt: str,
    *,
    runner: Optional[Callable[..., Any]] = None,
    hermes_bin: str = "/usr/local/bin/hermes",
    event_callback: Optional[Callable[[dict[str, Any]], None]] = None,
    process_factory: Callable[..., Any] = subprocess.Popen,
    timeout: float = _HOSTED_CHAT_TIMEOUT_SECONDS,
    kanban_task_id: Optional[str] = None,
    session_id: str = "",
    cancel_check: Optional[Callable[[], bool]] = None,
    action: str = "chat",
    focus_topic: str = "",
    artifact_context: Optional[dict[str, str]] = None,
) -> str:
    """Run a profile through a structured JSONL child event channel."""
    if runner is not None:
        if action != "chat":
            raise ValueError("legacy profile runner only supports chat")
        return _legacy_profile_turn(
            profile,
            prompt,
            runner=runner,
            hermes_bin=hermes_bin,
            kanban_task_id=kanban_task_id,
        )

    runtime_home = _hosted_runtime_home(profile, artifact_context)
    env = {
        **os.environ,
        "HOME": os.environ.get("HOME", "/home/hermes"),
        "HERMES_HOME": runtime_home,
        "HERMES_SESSION_SOURCE": "dashboard-group",
        # Keep the temporary fallback runner on the same full-schema/lazy-MCP
        # contract as the persistent TUI gateway. It must not probe every
        # configured service before the first model token.
        "HERMES_FULL_TOOL_DEFINITIONS": "1",
        "HERMES_API_MAX_RETRIES": str(_HOSTED_CHAT_API_ATTEMPTS),
        "HERMES_API_RETRY_CLIENT_ERRORS": "1",
        "HERMES_API_RETRY_DELAY_SECONDS": str(_HOSTED_CHAT_API_RETRY_DELAY_SECONDS),
        "HERMES_API_RETRY_STATUS_LIVE": "1",
    }
    inherited_pythonpath = str(env.get("PYTHONPATH") or "").strip()
    pythonpath_entries = [_RUNTIME_IMPORT_ROOT]
    if inherited_pythonpath:
        pythonpath_entries.extend(inherited_pythonpath.split(os.pathsep))
    env["PYTHONPATH"] = os.pathsep.join(dict.fromkeys(pythonpath_entries))
    if kanban_task_id:
        env["HERMES_KANBAN_TASK"] = kanban_task_id
    else:
        env.pop("HERMES_KANBAN_TASK", None)
    if artifact_context:
        retry_deadline_at = int(artifact_context.get("model_retry_deadline_at") or 0)
        retry_attempt_offset = max(
            0, int(artifact_context.get("model_retry_attempt") or 0)
        )
        remaining_attempts = max(1, _HOSTED_CHAT_API_ATTEMPTS - retry_attempt_offset)
        env.update(
            {
                "HERMES_TOOL_ARTIFACT_ROOT": str(
                    artifact_context.get("root") or get_hermes_home()
                ),
                "HERMES_TOOL_ARTIFACT_OWNER": str(
                    artifact_context.get("owner_id") or ""
                ),
                "HERMES_TOOL_ARTIFACT_CONVERSATION": str(
                    artifact_context.get("conversation_id") or ""
                ),
                "HERMES_TOOL_ARTIFACT_TURN": str(
                    artifact_context.get("turn_id") or ""
                ),
                "HERMES_ACCOUNT_GENERATION": str(
                    artifact_context.get("account_generation") or ""
                ),
                "HERMES_API_MAX_RETRIES": str(remaining_attempts),
                "HERMES_API_RETRY_ATTEMPT_OFFSET": str(retry_attempt_offset),
                "HERMES_API_RETRY_DEADLINE_EPOCH_MS": str(retry_deadline_at),
            }
        )
    if (
        action == "chat"
        and process_factory is subprocess.Popen
        and not kanban_task_id
        and artifact_context
        and str(artifact_context.get("conversation_id") or "").strip()
    ):
        try:
            return run_hosted_gateway_turn(
                prompt,
                runtime_home=str(runtime_home),
                owner_id=str(artifact_context.get("owner_id") or ""),
                account_generation=str(
                    artifact_context.get("account_generation") or ""
                ),
                conversation_id=str(artifact_context.get("conversation_id") or ""),
                turn_id=str(artifact_context.get("turn_id") or ""),
                profile=profile,
                artifact_root=str(
                    artifact_context.get("root") or get_hermes_home()
                ),
                import_root=_RUNTIME_IMPORT_ROOT,
                requested_session_id=str(session_id or ""),
                allow_tools=str(
                    artifact_context.get("allow_tools", "1")
                ).strip().lower() not in {"0", "false", "no", "off"},
                event_callback=event_callback,
                cancel_check=cancel_check,
                timeout=timeout,
                extra_env={
                    "HERMES_API_MAX_RETRIES": env["HERMES_API_MAX_RETRIES"],
                    "HERMES_API_RETRY_CLIENT_ERRORS": "1",
                    "HERMES_API_RETRY_DELAY_SECONDS": env[
                        "HERMES_API_RETRY_DELAY_SECONDS"
                    ],
                    "HERMES_API_RETRY_STATUS_LIVE": "1",
                    "HERMES_API_RETRY_ATTEMPT_OFFSET": str(
                        env.get("HERMES_API_RETRY_ATTEMPT_OFFSET") or "0"
                    ),
                    # Hosted server-side roles (reporter, server fallback) use
                    # the same provider stale-stream safety as normal turns:
                    # deepseek-v4-flash has a 600s reasoning floor, so long
                    # internal prompts are not killed by an artificial 120s
                    # fail-fast timeout. The product's existing stale detector
                    # still bounds a genuinely wedged connection.
                    "HERMES_API_RETRY_DEADLINE_EPOCH_MS": str(
                        env.get("HERMES_API_RETRY_DEADLINE_EPOCH_MS") or "0"
                    ),
                },
            )
        except HostedTuiGatewayCancelled as exc:
            raise _HostedTurnCancelled("Hosted turn cancelled") from exc

    command = [sys.executable, str(Path(__file__).resolve()), "--profile-event-runner"]
    deadline = time.monotonic() + timeout
    process = process_factory(
        command,
        shell=False,
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        bufsize=1,
        env=env,
    )
    if process.stdin is None or process.stdout is None:
        process.kill()
        raise RuntimeError("Hermes 结构化执行通道启动失败")
    line_queue: queue.Queue[Optional[str]] = queue.Queue()
    writer_errors: queue.Queue[BaseException] = queue.Queue(maxsize=1)
    stderr_tail: list[str] = []
    stderr_tail_chars = 0

    def _write_stdin() -> None:
        try:
            process.stdin.write(
                json.dumps(
                    {
                        "prompt": prompt,
                        "session_id": str(session_id or "").strip(),
                        "action": str(action or "chat").strip().lower(),
                        "focus_topic": str(focus_topic or "").strip(),
                        "capability_hints": [
                            str(item)
                            for item in (artifact_context or {}).get(
                                "capability_hints", []
                            )
                            if str(item).strip()
                        ],
                        "allow_tools": str(
                            (artifact_context or {}).get("allow_tools", "1")
                        ).strip().lower() not in {"0", "false", "no"},
                    },
                    ensure_ascii=False,
                )
            )
            process.stdin.close()
        except BaseException as exc:
            writer_errors.put(exc)

    def _read_stdout() -> None:
        try:
            for line in process.stdout:
                line_queue.put(line)
        finally:
            line_queue.put(None)

    def _read_stderr() -> None:
        nonlocal stderr_tail_chars
        if process.stderr is None:
            return
        while True:
            try:
                chunk = process.stderr.read(4096)
            except TypeError:
                chunk = process.stderr.read()
            except BaseException:
                return
            if not chunk:
                return
            stderr_tail.append(chunk)
            stderr_tail_chars += len(chunk)
            while stderr_tail and stderr_tail_chars > _HOSTED_STDERR_TAIL_CHARS:
                overflow = stderr_tail_chars - _HOSTED_STDERR_TAIL_CHARS
                if overflow >= len(stderr_tail[0]):
                    stderr_tail_chars -= len(stderr_tail.pop(0))
                else:
                    stderr_tail[0] = stderr_tail[0][overflow:]
                    stderr_tail_chars -= overflow

    writer = threading.Thread(target=_write_stdin, daemon=True)
    reader = threading.Thread(target=_read_stdout, daemon=True)
    stderr_reader = threading.Thread(target=_read_stderr, daemon=True)
    writer.start()
    reader.start()
    stderr_reader.start()

    first_model_event = False
    retry_deadline_at = int((artifact_context or {}).get("model_retry_deadline_at") or 0)

    def _forward_event(event: dict[str, Any]) -> None:
        nonlocal first_model_event
        if str(event.get("type") or "") in {
            "message.delta",
            "message.complete",
            "reasoning.delta",
            "thinking.delta",
            "tool.start",
            "subagent.start",
        }:
            first_model_event = True
        if event_callback is not None:
            event_callback(event)

    def _iter_lines():
        while True:
            if cancel_check is not None and cancel_check():
                raise _HostedTurnCancelled("Hosted turn cancelled")
            if not writer_errors.empty():
                raise RuntimeError("Hermes 结构化执行输入失败") from writer_errors.get()
            remaining = deadline - time.monotonic()
            if retry_deadline_at > 0 and not first_model_event:
                remaining = min(
                    remaining,
                    (retry_deadline_at - int(time.time() * 1000)) / 1000,
                )
            if remaining <= 0:
                if retry_deadline_at > 0 and not first_model_event:
                    raise TimeoutError("Model connection exceeded the 120 second retry budget")
                raise TimeoutError("Hermes profile execution timed out")
            try:
                line = line_queue.get(timeout=min(1.0, remaining))
            except queue.Empty:
                if process.poll() is not None and line_queue.empty():
                    return
                continue
            if line is None:
                return
            yield line

    try:
        response = consume_profile_event_stream(_iter_lines(), _forward_event)
        remaining = min(float(timeout), deadline - time.monotonic())
        if remaining <= 0:
            raise TimeoutError("Hermes profile execution timed out")
        return_code = process.wait(timeout=remaining)
    except Exception:
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                process.kill()
        stderr_reader.join(timeout=1)
        raise
    stderr_reader.join(timeout=1)
    stderr = "".join(stderr_tail).strip()
    if return_code != 0:
        raise RuntimeError(sanitize_runtime_error(stderr or "Hermes profile execution failed"))
    if not response:
        raise RuntimeError("Hermes profile returned an empty response")
    return response


def run_single_turn(
    profile: str,
    prompt: str,
    *,
    runner: Callable[..., Any] = subprocess.run,
    hermes_bin: str = "/usr/local/bin/hermes",
) -> str:
    command = [
        hermes_bin,
        "-p",
        profile,
        "chat",
        "-Q",
        "-q",
        prompt,
        "--source",
        "dashboard-single",
        "--max-turns",
        "45",
    ]
    result = runner(
        command,
        shell=False,
        capture_output=True,
        text=True,
        timeout=600,
        env={**os.environ, "HOME": os.environ.get("HOME", "/home/hermes")},
    )
    if result.returncode != 0:
        error = (
            result.stderr
            or result.stdout
            or "Hermes profile execution failed"
        ).strip()
        raise RuntimeError(error[-2000:])
    response = (result.stdout or "").strip()
    if not response:
        raise RuntimeError("Hermes profile returned an empty response")
    return response


def _append_event_delta(current: str, delta: Any) -> str:
    text = str(delta or "")
    if not text:
        return current
    if current and text.startswith(current):
        return text
    return current + text


def _activity_by_id_or_name(
    activities: list[dict[str, Any]],
    activity_id: str,
    name: str,
) -> Optional[dict[str, Any]]:
    if activity_id:
        for activity in reversed(activities):
            if str(activity.get("id") or "") == activity_id:
                return activity
    for activity in reversed(activities):
        if activity.get("status") == "running" and activity.get("name") == name:
            return activity
    return None


def _new_activity_id(prefix: str, activities: list[dict[str, Any]]) -> str:
    return f"{prefix}-{int(time.time() * 1000)}-{len(activities) + 1}"


_SUBAGENT_ID_FIELDS = ("child_session_id", "subagent_id", "task_id", "id")
_SUBAGENT_STREAM_EVENTS = {"subagent.text", "subagent.thinking"}


def _subagent_identity_values(payload: dict[str, Any]) -> list[str]:
    values: list[str] = []
    for field in _SUBAGENT_ID_FIELDS:
        value = str(payload.get(field) or "").strip()
        if value and value not in values:
            values.append(value)
    return values


def _subagent_activity(
    activities: list[dict[str, Any]],
    payload: dict[str, Any],
    name: str,
) -> tuple[Optional[dict[str, Any]], list[str]]:
    identities = _subagent_identity_values(payload)
    if identities:
        identity_set = set(identities)
        for activity in reversed(activities):
            if activity.get("kind") != "subagent":
                continue
            known = {
                str(activity.get("id") or "").strip(),
                *(
                    str(value or "").strip()
                    for value in activity.get("identity_ids") or []
                ),
            }
            if identity_set.intersection(known):
                return activity, identities
        return None, identities

    # Legacy progress events may not carry any identity. Reuse one existing
    # activity instead of manufacturing a new row for every progress update.
    same_name = [
        activity
        for activity in activities
        if activity.get("kind") == "subagent" and activity.get("name") == name
    ]
    for activity in reversed(same_name):
        if activity.get("status") == "running":
            return activity, identities
    return (same_name[-1] if same_name else None), identities


def _append_subagent_event(
    activity: dict[str, Any],
    event_type: str,
    payload: dict[str, Any],
    text: str,
    now: int,
) -> None:
    events = activity.setdefault("events", [])
    if not isinstance(events, list):
        events = []
        activity["events"] = events

    if (
        event_type in _SUBAGENT_STREAM_EVENTS
        and events
        and isinstance(events[-1], dict)
        and events[-1].get("type") == event_type
    ):
        event = events[-1]
        event["text"] = _append_event_delta(str(event.get("text") or ""), text)
        event["updated_at"] = now
    else:
        event: dict[str, Any] = {
            "type": event_type,
            "timestamp": int(payload.get("timestamp") or now),
        }
        if text:
            event["text"] = text
        tool_name = str(payload.get("tool_name") or "").strip()
        if event_type == "subagent.tool":
            tool_name = tool_name or str(payload.get("name") or "").strip()
        if tool_name:
            event["tool_name"] = tool_name
        if payload.get("args") is not None:
            event["args"] = payload.get("args")
        status = str(payload.get("status") or "").strip()
        if status:
            event["status"] = status
        events.append(event)

    transcript: list[str] = []
    for item in events:
        if not isinstance(item, dict):
            continue
        item_text = _structured_text(item.get("text"))
        item_type = str(item.get("type") or "")
        if item_type == "subagent.tool":
            tool_name = str(item.get("tool_name") or "tool")
            args = _structured_text(item.get("args"))
            detail = item_text or args
            transcript.append(f"{tool_name}: {detail}" if detail else tool_name)
        elif item_type == "subagent.complete":
            if item_text:
                transcript.append(f"Final: {item_text}")
        elif item_text:
            transcript.append(item_text)
    activity["output"] = "\n".join(transcript)


def _subagent_event_text(payload: dict[str, Any], *fields: str) -> str:
    for field in fields:
        value = payload.get(field)
        if value is None or value == "":
            continue
        # Stream callbacks carry meaningful leading/trailing whitespace in
        # string deltas. _structured_text intentionally strips it, so preserve
        # raw strings here and only structure non-string payloads.
        return value if isinstance(value, str) else _structured_text(value)
    return ""


def apply_profile_event(
    state: dict[str, Any],
    event: dict[str, Any],
) -> dict[str, Any]:
    """Reduce one structured Hermes event into a persistable role snapshot."""
    event_type = str(event.get("type") or "")
    payload = event.get("payload")
    payload = payload if isinstance(payload, dict) else {}
    activities = state.setdefault("activities", [])
    now = int(time.time() * 1000)

    def finish_retry_activity(status: str = "completed") -> None:
        for item in activities:
            if item.get("id") != "model-connection-retry":
                continue
            if item.get("status") == "running":
                item["status"] = status
                item["ended_at"] = now
                item["duration_ms"] = max(
                    0,
                    now - int(item.get("started_at") or now),
                )
            return

    def clear_transient_model_status_activities(*, clear_retry: bool) -> None:
        activities[:] = [
            item
            for item in activities
            if (
                item.get("id") != "model-runtime-status"
                and not str(item.get("id") or "").startswith("model-readiness-")
                and not (
                    clear_retry
                    and item.get("id") == "model-connection-retry"
                )
            )
        ]

    def is_model_spinner(text: str) -> bool:
        """Recognize gateway lifecycle text without hiding real reasoning."""
        normalized = " ".join(str(text or "").strip().lower().split())
        if not normalized:
            return True
        if normalized in {
            "thinking...",
            "reflecting...",
            "mulling...",
            "正在思考",
            "思考中",
            "正在连接模型",
            "连接模型中",
        }:
            return True
        # Hermes emits animated face/status prefixes such as
        # ``(◔_◔) mulling...`` while it is waiting for model output.
        return normalized.startswith("(") and (
            "mull" in normalized
            or "think" in normalized
            or normalized.endswith("...")
        )

    # Providers do not all use the same field for streamed model text.  Keep
    # the first-token boundary tied to real visible output while accepting the
    # delta/output/reasoning variants emitted by the official runtime.
    event_text = _structured_text(
        payload.get("text")
        or payload.get("delta")
        or payload.get("output")
        or payload.get("reasoning")
        or payload.get("content")
        or payload.get("message")
    )
    thinking_is_reasoning = event_type == "thinking.delta" and not is_model_spinner(
        event_text
    )
    text_started_execution = (
        event_type in {"message.delta", "reasoning.delta", "reasoning.available"}
        or thinking_is_reasoning
    ) and bool(event_text)
    if text_started_execution and not int(state.get("first_token_at") or 0):
        # Only real reasoning/message text starts the user-visible model clock.
        # Tool/MCP progress is execution detail and can precede the first token
        # by seconds; counting it makes cold-start latency look misleading.
        state["first_token_at"] = now

    if text_started_execution or event_type in {
        "error",
        "message.complete",
    }:
        terminal_error = (
            event_type == "error"
            or (
                event_type == "message.complete"
                and str(payload.get("status") or "").lower() == "error"
            )
        )
        clear_transient_model_status_activities(clear_retry=not terminal_error)

    if event_type in {"session.info", "request.accepted"}:
        if event_type == "request.accepted" and not int(state.get("model_started_at") or 0):
            state["model_started_at"] = now
        if event_type == "request.accepted":
            state["request_accepted"] = True
            state["request_accepted_at"] = int(state.get("request_accepted_at") or now)
        state["runtime_session_id"] = str(
            payload.get("session_id") or state.get("runtime_session_id") or ""
        ).strip()
        state["actual_model"] = str(payload.get("model") or state.get("actual_model") or "")
        state["actual_provider"] = str(
            payload.get("provider") or state.get("actual_provider") or ""
        )
    elif event_type == "provider.registered":
        witness_ref = _provider_witness_ref(payload)
        if witness_ref:
            runtime = state.setdefault("_runtime_metadata", {})
            refs = [
                str(item).strip()
                for item in runtime.get("provider_refs") or []
                if str(item).strip()
            ]
            if witness_ref not in refs:
                refs.append(witness_ref)
            runtime["provider_refs"] = refs
            # Keep the top-level durable projection in sync.  Subsequent
            # protocol events are built from this projection, not from a
            # transient child-process event, so the exact provider generation
            # remains visible for the whole turn.
            state["provider_refs"] = list(refs)
            bindings = state.setdefault("provider_bindings", {})
            if isinstance(bindings, dict):
                bindings[str(payload.get("interface_key") or witness_ref)] = {
                    "provider_id": str(payload.get("provider_id") or ""),
                    "generation": int(payload.get("generation") or 0),
                    "interface_key": str(payload.get("interface_key") or ""),
                    "status": str(payload.get("status") or ""),
                }
    elif event_type in {
        "reasoning.delta",
        "reasoning.available",
    } or thinking_is_reasoning:
        finish_retry_activity()
        text = event_text
        if text:
            activity = next(
                (
                    item
                    for item in reversed(activities)
                    if item.get("kind") == "reasoning" and item.get("status") == "running"
                ),
                None,
            )
            if activity is None:
                activity = {
                    "id": _new_activity_id("reasoning", activities),
                    "kind": "reasoning",
                    "category": "reasoning",
                    "name": "模型思考",
                    "input": "",
                    "output": "",
                    "status": "running",
                    "started_at": payload.get("started_at") or now,
                    "ended_at": None,
                }
                activities.append(activity)
            activity["output"] = _append_event_delta(
                str(activity.get("output") or ""), text
            )
            if event_type == "reasoning.available":
                activity["status"] = "completed"
                activity["ended_at"] = payload.get("ended_at") or now
                activity["duration_ms"] = max(
                    0,
                    int(activity["ended_at"]) - int(activity["started_at"]),
                )
    elif event_type == "message.delta":
        finish_retry_activity()
        for activity in reversed(activities):
            if activity.get("kind") == "reasoning" and activity.get("status") == "running":
                activity["status"] = "completed"
                activity["ended_at"] = now
                activity["duration_ms"] = max(
                    0,
                    now - int(activity.get("started_at") or now),
                )
                break
        state["content"] = _append_event_delta(
            str(state.get("content") or ""), event_text
        )
    elif event_type in {"tool.generating", "tool.progress"}:
        name = str(payload.get("name") or "工具调用")
        activity = _activity_by_id_or_name(
            activities,
            str(payload.get("tool_id") or ""),
            name,
        )
        if activity is None and event_type == "tool.generating":
            state["updated_at"] = now
            return state
        if activity is None:
            activity = {
                "id": str(payload.get("tool_id") or _new_activity_id("tool", activities)),
                "kind": "tool",
                "category": _tool_category(name),
                "name": name,
                "input": "",
                "output": "",
                "status": "running",
                "started_at": now,
                "ended_at": None,
            }
            activities.append(activity)
        activity["preview"] = _structured_text(
            payload.get("preview") or payload.get("message")
        )[:1000]
    elif event_type == "tool.start":
        finish_retry_activity()
        name = str(payload.get("name") or "工具调用")
        activity_id = str(payload.get("tool_id") or "")
        activity = _activity_by_id_or_name(activities, activity_id, name)
        if activity is None:
            activity = {
                "id": activity_id or _new_activity_id("tool", activities),
                "kind": "tool",
                "category": _tool_category(name),
                "name": name,
                "input": "",
                "output": "",
                "status": "running",
                "started_at": payload.get("started_at") or now,
                "ended_at": None,
            }
            activities.append(activity)
        activity.update(
            {
                "id": activity_id or activity.get("id"),
                "category": _tool_category(name),
                "name": name,
                "input": _structured_text(
                    payload.get("args") or payload.get("input") or payload.get("context")
                )[:8000],
                "status": "running",
                "started_at": activity.get("started_at") or payload.get("started_at") or now,
                "ended_at": None,
            }
        )
    elif event_type == "tool.complete":
        name = str(payload.get("name") or "工具调用")
        activity_id = str(payload.get("tool_id") or "")
        activity = _activity_by_id_or_name(activities, activity_id, name)
        if activity is None:
            activity = {
                "id": activity_id or _new_activity_id("tool", activities),
                "kind": "tool",
                "category": _tool_category(name),
                "name": name,
                "input": _structured_text(payload.get("args"))[:8000],
                "started_at": payload.get("started_at") or now,
            }
            activities.append(activity)
        error = _structured_text(payload.get("error"))
        activity.update(
            {
                "output": _structured_text(
                    payload.get("result_text")
                    or payload.get("result")
                    or payload.get("summary")
                )[-20_000:],
                "preview": _structured_text(payload.get("summary"))[:1000],
                "error": sanitize_runtime_error(error) if error else "",
                "status": "failed" if error else "completed",
                "ended_at": payload.get("ended_at") or now,
            }
        )
        if isinstance(payload.get("duration_s"), (int, float)):
            activity["duration_ms"] = round(float(payload["duration_s"]) * 1000)
        elif activity.get("started_at"):
            activity["duration_ms"] = max(
                0,
                int(activity["ended_at"]) - int(activity["started_at"]),
            )
    elif event_type.startswith("subagent."):
        name = str(payload.get("name") or payload.get("model") or "子 Agent")
        activity, identities = _subagent_activity(activities, payload, name)
        if activity is None:
            activity = {
                "id": identities[0] if identities else _new_activity_id("subagent", activities),
                "kind": "subagent",
                "category": "subagent",
                "name": name,
                "input": _structured_text(payload.get("goal") or payload.get("args"))[:8000],
                "output": "",
                "events": [],
                "status": "running",
                "started_at": now,
                "ended_at": None,
            }
            activities.append(activity)
        if identities:
            known_identities = [
                str(value or "").strip()
                for value in activity.get("identity_ids") or []
                if str(value or "").strip()
            ]
            for identity in identities:
                if identity not in known_identities:
                    known_identities.append(identity)
            activity["identity_ids"] = known_identities
            # child_session_id is the durable inspection target and therefore
            # becomes the public activity id when it is available.
            activity["id"] = identities[0]
            if payload.get("child_session_id"):
                activity["child_session_id"] = str(payload["child_session_id"])
        if event_type == "subagent.complete":
            text = _subagent_event_text(payload, "summary", "text", "preview")
        else:
            text = _subagent_event_text(payload, "text", "preview", "summary")
        _append_subagent_event(activity, event_type, payload, text, now)
        if text:
            activity["preview"] = text[:1000]
        if event_type == "subagent.complete":
            activity.update(
                {
                    "status": "failed"
                    if str(payload.get("status") or "").lower() in {"failed", "error"}
                    else "completed",
                    "ended_at": now,
                    "duration_ms": round(float(payload.get("duration_seconds") or 0) * 1000),
                }
            )
    elif event_type == "status.update":
        text = _structured_text(payload.get("text") or payload.get("status"))
        if text and not int(state.get("first_token_at") or 0):
            activity = next(
                (
                    item
                    for item in reversed(activities)
                    if item.get("id") == "model-runtime-status"
                ),
                None,
            )
            if activity is None:
                activity = {
                    "id": "model-runtime-status",
                    "kind": "status",
                    "category": "other",
                    "name": "运行状态",
                    "started_at": now,
                }
                activities.append(activity)
            activity.update(
                {
                    "output": text[:4000],
                    "status": "running",
                    "ended_at": None,
                    "duration_ms": max(0, now - int(activity.get("started_at") or now)),
                }
            )
    elif event_type == "connection.retry":
        attempt = max(1, int(payload.get("attempt") or 1))
        max_attempts = max(attempt, int(payload.get("max_attempts") or _HOSTED_CHAT_API_ATTEMPTS))
        activity = next(
            (
                item
                for item in reversed(activities)
                if item.get("id") == "model-connection-retry"
            ),
            None,
        )
        if activity is None:
            activity = {
                "id": "model-connection-retry",
                "kind": "status",
                "category": "other",
                "name": "运行状态",
                "started_at": now,
            }
            activities.append(activity)
        activity.update(
            {
                "name": f"正在重新连接 ({attempt}/{max_attempts})",
                # Intermediate causes stay server-side. The fifth failure is
                # persisted once as the terminal assistant error.
                "output": "",
                "status": "running",
                "ended_at": None,
                "duration_ms": 0,
                "attempt": attempt,
                "max_attempts": max_attempts,
            }
        )
        state["model_retry_attempt"] = attempt
        state["model_retry_max_attempts"] = max_attempts
    elif event_type == "message.complete":
        finish_retry_activity(
            "failed"
            if str(payload.get("status") or "").lower() == "error"
            else "completed"
        )
        final_text = _structured_text(
            payload.get("text")
            or payload.get("output")
            or payload.get("content")
            or payload.get("message")
        )
        if final_text:
            state["content"] = final_text
            if (
                str(payload.get("status") or "").lower() != "error"
                and not int(state.get("first_token_at") or 0)
            ):
                # Some providers expose only a terminal message instead of
                # streaming deltas. Its arrival is the first visible model
                # output, so it is also the correct first-token boundary.
                state["first_token_at"] = now
        state["runtime_session_id"] = str(
            payload.get("session_id") or state.get("runtime_session_id") or ""
        ).strip()
        state["status"] = (
            "failed" if str(payload.get("status") or "").lower() == "error" else "completed"
        )
    elif event_type == "error":
        finish_retry_activity("failed")
        state["error"] = sanitize_runtime_error(payload.get("message"))
        state["status"] = "failed"

    state["updated_at"] = now
    return state


def _queue_hosted_protocol_event(
    state: dict[str, Any],
    event: dict[str, Any],
) -> None:
    """Stage one canonical event for the next atomic hosted-state write."""

    raw_event_type = str(event.get("type") or "").strip().lower()
    if raw_event_type == "session:compress":
        raw_payload = (
            dict(event.get("payload"))
            if isinstance(event.get("payload"), dict)
            else {}
        )
        compression_count = max(0, int(raw_payload.get("compression_count") or 0))
        session_id = str(raw_payload.get("session_id") or "").strip()
        old_session_id = str(raw_payload.get("old_session_id") or "").strip()
        pending_entries = state.setdefault("_session_entry_events", [])
        if not isinstance(pending_entries, list):
            pending_entries = []
            state["_session_entry_events"] = pending_entries
        pending_entries.append(
            {
                "entry_type": "compaction",
                "idempotency_key": (
                    f"compaction:{session_id}:{old_session_id}:{compression_count}"
                ),
                "payload": {
                    "session_id": session_id,
                    "old_session_id": old_session_id,
                    "in_place": _coerce_flag(raw_payload.get("in_place")),
                    "compression_count": compression_count,
                    "runtime": str(raw_payload.get("runtime") or "hermes"),
                    "thread_id": str(raw_payload.get("thread_id") or ""),
                    "runtime_turn_id": str(raw_payload.get("turn_id") or ""),
                },
                "occurred_at": int(time.time() * 1000),
            }
        )
        if session_id:
            state["runtime_session_id"] = session_id
        return

    event_type, payload, entity_id = normalize_legacy_profile_event(event)
    invocation = int(state.get("_protocol_invocation_index") or 0)
    if event_type == "agent.started":
        invocation += 1
        state["_protocol_invocation_index"] = invocation
        state["_saw_message_complete"] = False
        state["_protocol_started_entities"] = []
    elif invocation <= 0:
        invocation = 1
        state["_protocol_invocation_index"] = invocation
    payload = dict(payload)
    if not entity_id:
        if event_type.startswith("message."):
            entity_id = f"message-invocation-{invocation}"
        elif event_type.startswith("thinking."):
            entity_id = f"thinking-invocation-{invocation}"
        elif event_type.startswith("subagent."):
            entity_id = f"subagent-invocation-{invocation}"
        elif event_type.startswith("agent."):
            entity_id = f"agent-invocation-{invocation}"
    if entity_id:
        payload.setdefault("entity_id", entity_id)
    pending = state.setdefault("_protocol_events", [])
    if not isinstance(pending, list):
        pending = []
        state["_protocol_events"] = pending

    started_entities = {
        str(item)
        for item in state.get("_protocol_started_entities") or []
        if str(item)
    }
    start_type = {
        "message.delta": "message.started",
        "message.completed": "message.started",
        "thinking.delta": "thinking.started",
        "thinking.completed": "thinking.started",
        "subagent.progress": "subagent.started",
        "subagent.completed": "subagent.started",
        "subagent.failed": "subagent.started",
    }.get(event_type)
    started_key = f"{start_type}:{entity_id}" if start_type and entity_id else ""

    def stage(kind: str, body: dict[str, Any], staged_entity_id: str) -> None:
        next_index = int(state.get("_protocol_event_index") or 0) + 1
        state["_protocol_event_index"] = next_index
        pending.append(
            {
                "event_type": kind,
                # Profile events may contain tool arguments, connector errors,
                # or model output.  Persist the redacted projection only; the
                # runtime does not need raw credentials to replay a lifecycle.
                "payload": _redact_sensitive(body),
                "entity_id": staged_entity_id,
                "idempotency_key": (
                    f"profile-event:{next_index}:{kind}:{staged_entity_id}"
                ),
                "occurred_at": int(body.get("timestamp") or time.time() * 1000),
                "runtime": dict(state.get("_runtime_metadata") or {}),
            }
        )

    if started_key and started_key not in started_entities:
        stage(
            start_type,
            {"entity_id": entity_id, "synthetic": True},
            entity_id,
        )
        started_entities.add(started_key)
        state["_protocol_started_entities"] = sorted(started_entities)
    stage(event_type, payload, entity_id)
    if event_type == "message.completed":
        state["_saw_message_complete"] = True


def _hosted_runtime_metadata(
    state: dict[str, Any],
    *,
    turn_id: str,
    role_stage: str,
    lifecycle_state: str = "",
) -> dict[str, Any]:
    """Build typed event metadata from durable role state, never UI labels."""

    runtime_refs = (state.get("_runtime_metadata") or {}).get("provider_refs")
    provider_refs = [
        str(item).strip()
        for item in (state.get("provider_refs") or runtime_refs or [])
        if str(item).strip()
    ]
    dependency_state = state.get("dependency_state")
    return {
        "component_id": str(
            state.get("component_id") or f"fiber:{turn_id}:{role_stage}"
        ),
        "parent_component_id": str(
            state.get("parent_component_id") or f"fiber:turn:{turn_id}"
        ),
        "provider_refs": provider_refs,
        "dependency_state": _redact_sensitive(dict(dependency_state)) if isinstance(dependency_state, dict) else {},
        "lifecycle_state": str(
            lifecycle_state
            or state.get("lifecycle_state")
            or ("completed" if state.get("status") == "completed" else "failed" if state.get("status") == "failed" else "active")
        ),
        "effect_scope_id": str(state.get("effect_scope_id") or ""),
        "plan_node_id": str(state.get("plan_node_id") or role_stage),
        "artifact_refs": [
            str(item).strip()[:512]
            for item in state.get("artifact_refs") or []
            if str(item).strip()
        ],
        "contract_revision": str(state.get("contract_revision") or "hosted-role.v1"),
        "policy_snapshot_hash": str(state.get("policy_snapshot_hash") or ""),
    }


def _remove_duplicate_reasoning_activities(
    activities: list[dict[str, Any]],
    final_content: str,
) -> list[dict[str, Any]]:
    if not _structured_text(final_content):
        return activities
    return [
        activity
        for activity in activities
        if not (
            activity.get("kind") == "reasoning"
            and _reasoning_repeats_final(activity.get("output"), final_content)
        )
    ]


def _runner_supports_keyword(runner: Callable[..., Any], keyword: str) -> bool:
    try:
        parameters = inspect.signature(runner).parameters.values()
    except (TypeError, ValueError):
        return False
    return any(
        parameter.name == keyword
        or parameter.kind == inspect.Parameter.VAR_KEYWORD
        for parameter in parameters
    )


def _runner_supports_events(runner: Callable[..., Any]) -> bool:
    return _runner_supports_keyword(runner, "event_callback")


def _hosted_turn_allows_tools(run: dict[str, Any]) -> bool:
    """Skip tool/MCP discovery for ordinary one-shot chat turns.

    A hosted chat process is short-lived, so discovering every configured MCP
    before the model sees a trivial message is directly on the first-token
    path.  The router already records the small set of chat requests that
    genuinely need tools (for example, a local iOS capability or a file
    artifact); preserve tools for those requests and for all work turns.
    """

    route_metadata = (
        run.get("route_metadata")
        if isinstance(run.get("route_metadata"), dict)
        else {}
    )
    mode = str(
        run.get("mode") or route_metadata.get("mode") or "work"
    ).strip().lower()
    if mode != "chat":
        return True
    if _coerce_flag(run.get("artifact_required")) or _coerce_flag(
        route_metadata.get("artifact_required")
    ):
        return True
    if any(str(item).strip() for item in run.get("attachment_ids") or []):
        return True
    if _coerce_flag(route_metadata.get("needs_tools")):
        return True
    return any(
        str(item).strip()
        for item in route_metadata.get("capability_hints") or []
    )


def _invoke_profile_runner(
    runner: Callable[..., str],
    profile: str,
    prompt: str,
    event_callback: Callable[[dict[str, Any]], None],
    kanban_task_id: str,
    session_id: str = "",
    cancel_check: Optional[Callable[[], bool]] = None,
    artifact_context: Optional[dict[str, str]] = None,
) -> str:
    kwargs: dict[str, Any] = {}
    if _runner_supports_events(runner):
        kwargs["event_callback"] = event_callback
    if kanban_task_id and _runner_supports_keyword(runner, "kanban_task_id"):
        kwargs["kanban_task_id"] = kanban_task_id
    if session_id and _runner_supports_keyword(runner, "session_id"):
        kwargs["session_id"] = session_id
    if cancel_check is not None and _runner_supports_keyword(runner, "cancel_check"):
        kwargs["cancel_check"] = cancel_check
    if artifact_context and _runner_supports_keyword(runner, "artifact_context"):
        kwargs["artifact_context"] = dict(artifact_context)
    return str(runner(profile, prompt, **kwargs))


def _run_local_intervention_reply(
    conversation_id: str,
    turn_id: str,
    *,
    profile: str,
    runtime_profile: str,
    runner: Callable[..., str],
    kanban_task_id: str,
    runtime_session_id: str,
    prompt: str,
    artifact_context: dict[str, str],
) -> tuple[str, dict[str, Any]]:
    """Run the targeted reply in the same durable child session."""

    reply_state: dict[str, Any] = {
        "content": "",
        "status": "streaming",
        "activities": [],
        "actual_model": "",
        "actual_provider": "",
        "provider_bindings": {},
        "provider_refs": [],
        "runtime_session_id": str(runtime_session_id or "").strip(),
        "started_at": int(time.time() * 1000),
    }

    def on_event(event: dict[str, Any]) -> None:
        if _hosted_turn_cancellation_requested(conversation_id, turn_id):
            raise _HostedTurnCancelled("Hosted turn cancelled")
        # ``thinking.delta`` is the Hermes lifecycle spinner, not model
        # reasoning.  Preserve the event type so the reducer can discard the
        # spinner and the first-token timer cannot start before real output.
        apply_profile_event(reply_state, event)

    boundary_profile = runtime_profile or profile
    before = _runtime_session_boundary(
        boundary_profile,
        str(reply_state.get("runtime_session_id") or ""),
    )
    result = _invoke_profile_runner(
        runner,
        runtime_profile or profile,
        prompt,
        on_event,
        kanban_task_id,
        str(reply_state.get("runtime_session_id") or ""),
        lambda: _hosted_turn_cancellation_requested(conversation_id, turn_id),
        artifact_context,
    ).strip()
    if not result:
        raise RuntimeError("Hermes profile returned an empty intervention response")
    boundary = _runtime_session_boundary(
        boundary_profile,
        str(reply_state.get("runtime_session_id") or ""),
        after_message_id=int(before.get("tip_message_id") or 0),
    )
    if boundary.get("session_id"):
        reply_state["runtime_session_id"] = str(boundary["session_id"])
    reply_state["runtime_user_message_id"] = boundary.get("user_message_id")
    reply_state["runtime_tip_message_id"] = boundary.get("tip_message_id")
    reply_state["content"] = result
    reply_state["status"] = "completed"
    return result, reply_state


def _persist_hosted_role_state(
    conversation_id: str,
    turn_id: str,
    *,
    profile: str,
    role_stage: str,
    role_label: str,
    state: dict[str, Any],
    content_fallback: str,
    final_report: bool = False,
    semantic_milestone: str = "",
    visible: bool = True,
    persist: bool = True,
) -> None:
    state_content = str(state.get("content") or "").strip()
    state_status = str(state.get("status") or "streaming")
    state_error = str(state.get("error") or "").strip()
    content = state_content or (
        f"本阶段未完成：{state_error}"
        if state_status == "failed" and state_error
        else content_fallback
    )
    activities = [
        _redact_sensitive(dict(item))
        for item in state.get("activities") or []
        if isinstance(item, dict)
    ]
    base_stage = role_stage.split(":", 1)[0]
    handoff_to = {
        "worker": ["reviewer"],
        "reviewer": ["reporter"],
        "dispatch": ["worker"],
    }.get(base_stage, [])
    now = int(time.time() * 1000)
    if state_status in _HOSTED_TERMINAL_STATUSES:
        phase = "handoff" if base_stage in {"worker", "reviewer"} else "completed"
    elif state_content or activities:
        phase = "progress"
    else:
        phase = "opening"
    if base_stage == "chat":
        # A normal chat reply is one bubble whose content and status evolve in
        # place. Keeping the durable key stable prevents the streaming/progress
        # projection and the terminal projection from becoming duplicate
        # assistant messages in the conversation history.
        phase_role_stage = "chat"
        message_key = f"{turn_id}:chat:completed"
    elif semantic_milestone and state_status not in _HOSTED_TERMINAL_STATUSES:
        phase = "milestone"
        semantic_hash = hashlib.sha256(
            semantic_milestone.strip().encode("utf-8")
        ).hexdigest()[:16]
        phase_role_stage = f"{role_stage}.milestone.{semantic_hash}"
        message_key = f"{turn_id}:{role_stage}:milestone:{semantic_hash}"
    else:
        phase_role_stage = (
            role_stage
            if state_status in _HOSTED_TERMINAL_STATUSES
            else f"{role_stage}.{phase}"
        )
        message_key = f"{turn_id}:{role_stage}:{phase}"
    member_id = hosted_member_id(profile, role_stage)
    snapshot = {
        "profile": profile,
        "member_id": member_id,
        "content": content,
        "status": state_status,
        "activities": activities,
        "actual_model": str(state.get("actual_model") or ""),
        "actual_provider": str(state.get("actual_provider") or ""),
        "provider_bindings": dict(state.get("provider_bindings") or {}),
        "provider_refs": list(
            (state.get("_runtime_metadata") or {}).get("provider_refs") or []
        ),
        "runtime_session_id": str(
            state.get("runtime_session_id") or ""
        ).strip(),
        "started_at": int(state.get("started_at") or now),
        "model_started_at": int(state.get("model_started_at") or 0),
        "first_token_at": int(state.get("first_token_at") or 0),
        "completed_at": now if str(state.get("status") or "") in _HOSTED_TERMINAL_STATUSES else None,
        "milestone_count": int(state.get("milestone_count") or 0),
        "milestone_content": str(state.get("milestone_content") or ""),
        "request_accepted": _coerce_flag(state.get("request_accepted")),
        "request_accepted_at": int(state.get("request_accepted_at") or 0),
        "model_retry_attempt": int(state.get("model_retry_attempt") or 0),
        "model_retry_max_attempts": int(
            state.get("model_retry_max_attempts") or _HOSTED_CHAT_API_ATTEMPTS
        ),
        "runtime_message_before": int(state.get("runtime_message_before") or 0),
        "runtime_user_message_id": state.get("runtime_user_message_id"),
        "runtime_tip_message_id": state.get("runtime_tip_message_id"),
        "_protocol_event_index": int(state.get("_protocol_event_index") or 0),
        "_protocol_invocation_index": int(
            state.get("_protocol_invocation_index") or 0
        ),
        "_protocol_started_entities": [
            str(item)
            for item in state.get("_protocol_started_entities") or []
            if str(item)
        ],
        "updated_at": now,
    }
    patch = {"role_events": {role_stage: snapshot}}
    if base_stage == "chat" and snapshot["model_retry_attempt"]:
        patch["model_retry_attempt"] = snapshot["model_retry_attempt"]
    if base_stage == "chat" and snapshot["first_token_at"]:
        patch["model_first_token_at"] = snapshot["first_token_at"]
    if base_stage == "chat" and snapshot["model_started_at"]:
        patch["model_started_at"] = snapshot["model_started_at"]
    if base_stage != "chat":
        # Every hosted role joins the durable roster with its first persisted
        # stage event, so clients never hardcode the team composition.
        patch["participants"] = [
            hosted_participant_descriptor(profile, role_stage=role_stage)
        ]
    if snapshot["request_accepted"]:
        patch["request_accepted"] = True
        patch["request_accepted_at"] = snapshot["request_accepted_at"] or now
    projected_message = {
        "role": "assistant",
        "name": profile,
        "content": content,
        "status": snapshot["status"],
        "kind": "message",
        "meta": {
            "role_stage": phase_role_stage,
            "base_role_stage": base_stage,
            "phase": phase,
            "message_key": message_key,
            "role_label": role_label,
            "profile": profile,
            "member_id": member_id,
            "handoff_to": handoff_to,
            "started_at": snapshot["started_at"],
            "model_started_at": snapshot["model_started_at"] or None,
            "first_token_at": snapshot["first_token_at"] or None,
            "completed_at": snapshot["completed_at"],
            "collapse_activities": True,
            "final_report": final_report and state_status in _HOSTED_TERMINAL_STATUSES,
            "activities": activities,
            "actual_model": snapshot["actual_model"],
            "actual_provider": snapshot["actual_provider"],
            "runtime_session_id": str(
                state.get("runtime_session_id") or ""
            ).strip(),
            "runtime_message_id": state.get("runtime_tip_message_id"),
        },
    }
    pending_protocol_events = [
        {**dict(item), "role_stage": role_stage}
        for item in state.get("_protocol_events") or []
        if isinstance(item, dict)
    ]
    pending_session_entries = [
        {
            **dict(item),
            "payload": {
                **(
                    dict(item.get("payload"))
                    if isinstance(item.get("payload"), dict)
                    else {}
                ),
                "turn_id": turn_id,
                "role_stage": role_stage,
                "profile": profile,
            },
        }
        for item in state.get("_session_entry_events") or []
        if isinstance(item, dict)
    ]
    if persist:
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch=patch,
            runtime_session=(
                profile,
                str(state.get("runtime_session_id") or "").strip(),
            ),
            message=projected_message if visible else None,
            protocol_events=pending_protocol_events,
            session_entries=pending_session_entries,
        )
        if pending_protocol_events:
            state["_protocol_events"] = []
            state["_live_protocol_event_count"] = 0
        if pending_session_entries:
            state["_session_entry_events"] = []
    else:
        live_event_offset = max(
            0,
            min(
                int(state.get("_live_protocol_event_count") or 0),
                len(pending_protocol_events),
            ),
        )
        _publish_live_hosted_role_projection(
            conversation_id,
            turn_id,
            patch=patch,
            message=projected_message if visible else None,
            protocol_events=pending_protocol_events[live_event_offset:],
        )
        state["_live_protocol_event_count"] = len(pending_protocol_events)


def _run_hosted_role(
    conversation_id: str,
    turn_id: str,
    *,
    profile: str,
    role_stage: str,
    role_label: str,
    prompt: str,
    runner: Callable[..., str],
    kanban_task_id: str,
    start_text: str,
    runtime_profile: str = "",
    runtime_session_id: str = "",
    final_report: bool = False,
    previous_state: Optional[dict[str, Any]] = None,
    execution_owner: str = "",
    visible: bool = True,
    provider_max_attempts: Optional[int] = None,
    retry_sleeper: Callable[[float], None] = time.sleep,
) -> tuple[str, str, dict[str, Any]]:
    execution_owner = str(execution_owner or f"local-{uuid.uuid4().hex}")
    with _STATE_LOCK:
        artifact_state = load_single_state()
        artifact_conversation = _conversation_by_id(artifact_state, conversation_id)
        artifact_run = (artifact_conversation.get("hosted_turns") or {}).get(turn_id)
        artifact_run = artifact_run if isinstance(artifact_run, dict) else {}
        artifact_owner_id = str(
            artifact_conversation.get("owner_id") or LOCAL_OWNER_ID
        )
    captured_generation = str(
        getattr(_HOSTED_EXECUTION_GENERATION, "value", "")
    ).strip()
    # start_hosted_workflow validates and captures the account generation once
    # before entering the role. Reopening MobileDeviceStore here is redundant
    # for every role setup (and costs a SQLite open on the first-token path).
    # Direct/test callers without the execution capture retain the validated
    # store lookup fallback.
    live_generation = (
        captured_generation
        or _account_generation_for_owner(artifact_owner_id)
    )
    if captured_generation and captured_generation != live_generation:
        raise RuntimeError("stale hosted turn account generation")
    # Ordinary hosted chat turns do not need the expensive MCP/tool discovery
    # path.  Explicit tool/capability requests and all work turns retain the
    # full contract; a plain "你好" should reach the model directly.
    allow_tools = _hosted_turn_allows_tools(artifact_run)
    artifact_context = {
        "root": str(get_hermes_home()),
        "owner_id": artifact_owner_id,
        "conversation_id": conversation_id,
        "turn_id": turn_id,
        "account_generation": captured_generation or live_generation,
        "model_retry_deadline_at": int(
            artifact_run.get("model_retry_deadline_at") or 0
        ),
        "model_retry_attempt": int(artifact_run.get("model_retry_attempt") or 0),
        "capability_hints": [
            str(item)
            for item in (
                (artifact_run.get("route_metadata") or {}).get("capability_hints")
                if isinstance(artifact_run.get("route_metadata"), dict)
                else []
            ) or []
            if str(item).strip()
        ],
        "allow_tools": "1" if allow_tools else "0",
    }
    state = {
        "content": "",
        "status": "streaming",
        "activities": [],
        "actual_model": "",
        "actual_provider": "",
        "runtime_session_id": str(runtime_session_id or "").strip(),
        "started_at": int(time.time() * 1000),
        "model_started_at": 0,
        "first_token_at": 0,
        "milestone_count": 0,
        "milestone_content": "",
        "request_accepted": False,
        "request_accepted_at": 0,
        "model_retry_attempt": 0,
        "model_retry_max_attempts": _HOSTED_CHAT_API_ATTEMPTS,
        "runtime_message_before": 0,
        "runtime_user_message_id": None,
        "runtime_tip_message_id": None,
        "_protocol_event_index": 0,
        "_protocol_invocation_index": 0,
        "_protocol_started_entities": [],
        "_protocol_events": [],
        "_saw_message_complete": False,
        "_runtime_metadata": {
            "component_id": f"fiber:{turn_id}:{role_stage}",
            "parent_component_id": f"fiber:turn:{turn_id}",
            "provider_refs": [],
            "dependency_state": {},
            "lifecycle_state": "activating",
            "effect_scope_id": f"hosted-role:{execution_owner}",
            "plan_node_id": role_stage,
            "artifact_refs": [],
            "contract_revision": "hosted-role.v1",
            "policy_snapshot_hash": "",
        },
    }
    if isinstance(previous_state, dict):
        state.update(
            {
                "content": str(previous_state.get("content") or ""),
                "activities": [dict(item) for item in previous_state.get("activities") or []],
                "actual_model": str(previous_state.get("actual_model") or ""),
                "actual_provider": str(previous_state.get("actual_provider") or ""),
                "provider_bindings": dict(previous_state.get("provider_bindings") or {}),
                "provider_refs": [
                    str(item).strip()
                    for item in previous_state.get("provider_refs") or []
                    if str(item).strip()
                ],
                "runtime_session_id": str(
                    previous_state.get("runtime_session_id")
                    or runtime_session_id
                    or ""
                ).strip(),
                "status": str(previous_state.get("status") or "streaming"),
                "started_at": int(
                    previous_state.get("started_at")
                    or state["started_at"]
                ),
                "model_started_at": int(
                    previous_state.get("model_started_at") or 0
                ),
                "first_token_at": int(previous_state.get("first_token_at") or 0),
                "milestone_count": int(previous_state.get("milestone_count") or 0),
                "milestone_content": str(previous_state.get("milestone_content") or ""),
                "request_accepted": _coerce_flag(previous_state.get("request_accepted")),
                "request_accepted_at": int(previous_state.get("request_accepted_at") or 0),
                "model_retry_attempt": int(
                    previous_state.get("model_retry_attempt") or 0
                ),
                "model_retry_max_attempts": int(
                    previous_state.get("model_retry_max_attempts")
                    or _HOSTED_CHAT_API_ATTEMPTS
                ),
                "runtime_message_before": int(
                    previous_state.get("runtime_message_before") or 0
                ),
                "runtime_user_message_id": previous_state.get(
                    "runtime_user_message_id"
                ),
                "runtime_tip_message_id": previous_state.get(
                    "runtime_tip_message_id"
                ),
                "_protocol_event_index": int(
                    previous_state.get("_protocol_event_index") or 0
                ),
                "_protocol_invocation_index": int(
                    previous_state.get("_protocol_invocation_index") or 0
                ),
                "_protocol_started_entities": [
                    str(item)
                    for item in previous_state.get("_protocol_started_entities") or []
                    if str(item)
                ],
                "_saw_message_complete": bool(
                    previous_state.get("_saw_message_complete")
                ),
            }
        )
        previous_runtime = previous_state.get("_runtime_metadata")
        if isinstance(previous_runtime, dict):
            state["_runtime_metadata"].update(
                {
                    "provider_refs": [
                        str(item).strip()
                        for item in previous_runtime.get("provider_refs") or []
                        if str(item).strip()
                    ],
                    "dependency_state": dict(previous_runtime.get("dependency_state") or {})
                    if isinstance(previous_runtime.get("dependency_state"), dict)
                    else {},
                }
            )
    if (
        str(state.get("status") or "") in _HOSTED_TERMINAL_STATUSES
        and str(state.get("content") or "").strip()
    ):
        return (
            str(state["content"]).strip(),
            str(state["status"]),
            state,
        )
    if not _activate_hosted_role(
        conversation_id,
        turn_id,
        role_stage=role_stage,
        profile=profile,
        execution="local",
        execution_owner=execution_owner,
        lease_ms=_hosted_chat_lease_ms(),
    ):
        raise RuntimeError("同一角色阶段已有活动执行 owner")
    role_effect_scope = EffectScope(
        owner_id=f"hosted-role:{conversation_id}:{turn_id}:{role_stage}",
        scope_id=f"hosted-role:{execution_owner}",
    )
    track_hosted_role_claim(
        role_effect_scope,
        lambda: _clear_hosted_active_role(
            conversation_id,
            turn_id,
            role_stage=role_stage,
            execution_owner=execution_owner,
        ),
        role_stage=role_stage,
        owner=execution_owner,
    )
    state["_runtime_metadata"] = {
        **dict(state.get("_runtime_metadata") or {}),
        **_hosted_runtime_metadata(
            state,
            turn_id=turn_id,
            role_stage=role_stage,
            lifecycle_state="active",
        ),
        "effect_scope_id": role_effect_scope.scope_id,
    }

    def release_role_claim() -> None:
        try:
            role_effect_scope.close_sync()
        except Exception:
            logger.exception("hosted role effect scope cleanup failed")
    if role_stage.split(":", 1)[0] != "chat":
        _queue_hosted_protocol_event(
            state,
            {"type": "request.accepted", "payload": {"status": "started"}},
        )
        _persist_hosted_role_state(
            conversation_id,
            turn_id,
            profile=profile,
            role_stage=role_stage,
            role_label=role_label,
            state=state,
            content_fallback=start_text,
            final_report=final_report,
            visible=visible,
        )
    last_persisted_at = 0.0
    first_visible_published = False
    last_live_published_at = 0.0
    last_intervention_poll_at = 0.0
    atomic_depth = 0

    def claim_pending_intervention(
        deliveries: Optional[set[str]] = None,
        *,
        force: bool = False,
    ) -> Optional[dict[str, Any]]:
        nonlocal last_intervention_poll_at
        now = time.monotonic()
        if (
            not force
            and now - last_intervention_poll_at
            < _HOSTED_INTERVENTION_POLL_SECONDS
        ):
            return None
        last_intervention_poll_at = now
        pending = _pending_hosted_role_intervention(
            conversation_id,
            turn_id,
            role_stage=role_stage,
            profile=profile,
            include_processing=True,
            deliveries=deliveries,
        )
        if not isinstance(pending, dict):
            return None
        checkpoint = _hosted_role_checkpoint(
            role_stage=role_stage,
            profile=profile,
            execution="local",
            role_state=state,
        )
        claimed = _claim_hosted_role_intervention(
            conversation_id,
            turn_id,
            role_stage=role_stage,
            profile=profile,
            checkpoint=checkpoint,
            intervention_id=str(pending.get("id") or ""),
            execution_owner=execution_owner,
            lease_ms=_hosted_chat_lease_ms(),
            deliveries=deliveries,
        )
        if (
            claimed is None
            and str(pending.get("status") or "") == "processing"
        ):
            raise RuntimeError("定向干预正在由另一 execution owner 处理")
        return claimed

    def cancellation_requested() -> bool:
        if _hosted_turn_cancellation_requested(conversation_id, turn_id):
            return True
        if atomic_depth != 0:
            return False
        pending = claim_pending_intervention({"steer"})
        if not isinstance(pending, dict):
            return False
        if str(pending.get("status") or "pending") == "pending":
            return True
        now = int(time.time() * 1000)
        return bool(
            str(pending.get("execution_owner") or "") == execution_owner
            or int(pending.get("lease_expires_at") or 0) <= now
        )

    def persist() -> None:
        nonlocal last_persisted_at
        base_stage = role_stage.split(":", 1)[0]
        if (
            base_stage == "chat"
            and not str(state.get("content") or "").strip()
            and not state.get("activities")
            and not state.get("_session_entry_events")
            and str(state.get("status") or "") not in _HOSTED_TERMINAL_STATUSES
        ):
            patch: dict[str, Any] = {}
            if state.get("request_accepted"):
                patch.update(
                    {
                        "request_accepted": True,
                        # Preserve the actual gateway request.accepted edge;
                        # this fast chat projection may run much later.
                        "request_accepted_at": int(
                            state.get("request_accepted_at") or time.time() * 1000
                        ),
                    }
                )
            _persist_hosted_turn(
                conversation_id,
                turn_id,
                patch=patch,
                runtime_session=(
                    profile,
                    str(state.get("runtime_session_id") or "").strip(),
                ),
            )
            last_persisted_at = time.monotonic()
            return
        _persist_hosted_role_state(
            conversation_id,
            turn_id,
            profile=profile,
            role_stage=role_stage,
            role_label=role_label,
            state=state,
            content_fallback=start_text,
            final_report=final_report,
            visible=visible,
        )
        last_persisted_at = time.monotonic()

    def on_event(event: dict[str, Any]) -> None:
        nonlocal atomic_depth, first_visible_published, last_live_published_at
        if _hosted_turn_cancellation_requested(conversation_id, turn_id):
            raise _HostedTurnCancelled("Hosted turn cancelled")
        protocol_event = event
        event_type = str(event.get("type") or "")
        if event_type in {"tool.start", "subagent.start"} and atomic_depth == 0:
            intervention = claim_pending_intervention({"steer"}, force=True)
            if isinstance(intervention, dict):
                raise _HostedRoleIntervention(intervention)
        if event_type in {"tool.start", "subagent.start"}:
            atomic_depth += 1
        current_content = str(state.get("content") or "").strip()
        previous_milestone = str(state.get("milestone_content") or "")
        if (
            visible
            and event_type in {"tool.start", "subagent.start"}
            and current_content
            and current_content != previous_milestone
        ):
            milestone_count = int(state.get("milestone_count") or 0) + 1
            milestone_content = (
                current_content[len(previous_milestone):].strip()
                if previous_milestone and current_content.startswith(previous_milestone)
                else current_content
            )
            base_stage = role_stage.split(":", 1)[0]
            _persist_hosted_turn(
                conversation_id,
                turn_id,
                message={
                    "role": "assistant",
                    "name": profile,
                    "content": milestone_content,
                    "status": "completed",
                    "kind": "message",
                    "meta": {
                        "role_stage": f"{role_stage}.milestone.{milestone_count}",
                        "base_role_stage": base_stage,
                        "phase": "milestone",
                        "message_key": f"{turn_id}:{role_stage}:milestone:{milestone_count}",
                        "role_label": role_label,
                        "profile": profile,
                        "final_report": False,
                        "collapse_activities": True,
                        "activities": [dict(item) for item in state.get("activities") or []],
                        "actual_model": str(state.get("actual_model") or ""),
                        "actual_provider": str(state.get("actual_provider") or ""),
                    },
                },
            )
            state["milestone_count"] = milestone_count
            state["milestone_content"] = current_content
        had_content = bool(str(state.get("content") or ""))
        had_reasoning = any(
            activity.get("kind") == "reasoning"
            for activity in state.get("activities") or []
        )
        first_status_update = event_type == "status.update" and not any(
            str(activity.get("id") or "") == "model-runtime-status"
            for activity in state.get("activities") or []
            if isinstance(activity, dict)
        )
        # Chat status is transient.  Persisting the first "thinking" marker
        # synchronously rewrites the multi-megabyte profile before the model
        # can produce its first visible token.  The accepted event, first
        # visible delta, and terminal event still make the durable timeline
        # complete without that extra write.
        if role_stage.split(":", 1)[0] == "chat":
            first_status_update = False
        apply_profile_event(state, event)
        _queue_hosted_protocol_event(state, protocol_event)
        if event_type in {"tool.complete", "subagent.complete"}:
            atomic_depth = max(0, atomic_depth - 1)
        if event_type == "request.accepted":
            state["request_accepted"] = True
        first_visible_delta = (
            event_type == "message.delta" and not had_content
        ) or (
            event_type == "reasoning.delta"
            and not had_reasoning
            and not had_content
        )
        first_visible_delta = first_visible_delta and not first_visible_published
        has_execution_activity = any(
            isinstance(activity, dict)
            and activity.get("kind") in {"tool", "subagent"}
            for activity in state.get("activities") or []
        )
        # The enqueue transaction already durably records a normal chat's
        # user message and turn shell.  Keep accepted/status events live over
        # SSE, but do not rewrite the multi-megabyte profile on every transient
        # chat event before the provider emits a token.  Workflow roles still
        # use the periodic checkpoint path because their tool/subagent state
        # must survive a worker restart.
        is_chat_role = role_stage.split(":", 1)[0] == "chat"
        live_event_types = {
            "agent.started",
            "connection.retry",
            "error",
            "message.complete",
            "message.delta",
            "reasoning.available",
            "reasoning.delta",
            "request.accepted",
            "session.info",
            "status.update",
            "subagent.complete",
            "subagent.progress",
            "subagent.start",
            "thinking.delta",
            "tool.complete",
            "tool.generating",
            "tool.progress",
            "tool.start",
        }
        force_live_projection = event_type in {
            "agent.started",
            "connection.retry",
            "error",
            "message.complete",
            "reasoning.available",
            "request.accepted",
            "session.info",
            "subagent.complete",
            "subagent.start",
            "tool.complete",
            "tool.start",
        } or first_visible_delta
        live_now = time.monotonic()
        should_publish_live = (
            is_chat_role
            and event_type in live_event_types
            and (
                force_live_projection
                or live_now - last_live_published_at >= 0.05
            )
        )
        if should_publish_live:
            # Keep lifecycle/first-token rendering independent from the
            # durable JSON checkpoint.  The latter can take seconds under
            # load; the live projection is replaced by the next checkpoint.
            _persist_hosted_role_state(
                conversation_id,
                turn_id,
                profile=profile,
                role_stage=role_stage,
                role_label=role_label,
                state=state,
                content_fallback=start_text,
                final_report=final_report,
                visible=visible,
                persist=False,
            )
            last_live_published_at = live_now
            if first_visible_delta:
                first_visible_published = True
        should_persist = (
            (
                event_type == "request.accepted"
                and not is_chat_role
            )
            or event_type in {"error", "message.complete"}
            or first_status_update
            or (first_visible_delta and not is_chat_role)
            or (
                not is_chat_role
                and _coerce_flag(state.get("request_accepted"))
                and has_execution_activity
                and time.monotonic() - last_persisted_at >= _HOSTED_EVENT_FLUSH_SECONDS
            )
        )
        if should_persist:
            persist()
        if atomic_depth == 0:
            intervention = claim_pending_intervention(
                {"steer"},
                force=event_type in {"tool.complete", "subagent.complete"},
            )
            if isinstance(intervention, dict):
                persist()
                raise _HostedRoleIntervention(intervention)

    # The real Hermes child already performs the five bounded provider
    # attempts. Re-running the entire child would duplicate those attempts and
    # could keep a failed iOS turn alive beyond its two-minute contract.
    attempts = (
        1
        if runner is run_profile_turn
        else max(
            1,
            int(
                provider_max_attempts
                if provider_max_attempts is not None
                else _HOSTED_TRANSIENT_RETRIES + 1
            ),
        )
    )
    for attempt in range(1, attempts + 1):
        try:
            boundary_profile = runtime_profile or profile
            if not int(state.get("runtime_message_before") or 0):
                before = _runtime_session_boundary(
                    boundary_profile,
                    str(state.get("runtime_session_id") or ""),
                )
                state["runtime_message_before"] = int(
                    before.get("tip_message_id") or 0
                )
            intervention = claim_pending_intervention({"steer"}, force=True)
            if isinstance(intervention, dict):
                raise _HostedRoleIntervention(intervention)
            result = _invoke_profile_runner(
                runner,
                runtime_profile or profile,
                prompt,
                on_event,
                kanban_task_id,
                str(state.get("runtime_session_id") or ""),
                cancellation_requested,
                artifact_context,
            ).strip()
            intervention = claim_pending_intervention(
                {"steer", "follow_up"},
                force=True,
            )
            if isinstance(intervention, dict):
                raise _HostedRoleIntervention(intervention)
            if not result:
                raise RuntimeError("Hermes profile returned an empty response")
            boundary = _runtime_session_boundary(
                boundary_profile,
                str(state.get("runtime_session_id") or ""),
                after_message_id=int(state.get("runtime_message_before") or 0),
            )
            if boundary.get("session_id"):
                state["runtime_session_id"] = str(boundary["session_id"])
            state["runtime_user_message_id"] = boundary.get("user_message_id")
            state["runtime_tip_message_id"] = boundary.get("tip_message_id")
            state["content"] = result
            state["status"] = "completed"
            if not state.get("_saw_message_complete"):
                _queue_hosted_protocol_event(
                    state,
                    {
                        "type": "message.complete",
                        "payload": {
                            "text": result,
                            "status": "completed",
                            "entity_id": f"{turn_id}:{role_stage}:final",
                        },
                    },
                )
            state["activities"] = _remove_duplicate_reasoning_activities(
                state.get("activities") or [],
                result,
            )
            persist()
            release_role_claim()
            return result, "completed", state
        except Exception as exc:
            intervention = (
                dict(exc.intervention)
                if isinstance(exc, _HostedRoleIntervention)
                else None
            )
            if (
                intervention is None
                and isinstance(exc, _HostedTurnCancelled)
                and not _hosted_turn_cancellation_requested(conversation_id, turn_id)
            ):
                intervention = claim_pending_intervention({"steer"}, force=True)
            if isinstance(intervention, dict):
                checkpoint = dict(intervention.get("checkpoint") or {})
                if not checkpoint:
                    checkpoint = _hosted_role_checkpoint(
                        role_stage=role_stage,
                        profile=profile,
                        execution="local",
                        role_state=state,
                    )
                state["status"] = "streaming"
                persist()
                try:
                    intervention_reply, reply_state = _run_local_intervention_reply(
                        conversation_id,
                        turn_id,
                        profile=profile,
                        runtime_profile=runtime_profile,
                        runner=runner,
                        kanban_task_id=kanban_task_id,
                        runtime_session_id=str(state.get("runtime_session_id") or ""),
                        prompt=_hosted_intervention_reply_prompt(
                            role_label=role_label,
                            intervention=intervention,
                            checkpoint=checkpoint,
                        ),
                        artifact_context=artifact_context,
                    )
                except _HostedTurnCancelled:
                    _finish_hosted_turn_if_cancelled(conversation_id, turn_id)
                    state["status"] = "cancelled"
                    release_role_claim()
                    return str(state.get("content") or "").strip(), "cancelled", state
                except Exception as reply_exc:
                    intervention_reply = (
                        "已在安全边界暂停；定向回复执行失败："
                        f"{sanitize_runtime_error(reply_exc)}。后续将携带检查点继续。"
                    )
                    reply_state = {}
                _complete_hosted_role_intervention(
                    conversation_id,
                    turn_id,
                    intervention_id=str(intervention.get("id") or ""),
                    claim_token=str(intervention.get("claim_token") or ""),
                    execution_owner=execution_owner,
                    role_stage=role_stage,
                    role_label=role_label,
                    profile=profile,
                    reply=intervention_reply,
                    checkpoint=checkpoint,
                    resume_role_stage=role_stage,
                )
                if reply_state.get("runtime_session_id"):
                    state["runtime_session_id"] = str(reply_state["runtime_session_id"])
                if reply_state.get("runtime_tip_message_id"):
                    state["runtime_message_before"] = int(
                        reply_state["runtime_tip_message_id"]
                    )
                    state["runtime_tip_message_id"] = reply_state[
                        "runtime_tip_message_id"
                    ]
                state["content"] = ""
                state["status"] = "streaming"
                release_role_claim()
                return _run_hosted_role(
                    conversation_id,
                    turn_id,
                    profile=profile,
                    role_stage=role_stage,
                    role_label=role_label,
                    prompt=_hosted_intervention_resume_prompt(
                        prompt,
                        intervention=intervention,
                        checkpoint=checkpoint,
                        reply=intervention_reply,
                    ),
                    runner=runner,
                    kanban_task_id=kanban_task_id,
                    start_text="已优先处理定向干预，正在从检查点恢复。",
                    runtime_profile=runtime_profile,
                    runtime_session_id=str(state.get("runtime_session_id") or ""),
                    final_report=final_report,
                    previous_state=state,
                    execution_owner=execution_owner,
                    visible=visible,
                    provider_max_attempts=provider_max_attempts,
                    retry_sleeper=retry_sleeper,
                )
            if isinstance(exc, _HostedTurnCancelled) or _hosted_turn_cancellation_requested(
                conversation_id,
                turn_id,
            ):
                _finish_hosted_turn_if_cancelled(conversation_id, turn_id)
                state["status"] = "cancelled"
                release_role_claim()
                return str(state.get("content") or "").strip(), "cancelled", state
            terminal_content = str(state.get("content") or "").strip()
            if str(state.get("status") or "") == "failed" and terminal_content:
                clean_error = sanitize_runtime_error(exc)
                state["error"] = clean_error
                state["activities"] = _remove_duplicate_reasoning_activities(
                    state.get("activities") or [],
                    terminal_content,
                )
                persist()
                release_role_claim()
                return terminal_content, "failed", state
            transient = _is_transient_runtime_error(exc)
            has_tool_activity = any(
                activity.get("kind") in {"tool", "subagent"}
                for activity in state.get("activities") or []
            )
            if transient and not has_tool_activity and attempt < attempts:
                retry_event = {
                    "type": "connection.retry",
                    "payload": {
                        "attempt": attempt + 1,
                        "max_attempts": attempts,
                    },
                }
                apply_profile_event(state, retry_event)
                _queue_hosted_protocol_event(state, retry_event)
                state["status"] = "streaming"
                persist()
                retry_sleeper(0.5 * attempt)
                continue
            clean_error = sanitize_runtime_error(exc)
            partial = str(state.get("content") or "").strip()
            result = (
                f"{partial}\n\n本阶段未完成：{clean_error}"
                if partial
                else f"本阶段未完成：{clean_error}"
            )
            state["content"] = result
            state["status"] = "failed"
            state["error"] = clean_error
            state["activities"] = _remove_duplicate_reasoning_activities(
                state.get("activities") or [],
                result,
            )
            persist()
            release_role_claim()
            return result, "failed", state

    release_role_claim()
    raise RuntimeError("Hermes 托管角色执行状态异常")


def _request_remote_role_intervention_cancel(
    conversation_id: str,
    turn_id: str,
    *,
    remote_run_id: str,
    role_stage: str,
    profile: str,
    intervention_id: str = "",
    execution_owner: str = "",
) -> Optional[dict[str, Any]]:
    """Claim one @ control and cancel only its active remote run."""

    wanted = str(intervention_id or "")
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            return None
        remote_run = next(
            (
                item
                for item in (run.get("remote_runs") or {}).values()
                if isinstance(item, dict)
                and str(item.get("id") or "") == str(remote_run_id or "")
            ),
            None,
        )
        if not isinstance(remote_run, dict):
            return None
        intervention = next(
            (
                item
                for item in run.get("interventions") or []
                if isinstance(item, dict)
                and (not wanted or str(item.get("id") or "") == wanted)
                and str(item.get("status") or "pending") in {
                    "pending",
                    "processing",
                }
                and _intervention_matches_role(
                    item,
                    role_stage=role_stage,
                    profile=profile,
                )
            ),
            None,
        )
        if not isinstance(intervention, dict):
            return None
        now = int(time.time() * 1000)
        execution_owner = str(execution_owner or f"remote:{remote_run_id}")
        current_status = str(intervention.get("status") or "pending")
        current_owner = str(intervention.get("execution_owner") or "")
        lease_expires_at = int(intervention.get("lease_expires_at") or 0)
        if current_status == "processing":
            if current_owner == execution_owner and lease_expires_at > now:
                return dict(intervention)
            if lease_expires_at > now:
                return None
        checkpoint = _hosted_role_checkpoint(
            role_stage=role_stage,
            profile=profile,
            execution="remote",
            remote_run=remote_run,
        )
        intervention.update(
            {
                "status": "processing",
                "claim_token": uuid.uuid4().hex,
                "execution_owner": execution_owner,
                "lease_expires_at": now + 120_000,
                "claimed_at": now,
                "active_role_stage": role_stage,
                "active_profile": profile,
                "checkpoint": _redact_sensitive(dict(checkpoint)),
                "updated_at": now,
            }
        )
        if current_status == "processing":
            intervention["reclaimed_at"] = now
        if str(remote_run.get("status") or "") not in _REMOTE_TERMINAL_STATUSES:
            remote_run.update(
                {
                    "cancel_requested": True,
                    "cancel_kind": "intervention",
                    "cancel_intervention_id": str(intervention.get("id") or ""),
                    "cancel_reason": str(intervention.get("content") or "")[:1000],
                    "cancel_requested_at": now,
                    "updated_at": now,
                }
            )
        run["updated_at"] = now
        conversation["updated_at"] = now
        save_single_state(state)
        claimed = dict(intervention)
    _notify_hosted_update(conversation_id)
    return claimed


def _run_hosted_remote_role(
    conversation_id: str,
    turn_id: str,
    *,
    profile: str,
    role_stage: str,
    role_label: str,
    prompt: str,
    kanban_task_id: str,
    start_text: str,
    artifact_required: bool = False,
    delivery_context: str = "",
    attachment_context: str = "",
    rework_round: int = 0,
    connector_id: str = "",
    visible: bool = True,
) -> tuple[str, str, dict[str, Any]]:
    """Wait for a DBB3/PC connector run and project its checkpoints.

    The remote id is derived from the conversation, turn, role phase and
    profile. Restarting the dashboard therefore reattaches to the same queue
    item instead of creating another remote Kanban task.
    """

    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        hosted = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(hosted, dict):
            raise RuntimeError("托管任务记录不存在")
        title = str(hosted.get("title") or summarize_task_title(hosted.get("content")))
        run_snapshot = dict(hosted)
    remote = _ensure_remote_run(
        conversation_id,
        turn_id,
        role_stage=role_stage,
        profile=profile,
        title=title,
        objective=prompt,
        local_task_id=kanban_task_id,
        artifact_required=artifact_required,
        delivery_context=delivery_context,
        attachment_context=attachment_context,
        attachment_ids=list(run_snapshot.get("attachment_ids") or []),
        attempt=rework_round + 1,
        connector_id=connector_id,
    )
    active_remote_id = str(remote.get("id") or "")
    connector_provider = _observe_runtime_provider(
        provider_id=_runtime_provider_id("connector", connector_id or "server"),
        interface_key="connector:hosted-remote",
        health="healthy" if str(remote.get("status") or "") not in {"failed", "cancelled"} else "unhealthy",
        metadata={
            "connector_id": connector_id,
            "remote_run_id": active_remote_id,
            "version": str(remote.get("worker_version") or "unknown"),
        },
    )
    if connector_provider:
        connector_ref = _provider_witness_ref(connector_provider)
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "provider_bindings": {
                    f"connector:{connector_id or 'server'}": connector_provider,
                },
                "provider_refs": [connector_ref] if connector_ref else [],
            },
        )
    coordinator_owner = f"remote-coordinator:{active_remote_id}:{uuid.uuid4().hex}"
    revision = -1
    remaining_seconds = max(
        0.0,
        (int(remote.get("deadline_at") or 0) - int(time.time() * 1000)) / 1000,
    )
    configured_wait = _positive_int(os.environ.get("HERMES_REMOTE_RUN_WAIT_SECONDS"))
    if configured_wait is not None:
        remaining_seconds = min(remaining_seconds, float(configured_wait))
    deadline = time.monotonic() + remaining_seconds
    while True:
        # Observe a committed result before attempting takeover. This order is
        # essential when the original owner clears its lane immediately after
        # publishing the terminal role_event.
        with _STATE_LOCK:
            waiting_state = load_single_state()
            waiting_conversation = _conversation_by_id(waiting_state, conversation_id)
            waiting_hosted = (waiting_conversation.get("hosted_turns") or {}).get(turn_id)
            if not isinstance(waiting_hosted, dict):
                raise RuntimeError("Hosted turn no longer exists")
            authoritative = (waiting_hosted.get("role_events") or {}).get(role_stage)
            hosted_terminal = str(waiting_hosted.get("status") or "") in _HOSTED_TERMINAL_STATUSES
        if (
            isinstance(authoritative, dict)
            and str(authoritative.get("status") or "") in _HOSTED_TERMINAL_STATUSES
        ):
            authoritative_state = dict(authoritative)
            result = str(authoritative_state.get("content") or "").strip()
            status = (
                "completed"
                if str(authoritative_state.get("status") or "") == "completed"
                else "failed"
            )
            return result, status, authoritative_state
        if hosted_terminal:
            return "", "failed", {"content": "", "status": "failed", "activities": []}
        if _activate_hosted_role(
            conversation_id,
            turn_id,
            role_stage=role_stage,
            profile=profile,
            execution="remote",
            remote_run_id=active_remote_id,
            execution_owner=coordinator_owner,
        ):
            break
        if time.monotonic() >= deadline:
            _advance_remote_run_deadline(active_remote_id)
            deadline = time.monotonic() + _REMOTE_CANCELLATION_GRACE_SECONDS
        revision = _wait_for_hosted_update(revision, 15.0)
    remote_effect_scope = EffectScope(
        owner_id=f"hosted-remote-role:{conversation_id}:{turn_id}:{role_stage}",
        scope_id=f"hosted-remote-role:{coordinator_owner}",
    )
    track_hosted_role_claim(
        remote_effect_scope,
        lambda: _clear_hosted_active_role(
            conversation_id,
            turn_id,
            role_stage=role_stage,
            remote_run_id=active_remote_id,
            execution_owner=coordinator_owner,
        ),
        role_stage=role_stage,
        owner=coordinator_owner,
    )

    def release_remote_role_claim() -> None:
        try:
            remote_effect_scope.close_sync()
        except Exception:
            logger.exception("remote hosted role effect scope cleanup failed")
    if visible and str(remote.get("status") or "queued") not in _REMOTE_TERMINAL_STATUSES:
        _remote_run_state_message(
            conversation_id,
            turn_id,
            remote,
            role_label=role_label,
        )

    configured_fallback = _positive_int(
        os.environ.get("HERMES_REMOTE_FALLBACK_SECONDS")
    )
    fallback_deadline = time.monotonic() + float(
        min(configured_fallback or _REMOTE_SERVER_FALLBACK_SECONDS, 60)
    )
    # Progress-based stall detection. A claimed remote run that stops updating
    # (no status/checkpoint/activity change) is treated as stuck. This is not
    # an arbitrary total-time cap; it reacts to actual liveness.
    last_seen_remote_updated_at = -1
    last_remote_progress_at = time.monotonic()

    while True:
        if not _renew_hosted_active_role(
            conversation_id,
            turn_id,
            role_stage=role_stage,
            execution_owner=coordinator_owner,
        ):
            release_remote_role_claim()
            return _run_hosted_remote_role(
                conversation_id,
                turn_id,
                profile=profile,
                role_stage=role_stage,
                role_label=role_label,
                prompt=prompt,
                kanban_task_id=kanban_task_id,
                start_text=start_text,
                artifact_required=artifact_required,
                delivery_context=delivery_context,
                attachment_context=attachment_context,
                rework_round=rework_round,
                connector_id=connector_id,
                visible=visible,
            )
        with _STATE_LOCK:
            state = load_single_state()
            location = _remote_run_location(state, str(remote.get("id") or ""))
            if location is None:
                raise RuntimeError("远程执行记录不存在")
            _conversation, _hosted, _role_key, current = location
            remote = dict(current)
            turn_cancel_requested = _coerce_flag(_hosted.get("cancel_requested"))
        status = str(remote.get("status") or "queued")
        current_updated_at = int(remote.get("updated_at") or 0)
        if current_updated_at != last_seen_remote_updated_at:
            last_seen_remote_updated_at = current_updated_at
            last_remote_progress_at = time.monotonic()
        elif (
            status not in _REMOTE_TERMINAL_STATUSES
            and time.monotonic() - last_remote_progress_at
            >= _HOSTED_REMOTE_ROLE_STALL_SECONDS
        ):
            now_ms = int(time.time() * 1000)
            with _STATE_LOCK:
                stall_state = load_single_state()
                stall_location = _remote_run_location(
                    stall_state,
                    active_remote_id,
                )
                if stall_location is not None:
                    _stall_conversation, _stall_hosted, _role_key, current = stall_location
                    current.update(
                        {
                            "status": "timed_out",
                            "terminal": True,
                            "cancel_requested": True,
                            "cancel_kind": "stall",
                            "cancel_reason": "Remote run stopped advancing; liveness timeout",
                            "error": "Remote run stalled (no persisted state update)",
                            "summary": "Remote run stalled (no persisted state update)",
                            "completed_at": now_ms,
                            "updated_at": now_ms,
                        }
                    )
                    _stall_hosted.update(
                        {
                            "stage": "failed",
                            "remote_cancel_pending": True,
                            "cancel_requested": True,
                            "cancel_kind": "stall",
                            "updated_at": now_ms,
                        }
                    )
                    save_single_state(stall_state)
            _notify_hosted_update(conversation_id)
            release_remote_role_claim()
            return "", "failed", {
                "content": "",
                "status": "failed",
                "error": "Remote run stalled (no persisted state update)",
                "activities": [],
            }
        pending_intervention = _pending_hosted_role_intervention(
            conversation_id,
            turn_id,
            role_stage=role_stage,
            profile=profile,
            deliveries={"steer"},
        )
        remote_intervention_id = str(remote.get("cancel_intervention_id") or "")
        if (
            not turn_cancel_requested
            and status not in _REMOTE_TERMINAL_STATUSES
            and (isinstance(pending_intervention, dict) or remote_intervention_id)
        ):
            claimed = _request_remote_role_intervention_cancel(
                conversation_id,
                turn_id,
                remote_run_id=active_remote_id,
                role_stage=role_stage,
                profile=profile,
                intervention_id=(
                    remote_intervention_id
                    or str((pending_intervention or {}).get("id") or "")
                ),
                execution_owner=coordinator_owner,
            )
            if isinstance(claimed, dict):
                remote.update(
                    {
                        "cancel_requested": True,
                        "cancel_kind": "intervention",
                        "cancel_intervention_id": str(claimed.get("id") or ""),
                    }
                )
                remote_intervention_id = str(claimed.get("id") or "")
        if turn_cancel_requested and status not in _REMOTE_TERMINAL_STATUSES:
            # A queued run has not been claimed by a device, so it can be
            # terminally cancelled on the server immediately. Waiting for a
            # connector cancellation poll here was the reason the iOS stop
            # button appeared stuck during a disconnected two-device run.
            if status == "queued" or not str(remote.get("lease_owner") or "").strip():
                now = int(time.time() * 1000)
                with _STATE_LOCK:
                    state = load_single_state()
                    location = _remote_run_location(state, active_remote_id)
                    if location is not None:
                        _conversation, _hosted, _role_key, current = location
                        current.update(
                            {
                                "status": "cancelled",
                                "terminal": True,
                                "cancel_requested": True,
                                "cancel_kind": "turn",
                                "completed_at": now,
                                "updated_at": now,
                            }
                        )
                        save_single_state(state)
                _notify_hosted_update(conversation_id)
                release_remote_role_claim()
                _finish_hosted_turn_if_cancelled(conversation_id, turn_id)
                return "远程执行已取消。", "cancelled", {
                    "content": "远程执行已取消。",
                    "status": "cancelled",
                    "activities": list(remote.get("activities") or []),
                }
            _persist_hosted_turn(
                conversation_id,
                turn_id,
                patch={
                    "remote_cancel_pending": True,
                    "stage": "cancel_requested",
                },
            )
            release_remote_role_claim()
            return "远程执行已请求取消。", "failed", {
                "content": "远程执行已请求取消。",
                "status": "failed",
                "activities": list(remote.get("activities") or []),
            }
        # ``queued``/unclaimed is the precise signal that neither DBB3 nor PC
        # has accepted the role. Do not wait for the much longer remote run
        # deadline: hand the role to the server Hermes runtime while retaining
        # the original role/profile in the audit record.
        lease_owner = str(remote.get("lease_owner") or "").strip()
        lease_until = _nonnegative_int(remote.get("lease_until"))
        lease_expired = (
            bool(lease_owner)
            and lease_until > 0
            and int(time.time() * 1000) >= lease_until
        )
        unclaimed = (
            status in {"queued", "leased"}
            and not _nonnegative_int(remote.get("started_at"))
            and not str(remote.get("remote_task_id") or "").strip()
            and (not lease_owner or lease_expired)
        )
        if unclaimed and time.monotonic() >= fallback_deadline:
            now = int(time.time() * 1000)
            with _STATE_LOCK:
                state = load_single_state()
                location = _remote_run_location(state, active_remote_id)
                if location is not None:
                    _conversation, hosted, _role_key, current = location
                    current.update(
                        {
                            "status": "cancelled",
                            "terminal": True,
                            "cancel_requested": True,
                            "cancel_kind": "server_fallback",
                            "cancel_reason": "Remote connector unavailable; server Hermes fallback activated",
                            "completed_at": now,
                            "updated_at": now,
                        }
                    )
                    hosted.update(
                        {
                            "stage": "server_fallback",
                            "remote_fallback": True,
                            "remote_fallback_at": now,
                            "updated_at": now,
                        }
                    )
                    save_single_state(state)
            _notify_hosted_update(conversation_id)
            release_remote_role_claim()
            if _hosted_turn_cancellation_requested(conversation_id, turn_id):
                _finish_hosted_turn_if_cancelled(conversation_id, turn_id)
                return "任务已取消。", "cancelled", {
                    "content": "任务已取消。",
                    "status": "cancelled",
                    "activities": [],
                }
            fallback_stage = f"{role_stage}:server-fallback"
            fallback_result, fallback_status, fallback_state = _run_hosted_role(
                conversation_id,
                turn_id,
                profile="default",
                role_stage=fallback_stage,
                role_label="Hermes · 服务器兜底",
                prompt=(
                    "远程成员当前不可达。你是服务器 Hermes 兜底执行器；"
                    "请直接完成同一角色阶段，保留完整工具定义和用户目标，"
                    "不要等待 DBB3 或 PC。\n\n"
                    f"{prompt}"
                ),
                runner=run_profile_turn,
                kanban_task_id="",
                start_text="远程成员不可达，已切换服务器 Hermes 兜底。",
                visible=True,
            )
            fallback_state = dict(fallback_state)
            fallback_state.update(
                {
                    "server_fallback": True,
                    "fallback_from_profile": profile,
                    "fallback_from_role_stage": role_stage,
                }
            )
            # Keep the original role key authoritative for workflow bookkeeping;
            # the visible message belongs to the server Hermes role above.
            _persist_hosted_role_state(
                conversation_id,
                turn_id,
                profile=profile,
                role_stage=role_stage,
                role_label=role_label,
                state=fallback_state,
                content_fallback=fallback_result,
                visible=False,
            )
            return fallback_result, fallback_status, fallback_state
        remote_deadline = _positive_int(remote.get("deadline_at"))
        if (
            remote_deadline is not None
            and int(time.time() * 1000) >= remote_deadline
        ):
            _advance_remote_run_deadline(active_remote_id)
            with _STATE_LOCK:
                state = load_single_state()
                location = _remote_run_location(state, active_remote_id)
                if location is not None:
                    remote = dict(location[3])
            status = str(remote.get("status") or "queued")
        if status in _REMOTE_TERMINAL_STATUSES:
            pending_intervention = _pending_hosted_role_intervention(
                conversation_id,
                turn_id,
                role_stage=role_stage,
                profile=profile,
                deliveries={"steer", "follow_up"},
            )
            terminal_intervention_id = (
                remote_intervention_id
                or str((pending_intervention or {}).get("id") or "")
            )
            if terminal_intervention_id:
                checkpoint = _hosted_role_checkpoint(
                    role_stage=role_stage,
                    profile=profile,
                    execution="remote",
                    remote_run=remote,
                )
                intervention = _request_remote_role_intervention_cancel(
                    conversation_id,
                    turn_id,
                    remote_run_id=active_remote_id,
                    role_stage=role_stage,
                    profile=profile,
                    intervention_id=terminal_intervention_id,
                    execution_owner=coordinator_owner,
                ) or _hosted_intervention_by_id(
                    conversation_id,
                    turn_id,
                    terminal_intervention_id,
                )
                if isinstance(intervention, dict):
                    refreshed = _refresh_claimed_intervention_checkpoint(
                        conversation_id,
                        turn_id,
                        intervention_id=terminal_intervention_id,
                        claim_token=str(intervention.get("claim_token") or ""),
                        execution_owner=coordinator_owner,
                        role_stage=role_stage,
                        profile=profile,
                        checkpoint=checkpoint,
                    )
                    if isinstance(refreshed, dict):
                        intervention = refreshed
                    checkpoint = dict(intervention.get("checkpoint") or checkpoint)
                    digest = hashlib.sha256(
                        terminal_intervention_id.encode("utf-8")
                    ).hexdigest()[:12]
                    reply_stage = f"{role_stage}:intervention:{digest}"
                    resume_stage = f"{role_stage}:resume:{digest}"
                    intervention_reply = str(intervention.get("reply") or "").strip()
                    if str(intervention.get("status") or "") != "completed":
                        release_remote_role_claim()
                        reply_result, reply_status, _reply_state = _run_hosted_remote_role(
                            conversation_id,
                            turn_id,
                            profile=profile,
                            role_stage=reply_stage,
                            role_label=f"{role_label} · 干预回复",
                            prompt=_hosted_intervention_reply_prompt(
                                role_label=role_label,
                                intervention=intervention,
                                checkpoint=checkpoint,
                            ),
                            kanban_task_id=kanban_task_id,
                            start_text="已在安全边界暂停，正在优先回复定向干预。",
                            artifact_required=False,
                            delivery_context="Reply to the intervention only; do not create artifacts.",
                            attachment_context="",
                            rework_round=rework_round,
                            connector_id=connector_id,
                            visible=visible,
                        )
                        intervention_reply = (
                            reply_result
                            if reply_status == "completed" and reply_result.strip()
                            else "已在安全边界暂停；定向回复未完整执行，将携带检查点继续。"
                        )
                        _complete_hosted_role_intervention(
                            conversation_id,
                            turn_id,
                            intervention_id=terminal_intervention_id,
                            claim_token=str(intervention.get("claim_token") or ""),
                            execution_owner=coordinator_owner,
                            role_stage=role_stage,
                            role_label=role_label,
                            profile=profile,
                            reply=intervention_reply,
                            checkpoint=checkpoint,
                            resume_role_stage=resume_stage if status == "cancelled" else "",
                        )
                    if status == "cancelled":
                        resumed_result, resumed_status, resumed_state = (
                            _run_hosted_remote_role(
                                conversation_id,
                                turn_id,
                                profile=profile,
                                role_stage=resume_stage,
                                role_label=f"{role_label} · 恢复",
                                prompt=_hosted_intervention_resume_prompt(
                                    prompt,
                                    intervention=intervention,
                                    checkpoint=checkpoint,
                                    reply=intervention_reply,
                                ),
                                kanban_task_id=kanban_task_id,
                                start_text="已优先处理定向干预，正在从远程检查点恢复。",
                                artifact_required=artifact_required,
                                delivery_context=delivery_context,
                                attachment_context=attachment_context,
                                rework_round=rework_round,
                                connector_id=connector_id,
                                visible=visible,
                            )
                        )
                        _persist_hosted_role_state(
                            conversation_id,
                            turn_id,
                            profile=profile,
                            role_stage=role_stage,
                            role_label=role_label,
                            state=resumed_state,
                            content_fallback=resumed_result,
                            visible=visible,
                        )
                        return resumed_result, resumed_status, resumed_state
            result = str(remote.get("result") or remote.get("summary") or "").strip()
            if status != "completed" and remote.get("error"):
                result = result or f"远程执行失败：{remote['error']}"
            result = result or ("远程执行完成。" if status == "completed" else "远程执行未通过。")
            role_state = {
                "content": result,
                "status": "completed" if status == "completed" else "failed",
                "activities": [dict(item) for item in remote.get("activities") or [] if isinstance(item, dict)],
                "actual_model": str(remote.get("actual_model") or ""),
                "actual_provider": str(remote.get("actual_provider") or ""),
                "started_at": int(remote.get("started_at") or remote.get("created_at") or int(time.time() * 1000)),
                "milestone_count": 0,
                "milestone_content": "",
            }
            _persist_hosted_role_state(
                conversation_id,
                turn_id,
                profile=profile,
                role_stage=role_stage,
                role_label=role_label,
                state=role_state,
                content_fallback=result,
                visible=visible,
            )
            release_remote_role_claim()
            return result, role_state["status"], role_state
        if visible:
            _remote_run_state_message(
                conversation_id,
                turn_id,
                remote,
                role_label=role_label,
            )
        if time.monotonic() >= deadline:
            _advance_remote_run_deadline(active_remote_id)
            deadline = time.monotonic() + _REMOTE_CANCELLATION_GRACE_SECONDS
        revision = _wait_for_hosted_update(revision, 15.0)


def create_hosted_turn_record(
    conversation: dict[str, Any],
    *,
    turn_id: str,
    user_message_id: str = "",
    content: str,
    title: str,
    profiles: list[str],
    artifact_required: bool,
    attachment_context: str = "",
    delivery_context: str = "",
    user_delivery_context: str = "",
    mode: str = "work",
    route_metadata: Optional[dict[str, Any]] = None,
    output_dir: str = "",
    attachment_ids: Optional[list[str]] = None,
) -> dict[str, Any]:
    normalized_turn_id = str(turn_id or "").strip()
    if not normalized_turn_id:
        raise ValueError("turn_id is required")
    hosted_turns = conversation.get("hosted_turns")
    if not isinstance(hosted_turns, dict):
        hosted_turns = {}
        conversation["hosted_turns"] = hosted_turns
    existing = hosted_turns.get(normalized_turn_id)
    if isinstance(existing, dict):
        return existing
    cancel_key = (str(conversation.get("id") or ""), normalized_turn_id)
    with _HOSTED_CANCEL_STATE_LOCK:
        _HOSTED_CANCEL_SIGNALS.discard(cancel_key)
        _HOSTED_CANCEL_CACHE.pop(cancel_key, None)
    now = int(time.time() * 1000)
    normalized_mode = str(mode or "work").strip().lower()
    if normalized_mode not in {"chat", "work"}:
        normalized_mode = "work"
    route_metadata = dict(route_metadata or {})
    owner_id = str(conversation.get("owner_id") or LOCAL_OWNER_ID)
    account_generation = str(conversation.get("account_generation") or "").strip()
    if not account_generation:
        account_generation = _account_generation_for_owner(owner_id)
        conversation["account_generation"] = account_generation
    artifact_producers = _artifact_producer_profiles(
        route_metadata,
        profiles,
        required=bool(artifact_required),
    )
    record = {
        "turn_id": normalized_turn_id,
        # The account-scoped conversation stores the optimistic user message
        # before the official gateway receives the prompt. Keep its identity
        # on the turn so a first-turn prompt can project only prior history.
        "user_message_id": str(user_message_id or "").strip(),
        "account_generation": account_generation,
        "status": "queued",
        "stage": "accepted",
        "content": str(content or "").strip(),
        "title": str(title or "").strip() or summarize_task_title(content),
        "profiles": list(
            dict.fromkeys(str(item).strip() for item in profiles if str(item).strip())
        ),
        "artifact_required": bool(artifact_required),
        "artifact_producer_profiles": artifact_producers,
        "artifact": dict(route_metadata.get("artifact") or {}),
        "mode": normalized_mode,
        "route_metadata": route_metadata,
        "attachment_ids": list(
            dict.fromkeys(
                str(item).strip()
                for item in (attachment_ids or [])
                if str(item).strip().startswith("file_")
            )
        ),
        "attachment_context": str(attachment_context or "").strip(),
        "delivery_context": str(delivery_context or "").strip(),
        "user_delivery_context": str(user_delivery_context or "").strip(),
        "output_dir": str(output_dir or "").strip(),
        "cancel_requested": False,
        "interventions": [],
        "active_roles": {},
        "supervisor_checks": {},
        "participants": [],
        "created_at": now,
        "updated_at": now,
    }
    hosted_turns[normalized_turn_id] = record
    if normalized_mode == "work":
        append_hosted_event(
            conversation,
            conversation_id=str(conversation.get("id") or "conversation"),
            turn_id=normalized_turn_id,
            role_stage="manager",
            event_type="role.handoff",
            entity_id=f"{normalized_turn_id}:collaboration-lift",
            idempotency_key=f"turn:{normalized_turn_id}:collaboration-lift",
            account_generation=account_generation,
            payload={
                "entity_id": f"{normalized_turn_id}:collaboration-lift",
                "action": "collaboration_lift",
                "from_role": "chat",
                "to_role": "manager",
            },
            occurred_at=now,
        )
    _append_attachment_session_entries(
        conversation,
        turn_id=normalized_turn_id,
        role_stage="user",
        attachments=record["attachment_ids"],
        direction="input",
        occurred_at=now,
    )
    conversation["updated_at"] = now
    return record


def hosted_artifact_instruction(
    run: dict[str, Any],
    *,
    remote_workers: bool,
) -> str:
    if not _coerce_flag(run.get("artifact_required")):
        return "本任务未要求交付文件。不要创建、复制或上传文件，只提交文字结果和必要证据。"
    if not remote_workers:
        return str(run.get("delivery_context") or "").strip()
    user_context = str(run.get("user_delivery_context") or "").strip()
    return "\n".join(
        item
        for item in (
            user_context,
            "This role executes on a remote DBB3 worker; the public server output directory is not mounted here.",
            "Create every requested deliverable inside $HERMES_KANBAN_WORKSPACE using an absolute path.",
            "Before exiting, call kanban_complete(artifacts=[...]) with every deliverable absolute path so the cloud connector uploads it to the account file library.",
            "Do not rely on a prose path or a Kanban comment as artifact registration.",
        )
        if item
    )


def _artifact_producer_profiles(
    route_metadata: dict[str, Any],
    profiles: list[str],
    *,
    required: bool,
) -> list[str]:
    """Assign overall file delivery to specific execution lanes."""

    workers = [
        str(profile).strip()
        for profile in profiles
        if collaboration_role(str(profile)) == "worker"
    ]
    if not required or not workers:
        return []
    artifact = route_metadata.get("artifact")
    artifact = dict(artifact) if isinstance(artifact, dict) else {}
    requested = [
        str(value).strip().lower()
        for value in artifact.get("producer_profiles") or []
        if str(value).strip()
    ]
    requested.extend(
        f"{str(value).strip().lower()}-worker"
        for value in artifact.get("producer_targets") or []
        if str(value).strip().lower() in {"dbb3", "pc"}
    )
    selected = [profile for profile in workers if profile.lower() in requested]
    return list(dict.fromkeys(selected or workers[:1]))


def create_hosted_kanban_task(
    *,
    conversation_id: str,
    turn_id: str,
    title: str,
    content: str,
    profiles: Optional[list[str]] = None,
    output_dir: str = "",
    manager_plan: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    from hermes_cli import kanban_db, kanban_decompose

    kanban_db.init_db()
    conn = kanban_db.connect()
    try:
        lane_context = ", ".join(profiles or [])
        # The execution path stays in the hosted run and role prompt. Kanban
        # bodies are user-visible and must not expose server filesystem paths.
        plan_blocks: list[str] = []
        if isinstance(manager_plan, dict):
            for label, value in (
                ("执行方案", manager_plan.get("approach")),
                ("任务要求", manager_plan.get("task_requirements")),
                ("测试方案", manager_plan.get("test_plan")),
            ):
                if str(value or "").strip():
                    plan_blocks.append(f"【{label}】\n{str(value).strip()[:12000]}")
            criteria = manager_plan.get("acceptance_criteria") or []
            if criteria:
                plan_blocks.append(
                    "【验收标准】\n"
                    + "\n".join(f"- {str(item).strip()[:2000]}" for item in criteria if str(item).strip())
                )
            flow = manager_plan.get("flow") or []
            if flow:
                plan_blocks.append(
                    "【流程方案】\n"
                    + "\n".join(f"{index}. {str(item).strip()[:2000]}" for index, item in enumerate(flow, start=1) if str(item).strip())
                )
        task_body = "\n\n".join(
            item
            for item in (
                content,
                *plan_blocks,
                f"Required execution lanes: {lane_context}." if lane_context else "",
            )
            if item
        )
        task_id = kanban_db.create_task(
            conn,
            title=title,
            body=task_body,
            created_by="unified-webui-hosted",
            workspace_kind="scratch",
            triage=True,
            idempotency_key=f"collaboration:{conversation_id}:{turn_id}",
            goal_mode=True,
            session_id=conversation_id,
            context_variables=(
                dict(manager_plan.get("context_variables"))
                if isinstance(manager_plan, dict)
                and isinstance(manager_plan.get("context_variables"), dict)
                and manager_plan.get("context_variables")
                else None
            ),
        )
    finally:
        conn.close()
    try:
        outcome = kanban_decompose.decompose_task(
            task_id,
            author="unified-webui-hosted",
        )
        child_ids = outcome.child_ids or []
        profile_task_ids: dict[str, str] = {}
        if child_ids:
            conn = kanban_db.connect()
            try:
                for child_id in child_ids:
                    child = kanban_db.get_task(conn, child_id)
                    if child is not None and child.assignee:
                        profile_task_ids.setdefault(str(child.assignee), str(child.id))
            finally:
                conn.close()
        return {
            "task_id": task_id,
            "fanout": bool(outcome.fanout),
            "child_ids": child_ids,
            "profile_task_ids": profile_task_ids,
            "reason": outcome.reason,
        }
    except Exception as exc:
        return {
            "task_id": task_id,
            "fanout": False,
            "child_ids": [],
            "reason": f"任务拆分暂时失败：{exc}",
        }


def _notify_hosted_update(conversation_id: str = "") -> int:
    global _HOSTED_UPDATE_REVISION
    normalized_conversation_id = str(conversation_id or "").strip()
    with _HOSTED_UPDATE_CONDITION:
        _HOSTED_UPDATE_REVISION += 1
        if normalized_conversation_id:
            _HOSTED_UPDATE_REVISIONS[normalized_conversation_id] = (
                _HOSTED_UPDATE_REVISIONS.get(normalized_conversation_id, 0) + 1
            )
        _HOSTED_UPDATE_CONDITION.notify_all()
        return (
            _HOSTED_UPDATE_REVISIONS[normalized_conversation_id]
            if normalized_conversation_id
            else _HOSTED_UPDATE_REVISION
        )


def _completion_notification_record(
    conversation_id: str,
    turn_id: str,
    status: str,
    result: str,
) -> dict[str, Any]:
    now = int(time.time() * 1000)
    collapse_id = "hermes-turn-" + hashlib.sha256(
        f"{conversation_id}\0{turn_id}".encode("utf-8")
    ).hexdigest()[:40]
    return {
        "id": collapse_id,
        "state": "queued",
        "task_status": str(status or "completed").strip().lower(),
        "result": str(result or "").strip()[:50_000],
        "collapse_id": collapse_id,
        "attempts": 0,
        "deliveries": {},
        "last_error": "",
        "next_attempt_at": now,
        "created_at": now,
        "updated_at": now,
    }


def _schedule_mobile_notification(
    conversation_id: str,
    turn_id: str,
    kind: str,
    status: str,
    result: str,
) -> None:
    """Queue a persisted notification on the process-wide APNs dispatcher.

    kind="completion" delivers a task-completion push; kind="awaiting"
    delivers a "needs your decision" push while the member parks on a
    human question. Each kind has its own durable record so an awaiting
    push followed by a completion push do not overwrite each other.
    """

    global _MOBILE_NOTIFICATION_DISPATCH_THREAD

    field = "notification" if kind == "completion" else "notification_awaiting"
    try:
        with _STATE_LOCK:
            state = load_single_state()
            conversation = _conversation_by_id(state, conversation_id)
            run = (conversation.get("hosted_turns") or {}).get(turn_id)
            if not isinstance(run, dict):
                return
            owner_id = str(conversation.get("owner_id") or "").strip()
            notification = run.get(field)
            if not isinstance(notification, dict):
                notification = _completion_notification_record(
                    conversation_id,
                    turn_id,
                    status,
                    result,
                )
                run[field] = notification
                save_single_state(state)
            notification_state = str(notification.get("state") or "queued")
        if notification_state in _MOBILE_NOTIFICATION_TERMINAL_STATUSES:
            return
        if not owner_id:
            _persist_notification_outcome(
                conversation_id,
                turn_id,
                kind,
                {
                    "state": "no_recipients",
                    "deliveries": {},
                    "error": "notification_owner_missing",
                },
            )
            return
        key = f"{conversation_id}:{turn_id}:{kind}"
        due_at = max(
            int(time.time() * 1000),
            int(notification.get("next_attempt_at") or 0),
        )
        with _MOBILE_NOTIFICATION_DISPATCH_CONDITION:
            current = _MOBILE_NOTIFICATION_PENDING.get(key)
            if current is None or due_at < current[2]:
                _MOBILE_NOTIFICATION_PENDING[key] = (
                    conversation_id,
                    turn_id,
                    due_at,
                    kind,
                )
            if (
                _MOBILE_NOTIFICATION_DISPATCH_THREAD is None
                or not _MOBILE_NOTIFICATION_DISPATCH_THREAD.is_alive()
            ):
                _MOBILE_NOTIFICATION_DISPATCH_THREAD = threading.Thread(
                    target=_mobile_notification_dispatch_loop,
                    name="hermes-apns-dispatcher",
                    # Claims and per-device outcomes are durable before each
                    # network step, so process exit leaves replayable work.
                    daemon=True,
                )
                _MOBILE_NOTIFICATION_DISPATCH_THREAD.start()
            _MOBILE_NOTIFICATION_DISPATCH_CONDITION.notify()
    except Exception:
        # The persisted outbox remains available for startup replay.
        return


def _schedule_mobile_completion_notification(
    conversation_id: str,
    turn_id: str,
    status: str,
    result: str,
) -> None:
    """Queue a persisted task-completion notification (background exit UX)."""

    _schedule_mobile_notification(conversation_id, turn_id, "completion", status, result)


def _schedule_mobile_awaiting_notification(
    conversation_id: str,
    turn_id: str,
    question: str,
) -> None:
    """Queue a "needs your decision" notification for a parked member.

    The member asked the user a question and is waiting. If the app is in
    the background this is the highest-priority signal — without it the
    workflow parks silently until the user reopens the app.
    """

    _schedule_mobile_notification(
        conversation_id,
        turn_id,
        "awaiting",
        "awaiting",
        str(question or "等待你的决定").strip()[:4000],
    )


def _cancel_pending_awaiting_notification(
    conversation_id: str,
    turn_id: str,
) -> None:
    """Retire an unanswered awaiting push: the member resumed (answer applied)."""

    try:
        with _STATE_LOCK:
            state = load_single_state()
            conversation = _conversation_by_id(state, conversation_id)
            run = (conversation.get("hosted_turns") or {}).get(turn_id)
            if not isinstance(run, dict):
                return
            notification = run.get("notification_awaiting")
            if not isinstance(notification, dict):
                return
            if str(notification.get("state") or "queued") in _MOBILE_NOTIFICATION_TERMINAL_STATUSES:
                return
            now = int(time.time() * 1000)
            run["notification_awaiting"] = {
                **notification,
                "state": "delivered",
                "last_error": "awaiting_resolved",
                "completed_at": now,
                "updated_at": now,
            }
            save_single_state(state)
        key = f"{conversation_id}:{turn_id}:awaiting"
        with _MOBILE_NOTIFICATION_DISPATCH_CONDITION:
            _MOBILE_NOTIFICATION_PENDING.pop(key, None)
    except Exception:
        return


def _schedule_persisted_terminal_notification(
    conversation_id: str,
    turn_id: str,
    persisted_run: dict[str, Any],
    *,
    fallback_result: str = "",
) -> None:
    """Notify only the terminal state that won the durable state transition."""

    actual_status = str(persisted_run.get("status") or "")
    if actual_status not in _HOSTED_TERMINAL_STATUSES:
        return
    notification = persisted_run.get("notification")
    notification = dict(notification) if isinstance(notification, dict) else {}
    task_status = str(notification.get("task_status") or actual_status)
    if task_status != actual_status:
        task_status = actual_status
    result = str(
        notification.get("result")
        or persisted_run.get("reporter_result")
        or persisted_run.get("chat_result")
        or fallback_result
    )
    _schedule_mobile_completion_notification(
        conversation_id,
        turn_id,
        task_status,
        result,
    )


def _replay_persisted_mobile_notifications() -> None:
    """Re-enqueue every durable non-terminal notification after a restart."""

    try:
        with _STATE_LOCK:
            state = load_single_state()
            for conversation in state.get("conversations") or []:
                if not isinstance(conversation, dict):
                    continue
                conversation_id = str(conversation.get("id") or "")
                if not conversation_id:
                    continue
                for turn_id, run in (conversation.get("hosted_turns") or {}).items():
                    if not isinstance(run, dict):
                        continue
                    for field, kind in (
                        ("notification", "completion"),
                        ("notification_awaiting", "awaiting"),
                    ):
                        notification = run.get(field)
                        if not isinstance(notification, dict):
                            continue
                        if (
                            str(notification.get("state") or "queued")
                            in _MOBILE_NOTIFICATION_TERMINAL_STATUSES
                        ):
                            continue
                        key = f"{conversation_id}:{turn_id}:{kind}"
                        due_at = max(
                            int(time.time() * 1000),
                            int(notification.get("next_attempt_at") or 0),
                        )
                        with _MOBILE_NOTIFICATION_DISPATCH_CONDITION:
                            current = _MOBILE_NOTIFICATION_PENDING.get(key)
                            if current is None or due_at < current[2]:
                                _MOBILE_NOTIFICATION_PENDING[key] = (
                                    conversation_id,
                                    str(turn_id),
                                    due_at,
                                    kind,
                                )
        with _MOBILE_NOTIFICATION_DISPATCH_CONDITION:
            _MOBILE_NOTIFICATION_DISPATCH_CONDITION.notify()
    except Exception:
        logger.exception("mobile notification replay failed")


def _mobile_notification_dispatch_loop() -> None:
    """Deliver all persistent APNs jobs without allocating one thread per job."""

    _replay_persisted_mobile_notifications()
    while True:
        # A hosted server can legitimately run without APNs credentials (for
        # example during local/self-hosted deployment). Keep the durable
        # outbox retryable for a later configuration change, but do not drain
        # every pending record in a tight loop and serialize the large
        # collaboration state document for each failed attempt.
        try:
            from hermes_cli.dashboard_auth.mobile_notifications import apns_configured

            if not apns_configured():
                with _MOBILE_NOTIFICATION_DISPATCH_CONDITION:
                    _MOBILE_NOTIFICATION_DISPATCH_CONDITION.wait(timeout=300.0)
                continue
        except Exception:
            # Preserve the existing fail-open delivery behavior when the
            # optional notification module is unavailable.
            pass
        with _MOBILE_NOTIFICATION_DISPATCH_CONDITION:
            while not _MOBILE_NOTIFICATION_PENDING:
                _MOBILE_NOTIFICATION_DISPATCH_CONDITION.wait()
            key, pending = min(
                _MOBILE_NOTIFICATION_PENDING.items(),
                key=lambda item: item[1][2],
            )
            conversation_id, turn_id, due_at, kind = pending
            remaining_ms = due_at - int(time.time() * 1000)
            if remaining_ms > 0:
                _MOBILE_NOTIFICATION_DISPATCH_CONDITION.wait(
                    timeout=remaining_ms / 1000
                )
                continue
            _MOBILE_NOTIFICATION_PENDING.pop(key, None)

        try:
            retry_delay_ms = _deliver_persisted_notification(
                conversation_id,
                turn_id,
                kind,
            )
        except Exception:
            retry_delay_ms = 60_000
        if retry_delay_ms is not None:
            with _MOBILE_NOTIFICATION_DISPATCH_CONDITION:
                _MOBILE_NOTIFICATION_PENDING[key] = (
                    conversation_id,
                    turn_id,
                    int(time.time() * 1000) + max(0, retry_delay_ms),
                    kind,
                )
                _MOBILE_NOTIFICATION_DISPATCH_CONDITION.notify()


def _deliver_persisted_notification(
    conversation_id: str,
    turn_id: str,
    kind: str,
) -> Optional[int]:
    field = "notification" if kind == "completion" else "notification_awaiting"
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            return None
        notification = run.get(field)
        if not isinstance(notification, dict):
            return None
        notification_state = str(notification.get("state") or "queued")
        if notification_state in _MOBILE_NOTIFICATION_TERMINAL_STATUSES:
            return None
        now = int(time.time() * 1000)
        next_attempt_at = int(notification.get("next_attempt_at") or 0)
        if notification_state == "retry" and next_attempt_at > now:
            return next_attempt_at - now
        owner_id = str(conversation.get("owner_id") or "").strip()
        claimed = {
            **notification,
            "state": "delivering",
            "attempts": int(notification.get("attempts") or 0) + 1,
            "updated_at": now,
        }
        run[field] = claimed
        save_single_state(state)

    if not owner_id:
        return _persist_notification_outcome(
            conversation_id,
            turn_id,
            kind,
            {
                "state": "no_recipients",
                "deliveries": dict(claimed.get("deliveries") or {}),
                "error": "notification_owner_missing",
            },
        )

    # Presence suppression: while the owner watches this conversation live
    # (hosted-events SSE open), a loud push is noise — the terminal state
    # renders in-app. The moment the stream drops (app backgrounded/killed),
    # _sse_presence_leave forces the due time to now and the dispatcher fires
    # within seconds. This is the core of the background-exit completion UX.
    if _has_active_sse_watcher(conversation_id):
        return _persist_notification_outcome(
            conversation_id,
            turn_id,
            kind,
            {
                "state": "retry",
                "deliveries": dict(claimed.get("deliveries") or {}),
                "error": "notification_suppressed_online",
            },
        )

    def persist_progress(deliveries: dict[str, dict[str, Any]]) -> None:
        with _STATE_LOCK:
            current_state = load_single_state()
            current_conversation = _conversation_by_id(current_state, conversation_id)
            current_run = (current_conversation.get("hosted_turns") or {}).get(turn_id)
            if not isinstance(current_run, dict):
                return
            current = current_run.get(field)
            if not isinstance(current, dict):
                return
            current_run[field] = {
                **current,
                "deliveries": deliveries,
                "updated_at": int(time.time() * 1000),
            }
            save_single_state(current_state)

    try:
        if kind == "awaiting":
            from hermes_cli.dashboard_auth.mobile_notifications import (
                deliver_account_notification_push,
            )

            outcome = deliver_account_notification_push(
                owner_id=owner_id,
                notification_id=(
                    "awaiting:" + claimed.get("collapse_id", "turn")
                )[:256],
                title="Hermes 成员需要你的决定",
                body=str(claimed.get("result") or "等待你的决定")[:180],
                category="awaiting",
                deep_link=(
                    "hermes-agent://conversation/"
                    f"{quote(conversation_id, safe='')}"
                    f"?turn={quote(turn_id, safe='')}"
                ),
                data={
                    "conversation_id": conversation_id,
                    "turn_id": turn_id,
                },
                previous_deliveries=dict(claimed.get("deliveries") or {}),
                progress_callback=persist_progress,
            )
        else:
            from hermes_cli.dashboard_auth.mobile_notifications import (
                deliver_task_completion_push,
            )

            outcome = deliver_task_completion_push(
                owner_id=owner_id,
                conversation_id=conversation_id,
                turn_id=turn_id,
                status=str(claimed.get("task_status") or "completed"),
                result=str(claimed.get("result") or ""),
                collapse_id=str(claimed.get("collapse_id") or claimed.get("id") or ""),
                previous_deliveries=dict(claimed.get("deliveries") or {}),
                progress_callback=persist_progress,
            )
    except Exception as exc:
        outcome = {
            "state": "retry",
            "deliveries": dict(claimed.get("deliveries") or {}),
            "error": f"notification_delivery_failed:{type(exc).__name__}"[:240],
        }
    return _persist_notification_outcome(conversation_id, turn_id, kind, outcome)


def _persist_notification_outcome(
    conversation_id: str,
    turn_id: str,
    kind: str,
    outcome: dict[str, Any],
) -> Optional[int]:
    field = "notification" if kind == "completion" else "notification_awaiting"
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            return None
        notification = run.get(field)
        if not isinstance(notification, dict):
            return None
        now = int(time.time() * 1000)
        outcome_state = str(outcome.get("state") or "retry")
        error = str(outcome.get("error") or "")[:240]
        next_attempt_at = 0
        retry_delay_ms: Optional[int] = None
        if outcome_state == "retry":
            if error == "notification_suppressed_online":
                # The user is watching live: re-check on a short cadence so
                # the push fires within seconds of the app going offline.
                retry_delay_ms = _NOTIFICATION_ONLINE_RECHECK_MS
            else:
                retry_delay_ms = _notification_retry_delay_ms(
                    int(notification.get("attempts") or 1)
                )
                if error == "apns_not_configured":
                    retry_delay_ms = 5 * 60 * 1000
            next_attempt_at = now + retry_delay_ms
        run[field] = {
            **notification,
            "state": outcome_state,
            "deliveries": dict(outcome.get("deliveries") or {}),
            "last_error": error,
            "next_attempt_at": next_attempt_at,
            "updated_at": now,
            **(
                {"completed_at": now}
                if outcome_state in _MOBILE_NOTIFICATION_TERMINAL_STATUSES
                else {}
            ),
        }
        save_single_state(state)
    _notify_hosted_update(conversation_id)
    if outcome_state != "retry":
        return None
    return retry_delay_ms


def _notification_retry_delay_ms(attempts: int) -> int:
    exponent = max(0, min(int(attempts) - 1, 8))
    return min(60 * 60 * 1000, 15_000 * (2**exponent))


def _has_active_sse_watcher(conversation_id: str) -> bool:
    with _CONVERSATION_SSE_PRESENCE_LOCK:
        return _CONVERSATION_SSE_PRESENCE.get(str(conversation_id or ""), 0) > 0


def _sse_presence_enter(conversation_id: str) -> None:
    with _CONVERSATION_SSE_PRESENCE_LOCK:
        _CONVERSATION_SSE_PRESENCE[conversation_id] = (
            _CONVERSATION_SSE_PRESENCE.get(conversation_id, 0) + 1
        )


def _sse_presence_leave(conversation_id: str) -> None:
    """The last watcher dropped: fire any push suppressed while they watched."""

    became_absent = False
    with _CONVERSATION_SSE_PRESENCE_LOCK:
        count = _CONVERSATION_SSE_PRESENCE.get(conversation_id, 0) - 1
        if count <= 0:
            _CONVERSATION_SSE_PRESENCE.pop(conversation_id, None)
            became_absent = True
        else:
            _CONVERSATION_SSE_PRESENCE[conversation_id] = count
    if not became_absent:
        return
    with _MOBILE_NOTIFICATION_DISPATCH_CONDITION:
        for key, pending in list(_MOBILE_NOTIFICATION_PENDING.items()):
            if pending[0] == conversation_id:
                _MOBILE_NOTIFICATION_PENDING[key] = (
                    pending[0],
                    pending[1],
                    0,
                    pending[3],
                )
        _MOBILE_NOTIFICATION_DISPATCH_CONDITION.notify()


def _hosted_update_revision(conversation_id: str = "") -> int:
    normalized_conversation_id = str(conversation_id or "").strip()
    with _HOSTED_UPDATE_CONDITION:
        if normalized_conversation_id:
            return _HOSTED_UPDATE_REVISIONS.get(normalized_conversation_id, 0)
        return _HOSTED_UPDATE_REVISION


def _wait_for_hosted_update(
    revision: int,
    timeout: float = 15.0,
    conversation_id: str = "",
) -> int:
    normalized_conversation_id = str(conversation_id or "").strip()
    with _HOSTED_UPDATE_CONDITION:
        current_revision = (
            _HOSTED_UPDATE_REVISIONS.get(normalized_conversation_id, 0)
            if normalized_conversation_id
            else _HOSTED_UPDATE_REVISION
        )
        if current_revision <= revision:
            _HOSTED_UPDATE_CONDITION.wait(timeout=timeout)
        return (
            _HOSTED_UPDATE_REVISIONS.get(normalized_conversation_id, 0)
            if normalized_conversation_id
            else _HOSTED_UPDATE_REVISION
        )


def _persist_hosted_turn(
    conversation_id: str,
    turn_id: str,
    *,
    patch: Optional[dict[str, Any]] = None,
    message: Optional[dict[str, Any]] = None,
    runtime_session: Optional[tuple[str, str]] = None,
    source_message_meta: Optional[dict[str, Any]] = None,
    protocol_events: Optional[list[dict[str, Any]]] = None,
    session_entries: Optional[list[dict[str, Any]]] = None,
    expected_account_generation: str = "",
) -> dict[str, Any]:
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            raise RuntimeError("托管任务记录不存在")
        owner_id = str(conversation.get("owner_id") or LOCAL_OWNER_ID)
        live_generation = _account_generation_for_owner(owner_id)
        conversation_generation = str(
            conversation.get("account_generation") or ""
        ).strip()
        run_generation = str(run.get("account_generation") or "").strip()
        expected_generation = str(
            expected_account_generation
            or getattr(_HOSTED_EXECUTION_GENERATION, "value", "")
            or run_generation
            or conversation_generation
            or live_generation
        ).strip()
        if (
            live_generation != expected_generation
            or (conversation_generation and conversation_generation != expected_generation)
            or (run_generation and run_generation != expected_generation)
        ):
            raise RuntimeError("stale hosted turn account generation")
        conversation["account_generation"] = expected_generation
        run["account_generation"] = expected_generation
        incoming_status = str((patch or {}).get("status") or "").lower()
        current_status = str(run.get("status") or "").lower()
        if current_status in _HOSTED_TERMINAL_STATUSES:
            # The first terminal transaction is authoritative. Even a late
            # writer repeating the same status may carry stale fields or a
            # duplicate message. Repair legacy terminal records, but never
            # apply the retry's stale patch or message.
            before_cursor = int(conversation.get("hosted_event_cursor") or 0)
            before_entry_cursor = int(conversation.get("session_entry_cursor") or 0)
            _append_canonical_turn_terminal(
                conversation,
                conversation_id=conversation_id,
                turn_id=turn_id,
                run=run,
                occurred_at=int(run.get("completed_at") or time.time() * 1000),
            )
            if (
                int(conversation.get("hosted_event_cursor") or 0) != before_cursor
                or int(conversation.get("session_entry_cursor") or 0)
                != before_entry_cursor
            ):
                save_single_state(state)
                _notify_hosted_update(conversation_id)
            return dict(run)
        if (
            (_coerce_flag(run.get("cancel_requested")) or current_status == "cancelled")
            and incoming_status != "cancelled"
        ):
            return dict(run)
        now = int(time.time() * 1000)
        previous_stage = str(run.get("stage") or "accepted")
        if patch:
            for key, value in patch.items():
                if key == "role_events" and isinstance(value, dict):
                    role_events = run.get("role_events")
                    if not isinstance(role_events, dict):
                        role_events = {}
                        run["role_events"] = role_events
                    role_events.update(value)
                elif key == "participants" and isinstance(value, list):
                    _merge_hosted_participants(run, value)
                else:
                    run[key] = value
        current_stage = str(run.get("stage") or previous_stage)
        if current_stage != previous_stage:
            transition_sequence = int(run.get("stage_transition_sequence") or 0) + 1
            run["stage_transition_sequence"] = transition_sequence
            append_hosted_event(
                conversation,
                conversation_id=conversation_id,
                turn_id=turn_id,
                role_stage="turn",
                event_type="role.handoff",
                entity_id=f"{turn_id}:stage:{transition_sequence}",
                idempotency_key=(
                    f"turn:{turn_id}:stage:{transition_sequence}:"
                    f"{previous_stage}:{current_stage}"
                ),
                account_generation=expected_generation,
                payload={
                    "entity_id": f"{turn_id}:stage:{transition_sequence}",
                    "action": "stage_transition",
                    "from_role": previous_stage,
                    "to_role": current_stage,
                },
                occurred_at=now,
            )
        run["updated_at"] = now
        conversation["updated_at"] = now
        terminal_status = str(run.get("status") or "").lower()
        if terminal_status in _HOSTED_TERMINAL_STATUSES:
            run.setdefault("terminal_commit_id", f"terminal_{uuid.uuid4().hex}")
            run.setdefault("terminal_committed_at", now)
            active_statuses = {"pending", "queued", "running", "starting", "streaming"}
            for intervention in run.get("interventions") or []:
                if not isinstance(intervention, dict):
                    continue
                if str(intervention.get("status") or "pending") not in {
                    "pending",
                    "processing",
                }:
                    continue
                intervention.update(
                    {
                        "status": "cancelled",
                        "cancel_reason": f"hosted_turn_{terminal_status}",
                        "cancelled_at": now,
                        "completed_at": now,
                        "updated_at": now,
                    }
                )
                intervention.pop("claim_token", None)
                intervention.pop("execution_owner", None)
                intervention["lease_expires_at"] = 0
                intervention_id = str(intervention.get("id") or "").strip()
                if intervention_id:
                    append_session_entry(
                        conversation,
                        entry_type="intervention",
                        idempotency_key=(
                            f"intervention:{intervention_id}:cancelled:"
                            f"{terminal_status}"
                        ),
                        payload={
                            "intervention_id": intervention_id,
                            "turn_id": turn_id,
                            "status": "cancelled",
                            "reason": f"hosted_turn_{terminal_status}",
                        },
                        occurred_at=now,
                    )
            run["active_roles"] = {}
            for state_key in ("role_events", "remote_runs"):
                child_states = run.get(state_key)
                if not isinstance(child_states, dict):
                    continue
                for child_state in child_states.values():
                    if not isinstance(child_state, dict):
                        continue
                    if terminal_status == "cancelled" and state_key == "remote_runs":
                        child_state["cancel_requested"] = True
                        child_state["cancel_kind"] = "turn"
                        child_state["cancel_intervention_id"] = ""
                        child_state["cancel_reason"] = str(
                            run.get("cancel_reason") or "用户取消"
                        )[:1000]
                        child_state["cancel_requested_at"] = now
                        child_state["cancel_force_terminal_at"] = (
                            now + _REMOTE_USER_CANCEL_FORCE_SECONDS * 1000
                        )
                        # The hosted turn is terminal immediately, but a live
                        # device worker still needs a durable cancellation to
                        # pull and acknowledge.  `cancelling` is deliberately
                        # non-terminal; the cancel claim owns the only allowed
                        # transition from here to `cancelled`.
                        if str(child_state.get("status") or "").lower() not in _REMOTE_TERMINAL_STATUSES:
                            child_state["status"] = "cancelling"
                            child_state.pop("completed_at", None)
                        child_state["updated_at"] = now
                    if str(child_state.get("status") or "").lower() in active_statuses:
                        child_state["status"] = terminal_status
                        child_state["completed_at"] = now
                        child_state["updated_at"] = now
                    if state_key == "remote_runs":
                        _seal_remote_run_claim(child_state, now=now)
            for existing_message in conversation.get("messages") or []:
                if not isinstance(existing_message, dict):
                    continue
                existing_meta = existing_message.get("meta")
                if not isinstance(existing_meta, dict):
                    continue
                if str(existing_meta.get("runtime_turn_id") or "") != turn_id:
                    continue
                if str(existing_message.get("status") or "").lower() not in active_statuses:
                    continue
                existing_message["status"] = terminal_status
                existing_message["updated_at"] = now
                existing_meta["completed_at"] = now
                for activity in existing_meta.get("activities") or []:
                    if not isinstance(activity, dict):
                        continue
                    if str(activity.get("status") or "").lower() in active_statuses:
                        activity["status"] = terminal_status
                        activity["completed_at"] = now
                        activity["updated_at"] = now
                _project_native_message(existing_message)
            for runtime_run in (conversation.get("runtime_runs") or {}).values():
                if not isinstance(runtime_run, dict):
                    continue
                if str(runtime_run.get("turn_id") or "") != turn_id:
                    continue
                if str(runtime_run.get("status") or "").lower() not in active_statuses:
                    continue
                runtime_run["status"] = terminal_status
                runtime_run["completed_at"] = now
                runtime_run["updated_at"] = now
        if runtime_session:
            runtime_profile, runtime_session_id = runtime_session
            if str(runtime_session_id or "").strip():
                set_conversation_runtime_session(
                    conversation,
                    str(runtime_profile or "default"),
                    str(runtime_session_id),
                )
        if source_message_meta:
            source_id = next(
                (
                    str(record.get("message_id") or "")
                    for record in (conversation.get("enqueue_requests") or {}).values()
                    if isinstance(record, dict)
                    and str(record.get("turn_id") or "") == turn_id
                ),
                "",
            )
            source_message = next(
                (
                    item
                    for item in conversation.get("messages") or []
                    if isinstance(item, dict)
                    and str(item.get("id") or "") == source_id
                ),
                None,
            )
            if source_message is not None:
                source_message["meta"] = {
                    **(
                        source_message.get("meta")
                        if isinstance(source_message.get("meta"), dict)
                        else {}
                    ),
                    **source_message_meta,
                }
                source_message["updated_at"] = now
                _project_native_message(source_message)
        def append_protocol_event(protocol_event: dict[str, Any]) -> None:
            append_hosted_event(
                conversation,
                conversation_id=conversation_id,
                turn_id=turn_id,
                role_stage=str(
                    protocol_event.get("role_stage")
                    or next(
                        (
                            str(item.get("role_stage") or "")
                            for item in (patch or {}).get("role_events", {}).values()
                            if isinstance(item, dict)
                        ),
                        "chat",
                    )
                ),
                event_type=str(protocol_event.get("event_type") or "message.delta"),
                payload=(
                    protocol_event.get("payload")
                    if isinstance(protocol_event.get("payload"), dict)
                    else {}
                ),
                entity_id=str(protocol_event.get("entity_id") or ""),
                idempotency_key=str(protocol_event.get("idempotency_key") or ""),
                occurred_at=int(protocol_event.get("occurred_at") or now),
                account_generation=expected_generation,
                **_runtime_event_kwargs(protocol_event),
            )

        for session_entry in session_entries or []:
            if not isinstance(session_entry, dict):
                continue
            append_session_entry(
                conversation,
                entry_type=str(session_entry.get("entry_type") or "label"),
                idempotency_key=str(session_entry.get("idempotency_key") or ""),
                payload=(
                    dict(session_entry.get("payload"))
                    if isinstance(session_entry.get("payload"), dict)
                    else {}
                ),
                occurred_at=int(session_entry.get("occurred_at") or now),
            )

        for protocol_event in protocol_events or []:
            if not isinstance(protocol_event, dict):
                continue
            if str(protocol_event.get("event_type") or "") in {
                "turn.completed",
                "turn.cancelled",
                "turn.failed",
            }:
                # Role-level errors are provisional. Only the authoritative run
                # transition below may commit the turn terminal.
                continue
            append_protocol_event(protocol_event)
        if message:
            message_meta = dict(message.get("meta") or {})
            message_meta.setdefault("runtime_turn_id", turn_id)
            role_stage = str(message_meta.get("role_stage") or "")
            default_phase = str(
                message_meta.get("phase")
                or message.get("status")
                or "completed"
            )
            message_meta.setdefault("phase", default_phase)
            if role_stage:
                message_meta.setdefault(
                    "message_key",
                    f"{turn_id}:{role_stage}:{default_phase}",
                )
            message_key = str(message_meta.get("message_key") or "")

            def matches_message(item: dict[str, Any]) -> bool:
                item_meta = item.get("meta")
                if not isinstance(item_meta, dict):
                    return False
                if item_meta.get("runtime_turn_id") != turn_id:
                    return False
                if message_key:
                    return str(item_meta.get("message_key") or "") == message_key
                return (
                    str(item_meta.get("role_stage") or "") == role_stage
                    and str(item.get("kind") or "message")
                    == str(message.get("kind") or "message")
                )

            messages = conversation.setdefault("messages", [])
            existing_index = next(
                (
                    index
                    for index, item in enumerate(messages)
                    if isinstance(item, dict) and matches_message(item)
                ),
                None,
            )
            if existing_index is None:
                existing = _append_message(
                    conversation,
                    role=str(message.get("role") or "assistant"),
                    name=str(message.get("name") or "default"),
                    content=str(message.get("content") or "").strip(),
                    status=str(message.get("status") or "completed"),
                    kind=str(message.get("kind") or "message"),
                    meta=message_meta,
                )
            else:
                existing = messages[existing_index]
                previous_content = str(existing.get("content") or "")
                # Replace the snapshot instead of mutating it in place. Event
                # consumers may still hold the pre-token object; mutating that
                # object makes a blank processing snapshot appear to have
                # contained the final reply all along.
                existing = {
                    **existing,
                    "content": str(message.get("content") or "").strip(),
                    "status": str(message.get("status") or "completed"),
                    "meta": {**existing.get("meta", {}), **message_meta},
                    "updated_at": now,
                }
                _project_native_message(existing)
                messages[existing_index] = existing
                message_status = str(existing.get("status") or "completed").lower()
                message_content = str(existing.get("content") or "")
                stream_entries = append_message_stream_entries(
                    conversation,
                    message_id=str(existing.get("id") or ""),
                    previous_content=previous_content,
                    current_content=message_content,
                    status=message_status,
                    role=str(existing.get("role") or "assistant"),
                    name=str(existing.get("name") or ""),
                    kind=str(existing.get("kind") or "message"),
                    turn_id=turn_id,
                    role_stage=role_stage or "chat",
                    occurred_at=now,
                )
                _append_attachment_session_entries(
                    conversation,
                    turn_id=turn_id,
                    role_stage=role_stage or "chat",
                    attachments=message_meta.get("attachments"),
                    direction="output",
                    occurred_at=now,
                )
                for stream_entry in stream_entries:
                    stream_payload = dict(stream_entry.get("payload") or {})
                    operation = str(stream_payload.get("operation") or "reference")
                    event_payload = {
                        "entity_id": str(existing.get("id") or ""),
                        "status": message_status,
                        "role": str(existing.get("role") or "assistant"),
                        "name": str(existing.get("name") or ""),
                        "operation": operation,
                        "content_sha256": str(
                            stream_payload.get("content_sha256") or ""
                        ),
                        "content_length": int(
                            stream_payload.get("content_length") or 0
                        ),
                    }
                    if operation == "append":
                        event_payload["delta"] = str(
                            stream_payload.get("content_delta") or ""
                        )
                        # Keep compatibility with clients that still read the
                        # legacy field; it now contains only the bounded delta.
                        event_payload["content"] = event_payload["delta"]
                        event_payload["offset"] = int(
                            stream_payload.get("offset") or 0
                        )
                    elif operation == "replace":
                        event_payload["content"] = message_content
                    else:
                        event_payload["content_ref"] = str(
                            stream_payload.get("content_ref") or ""
                        )
                    append_hosted_event(
                        conversation,
                        conversation_id=conversation_id,
                        turn_id=turn_id,
                        role_stage=role_stage or "chat",
                        event_type=(
                            "message.completed"
                            if message_status in _HOSTED_TERMINAL_STATUSES
                            else "message.delta"
                        ),
                        entity_id=str(existing.get("id") or ""),
                        idempotency_key=(
                            "message-update-event:"
                            + str(stream_entry.get("idempotency_key") or "")
                        ),
                        account_generation=expected_generation,
                        payload=event_payload,
                        occurred_at=now,
                    )
        # The final visible message and all session projections must precede the
        # turn terminal. The authoritative run state is the only terminal
        # producer, so normal, error, cancellation and recovery paths converge.
        _append_canonical_turn_terminal(
            conversation,
            conversation_id=conversation_id,
            turn_id=turn_id,
            run=run,
            occurred_at=int(run.get("completed_at") or now),
        )
        save_single_state(state)
        persisted = dict(run)
    _notify_hosted_update(conversation_id)
    return persisted


def _remote_run_location(
    state: dict[str, Any],
    remote_run_id: str,
) -> tuple[dict[str, Any], dict[str, Any], str, dict[str, Any]] | None:
    """Return conversation, hosted turn, role key and remote run by id."""

    wanted = str(remote_run_id or "").strip()
    if not wanted:
        return None
    for conversation in state.get("conversations") or []:
        if not isinstance(conversation, dict):
            continue
        for turn in (conversation.get("hosted_turns") or {}).values():
            if not isinstance(turn, dict):
                continue
            for role_key, remote_run in (turn.get("remote_runs") or {}).items():
                if isinstance(remote_run, dict) and str(remote_run.get("id") or "") == wanted:
                    return conversation, turn, str(role_key), remote_run
    return None


def _remote_run_public(remote_run: dict[str, Any]) -> dict[str, Any]:
    """Return the connector-safe subset of a remote run record."""

    return {
        key: remote_run.get(key)
        for key in (
            "id",
            "idempotency_key",
            "connector_id",
            "profile",
            "owner_id",
            "account_generation",
            "title",
            "objective",
            "local_task_id",
            "attempt",
            "max_runtime_seconds",
            "deadline_at",
            "artifact_required",
            "created_at",
            "updated_at",
            "status",
            "checkpoint_cursor",
            "remote_task_id",
            "root_task_id",
            "session_id",
            "cancel_requested",
            "cancel_reason",
            "cancel_kind",
            "cancel_intervention_id",
            "cancel_requested_at",
            "claim_token",
            "lease_until",
            "delivery_context",
            "attachment_context",
            "attachment_ids",
        )
        if key in remote_run
    }


def _connector_for_profile(profile: str) -> str:
    normalized = str(profile or "").strip().lower()
    if normalized == "pc-worker":
        return "pc-primary"
    return "dbb3-primary"


def _remote_run_connector_id(remote_run: dict[str, Any]) -> str:
    return str(
        remote_run.get("connector_id")
        or _connector_for_profile(str(remote_run.get("profile") or ""))
    ).strip()[:128]


def _assert_remote_run_account_boundary(
    conversation: dict[str, Any],
    remote_run: dict[str, Any],
) -> None:
    owner_id = str(conversation.get("owner_id") or LOCAL_OWNER_ID).strip()
    run_owner = str(remote_run.get("owner_id") or "").strip()
    run_generation = str(remote_run.get("account_generation") or "").strip()
    if run_owner != owner_id or not run_generation:
        raise CollaborationAccountDeletionInProgress()
    live_generation = _account_generation_for_owner(owner_id)
    conversation_generation = str(
        conversation.get("account_generation") or ""
    ).strip()
    if (
        run_generation != live_generation
        or (conversation_generation and run_generation != conversation_generation)
    ):
        raise CollaborationAccountDeletionInProgress()


def _remote_profile_server_cap_seconds(profile: str) -> int:
    raw = os.environ.get("HERMES_REMOTE_SERVER_CAP_SECONDS", "").strip()
    if raw:
        try:
            value = int(raw)
            if value >= 0:
                return value
        except (TypeError, ValueError):
            pass
    return 1800 if str(profile or "").strip() == "pc-worker" else 900


def _positive_int(value: Any) -> Optional[int]:
    try:
        parsed = int(value)
    except (TypeError, ValueError, OverflowError):
        return None
    return parsed if parsed > 0 else None


def _positive_int_or_none(value: Any) -> Optional[int]:
    """Non-negative int or None (0 stays 0 — a fresh session at 0% is real)."""
    if isinstance(value, bool):
        return None
    try:
        parsed = int(value)
    except (TypeError, ValueError, OverflowError):
        return None
    return parsed if parsed >= 0 else None


def _nonnegative_int(value: Any, default: int = 0) -> int:
    if isinstance(value, bool):
        return default
    try:
        parsed = int(value)
    except (TypeError, ValueError, OverflowError):
        return default
    return parsed if parsed >= 0 else default


def _coerce_flag(value: Any, default: bool = False) -> bool:
    """Normalize persisted JSON flags without treating text ``"false"`` as true."""

    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"1", "true", "yes", "on"}:
            return True
        if normalized in {"0", "false", "no", "off", ""}:
            return False
    return default


def _remote_run_deadline_fields(
    hosted: dict[str, Any],
    profile: str,
    now: int,
) -> tuple[int, int]:
    """Return effective max runtime and deadline for one remote run."""

    server_cap = _remote_profile_server_cap_seconds(profile)
    route_metadata = hosted.get("route_metadata")
    if not isinstance(route_metadata, dict):
        route_metadata = {}
    policy_candidates = [
        hosted.get("max_runtime_seconds"),
        route_metadata.get("remote_max_runtime_seconds"),
        route_metadata.get("max_runtime_seconds"),
    ]
    policy_seconds = next(
        (item for item in (_positive_int(value) for value in policy_candidates) if item),
        None,
    )
    max_runtime = min(
        value for value in (server_cap, policy_seconds) if value is not None
    )
    deadline = now + max_runtime * 1000
    hosted_deadline = _positive_int(hosted.get("deadline_at"))
    if hosted_deadline is not None:
        deadline = min(deadline, hosted_deadline)
        max_runtime = max(1, int((deadline - now + 999) // 1000))
    return max_runtime, deadline


def _request_remote_timeout_locked(
    hosted: dict[str, Any],
    remote_run: dict[str, Any],
    *,
    now: int,
) -> bool:
    """Advance one overdue remote run toward a timeout terminal state."""

    status = str(remote_run.get("status") or "queued").strip().lower()
    if status in _REMOTE_TERMINAL_STATUSES:
        return False
    deadline_at = _positive_int(remote_run.get("deadline_at"))
    cancel_requested = _coerce_flag(remote_run.get("cancel_requested"))
    if cancel_requested:
        # Any requested cancellation (timeout, user turn cancel, intervention
        # pause) gets a bounded force-terminal window: if the connector stays
        # offline past it, the run is sealed here so the hosted bookkeeping
        # converges instead of hanging in `cancelling` for the full deadline.
        force_terminal_at = _positive_int(remote_run.get("cancel_force_terminal_at"))
        if force_terminal_at is None or now < force_terminal_at:
            return False
        kind = str(remote_run.get("cancel_kind") or "")
        final_status = "timed_out" if kind == "timeout" else "cancelled"
        remote_run.update(
            {
                "status": final_status,
                "terminal": True,
                "error": remote_run.get("error") or f"Remote run {final_status}",
                "summary": remote_run.get("summary") or f"Remote run {final_status}",
                "completed_at": now,
                "updated_at": now,
            }
        )
        _seal_remote_run_claim(remote_run, now=now)
        # The hosted turn must also carry the cancellation flag so the
        # turn-level finisher converges even when the workflow thread that
        # originally observed the run is gone (crash / restart / gap).
        hosted["cancel_requested"] = True
        hosted.setdefault("cancel_kind", kind or "cancel")
        return True
    if deadline_at is None or now < deadline_at:
        return False

    old_token = str(remote_run.pop("claim_token", "") or "")
    if old_token:
        remote_run["superseded_claim_sha256"] = hashlib.sha256(
            old_token.encode("utf-8")
        ).hexdigest()
    remote_run.pop("lease_owner", None)
    remote_run["lease_until"] = 0
    remote_run.update(
        {
            "status": "cancel_requested",
            "cancel_requested": True,
            "cancel_kind": "timeout",
            "cancel_reason": "Remote run timed out",
            "cancel_requested_at": now,
            "cancel_force_terminal_at": now + _REMOTE_CANCELLATION_GRACE_SECONDS * 1000,
            "updated_at": now,
        }
    )
    hosted.update(
        {
            "stage": "awaiting_cancellation",
            "remote_cancel_pending": True,
            "cancel_requested": True,
            "cancel_kind": "timeout",
            "updated_at": now,
        }
    )
    return True


def _advance_remote_run_deadlines(
    state: dict[str, Any],
    *,
    now: Optional[int] = None,
) -> set[str]:
    """Apply remote timeout transactions and return changed conversation ids."""

    instant = int(time.time() * 1000) if now is None else int(now)
    changed_conversation_ids: set[str] = set()
    for conversation in state.get("conversations") or []:
        if not isinstance(conversation, dict):
            continue
        for hosted in (conversation.get("hosted_turns") or {}).values():
            if not isinstance(hosted, dict):
                continue
            for remote_run in (hosted.get("remote_runs") or {}).values():
                if not isinstance(remote_run, dict):
                    continue
                if _request_remote_timeout_locked(hosted, remote_run, now=instant):
                    changed_conversation_ids.add(str(conversation.get("id") or ""))
    return {item for item in changed_conversation_ids if item}


def _advance_remote_run_deadline(remote_run_id: str) -> dict[str, Any] | None:
    changed_conversation_ids: set[str] = set()
    persisted: dict[str, Any] | None = None
    now = int(time.time() * 1000)
    with _STATE_LOCK:
        state = load_single_state()
        location = _remote_run_location(state, remote_run_id)
        if location is None:
            return None
        conversation, hosted, _role_key, remote_run = location
        if _request_remote_timeout_locked(hosted, remote_run, now=now):
            save_single_state(state)
            changed_conversation_ids.add(str(conversation.get("id") or ""))
        persisted = dict(remote_run)
    for conversation_id in changed_conversation_ids:
        _notify_hosted_update(conversation_id)
    return persisted


def _connector_conflict(reason: str, message: str) -> HTTPException:
    """Build the stable connector-v2 conflict envelope."""

    return HTTPException(
        status_code=409,
        detail={"reason": str(reason), "message": str(message)},
    )


def _require_connector_account_boundary(
    conversation: dict[str, Any],
    remote_run: dict[str, Any],
) -> None:
    try:
        _assert_remote_run_account_boundary(conversation, remote_run)
    except CollaborationAccountDeletionInProgress as exc:
        raise _connector_conflict(
            "generation_deleted",
            "Remote run account generation was deleted",
        ) from exc


def _remote_run_id(
    conversation_id: str,
    turn_id: str,
    role_stage: str,
    profile: str,
) -> str:
    digest = hashlib.sha256(
        f"{conversation_id}:{turn_id}:{role_stage}:{profile}".encode("utf-8")
    ).hexdigest()[:24]
    return f"remote_{digest}"


def _ensure_remote_run(
    conversation_id: str,
    turn_id: str,
    *,
    role_stage: str,
    profile: str,
    title: str,
    objective: str,
    local_task_id: str,
    artifact_required: bool,
    delivery_context: str,
    attachment_context: str,
    attachment_ids: Optional[list[str]] = None,
    attempt: int = 1,
    connector_id: str = "",
) -> dict[str, Any]:
    """Create or reuse the durable DBB3/PC queue item for one role phase."""

    remote_id = _remote_run_id(conversation_id, turn_id, role_stage, profile)
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        hosted = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(hosted, dict):
            raise RuntimeError("托管任务记录不存在")
        owner_id = str(conversation.get("owner_id") or LOCAL_OWNER_ID).strip()
        live_generation = _account_generation_for_owner(owner_id)
        account_generation = str(
            conversation.get("account_generation")
            or hosted.get("account_generation")
            or ""
        ).strip()
        if account_generation and account_generation != live_generation:
            raise CollaborationAccountDeletionInProgress()
        account_generation = live_generation
        conversation["account_generation"] = account_generation
        hosted["account_generation"] = account_generation
        remote_runs = hosted.get("remote_runs")
        if not isinstance(remote_runs, dict):
            remote_runs = {}
            hosted["remote_runs"] = remote_runs
        existing = remote_runs.get(role_stage)
        if isinstance(existing, dict) and str(existing.get("id") or "") == remote_id:
            existing_owner = str(existing.get("owner_id") or "").strip()
            existing_generation = str(
                existing.get("account_generation") or ""
            ).strip()
            if existing_owner and existing_owner != owner_id:
                raise CollaborationAccountDeletionInProgress()
            if existing_generation and existing_generation != account_generation:
                raise CollaborationAccountDeletionInProgress()
            if not existing_owner or not existing_generation:
                existing["owner_id"] = owner_id
                existing["account_generation"] = account_generation
                save_single_state(state)
            return dict(existing)
        now = int(time.time() * 1000)
        max_runtime_seconds, deadline_at = _remote_run_deadline_fields(
            hosted, profile, now
        )
        record = {
            "id": remote_id,
            "idempotency_key": f"collaboration:{conversation_id}:{turn_id}:{role_stage}",
            "conversation_id": conversation_id,
            "turn_id": turn_id,
            "role_stage": role_stage,
            "profile": profile,
            "owner_id": owner_id,
            "account_generation": account_generation,
            "connector_id": connector_id.strip()[:128] or _connector_for_profile(profile),
            "title": title,
            "objective": objective,
            "local_task_id": local_task_id,
            "attempt": max(1, int(attempt)),
            "max_runtime_seconds": max_runtime_seconds,
            "artifact_required": bool(artifact_required),
            "delivery_context": delivery_context,
            "attachment_context": attachment_context,
            "attachment_ids": list(
                dict.fromkeys(
                    str(item).strip()
                    for item in (attachment_ids or [])
                    if str(item).strip().startswith("file_")
                )
            ),
            "status": "queued",
            "checkpoint_cursor": 0,
            "activities": [],
            "result": "",
            "summary": "",
            "error": "",
            "cancel_requested": False,
            "cancel_reason": "",
            "created_at": now,
            "updated_at": now,
        }
        record["deadline_at"] = deadline_at
        remote_runs[role_stage] = record
        save_single_state(state)
    _notify_hosted_update(conversation_id)
    _push_connector_event(
        str(record.get("connector_id") or ""),
        {"type": "run.created", "remote_run_id": remote_id},
    )
    return dict(record)


def _parse_choice_options(text: str) -> list[dict[str, str]]:
    """Parse A./B./C. choice options out of an awaiting-input reason.

    Workers format the question as::

        需要你决定：选哪个方案？
        选项：
        A. 方案一
        B. 方案二
        C. 方案三

    Returns [{"id": "A", "label": "方案一"}, ...]. Letter and 1-2 digit
    numeric numbering are both accepted (1. 方案一 → id "1"). Custom input
    is always available on the client side, so no fallback option is
    synthesized. Scanning stops at the first non-option line after the list
    so trailing prose is never parsed as an option.
    """
    options: list[dict[str, str]] = []
    if not text:
        return options
    seen_option = False
    for line in str(text).splitlines():
        line = line.strip()
        if not line:
            continue
        if re.match(r"^(选项|options?|choices?)\s*[:：]$", line, re.IGNORECASE):
            continue
        match = re.match(r"^([A-Za-z]|\d{1,2})[.、．:：]\s*(.+)$", line)
        if not match:
            if seen_option:
                break
            continue
        label = match.group(2).strip()
        if not label:
            continue
        seen_option = True
        options.append({"id": match.group(1).upper(), "label": label[:500]})
        if len(options) >= 6:
            break
    return options


def _strip_choice_options(text: str) -> str:
    """Remove the trailing 选项：A./B./C. list from an awaiting-input reason.

    The choice card renders the question separately from the tappable
    options, so the question payload should not repeat the option list.
    Only lines inside the options section (after the 选项/Options header)
    are removed — prose elsewhere in the reason is left untouched.
    """
    if not text:
        return ""
    kept: list[str] = []
    in_options = False
    for line in str(text).splitlines():
        stripped = line.strip()
        if re.match(r"^(选项|options?|choices?)\s*[:：]$", stripped, re.IGNORECASE):
            in_options = True
            continue
        if in_options:
            if re.match(r"^([A-Za-z]|\d{1,2})[.、．:：]\s*", stripped):
                continue
            in_options = False
        kept.append(line)
    return "\n".join(kept).strip()


def _remote_run_state_message(
    conversation_id: str,
    turn_id: str,
    remote_run: dict[str, Any],
    *,
    role_label: str,
) -> None:
    """Project a remote checkpoint into the same collapsible native message."""

    profile = str(remote_run.get("profile") or "default")
    role_stage = str(remote_run.get("role_stage") or f"worker:{profile}")
    status = str(remote_run.get("status") or "queued")
    semantic_progress = str(
        remote_run.get("summary") or remote_run.get("result") or ""
    ).strip()
    result = str(remote_run.get("result") or remote_run.get("summary") or "").strip()
    intervention_pause = (
        status == "cancelled"
        and str(remote_run.get("cancel_kind") or "") == "intervention"
    )
    if intervention_pause:
        content = result or "远程角色已在安全边界暂停，正在优先处理定向干预。"
    elif status == "awaiting_input":
        content = result or "等待用户决策：该成员已暂停，等待你选择方向后继续。"
    elif status in _REMOTE_TERMINAL_STATUSES:
        content = result or (
            f"远程执行已结束：{remote_run.get('error')}"
            if remote_run.get("error")
            else "远程执行已结束。"
        )
    elif status == "running":
        content = result or "已连接远程执行器，正在执行。"
    else:
        content = "已排队等待远程执行器领取。"
    activities = [
        dict(item)
        for item in remote_run.get("activities") or []
        if isinstance(item, dict)
    ]
    # Worker-delegated subagents (agent team) recorded in the completion
    # metadata: render each as a terminal subagent card alongside the run's
    # activity stream, mirroring the server-side manager's subagent events.
    for index, sub in enumerate(remote_run.get("subagents") or []):
        if not isinstance(sub, dict):
            continue
        goal = str(sub.get("goal") or "子 Agent").strip()[:2000]
        outcome = str(sub.get("outcome") or "completed").strip().lower()
        summary = str(sub.get("summary") or "").strip()[:4000]
        now_ms = int(time.time() * 1000)
        activities.append(
            {
                "id": f"remote-subagent:{profile}:{index}:{goal[:64]}",
                "kind": "subagent",
                "category": "subagent",
                "name": goal,
                "tool_name": "delegate_task",
                "status": (
                    "failed"
                    if outcome in {"failed", "error", "interrupted", "cancelled"}
                    else "completed"
                ),
                "input": "",
                "output": summary,
                "detail": summary,
                "summary": summary or goal,
                "error": "",
                "model": str(remote_run.get("actual_model") or ""),
                "provider": str(remote_run.get("actual_provider") or ""),
                "created_at": now_ms,
                "started_at": now_ms,
                "completed_at": now_ms,
                "duration_ms": 0,
            }
        )
    state = {
        "content": content,
        "status": (
            "streaming"
            if intervention_pause
            else "completed"
            if status == "completed"
            else "failed"
            if status in {"failed", "cancelled"}
            else "streaming"
        ),
        "activities": activities,
        "actual_model": str(remote_run.get("actual_model") or ""),
        "actual_provider": str(remote_run.get("actual_provider") or ""),
        "context_used_percent": remote_run.get("context_used_percent"),
        "started_at": int(remote_run.get("started_at") or remote_run.get("created_at") or int(time.time() * 1000)),
        "completed_at": int(remote_run.get("completed_at") or 0) or None,
        "updated_at": int(remote_run.get("updated_at") or int(time.time() * 1000)),
    }
    _persist_hosted_role_state(
        conversation_id,
        turn_id,
        profile=profile,
        role_stage=role_stage,
        role_label=role_label,
        state=state,
        content_fallback=content,
        semantic_milestone=(
            semantic_progress if status == "running" or intervention_pause else ""
        ),
    )


def request_hosted_turn_cancellation(
    conversation_id: str,
    turn_id: str,
    *,
    reason: str = "用户取消",
    request_id: str = "",
) -> dict[str, Any]:
    cancel_key = (str(conversation_id), str(turn_id))
    # Signal the running gateway callback before touching the multi-megabyte
    # durable store. This makes the stop control immediate even while another
    # event is being persisted.
    with _HOSTED_CANCEL_STATE_LOCK:
        _HOSTED_CANCEL_SIGNALS.add(cancel_key)
        _HOSTED_CANCEL_CACHE[cancel_key] = (time.monotonic(), True)
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            now = int(time.time() * 1000)
            pending = conversation.get("pending_turn_cancellations")
            if not isinstance(pending, dict):
                pending = {}
                conversation["pending_turn_cancellations"] = pending
            pending[turn_id] = {
                "turn_id": turn_id,
                "cancel_requested": True,
                "cancel_request_id": str(request_id or f"cancel-{turn_id}")[:256],
                "cancel_reason": str(reason or "用户取消").strip() or "用户取消",
                "cancel_requested_at": now,
                "updated_at": now,
            }
            append_hosted_event(
                conversation,
                conversation_id=conversation_id,
                turn_id=turn_id,
                role_stage="turn",
                event_type="turn.cancel_requested",
                entity_id=turn_id,
                idempotency_key=f"turn:{turn_id}:cancel-requested",
                account_generation=_account_generation_for_owner(
                    str(conversation.get("owner_id") or LOCAL_OWNER_ID)
                ),
                payload={
                    "entity_id": turn_id,
                    "reason": str(reason or "用户取消").strip() or "用户取消",
                },
                occurred_at=now,
            )
            if len(pending) > 2000:
                oldest = sorted(
                    pending,
                    key=lambda key: int((pending.get(key) or {}).get("updated_at") or 0),
                )[: len(pending) - 2000]
                for key in oldest:
                    pending.pop(key, None)
            conversation["updated_at"] = now
            save_single_state(state)
            _notify_hosted_update(conversation_id)
            return dict(pending[turn_id])
        if run.get("status") in _HOSTED_TERMINAL_STATUSES:
            with _HOSTED_CANCEL_STATE_LOCK:
                _HOSTED_CANCEL_SIGNALS.discard(cancel_key)
                _HOSTED_CANCEL_CACHE[cancel_key] = (time.monotonic(), False)
            return dict(run)
        now = int(time.time() * 1000)
        clean_reason = str(reason or "用户取消").strip() or "用户取消"
        run.update(
            {
                "cancel_requested": True,
                "cancel_request_id": str(
                    run.get("cancel_request_id")
                    or request_id
                    or f"cancel-{turn_id}"
                )[:256],
                "cancel_reason": clean_reason,
                "cancel_requested_at": now,
                "stage": "cancel_requested",
                "updated_at": now,
            }
        )
        for remote_run in (run.get("remote_runs") or {}).values():
            if not isinstance(remote_run, dict):
                continue
            if str(remote_run.get("status") or "queued") in _REMOTE_TERMINAL_STATUSES:
                continue
            remote_run.update(
                {
                    "cancel_requested": True,
                    "cancel_kind": "turn",
                    "cancel_intervention_id": "",
                    "cancel_reason": clean_reason[:1000],
                    "cancel_requested_at": now,
                    "updated_at": now,
                }
            )
        conversation["updated_at"] = now
        append_hosted_event(
            conversation,
            conversation_id=conversation_id,
            turn_id=turn_id,
            role_stage="turn",
            event_type="turn.cancel_requested",
            entity_id=turn_id,
            idempotency_key=f"turn:{turn_id}:cancel-requested",
            account_generation=_account_generation_for_owner(
                str(conversation.get("owner_id") or LOCAL_OWNER_ID)
            ),
            payload={"entity_id": turn_id, "reason": clean_reason},
            occurred_at=now,
        )
        persisted = dict(run)
        save_single_state(state)
    _notify_hosted_update(conversation_id)
    if str(persisted.get("status") or "") in _HOSTED_TERMINAL_STATUSES:
        _schedule_persisted_terminal_notification(
            conversation_id,
            turn_id,
            persisted,
            fallback_result=str(persisted.get("cancel_reason") or "用户取消"),
        )
    return persisted


def _hosted_turn_cancellation_requested(
    conversation_id: str,
    turn_id: str,
) -> bool:
    cancel_key = (str(conversation_id), str(turn_id))
    now = time.monotonic()
    with _HOSTED_CANCEL_STATE_LOCK:
        if cancel_key in _HOSTED_CANCEL_SIGNALS:
            return True
        cached = _HOSTED_CANCEL_CACHE.get(cancel_key)
        if cached is not None and now - cached[0] < _HOSTED_CANCEL_CACHE_SECONDS:
            return cached[1]
    with _HOSTED_LIVE_STATE_LOCK:
        live_conversation = _HOSTED_LIVE_CONVERSATIONS.get(
            str(conversation_id or "").strip()
        )
        live_turns = (
            live_conversation.get("hosted_turns")
            if isinstance(live_conversation, dict)
            else None
        )
        live_run = live_turns.get(turn_id) if isinstance(live_turns, dict) else None
        if isinstance(live_run, dict):
            requested = bool(
                live_run.get("cancel_requested")
                or live_run.get("status") == "cancelled"
            )
            with _HOSTED_CANCEL_STATE_LOCK:
                _HOSTED_CANCEL_CACHE[cancel_key] = (now, requested)
                if requested:
                    _HOSTED_CANCEL_SIGNALS.add(cancel_key)
            return requested
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        requested = bool(
            isinstance(run, dict)
            and (run.get("cancel_requested") or run.get("status") == "cancelled")
        )
    with _HOSTED_CANCEL_STATE_LOCK:
        _HOSTED_CANCEL_CACHE[cancel_key] = (now, requested)
        if requested:
            _HOSTED_CANCEL_SIGNALS.add(cancel_key)
    return requested


def _finish_hosted_turn_if_cancelled(
    conversation_id: str,
    turn_id: str,
) -> bool:
    # The live projection is updated by the enqueue/cancel transactions. A
    # normal chat almost always has no cancellation; avoid reopening the full
    # durable JSON just to prove that negative case. If the live projection
    # says cancellation is possible, fall through to the authoritative write.
    with _HOSTED_LIVE_STATE_LOCK:
        live_conversation = _HOSTED_LIVE_CONVERSATIONS.get(
            str(conversation_id or "").strip()
        )
        if isinstance(live_conversation, dict):
            live_turns = live_conversation.get("hosted_turns")
            live_run = (
                live_turns.get(turn_id)
                if isinstance(live_turns, dict)
                else None
            )
            if isinstance(live_run, dict) and not _coerce_flag(
                live_run.get("cancel_requested")
            ):
                return False
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict) or not _coerce_flag(run.get("cancel_requested")):
            return False
        if run.get("status") in {"completed", "cancelled"}:
            return run.get("status") == "cancelled"
        if any(
            isinstance(remote, dict)
            and str(remote.get("status") or "queued") not in _REMOTE_TERMINAL_STATUSES
            for remote in (run.get("remote_runs") or {}).values()
        ):
            return False
        reason = str(run.get("cancel_reason") or "用户取消")
        is_chat = str(run.get("mode") or "").strip().lower() == "chat"
        cancellation_text = (
            f"对话已取消：{reason}" if is_chat else f"任务已取消：{reason}"
        )
    now = int(time.time() * 1000)
    _persist_hosted_turn(
        conversation_id,
        turn_id,
        patch={
            "status": "cancelled",
            "stage": "cancelled",
            "cancelled_at": now,
            "completed_at": now,
            "notification": _completion_notification_record(
                conversation_id,
                turn_id,
                "cancelled",
                cancellation_text,
            ),
        },
        message={
            "role": "assistant",
            "name": "default",
            "content": cancellation_text,
            "status": "cancelled",
            "kind": "message",
            "meta": {
                "role_stage": "chat" if is_chat else "reporter",
                "role_label": "Hermes" if is_chat else "Hermes · 任务取消",
                "final_report": not is_chat,
            },
        },
        protocol_events=[
            {
                "role_stage": "turn",
                "event_type": "turn.cancelled",
                "entity_id": turn_id,
                "idempotency_key": f"turn:{turn_id}:cancelled",
                "occurred_at": now,
                "payload": {
                    "entity_id": turn_id,
                    "status": "cancelled",
                    "reason": reason,
                },
            }
        ],
    )
    return True


_HOSTED_CONTROL_ROOT_KEYS = frozenset(
    {"protocol", "verdict", "checks", "blockers", "findings", "required_actions"}
)
_HOSTED_REVIEW_CHECKS = (
    "requirements_met",
    "evidence_verified",
    "tests_passed",
    "risks_resolved",
)
_HOSTED_SUPERVISION_CHECKS = (
    "role_boundaries_respected",
    "task_coverage_complete",
    "evidence_sufficient",
    "process_compliant",
)


def _strict_json_object(text: str) -> Optional[dict[str, Any]]:
    """Decode exactly one JSON object and reject duplicate keys at every depth."""

    class DuplicateKeyError(ValueError):
        pass

    def unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise DuplicateKeyError(key)
            result[key] = value
        return result

    raw = str(text or "").strip()
    # The control protocol is deliberately closed: accept only one bare JSON
    # object or one complete Markdown JSON fence. Prefixes, suffixes, and
    # narrative text must never reach the reviewer/supervisor gate.
    if not raw.startswith("{"):
        fence = re.fullmatch(
            r"```(?:json)?[ \t]*\n?(.*?)\n?[ \t]*```", raw, re.DOTALL
        )
        if fence is None:
            return None
        raw = fence.group(1).strip()
    if not raw.endswith("}"):
        return None
    try:
        parsed = json.loads(raw, object_pairs_hook=unique_object)
    except (DuplicateKeyError, json.JSONDecodeError, TypeError, ValueError):
        return None
    return parsed if isinstance(parsed, dict) else None


def _strict_hosted_control_result(
    result: str,
    *,
    protocol: str,
    outcomes: tuple[str, ...],
    required_checks: tuple[str, ...],
) -> Optional[dict[str, Any]]:
    """Validate the closed verdict schema without interpreting narrative text."""

    parsed = _strict_json_object(result)
    if parsed is None or set(parsed) != _HOSTED_CONTROL_ROOT_KEYS:
        return None
    if parsed.get("protocol") != protocol or parsed.get("verdict") not in outcomes:
        return None
    checks = parsed.get("checks")
    if not isinstance(checks, dict) or set(checks) != set(required_checks):
        return None
    if any(type(checks.get(key)) is not bool for key in required_checks):
        return None
    for key in ("blockers", "findings", "required_actions"):
        values = parsed.get(key)
        if (
            not isinstance(values, list)
            or len(values) > 50
            or any(
                not isinstance(value, str)
                or not value.strip()
                or len(value) > 2000
                for value in values
            )
        ):
            return None
    verdict = str(parsed["verdict"])
    issue_count = sum(
        len(parsed[key]) for key in ("blockers", "findings", "required_actions")
    )
    if verdict == "PASS":
        if issue_count or not all(checks[key] for key in required_checks):
            return None
    elif (
        not parsed["required_actions"]
        or issue_count == 0
        or all(checks[key] for key in required_checks)
    ):
        # A negative control decision must identify a failed check and an
        # actionable structured reason. `blockers` may be empty when the model
        # puts the concrete problems in `findings` and the remediation steps in
        # `required_actions`; only the union of the three arrays must be
        # non-empty. Requiring `blockers` alone rejected valid CORRECTIVE_ACTION
        # results and made remote supervisor checkpoints fail with "格式无效".
        return None
    return parsed


def _control_result_has_json_envelope(text: str) -> bool:
    """True when the text contains any JSON-object envelope.

    The closed control protocol accepts exactly one strict JSON object.
    When a model emits malformed JSON (string booleans, duplicate keys,
    extra fields, prefixed/fenced envelopes), the narrative fallback must
    never reinterpret the literal ``"PASS"`` inside that JSON as a passing
    verdict. Any brace-delimited envelope defeats the relaxed path.
    """
    raw = str(text or "").strip()
    if not raw:
        return False
    start = raw.find("{")
    end = raw.rfind("}")
    return start != -1 and end > start


def _hosted_reviewer_control(result: str) -> Optional[dict[str, Any]]:
    strict = _strict_hosted_control_result(
        result,
        protocol="hermes.review.v1",
        outcomes=("PASS", "REWORK"),
        required_checks=_HOSTED_REVIEW_CHECKS,
    )
    if strict is not None:
        return strict
    # Format drift on long contexts: reviewer models sometimes paraphrase the
    # verdict, wrap the schema in extra keys (e.g. "checks": {"c1":"pass"}),
    # or emit narrative only. Downgrade to a structured decision when the
    # text carries an unambiguous verdict marker — same policy as the
    # supervisor's relaxed interpretation.
    if _control_result_has_json_envelope(result):
        return None
    text = str(result or "").strip()
    if re.search(r"(?:判定|结论|结果为|verdict)\s*[:：]?\s*PASS\b", text, re.I):
        return {
            "protocol": "hermes.review.v1",
            "verdict": "PASS",
            "checks": {key: True for key in _HOSTED_REVIEW_CHECKS},
            "blockers": [],
            "findings": [],
            "required_actions": [],
            "_relaxed_interpretation": True,
        }
    if re.search(
        r"(?:判定|结论|结果为|verdict)\s*[:：]?\s*REWORK\b",
        text,
        re.I,
    ):
        return {
            "protocol": "hermes.review.v1",
            "verdict": "REWORK",
            "checks": {key: False for key in _HOSTED_REVIEW_CHECKS},
            "blockers": [text[:2000]],
            "findings": [text[:2000]],
            "required_actions": ["依据审阅结论返工后重新提交。"],
            "_relaxed_interpretation": True,
        }
    # Narrative fallback. A bare PASS verdict word at a sentence boundary
    # with no rework/fail language nearby is a success marker; REWORK/FAIL
    # wording maps to a rework decision. Negation guard mirrors the
    # supervisor's: "未发现问题 / 无需返工 / 未要求整改" must not flip a PASS.
    _rework_pattern = re.compile(
        r"(?<![A-Za-z])(?:REWORK|FAILED|返工|不通过|未通过)(?![A-Za-z])",
        re.I,
    )
    _rework_neutral = re.compile(
        r"(?:返工交接|返工记录|返工历史|rework_history|rework_log|rework_items|返工列表)"
        r"|(?:未|无|不|没有|无需|未发现|没有发现|不存在|避免|排除)[^。；;\n]{0,6}?"
        r"(?<![A-Za-z])(?:REWORK|FAILED|返工|不通过|未通过)(?![A-Za-z])"
        r"|(?:[A-Za-z]+/){0,2}(?:active|running|stopped|inactive|pending|completed)/failed\b",
        re.I,
    )
    _rework_matches = [
        m for m in _rework_pattern.finditer(text)
        if not _rework_neutral.search(
            text[max(0, m.start() - 24) : min(len(text), m.end() + 24)]
        )
    ]
    if re.search(
        r"(?<![A-Za-z])(?:PASS|通过了|通过检查|检查通过|验收通过)(?![A-Za-z])",
        text,
        re.I,
    ) and not _rework_matches:
        return {
            "protocol": "hermes.review.v1",
            "verdict": "PASS",
            "checks": {key: True for key in _HOSTED_REVIEW_CHECKS},
            "blockers": [],
            "findings": [],
            "required_actions": [],
            "_relaxed_interpretation": True,
            "_relaxed_reason": "narrative verdict marker",
        }
    if _rework_matches:
        return {
            "protocol": "hermes.review.v1",
            "verdict": "REWORK",
            "checks": {key: False for key in _HOSTED_REVIEW_CHECKS},
            "blockers": [text[:2000]],
            "findings": [text[:2000]],
            "required_actions": ["依据审阅结论返工后重新提交。"],
            "_relaxed_interpretation": True,
            "_relaxed_reason": "narrative verdict marker",
        }
    return None


def _hosted_reviewer_verdict(result: str) -> str:
    control = _hosted_reviewer_control(result)
    return str(control["verdict"]).lower() if control is not None else "unknown"


def _hosted_control_display(
    result: str,
    *,
    kind: str,
    checkpoint_label: str = "",
) -> str:
    """Render user-visible Chinese text from a validated machine verdict."""

    if kind == "reviewer":
        control = _hosted_reviewer_control(result)
        if control is None:
            return "审阅控制结果格式无效，已按未通过处理。"
        if control["verdict"] == "PASS":
            return "审阅通过：全部验收、证据、测试和风险检查均已确认。"
        prefix = "审阅要求返工"
    else:
        control = _hosted_supervisor_control(result)
        label = f"“{checkpoint_label}”" if checkpoint_label else "当前检查点"
        if control is None:
            return f"监督控制结果格式无效，{label} 已按未通过处理。"
        if control["verdict"] == "PASS":
            return f"监督检查通过：{label} 的职责、覆盖、证据和流程均已确认。"
        prefix = f"监督要求整改：{label}"
    details = [
        *control["blockers"],
        *control["findings"],
        *control["required_actions"],
    ]
    return f"{prefix}：" + "；".join(details)


def _hosted_reviewer_protocol_prompt() -> str:
    return (
        "最终控制结果只允许输出一个 JSON 对象，不得使用 Markdown 代码块、引用、"
        "解释正文、前后缀或第二个对象。严格 schema："
        '{"protocol":"hermes.review.v1","verdict":"PASS|REWORK",'
        '"checks":{"requirements_met":true|false,"evidence_verified":true|false,'
        '"tests_passed":true|false,"risks_resolved":true|false},'
        '"blockers":["..."],"findings":["..."],"required_actions":["..."]}。'
        "键集、类型和枚举必须完全一致。PASS 时四项 checks 必须全为 true，且三个数组"
        "必须全空；REWORK 时至少一项 check 为 false，并在数组中给出具体问题和整改动作。"
    )


def _persist_hosted_reviewer_display(
    conversation_id: str,
    turn_id: str,
    *,
    profile: str,
    role_stage: str,
    role_label: str,
    raw_result: str,
    status: str,
    role_state: dict[str, Any],
) -> tuple[str, Optional[dict[str, Any]]]:
    """Keep the machine verdict private and expose a backend-rendered message."""

    control = _hosted_reviewer_control(raw_result)
    display_result = _hosted_control_display(raw_result, kind="reviewer")
    display_state = dict(role_state)
    display_state.update(
        {
            "content": display_result,
            "status": "failed" if status == "completed" and control is None else status,
        }
    )
    _persist_hosted_role_state(
        conversation_id,
        turn_id,
        profile=profile,
        role_stage=role_stage,
        role_label=role_label,
        state=display_state,
        content_fallback=display_result,
    )
    return display_result, control


def _review_requests_rework(result: str) -> bool:
    """Fail closed unless the reviewer emits one strict, consistent PASS."""

    return _hosted_reviewer_verdict(result) != "pass"


def _hosted_chat_attachment_context(
    conversation: dict[str, Any],
    run: dict[str, Any],
) -> str:
    """Resolve chat inputs from the account file library, not client paths."""

    attachment_ids = [
        str(item).strip()
        for item in run.get("attachment_ids") or []
        if str(item).strip().startswith("file_")
    ]
    if not attachment_ids:
        return str(run.get("attachment_context") or "").strip()
    owner_id = str(conversation.get("owner_id") or LOCAL_OWNER_ID).strip()
    account_generation = str(
        run.get("account_generation")
        or conversation.get("account_generation")
        or ""
    ).strip()
    if not account_generation:
        return "This turn's attachment boundary is unavailable."
    lines: list[str] = []
    library = _file_library()
    for file_id in attachment_ids:
        try:
            record, stored_path = library.resolve_download(
                owner_id,
                file_id,
                account_generation=account_generation,
            )
        except (KeyError, FileNotFoundError, ValueError, OSError):
            continue
        path = str(stored_path)
        name = re.sub(r"[\r\n]+", " ", str(record.get("name") or file_id)).strip()
        mime_type = re.sub(
            r"[\r\n]+",
            " ",
            str(record.get("mime_type") or "application/octet-stream"),
        ).strip()
        lines.append(
            f"- {name}: {path} (id={file_id}, type={mime_type}, size={int(record.get('size') or 0)} bytes)"
        )
    if lines:
        return "本轮账户云端持久附件：\n" + "\n".join(lines)
    return "本轮附件记录当前不可用：" + "、".join(attachment_ids)


def execute_hosted_chat(
    conversation_id: str,
    turn_id: str,
    *,
    runner: Callable[[str, str], str] = run_profile_turn,
    model_retry_delay_seconds: float = _HOSTED_CHAT_API_RETRY_DELAY_SECONDS,
    model_retry_sleeper: Callable[[float], None] = time.sleep,
    provider_max_attempts: Optional[int] = None,
    provider_retry_sleeper: Callable[[float], None] = time.sleep,
) -> None:
    """Run a durable simple turn through exactly one default Hermes."""
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            raise RuntimeError("Hosted turn record does not exist")
        if run.get("status") in _HOSTED_TERMINAL_STATUSES:
            return
        selected_profiles = [
            str(item).strip()
            for item in run.get("profiles") or []
            if str(item).strip()
        ]
        profile = selected_profiles[0] if selected_profiles else str(
            conversation.get("profile") or "default"
        )
        now = int(time.time() * 1000)
        model_retry_started_at = int(run.get("model_retry_started_at") or now)
        model_retry_deadline_at = int(
            run.get("model_retry_deadline_at")
            or model_retry_started_at + (_HOSTED_CHAT_MODEL_BUDGET_SECONDS * 1000)
        )
        run.update({
            "status": "running",
            "stage": "chat",
            "updated_at": now,
            "deadline_at": None if _HOSTED_CHAT_TIMEOUT_SECONDS == 0
                else now + (_HOSTED_CHAT_TIMEOUT_SECONDS * 1000),
            "lease_expires_at": now + _hosted_chat_lease_ms(),
            "model_retry_started_at": model_retry_started_at,
            "model_retry_deadline_at": model_retry_deadline_at,
            "model_retry_max_attempts": _HOSTED_CHAT_API_ATTEMPTS,
        })
        run.setdefault("started_at", now)
        _ensure_hosted_output_baseline(conversation_id, run)
        save_single_state(state)
        conversation_snapshot = dict(conversation)
        run = dict(run)
    if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
        return
    # The persistent official gateway is the source of truth for provider
    # readiness and already emits bounded connection.retry events. Running a
    # separate profile preflight duplicated the connection work and rewrote
    # the large collaboration state before the first request. Let the gateway
    # attempt the model directly; its retry/error events drive the same mobile
    # state machine without adding a cold-start round trip.
    content = str(run.get("content") or "").strip()
    selected_profiles = [
        str(item).strip() for item in run.get("profiles") or [] if str(item).strip()
    ]
    profile = selected_profiles[0] if selected_profiles else str(
        conversation_snapshot.get("profile") or "default"
    )
    attachment_context = _hosted_chat_attachment_context(
        conversation_snapshot,
        run,
    )
    delivery_context = str(run.get("delivery_context") or "").strip()
    content = "\n\n".join(
        item
        for item in (
            content,
            (
                f"{attachment_context}\n"
                "这些附件是本轮输入；请先读取实际文件，再根据用户要求回答。"
                if attachment_context
                else ""
            ),
            delivery_context,
        )
        if item
    )
    prompt_user_message_id = str(run.get("user_message_id") or "").strip()
    if not prompt_user_message_id:
        # Turns written before the identity field was introduced still need
        # the same official-session semantics. Resolve only the newest user
        # message with this turn's content as a compatibility fallback.
        for item in reversed(conversation_snapshot.get("messages") or []):
            if not isinstance(item, dict):
                continue
            if str(item.get("role") or "").strip().lower() != "user":
                continue
            if str(item.get("content") or "").strip() != str(
                run.get("content") or ""
            ).strip():
                continue
            prompt_user_message_id = str(item.get("id") or "").strip()
            if prompt_user_message_id:
                break
    runtime_session_id = str(
        (conversation_snapshot.get("runtime_sessions") or {}).get(profile) or ""
    ).strip()
    result, status, _role_state = _run_hosted_role(
        conversation_id,
        turn_id,
        profile=profile,
        role_stage="chat",
        role_label="Hermes",
        prompt=build_single_prompt(
            conversation_snapshot,
            profile,
            content,
            include_projected_history=not bool(runtime_session_id),
            exclude_message_id=prompt_user_message_id,
        ),
        runner=runner,
        kanban_task_id="",
        runtime_session_id=runtime_session_id,
        start_text="",
        previous_state=(run.get("role_events") or {}).get("chat"),
        provider_max_attempts=provider_max_attempts,
        retry_sleeper=provider_retry_sleeper,
    )
    if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
        return
    final_status = "completed" if status == "completed" else "failed"
    published_attachments: list[dict[str, Any]] = []
    if _coerce_flag(run.get("artifact_required")) and final_status == "completed":
        published_attachments = _hosted_turn_output_attachments(
            conversation_id,
            turn_id,
            int(run.get("started_at") or 0),
        )
        if not published_attachments:
            final_status = "failed"
            status = "failed"
            result = (
                f"{result}\n\n文件交付失败：Hermes 未在指定输出目录生成可下载文件。"
            ).strip()
    now = int(time.time() * 1000)
    first_token_at = int(_role_state.get("first_token_at") or 0)
    request_started_at = int(
        run.get("started_at")
        or _role_state.get("started_at")
        or now
    )
    persisted_run = _persist_hosted_turn(
        conversation_id,
        turn_id,
        patch={
            "chat_result": result,
            "chat_status": status,
            "status": final_status,
            "stage": final_status,
            "completed_at": now,
            "lease_expires_at": now,
            "error": str(_role_state.get("error") or "") if final_status == "failed" else "",
            "error_code": runtime_error_code(_role_state.get("error")) if final_status == "failed" else "",
            "retryable": False,
            "notification": _completion_notification_record(
                conversation_id,
                turn_id,
                final_status,
                result,
            ),
        },
        runtime_session=(
            profile,
            str(_role_state.get("runtime_session_id") or "").strip(),
        ),
        source_message_meta={
            "profile": profile,
            "runtime_session_id": str(
                _role_state.get("runtime_session_id") or ""
            ).strip(),
            "runtime_message_id": _role_state.get("runtime_user_message_id"),
        },
        message={
            "role": "assistant",
            "name": profile,
            "content": result,
            "status": final_status,
            "kind": "message",
            "meta": {
                "role_stage": "chat",
                "base_role_stage": "chat",
                "phase": final_status,
                "message_key": f"{turn_id}:chat:completed",
                "role_label": "Hermes",
                "profile": profile,
                "attachments": published_attachments,
                "started_at": request_started_at,
                "first_token_at": first_token_at or None,
                "completed_at": now,
                "duration_ms": max(0, now - request_started_at),
                "runtime_session_id": str(
                    _role_state.get("runtime_session_id") or ""
                ).strip(),
                "runtime_message_id": _role_state.get("runtime_tip_message_id"),
            },
        },
    )
    _schedule_persisted_terminal_notification(
        conversation_id,
        turn_id,
        persisted_run,
        fallback_result=result,
    )


def _persist_hosted_supervisor_check(
    conversation_id: str,
    turn_id: str,
    check_id: str,
    patch: dict[str, Any],
) -> dict[str, Any]:
    """Merge one durable supervisor checkpoint without replacing its siblings."""

    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            raise RuntimeError("托管任务记录不存在")
        checks = run.get("supervisor_checks")
        if not isinstance(checks, dict):
            checks = {}
            run["supervisor_checks"] = checks
        current = checks.get(check_id)
        record = dict(current) if isinstance(current, dict) else {"id": check_id}
        record.update(_redact_sensitive(dict(patch)))
        record["updated_at"] = int(time.time() * 1000)
        checks[check_id] = record
        run["updated_at"] = record["updated_at"]
        conversation["updated_at"] = record["updated_at"]
        save_single_state(state)
        persisted = dict(record)
    _notify_hosted_update(conversation_id)
    return persisted


def _hosted_supervisor_control(result: str) -> Optional[dict[str, Any]]:
    strict = _strict_hosted_control_result(
        result,
        protocol="hermes.supervision.v1",
        outcomes=("PASS", "CORRECTIVE_ACTION"),
        required_checks=_HOSTED_SUPERVISION_CHECKS,
    )
    if strict is not None:
        return strict
    # Remote executor workers sometimes paraphrase the verdict instead of
    # emitting the closed schema (format drift on long contexts). When the
    # narrative carries an unambiguous verdict marker, downgrade to a
    # structured decision so the control gate keeps working; the display
    # layer marks these as relaxed-interpretation results.
    if _control_result_has_json_envelope(result):
        return None
    text = str(result or "").strip()
    if re.search(r"(?:判定|结论|结果为|verdict)\s*[:：]?\s*PASS\b", text, re.I):
        return {
            "protocol": "hermes.supervision.v1",
            "verdict": "PASS",
            "checks": {key: True for key in _HOSTED_SUPERVISION_CHECKS},
            "blockers": [],
            "findings": [],
            "required_actions": [],
            "_relaxed_interpretation": True,
        }
    if re.search(
        r"(?:判定|结论|结果为|verdict)\s*[:：]?\s*CORRECTIVE_ACTION\b",
        text,
        re.I,
    ):
        return {
            "protocol": "hermes.supervision.v1",
            "verdict": "CORRECTIVE_ACTION",
            "checks": {key: False for key in _HOSTED_SUPERVISION_CHECKS},
            "blockers": [text[:2000]],
            "findings": [text[:2000]],
            "required_actions": ["依据叙述事实整改后重新提交检查点。"],
            "_relaxed_interpretation": True,
        }
    # Broader narrative fallback: workers often write "checkpoint ...: PASS."
    # or "verdict: PASS" with the JSON omitted entirely. A bare PASS verdict
    # word at a sentence boundary, with no corrective language nearby, is an
    # unambiguous success marker; CORRECTIVE_ACTION/REWORK/FAIL wording maps
    # to a corrective decision. Keep this last so strict JSON and the
    # prefixed markers above win when both are present.
    #
    # Negation guard: models commonly say "未发现问题 / 未制造返工 / 无需整改"
    # when passing — those corrective words must not flip a PASS into a
    # corrective decision. A corrective marker counts only when it is NOT
    # negated within the preceding few characters (未/无/不/没有/无需/不存).
    _corrective_pattern = re.compile(
        r"(?<![A-Za-z])(?:CORRECTIVE_ACTION|REWORK|FAILED|失败|返工|整改|不通过)(?![A-Za-z])",
        re.I,
    )
    # Neutral/structural uses of corrective wording that must NOT flip a PASS:
    #  - checkpoint names like "审阅与返工交接" / "返工记录" / "rework_history"
    #  - negated clauses "未发现问题" / "未制造返工" / "无需整改"
    #  - status enums like "active/inactive/failed" or "running/stopped/failed"
    #    (the failed token is a service/step state, not a control verdict)
    _corrective_neutral = re.compile(
        r"(?:返工交接|返工记录|返工历史|rework_history|rework_log|rework_items|返工列表)"
        r"|(?:未|无|不|没有|无需|未发现|没有发现|不存在|避免|排除)[^。；;\n]{0,6}?"
        r"(?<![A-Za-z])(?:CORRECTIVE_ACTION|REWORK|FAILED|失败|返工|整改|不通过)(?![A-Za-z])"
        r"|(?:[A-Za-z]+/){0,2}(?:active|running|stopped|inactive|pending|completed)/failed\b",
        re.I,
    )
    _corrective_matches = [
        m for m in _corrective_pattern.finditer(text)
        if not _corrective_neutral.search(
            text[max(0, m.start() - 24) : min(len(text), m.end() + 24)]
        )
    ]
    _has_plain_corrective = bool(_corrective_matches)
    if re.search(
        r"(?<![A-Za-z])(?:PASS|通过了|通过检查|检查通过)(?![A-Za-z])",
        text,
        re.I,
    ) and not _has_plain_corrective:
        return {
            "protocol": "hermes.supervision.v1",
            "verdict": "PASS",
            "checks": {key: True for key in _HOSTED_SUPERVISION_CHECKS},
            "blockers": [],
            "findings": [],
            "required_actions": [],
            "_relaxed_interpretation": True,
            "_relaxed_reason": "narrative verdict marker",
        }
    if _has_plain_corrective:
        return {
            "protocol": "hermes.supervision.v1",
            "verdict": "CORRECTIVE_ACTION",
            "checks": {key: False for key in _HOSTED_SUPERVISION_CHECKS},
            "blockers": [text[:2000]],
            "findings": [text[:2000]],
            "required_actions": ["依据叙述事实整改后重新提交检查点。"],
            "_relaxed_interpretation": True,
            "_relaxed_reason": "narrative verdict marker",
        }
    return None


def _hosted_supervisor_verdict(result: str) -> str:
    control = _hosted_supervisor_control(result)
    return str(control["verdict"]).lower() if control is not None else "unknown"


def _hosted_supervisor_protocol_prompt() -> str:
    return (
        "最终控制结果只允许输出一个 JSON 对象，不得使用 Markdown 代码块、引用、"
        "解释正文、前后缀或第二个对象。严格 schema："
        '{"protocol":"hermes.supervision.v1",'
        '"verdict":"PASS|CORRECTIVE_ACTION",'
        '"checks":{"role_boundaries_respected":true|false,'
        '"task_coverage_complete":true|false,"evidence_sufficient":true|false,'
        '"process_compliant":true|false},"blockers":["..."],'
        '"findings":["..."],"required_actions":["..."]}。'
        "键集、类型和枚举必须完全一致。PASS 时四项 checks 必须全为 true，且三个数组"
        "必须全空；CORRECTIVE_ACTION 时至少一项 check 为 false，并在数组中给出责任"
        "对象、事实、整改动作和复核证据。"
    )


def _bounded_supervisor_evidence(
    value: Any,
    *,
    depth: int = 0,
) -> tuple[Any, bool]:
    """Return field-preserving bounded evidence and whether anything was omitted."""

    if depth >= 8:
        return "[maximum depth exceeded]", True
    if isinstance(value, dict):
        bounded: dict[str, Any] = {}
        truncated = len(value) > 100
        for key in sorted(value, key=lambda item: str(item))[:100]:
            child, child_truncated = _bounded_supervisor_evidence(
                value[key],
                depth=depth + 1,
            )
            bounded[str(key)[:256]] = child
            truncated = truncated or child_truncated
        return bounded, truncated
    if isinstance(value, (list, tuple, set)):
        values = list(value)
        bounded_items: list[Any] = []
        truncated = len(values) > 100
        for item in values[:100]:
            child, child_truncated = _bounded_supervisor_evidence(
                item,
                depth=depth + 1,
            )
            bounded_items.append(child)
            truncated = truncated or child_truncated
        return bounded_items, truncated
    if isinstance(value, str) and len(value) > 4000:
        return value[:4000], True
    if value is None or isinstance(value, (str, int, float, bool)):
        return value, False
    rendered = str(value)
    return (rendered[:4000], len(rendered) > 4000)


def _require_supervisor_pass(
    checkpoint_label: str,
    check: dict[str, Any],
    *,
    conversation_id: str = "",
    turn_id: str = "",
) -> None:
    """Make supervision a control gate instead of advisory prompt text."""

    verdict = str(check.get("verdict") or "unknown")
    status = str(check.get("status") or "failed")
    if status == "completed" and verdict == "pass":
        return
    finding = str(
        check.get("display_result") or check.get("result") or ""
    ).strip()
    reason = (
        f"监督检查要求返工：{checkpoint_label}"
        if verdict == "corrective_action"
        else f"监督检查未形成可验证结论：{checkpoint_label}"
    )
    if conversation_id and turn_id:
        now = int(time.time() * 1000)
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "status": "failed",
                "stage": "failed",
                "error": reason,
                "supervisor_corrective_action": {
                    "checkpoint": checkpoint_label,
                    "verdict": verdict,
                    "finding": finding,
                    "required_action": reason,
                    "created_at": now,
                },
                "completed_at": now,
                "notification": _completion_notification_record(
                    conversation_id,
                    turn_id,
                    "failed",
                    reason,
                ),
            },
            message={
                "role": "assistant",
                "name": "supervisor",
                "content": "\n\n".join(item for item in (reason, finding) if item),
                "status": "failed",
                "kind": "message",
                "meta": {
                    "role_stage": "supervisor.corrective",
                    "base_role_stage": "supervisor",
                    "phase": "failed",
                    "message_key": f"{turn_id}:supervisor:corrective:{checkpoint_label}",
                    "role_label": _HERMES_SUPERVISOR_LABEL,
                    "profile": "supervisor",
                    "final_report": False,
                },
            },
        )
    if verdict == "corrective_action":
        raise RuntimeError(reason)
    raise RuntimeError(reason)


def _emit_rework_state_event(
    conversation_id: str,
    turn_id: str,
    *,
    phase: str,
    rework_round: int,
    checkpoint_label: str,
    feedback: str,
) -> None:
    """Emit rework state transitions for the mobile UI.

    phase="started" → "正在打回给 worker"；phase="dispatched" → "已打回给
    worker 重做"。Rendered as status chips on the rework card.
    """
    try:
        with _STATE_LOCK:
            state = load_single_state()
            conversation = _conversation_by_id(state, conversation_id)
            append_hosted_event(
                conversation,
                conversation_id=conversation_id,
                turn_id=turn_id,
                role_stage="rework",
                event_type=f"rework.{phase}",
                entity_id=f"rework:{rework_round}",
                idempotency_key=f"rework-{phase}:{turn_id}:{rework_round}",
                account_generation=_account_generation_for_owner(
                    str(conversation.get("owner_id") or LOCAL_OWNER_ID)
                ),
                payload={
                    "rework_round": int(rework_round),
                    "checkpoint": str(checkpoint_label or ""),
                    "feedback": str(feedback or "")[:4000],
                },
            )
            save_single_state(state)
            _notify_hosted_update(conversation_id)
    except Exception:
        logger.exception("rework state event failed")



def _supervisor_result_contradicts_verdict(result: str, verdict: str) -> bool:
    """Detect a cached supervisor verdict that contradicts its own text.

    A pre-upgrade (or model-error) record may contain a PASS verdict while
    the result text explicitly says the check did not pass. Trusting such a
    cache would let the supervisor gate pass without revalidation.
    """
    if verdict not in {"pass", "corrective_action"}:
        return False
    text = str(result or "").strip()
    if not text:
        return False
    fail_marker = re.compile(
        r"(?:没有通过|未通过|不通过|不能通过|无法通过|检查失败|校验失败|"
        r"测试失败|审核不通过|审阅不通过|FAILED|FAIL\b)",
        re.I,
    )
    neutral = re.compile(
        r"(?:没有发现|未发现|无|不存在|没有|未出现)"
        r"[^。；;\n]{0,8}?(?:未通过|不通过|失败|FAILED)",
        re.I,
    )
    for match in fail_marker.finditer(text):
        window = text[max(0, match.start() - 12):match.end() + 12]
        if neutral.search(window):
            continue
        return True
    return False


def _run_hosted_supervisor_check(
    conversation_id: str,
    turn_id: str,
    *,
    check_id: str,
    checkpoint_label: str,
    evidence: dict[str, Any],
    runner: Callable[..., str],
    remote: bool,
    kanban_task_id: str = "",
    visible: bool = True,
) -> tuple[str, str, dict[str, Any]]:
    """Execute, expose, and persist one independent supervisor check."""

    redacted_evidence = _redact_sensitive(dict(evidence))
    with _STATE_LOCK:
        current_state = load_single_state()
        current_conversation = _conversation_by_id(current_state, conversation_id)
        current_run = (current_conversation.get("hosted_turns") or {}).get(turn_id)
        current_run = current_run if isinstance(current_run, dict) else {}
    plan_revision = int(current_run.get("turn_plan_revision") or 0)
    source_revision = str(
        redacted_evidence.get("source_revision")
        or redacted_evidence.get("git_revision")
        or redacted_evidence.get("revision")
        or f"turn:{turn_id}:plan:{plan_revision or 0}"
    ).strip()
    prompt_version = str(
        redacted_evidence.get("prompt_version")
        or f"hermes.supervision.v1:{hashlib.sha256(_hosted_supervisor_protocol_prompt().encode('utf-8')).hexdigest()[:16]}"
    ).strip()
    if source_revision:
        redacted_evidence.setdefault("source_revision", source_revision)
    redacted_evidence.setdefault("prompt_version", prompt_version)
    evidence_json = json.dumps(
        redacted_evidence,
        ensure_ascii=False,
        default=str,
        sort_keys=True,
        separators=(",", ":"),
    )
    evidence_digest = hashlib.sha256(evidence_json.encode("utf-8")).hexdigest()
    bounded_evidence, evidence_truncated = _bounded_supervisor_evidence(
        redacted_evidence
    )
    bounded_evidence_json = json.dumps(
        bounded_evidence,
        ensure_ascii=False,
        default=str,
        sort_keys=True,
        separators=(",", ":"),
    )
    if len(bounded_evidence_json.encode("utf-8")) > 20000:
        evidence_truncated = True
        bounded_evidence = {
            "error": "bounded evidence exceeded the supervisor payload limit",
            "evidence_sha256": evidence_digest,
        }
        bounded_evidence_json = json.dumps(
            bounded_evidence,
            ensure_ascii=False,
            sort_keys=True,
        )

    cached_result_invalid = False
    expected_artifact_digest = str(redacted_evidence.get("artifact_digest") or "").strip()
    if not expected_artifact_digest:
        expected_artifact_digest = (
            digest_json(redacted_evidence.get("artifacts"))
            if redacted_evidence.get("artifacts")
            else "none"
        )
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        existing = (
            (run.get("supervisor_checks") or {}).get(check_id)
            if isinstance(run, dict)
            else None
        )
        if (
            isinstance(existing, dict)
            and str(existing.get("status") or "") == "completed"
            and str(existing.get("result") or "").strip()
            and (
                isinstance(existing.get("supervisor_verdict"), dict)
                and bool((existing.get("supervisor_verdict") or {}).get("valid"))
                and str((existing.get("supervisor_verdict") or {}).get("schema_version") or "")
                == "hermes.supervisor-verdict.v1"
                and str((existing.get("supervisor_verdict") or {}).get("artifact_digest") or "")
                == expected_artifact_digest
                and bool((existing.get("supervisor_verdict") or {}).get("evidence_refs"))
                and str((existing.get("supervisor_verdict") or {}).get("source_revision") or "").strip()
                and str((existing.get("supervisor_verdict") or {}).get("prompt_version") or "").strip()
            )
            and hmac.compare_digest(
                str(existing.get("evidence_sha256") or ""),
                evidence_digest,
            )
            and not existing.get("evidence_truncated")
        ):
            result = str(existing["result"])
            cached_verdict = _hosted_supervisor_verdict(result)
            if (
                cached_verdict in {"pass", "corrective_action"}
                and hmac.compare_digest(
                    str(existing.get("verdict") or ""),
                    cached_verdict,
                )
                and not _supervisor_result_contradicts_verdict(
                    result,
                    cached_verdict,
                )
            ):
                display_result = str(existing.get("display_result") or "").strip()
                if not display_result:
                    display_result = _hosted_control_display(
                        result,
                        kind="supervisor",
                        checkpoint_label=checkpoint_label,
                    )
                cached_state = dict(existing)
                _HOSTED_PROMPT_METRICS.observe(
                    schema_valid=True,
                    verdict=cached_verdict,
                    prompt_cache_hit=True,
                    token_cost=0,
                    context=f"{check_id}:cache",
                )
                return result, "completed", cached_state
            cached_result_invalid = True
        elif (
            isinstance(existing, dict)
            and str(existing.get("status") or "") == "completed"
            and str(existing.get("result") or "").strip()
        ):
            # A completed pre-upgrade or partially migrated record is not a
            # reusable role result. Mark it invalid so execution gets a fresh
            # role_stage instead of returning the completed role projection.
            cached_result_invalid = True

    now = int(time.time() * 1000)
    _persist_hosted_supervisor_check(
        conversation_id,
        turn_id,
        check_id,
        {
            "checkpoint": checkpoint_label,
            "status": "running",
            "evidence_sha256": evidence_digest,
            "evidence": bounded_evidence,
            "evidence_truncated": evidence_truncated,
            "started_at": now,
        },
    )
    role_stage = f"supervisor:{check_id}"
    if cached_result_invalid:
        invalid_digest = hashlib.sha256(
            str((existing or {}).get("result") or "").encode("utf-8")
        ).hexdigest()[:12]
        role_stage = f"{role_stage}:revalidate:{invalid_digest}"
    elif isinstance(existing, dict) and not hmac.compare_digest(
        str(existing.get("evidence_sha256") or ""),
        evidence_digest,
    ):
        role_stage = f"{role_stage}:evidence:{evidence_digest[:12]}"
    prompt = "\n".join(
        item
        for item in (
            supervisor_role_prompt(),
            hosted_progress_protocol(_HERMES_SUPERVISOR_LABEL),
            mention_priority_protocol(_HERMES_SUPERVISOR_LABEL),
            hosted_intervention_context(
                conversation_id,
                turn_id,
                role_stage=role_stage,
            ),
            f"当前强制检查点：{checkpoint_label}",
            "独立核对下方持久化证据。发现问题时必须点名责任角色、说明事实、整改动作和复核证据；没有问题时说明检查范围和通过依据。",
            (
                "本检查点在远程执行节点上运行：计划内出现的 task_id、child_ids 等"
                "标识属于执行节点自管的本地 kanban，监督者无需、也不得在本节点"
                "数据库验证它们的落库存在性（跨节点隔离），只审查计划结构、任务"
                "覆盖、角色边界与证据充分性。"
                if remote
                else ""
            ),
            _hosted_supervisor_protocol_prompt(),
            bounded_evidence_json,
        )
        if item
    )
    if remote:
        result, status, role_state = _run_hosted_remote_role(
            conversation_id,
            turn_id,
            profile=_DBB3_MANAGER_PROFILE,
            role_stage=role_stage,
            role_label=f"{_HERMES_SUPERVISOR_LABEL} · {checkpoint_label}",
            prompt=prompt,
            kanban_task_id=kanban_task_id,
            start_text=f"正在监督检查：{checkpoint_label}。",
            artifact_required=False,
            delivery_context="Return only the supervisor finding; do not create artifacts.",
            attachment_context="",
            connector_id="dbb3-primary",
            visible=visible,
        )
        supervisor_profile = _DBB3_MANAGER_PROFILE
    else:
        supervisor_profile = "supervisor"
        result, status, role_state = _run_hosted_role(
            conversation_id,
            turn_id,
            profile=supervisor_profile,
            role_stage=role_stage,
            role_label=f"{_HERMES_SUPERVISOR_LABEL} · {checkpoint_label}",
            prompt=prompt,
            runner=runner,
            kanban_task_id=kanban_task_id,
            start_text=f"正在监督检查：{checkpoint_label}。",
            previous_state=(
                ((run or {}).get("role_events") or {}).get(role_stage)
                if isinstance(run, dict)
                else None
            ),
            visible=visible,
        )
    completed_at = int(time.time() * 1000)
    verdict = (
        "unknown"
        if evidence_truncated or status != "completed"
        else _hosted_supervisor_verdict(result)
    )
    control = _hosted_supervisor_control(result) if not evidence_truncated else None
    runtime_verdict = build_supervisor_verdict(
        control,
        evidence=redacted_evidence,
        evidence_digest=evidence_digest,
        artifact_digest=str(redacted_evidence.get("artifact_digest") or ""),
        source_revision=source_revision,
        prompt_version=prompt_version,
        model=str(
            redacted_evidence.get("model")
            or role_state.get("actual_model")
            or ""
        ),
    )
    # The runtime witness is authoritative. A legacy parser may recognize a
    # narrative marker, but it cannot turn an invalid witness into PASS.
    if not runtime_verdict.valid:
        verdict = "unknown"
    else:
        verdict = runtime_verdict.verdict
    persisted_status = (
        "completed"
        if status == "completed" and verdict in {"pass", "corrective_action"}
        else "failed"
    )
    _HOSTED_PROMPT_METRICS.observe(
        schema_valid=runtime_verdict.valid,
        verdict=verdict,
        false_pass=(_hosted_supervisor_verdict(result) == "pass" and not runtime_verdict.valid),
        strict_reject=not runtime_verdict.valid,
        rework_requested=verdict == "corrective_action",
        rework_accepted=verdict == "corrective_action" and persisted_status == "completed",
        prompt_cache_hit=(
            bool(role_state.get("prompt_cache_hit"))
            if "prompt_cache_hit" in role_state
            else None
        ),
        token_cost=int(role_state.get("token_cost") or 0),
        artifact_checked=bool(redacted_evidence.get("artifact_required") or redacted_evidence.get("artifacts")),
        artifact_accepted=verdict == "pass" and runtime_verdict.artifact_digest not in {"", "none"},
        context=check_id,
    )
    display_result = _hosted_control_display(
        result,
        kind="supervisor",
        checkpoint_label=checkpoint_label,
    )
    display_state = dict(role_state)
    display_state.update({"content": display_result, "status": persisted_status})
    if visible:
        _persist_hosted_role_state(
            conversation_id,
            turn_id,
            profile=supervisor_profile,
            role_stage=role_stage,
            role_label=f"{_HERMES_SUPERVISOR_LABEL} · {checkpoint_label}",
            state=display_state,
            content_fallback=display_result,
        )
    else:
        # Post-report supervision is a server-side publication gate. Its
        # execution still remains in role_events/supervisor_checks for audit,
        # but it must not appear after the Reporter answer in the chat stream.
        with _STATE_LOCK:
            state = load_single_state()
            conversation = _conversation_by_id(state, conversation_id)
            messages = conversation.get("messages") or []
            retained = [
                item
                for item in messages
                if not (
                    isinstance(item, dict)
                    and isinstance(item.get("meta"), dict)
                    and str(item["meta"].get("runtime_turn_id") or "") == turn_id
                    and (
                        str(item["meta"].get("role_stage") or "") == role_stage
                        or str(item["meta"].get("role_stage") or "").startswith(
                            f"{role_stage}."
                        )
                    )
                )
            ]
            if len(retained) != len(messages):
                _rewrite_conversation_history_messages(
                    conversation_id,
                    lambda history_messages: [
                        item
                        for item in history_messages
                        if not (
                            isinstance(item.get("meta"), dict)
                            and str(item["meta"].get("runtime_turn_id") or "") == turn_id
                            and (
                                str(item["meta"].get("role_stage") or "") == role_stage
                                or str(item["meta"].get("role_stage") or "").startswith(
                                    f"{role_stage}."
                                )
                            )
                        )
                    ],
                )
                conversation["messages"] = retained
                conversation["updated_at"] = int(time.time() * 1000)
                save_single_state(state)
                _notify_hosted_update(conversation_id)
    persisted = _persist_hosted_supervisor_check(
        conversation_id,
        turn_id,
        check_id,
        {
            "checkpoint": checkpoint_label,
            "status": persisted_status,
            "result": result,
            "display_result": display_result,
            "verdict": verdict,
            "supervisor_verdict": runtime_verdict.public_dict(),
            "profile": supervisor_profile,
            "role_stage": role_stage,
            "evidence_sha256": evidence_digest,
            "evidence": bounded_evidence,
            "evidence_truncated": evidence_truncated,
            "activities": list(role_state.get("activities") or []),
            "prompt_metrics": _HOSTED_PROMPT_METRICS.snapshot(),
            "completed_at": completed_at,
        },
    )
    if visible and verdict in {"pass", "corrective_action"}:
        # Supervisor verdict card: severity drives the mobile badge/color
        # (pass = green, corrective = red with rework state changes).
        try:
            with _STATE_LOCK:
                state = load_single_state()
                conversation = _conversation_by_id(state, conversation_id)
                append_hosted_event(
                    conversation,
                    conversation_id=conversation_id,
                    turn_id=turn_id,
                    role_stage=role_stage,
                    event_type="supervisor.verdict",
                    entity_id=f"supervisor:{check_id}",
                    idempotency_key=f"supervisor-verdict:{turn_id}:{check_id}",
                    account_generation=_account_generation_for_owner(
                        str(conversation.get("owner_id") or LOCAL_OWNER_ID)
                    ),
                    payload={
                        "checkpoint": str(checkpoint_label),
                        "verdict": verdict,
                        "severity": (
                            "pass"
                            if verdict == "pass"
                            else "corrective"
                        ),
                        "display": str(display_result)[:4000],
                        # The mobile client's output fallback chain reads
                        # output/result/summary; duplicate the verdict body so
                        # the card always renders its text.
                        "summary": str(display_result)[:4000],
                        "check_id": str(check_id),
                        "schema_version": runtime_verdict.schema_version,
                        "evidence_refs": list(runtime_verdict.evidence_refs),
                        "artifact_digest": runtime_verdict.artifact_digest,
                        "source_revision": runtime_verdict.source_revision,
                        "prompt_version": runtime_verdict.prompt_version,
                        "evidence_digest": runtime_verdict.evidence_digest,
                        "witness_valid": runtime_verdict.valid,
                    },
                )
                save_single_state(state)
                _notify_hosted_update(conversation_id)
        except Exception:
            logger.exception("supervisor verdict event failed")
    return result, persisted_status, persisted


def execute_hosted_workflow(
    conversation_id: str,
    turn_id: str,
    *,
    runner: Callable[[str, str], str] = run_profile_turn,
    task_creator: Callable[..., dict[str, Any]] = create_hosted_kanban_task,
    manager_runner: Optional[Callable[[str, str], str]] = None,
    provider_max_attempts: Optional[int] = None,
    provider_retry_sleeper: Callable[[float], None] = time.sleep,
) -> None:
    captured_generation = str(
        getattr(_HOSTED_EXECUTION_GENERATION, "value", "")
    ).strip()
    live_generation = _hosted_turn_account_generation(conversation_id, turn_id)
    if captured_generation and captured_generation != live_generation:
        raise RuntimeError("stale hosted turn account generation")
    execution_generation = captured_generation or live_generation
    chat_mode = False
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            raise RuntimeError("托管任务记录不存在")
        if run.get("status") in _HOSTED_TERMINAL_STATUSES:
            return
        conversation_snapshot = dict(conversation)
        run = dict(run)
        route_metadata = (
            run.get("route_metadata")
            if isinstance(run.get("route_metadata"), dict)
            else {}
        )
        chat_mode = str(
            run.get("mode") or route_metadata.get("mode") or "work"
        ).lower() == "chat"
        if not chat_mode:
            run_record = (conversation.get("hosted_turns") or {}).get(turn_id)
            if not isinstance(run_record, dict):
                raise RuntimeError("hosted turn record does not exist")
            run_record["status"] = "running"
            if str(run_record.get("stage") or "") in {
                "",
                "accepted",
                "queued",
                "preparing",
            }:
                run_record["stage"] = "routing"
            run_record.setdefault("started_at", int(time.time() * 1000))
            run_record["updated_at"] = int(time.time() * 1000)
            _ensure_hosted_output_baseline(conversation_id, run_record)
            save_single_state(state)
            run = dict(run_record)

    if chat_mode:
        execute_hosted_chat(
            conversation_id,
            turn_id,
            runner=runner,
            provider_max_attempts=provider_max_attempts,
            provider_retry_sleeper=provider_retry_sleeper,
        )
        return

    # The public instance intentionally ships only the default Profile. Real
    # DBB3/PC work enters the connector queue; injected runners in tests keep
    # exercising the in-process contract.
    remote_workers = runner is run_profile_turn

    if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
        return

    content = str(run.get("content") or "").strip()
    title = str(run.get("title") or summarize_task_title(content))
    # Hermes slash directives persisted on the run record at enqueue time
    # (the router may rewrite route_metadata, so the record is authoritative).
    slash_directive = str(
        run.get("slash_command")
        or (route_metadata.get("slash_command") if isinstance(route_metadata, dict) else "")
        or ""
    ).strip().lower()
    slash_argument = str(
        run.get("slash_argument")
        or (route_metadata.get("slash_argument") if isinstance(route_metadata, dict) else "")
        or ""
    ).strip()
    plan_only = slash_directive == "plan"
    goal_override = slash_argument if slash_directive == "goal" else ""
    profiles = list(run.get("profiles") or ["default", "dbb3-worker", "reviewer"])
    ordered = collaboration_execution_order(profiles)
    fallback_worker_profiles = [
        item for item in ordered if collaboration_role(item) == "worker"
    ] or ["dbb3-worker"]
    reviewer_profile = "reviewer"
    reviewer_connector_id = "dbb3-primary"
    reporter_profile = "default"
    artifact_required = _coerce_flag(run.get("artifact_required"))
    attachment_context = _hosted_chat_attachment_context(conversation_snapshot, run)

    manager_plan = (
        dict(run.get("manager_plan") or {})
        if isinstance(run.get("manager_plan"), dict)
        else {}
    )
    manager_result = str(run.get("manager_result") or "")
    if (remote_workers or manager_runner is not None) and not manager_plan:
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "stage": "manager_planning",
                "participants": [
                    hosted_participant_descriptor(_DBB3_MANAGER_PROFILE)
                ],
            },
            message={
                "role": "assistant",
                "name": _DBB3_MANAGER_PROFILE,
                "content": "正在评估任务难度、拆分步骤并选择执行节点。",
                "status": "streaming",
                "kind": "message",
                "meta": {
                    "role_stage": "manager_planning",
                    "role_label": f"{_HERMES_MANAGER_LABEL} · 规划",
                    "profile": _DBB3_MANAGER_PROFILE,
                    "final_report": False,
                },
            },
        )
        manager_prompt = "\n".join(
            item
            for item in (
                _manager_plan_prompt(
                    content=content,
                    fallback_workers=fallback_worker_profiles,
                    attachment_context=attachment_context,
                    artifact_required=artifact_required,
                    goal_override=goal_override,
                    plan_only=plan_only,
                ),
                hosted_intervention_context(
                    conversation_id,
                    turn_id,
                    role_stage="dispatcher",
                ),
            )
            if item
        )
        if remote_workers:
            manager_result, manager_status, _manager_state = _run_hosted_remote_role(
                conversation_id,
                turn_id,
                profile=_DBB3_MANAGER_PROFILE,
                role_stage="manager_planning",
                role_label=f"{_HERMES_MANAGER_LABEL} · 规划",
                prompt=manager_prompt,
                kanban_task_id="",
                start_text="正在评估难度并形成结构化执行计划。",
                artifact_required=False,
                delivery_context="Return only the requested JSON plan.",
                attachment_context=attachment_context,
                connector_id="dbb3-primary",
            )
        else:
            manager_result, manager_status, _manager_state = _run_hosted_role(
                conversation_id,
                turn_id,
                profile=_DBB3_MANAGER_PROFILE,
                role_stage="manager_planning",
                role_label=f"{_HERMES_MANAGER_LABEL} · 规划",
                prompt=manager_prompt,
                runner=manager_runner or runner,
                kanban_task_id="",
                start_text="正在评估难度并形成结构化执行计划。",
            )
        if manager_status != "completed":
            raise RuntimeError(manager_result or f"{_HERMES_MANAGER_NAME} planning failed")
        manager_plan = _normalize_manager_plan(
            manager_result,
            content=content,
            fallback_workers=fallback_worker_profiles,
        )
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "manager_result": manager_result,
                "manager_plan": manager_plan,
                "profiles": ["default", *manager_plan["workers"], "reviewer"],
                "stage": "dispatching",
            },
        )

    if plan_only:
        # /plan 模式：方案本身就是交付物。整理成最终答复并结束本轮，
        # 不派发 worker，复用 reporter 阶段的完成持久化与推送路径。
        plan_report = _render_manager_plan_report(manager_plan, content, slash_argument)
        now = int(time.time() * 1000)
        _persist_hosted_plan_snapshot(
            conversation_id,
            turn_id,
            manager_plan,
            stage="completed",
            worker_statuses={},
            reviewer_status="",
            reviewer_result="",
            reporter_status="completed",
            final_status="completed",
        )
        persisted_run = _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "reporter_result": plan_report,
                "reporter_status": "completed",
                "status": "completed",
                "stage": "completed",
                "completed_at": now,
                "notification": _completion_notification_record(
                    conversation_id,
                    turn_id,
                    "completed",
                    plan_report,
                ),
            },
            message={
                "role": "assistant",
                "name": _DBB3_MANAGER_PROFILE,
                "content": plan_report,
                "status": "completed",
                "kind": "message",
                "meta": {
                    "role_stage": "reporter",
                    "role_label": "Hermes · 方案",
                    "collapse_activities": True,
                    "final_report": True,
                },
            },
        )
        _schedule_persisted_terminal_notification(
            conversation_id,
            turn_id,
            persisted_run,
            fallback_result=plan_report,
        )
        return

    if manager_plan.get("plan"):
        _persist_hosted_plan_snapshot(
            conversation_id,
            turn_id,
            manager_plan,
            stage="dispatching",
            worker_statuses=(
                run.get("worker_statuses")
                if isinstance(run.get("worker_statuses"), dict)
                else {}
            ),
            reviewer_status=str(run.get("reviewer_status") or ""),
            reviewer_result=str(run.get("reviewer_result") or ""),
            reporter_status=str(run.get("reporter_status") or ""),
            final_status=str(run.get("status") or ""),
        )

    worker_profiles = list(manager_plan.get("workers") or fallback_worker_profiles)
    if manager_plan.get("reviewer_target") == "pc":
        reviewer_connector_id = "pc-primary"
    turn_plan = build_hosted_turn_plan(
        turn_id=turn_id,
        worker_profiles=worker_profiles,
        reviewer_profile=reviewer_profile,
        reporter_profile=reporter_profile,
        artifact_required=artifact_required,
        revision=max(1, int(run.get("turn_plan_revision") or 1)),
    )
    # Manager planning has already completed before the plan is materialized;
    # the persisted ready queue must therefore expose dispatch as the next
    # executable node, not replay an obsolete initial state.
    turn_plan_snapshot = hosted_turn_plan_snapshot(
        turn_plan,
        completed=("manager_planning",),
    )
    _persist_hosted_turn(
        conversation_id,
        turn_id,
        patch={
            "turn_plan": turn_plan_snapshot,
            "turn_plan_revision": turn_plan.revision,
            "turn_plan_critical_path": turn_plan_snapshot["critical_path"],
            "turn_plan_ready_nodes": turn_plan_snapshot["initial_ready_nodes"],
        },
        protocol_events=[
            {
                "event_type": "turn.plan_created",
                "role_stage": "turn",
                "entity_id": f"{turn_id}:plan:{turn_plan.revision}",
                "idempotency_key": f"turn-plan:{turn_id}:{turn_plan.revision}",
                "payload": {
                    "plan_id": turn_plan.plan_id,
                    "revision": turn_plan.revision,
                    "critical_path": list(turn_plan.critical_path()),
                    "ready_nodes": list(turn_plan_snapshot["initial_ready_nodes"]),
                },
                "runtime": {
                    "component_id": f"fiber:plan:{turn_id}",
                    "lifecycle_state": "declared",
                    "plan_node_id": "dispatch",
                    "contract_revision": "hosted-turn-plan.v1",
                },
            }
        ],
    )
    _observe_runtime_provider(
        provider_id=_runtime_provider_id("model", str(run.get("model_provider") or "default")),
        interface_key="model:hosted",
        health="healthy" if str(run.get("model_provider") or "") else "unknown",
        metadata={"turn_id": turn_id, "generation": execution_generation},
    )
    artifact_producer_profiles = set(
        str(profile)
        for profile in (
            run.get("artifact_producer_profiles")
            or _artifact_producer_profiles(
                dict(run.get("route_metadata") or {}),
                worker_profiles,
                required=artifact_required,
            )
        )
        if str(profile)
    )
    artifact_instruction = hosted_artifact_instruction(
        run,
        remote_workers=remote_workers,
    )
    worker_kanban_instruction = (
        "官方 Kanban 是 DBB3 的唯一控制面。你可以读取根任务和已分配工作项，"
        "也可以向已分配工作项写入进度、证据和交接评论；"
        "不得创建、改派、关闭或删除根任务，也不得替 Manager 改变任务生命周期。"
    )
    reviewer_kanban_instruction = (
        "官方 Kanban 是 DBB3 的唯一控制面。你可以读取任务、证据和评论，"
        "并向已分配的审阅工作项写入验收结论；"
        "不得创建、改派、关闭或删除根任务。"
    )
    reporter_kanban_instruction = (
        "官方 Kanban 是 DBB3 的唯一控制面。你可以读取任务链用于最终汇总；"
        "不得创建、改派、关闭或删除根任务，也不要替执行者重复工作。"
    )

    task_id = str(run.get("task_id") or "")
    child_ids = [str(item) for item in run.get("child_ids") or [] if item]
    profile_task_ids = {
        str(profile): str(task)
        for profile, task in (run.get("profile_task_ids") or {}).items()
        if str(profile) and str(task)
    }
    if not task_id and not remote_workers:
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={"stage": "dispatching"},
            message={
                "role": "assistant",
                "name": "dispatcher",
                "content": "收到任务，正在结合上下文拆分并安排执行。",
                "status": "streaming",
                "kind": "message",
                "meta": {
                    "role_stage": "dispatch.opening",
                    "base_role_stage": "dispatch",
                    "phase": "opening",
                    "message_key": f"{turn_id}:dispatch:opening",
                    "role_label": "Hermes · 调度",
                    "profile": "dispatcher",
                    "handoff_to": worker_profiles,
                    "final_report": False,
                },
            },
        )
        task_info = task_creator(
            conversation_id=conversation_id,
            turn_id=turn_id,
            title=title,
            content=content,
            profiles=[*worker_profiles, reviewer_profile],
            output_dir=str(run.get("output_dir") or ""),
            manager_plan=manager_plan,
        )
        task_id = str(task_info.get("task_id") or "")
        child_ids = [str(item) for item in task_info.get("child_ids") or [] if item]
        profile_task_ids = {
            str(profile): str(task)
            for profile, task in (task_info.get("profile_task_ids") or {}).items()
            if str(profile) and str(task)
        }
        workflow_text = (
            f"DBB3 已创建根任务并拆分为 {len(child_ids)} 个执行步骤。"
            if task_info.get("fanout")
            else "DBB3 已创建根任务，正在按能力编排执行。"
        )
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "task_id": task_id,
                "child_ids": child_ids,
                "profile_task_ids": profile_task_ids,
                "stage": "dispatching",
            },
            message={
                "role": "system",
                "name": "工作流已启动",
                "content": workflow_text,
                "status": "completed",
                "kind": "workflow",
                "meta": {
                    "role_stage": "workflow",
                    "task_id": task_id,
                    "child_ids": child_ids,
                },
            },
        )
        if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
            return

    supervisor_statuses: dict[str, str] = {}
    supervisor_findings: dict[str, str] = {}
    # Remote lanes own their kanban on the executor node: the connector
    # creates the local root task and reports its id back via checkpoints.
    # Hand the supervisor the executor-local id (synced from the manager
    # checkpoint) so its kanban evidence checks hit real rows instead of
    # phantom server-side ids.
    plan_sync_task_id = task_id
    if remote_workers:
        plan_sync_task_id = str(
            (run.get("remote_runs") or {})
            .get("manager_planning", {})
            .get("remote_task_id")
            or ""
        ) or task_id
    plan_supervision, plan_supervision_status, _plan_supervision = (
        _run_hosted_supervisor_check(
            conversation_id,
            turn_id,
            check_id="plan_dispatch",
            checkpoint_label="计划形成与首次派发",
            evidence={
                "task_goal": content,
                "manager_plan": manager_plan,
                "worker_profiles": worker_profiles,
                "reviewer_profile": reviewer_profile,
                # Remote lanes own their kanban on the executor node with
                # per-account overlay homes; task ids named inside the plan
                # are not verifiable against the supervisor's local database.
                # Omit them so the plan check focuses on structure, coverage
                # and role boundaries instead of phantom-id cross checks.
                "task_id": "" if remote_workers else task_id,
                "child_ids": [] if remote_workers else child_ids,
                "profile_task_ids": (
                    {} if remote_workers else profile_task_ids
                ),
                "artifact_required": artifact_required,
                "artifact_acceptance_required": False,
            },
            runner=runner,
            remote=remote_workers,
            kanban_task_id=plan_sync_task_id,
        )
    )
    supervisor_statuses["plan_dispatch"] = plan_supervision_status
    supervisor_findings["plan_dispatch"] = str(
        _plan_supervision.get("display_result") or plan_supervision
    )
    _require_supervisor_pass(
        "计划形成与首次派发",
        _plan_supervision,
        conversation_id=conversation_id,
        turn_id=turn_id,
    )
    if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
        return

    ready_worker_nodes = next_ready_plan_nodes(
        turn_plan,
        completed=("manager_planning", "dispatch"),
    )
    ready_worker_ids = {node.node_id for node in ready_worker_nodes}
    _persist_hosted_turn(
        conversation_id,
        turn_id,
        patch={
            "turn_plan_ready_nodes": sorted(ready_worker_ids),
        },
        protocol_events=[
            {
                "event_type": "turn.node_completed",
                "role_stage": "turn",
                "entity_id": f"{turn_id}:node:manager_planning",
                "idempotency_key": f"turn-node-completed:{turn_id}:manager_planning",
                "payload": {"plan_node_id": "manager_planning", "status": "completed"},
                "runtime": {
                    "component_id": f"fiber:{turn_id}:manager_planning",
                    "lifecycle_state": "completed",
                    "plan_node_id": "manager_planning",
                    "contract_revision": "hosted-turn-plan.v1",
                },
            },
            {
                "event_type": "turn.node_completed",
                "role_stage": "turn",
                "entity_id": f"{turn_id}:node:dispatch",
                "idempotency_key": f"turn-node-completed:{turn_id}:dispatch",
                "payload": {"plan_node_id": "dispatch", "status": "completed"},
                "runtime": {
                    "component_id": f"fiber:{turn_id}:dispatch",
                    "lifecycle_state": "completed",
                    "plan_node_id": "dispatch",
                    "contract_revision": "hosted-turn-plan.v1",
                },
            },
            *(
                {
                    "event_type": "turn.node_ready",
                    "role_stage": "turn",
                    "entity_id": f"{turn_id}:node:{node.node_id}",
                    "idempotency_key": f"turn-node-ready:{turn_id}:{node.node_id}",
                    "payload": {"plan_node_id": node.node_id, "status": "ready"},
                    "runtime": {
                        "component_id": f"fiber:{node.node_id}",
                        "lifecycle_state": "active",
                        "plan_node_id": node.node_id,
                        "contract_revision": "hosted-turn-plan.v1",
                    },
                }
                for node in ready_worker_nodes
            ),
        ],
    )

    _persist_hosted_turn(
        conversation_id,
        turn_id,
        patch={
            "stage": "worker_running",
            # Dispatch is the authoritative join point: the manager and every
            # dispatched worker become first-class roster members here.
            "participants": [
                hosted_participant_descriptor(_DBB3_MANAGER_PROFILE),
                *(
                    hosted_participant_descriptor(profile, role_stage="worker")
                    for profile in worker_profiles
                ),
            ],
        },
        message={
            "role": "assistant",
            "name": reporter_profile,
            "content": (
                f"任务已由 DBB3 托管并派发给 {', '.join(worker_profiles)}。"
                f"完成后由 {reviewer_profile} 验收，再由我统一汇报。"
            ),
            "status": "completed",
            "kind": "message",
            "meta": {
                "role_stage": "dispatch",
                "role_label": "Hermes · 调度",
                "profile": "dispatcher",
                "handoff_to": worker_profiles,
                "final_report": False,
            },
        },
    )
    if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
        return

    if profile_task_ids:
        worker_task_scopes = {
            profile: profile_task_ids.get(profile, "")
            for profile in worker_profiles
        }
        reviewer_task_scope = profile_task_ids.get(reviewer_profile, "")
        reporter_task_scope = ""
    else:
        # Compatibility for pre-mapping persisted turns and injected task
        # creators in tests. New production turns always persist assignments.
        worker_task_scopes = {
            profile: (
                child_ids[index]
                if index < len(child_ids)
                else f"hosted-worker-{profile}-{turn_id}"
            )
            for index, profile in enumerate(worker_profiles)
        }
        reviewer_task_scope = (
            child_ids[len(worker_profiles)]
            if len(child_ids) > len(worker_profiles)
            else f"hosted-reviewer-{turn_id}"
        )
        reporter_task_scope = f"hosted-reporter-{turn_id}"

    worker_results = {
        str(profile): str(result)
        for profile, result in (run.get("worker_results") or {}).items()
        if str(profile) and str(result)
    }
    worker_statuses = {
        str(profile): str(status)
        for profile, status in (run.get("worker_statuses") or {}).items()
        if str(profile) and str(status)
    }

    manager_plan_blocks: list[str] = []
    if isinstance(manager_plan, dict):
        for label, value in (
            ("执行方案", manager_plan.get("approach")),
            ("任务要求", manager_plan.get("task_requirements")),
            ("测试方案", manager_plan.get("test_plan")),
        ):
            if str(value or "").strip():
                manager_plan_blocks.append(f"【{label}】\n{str(value).strip()[:12000]}")
        criteria = manager_plan.get("acceptance_criteria") or []
        if criteria:
            manager_plan_blocks.append(
                "【验收标准】\n"
                + "\n".join(
                    f"- {str(item).strip()[:2000]}"
                    for item in criteria
                    if str(item).strip()
                )
            )
        flow = manager_plan.get("flow") or []
        if flow:
            manager_plan_blocks.append(
                "【流程方案】\n"
                + "\n".join(
                    f"{index}. {str(item).strip()[:2000]}"
                    for index, item in enumerate(flow, start=1)
                    if str(item).strip()
                )
            )
        cvars = manager_plan.get("context_variables")
        if isinstance(cvars, dict) and cvars:
            try:
                cv_text = json.dumps(cvars, ensure_ascii=False, sort_keys=True)
                manager_plan_blocks.append(
                    "【共享上下文变量】\n"
                    f"```json\n{cv_text[:8000]}\n```\n"
                    "_跨步骤共享的结构化状态，视为权威；不要静默覆盖 manager 设置的键。_"
                )
            except (TypeError, ValueError):
                pass

    def _step_contract_blocks(step: dict[str, Any]) -> list[str]:
        """Render one plan step's handoff contract (refs + artifact I/O)."""
        blocks: list[str] = []
        refs = step.get("context_refs") or []
        if refs:
            blocks.append(
                "【本步骤上下文引用】\n"
                + "\n".join(f"- {str(item)[:128]}" for item in refs)
                + "\n_用 kanban_show 拉取引用任务的完整内容（正文/结果/评论）。_"
            )
        inputs = step.get("input_artifacts") or []
        outputs = step.get("output_artifacts") or []
        if inputs or outputs:
            contract_lines = []
            if inputs:
                contract_lines.append("输入（消费这些上游产物）：")
                contract_lines.extend(f"- {str(item)[:500]}" for item in inputs)
            if outputs:
                contract_lines.append("输出（本步骤必须产出）：")
                contract_lines.extend(f"- {str(item)[:500]}" for item in outputs)
            blocks.append("【产物交接契约】\n" + "\n".join(contract_lines))
        return blocks

    def execute_worker(
        profile: str,
        *,
        rework_feedback: str = "",
        rework_round: int = 0,
    ) -> tuple[str, str, str, dict[str, Any]]:
        lane_artifact_required = (
            artifact_required and profile in artifact_producer_profiles
        )
        lane_artifact_instruction = (
            artifact_instruction
            if lane_artifact_required
            else (
                "This execution lane is not the designated file producer. "
                "Return evidence and results to the reviewer, and do not fail "
                "only because this lane creates no deliverable file."
            )
        )
        role_stage = (
            f"worker:{profile}:rework:{rework_round}"
            if rework_round
            else "worker" if len(worker_profiles) == 1 else f"worker:{profile}"
        )
        worker_prompt = "\n".join(
            item
            for item in (
                "你正在 DBB3 唯一控制面的服务端托管工作流中。",
                f"你的 Profile：{profile}",
                f"官方 Kanban 根任务：{task_id}"
                if task_id and not remote_workers
                else "",
                worker_kanban_instruction,
                "你是任务执行者。只完成调度分配给当前 Profile 和目标设备的子任务。",
                "负责实际执行、工具调用、证据收集和必要产物创建。",
                "可以使用所有已配置的 Skill、MCP 和工具；正常的搜索、命令、取证和验证属于执行过程。",
                *manager_plan_blocks,
                *(
                    block
                    for step in manager_plan.get("plan") or []
                    if isinstance(step, dict)
                    and str(step.get("assignee") or "").strip().lower() == profile
                    for block in _step_contract_blocks(step)
                ),
                hosted_progress_protocol(profile),
                hosted_role_delivery_contract(profile),
                mention_priority_protocol(profile),
                hosted_intervention_context(
                    conversation_id,
                    turn_id,
                    role_stage=role_stage,
                ),
                "监督者对计划与派发的检查：",
                plan_supervision,
                "不要做最终总结；把结果、证据、耗时和遗留问题提交给审阅者。",
                f"用户任务：{content}",
                (
                    f"审阅者退回意见（第 {rework_round} 轮）：\n{rework_feedback}"
                    if rework_feedback
                    else ""
                ),
                attachment_context,
                lane_artifact_instruction,
            )
            if item
        )
        if remote_workers:
            result, status, role_state = _run_hosted_remote_role(
                conversation_id,
                turn_id,
                profile=profile,
                role_stage=role_stage,
                role_label=f"{profile} · 执行",
                prompt=worker_prompt,
                kanban_task_id=("" if remote_workers else worker_task_scopes[profile]),
                start_text="收到分配的子任务，正在执行。",
                artifact_required=lane_artifact_required,
                delivery_context=lane_artifact_instruction,
                attachment_context=attachment_context,
                rework_round=rework_round,
            )
        else:
            result, status, role_state = _run_hosted_role(
                conversation_id,
                turn_id,
                profile=profile,
                role_stage=role_stage,
                role_label=f"{profile} · 执行",
                prompt=worker_prompt,
                runner=runner,
                kanban_task_id=("" if remote_workers else worker_task_scopes[profile]),
                start_text="收到分配的子任务，正在执行。",
                previous_state=(run.get("role_events") or {}).get(role_stage),
            )
        return profile, result, status, role_state

    supervisor_rework_round = 0
    supervisor_rework_feedback = ""
    while True:
        pending_workers = [
            profile
            for profile in worker_profiles
            if f"worker:{profile}" in ready_worker_ids
            if worker_statuses.get(profile) != "completed" or not worker_results.get(profile)
        ]
        if pending_workers:
            with ThreadPoolExecutor(
                max_workers=len(pending_workers),
                thread_name_prefix=f"hosted-workers-{turn_id[-8:]}",
                initializer=_set_hosted_execution_generation,
                initargs=(execution_generation,),
            ) as executor:
                futures = {
                    executor.submit(
                        execute_worker,
                        profile,
                        rework_feedback=supervisor_rework_feedback,
                        rework_round=supervisor_rework_round,
                    ): profile
                    for profile in pending_workers
                }
                for future in as_completed(futures):
                    profile, result, status, _worker_state = future.result()
                    worker_results[profile] = result
                    worker_statuses[profile] = status
                    _persist_hosted_turn(
                        conversation_id,
                        turn_id,
                        patch={
                            "worker_results": dict(worker_results),
                            "worker_statuses": dict(worker_statuses),
                            "stage": "worker_running",
                        },
                        protocol_events=[
                            {
                                "event_type": (
                                    "turn.node_completed"
                                    if status == "completed"
                                    else "turn.node_blocked"
                                ),
                                "role_stage": "turn",
                                "entity_id": f"{turn_id}:node:worker:{profile}",
                                "idempotency_key": f"turn-node-result:{turn_id}:worker:{profile}",
                                "payload": {
                                    "plan_node_id": f"worker:{profile}",
                                    "status": status,
                                },
                                "runtime": {
                                    "component_id": f"fiber:worker:{profile}",
                                    "lifecycle_state": (
                                        "completed" if status == "completed" else "failed"
                                    ),
                                    "plan_node_id": f"worker:{profile}",
                                    "contract_revision": "hosted-turn-plan.v1",
                                },
                            }
                        ],
                    )
                    if manager_plan.get("plan"):
                        _persist_hosted_plan_snapshot(
                            conversation_id,
                            turn_id,
                            manager_plan,
                            stage="worker_running",
                            worker_statuses=worker_statuses,
                        )
        worker_result = "\n\n".join(
            f"## {profile}\n{worker_results.get(profile, '')}".strip()
            for profile in worker_profiles
        )
        worker_status = (
            "completed"
            if all(worker_statuses.get(profile) == "completed" for profile in worker_profiles)
            else "failed"
        )
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "worker_result": worker_result,
                "worker_status": worker_status,
                "worker_results": dict(worker_results),
                "worker_statuses": dict(worker_statuses),
                "stage": "reviewing",
                "participants": [
                    hosted_participant_descriptor(
                        reviewer_profile,
                        role_stage="reviewer",
                        node=(
                            "wsl"
                            if reviewer_connector_id == "pc-primary"
                            else "dbb3"
                        ),
                    ),
                ],
            },
        )
        if manager_plan.get("plan"):
            _persist_hosted_plan_snapshot(
                conversation_id,
                turn_id,
                manager_plan,
                stage="reviewing",
                worker_statuses=worker_statuses,
            )
        if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
            return

        worker_supervision, worker_supervision_status, _worker_supervision = (
            _run_hosted_supervisor_check(
                conversation_id,
                turn_id,
                check_id="worker_handoff",
                checkpoint_label="Worker 交接",
                evidence={
                    "task_goal": content,
                    "manager_plan": manager_plan,
                    "worker_results": worker_results,
                    "worker_statuses": worker_statuses,
                    "artifact_required": artifact_required,
                    "supervisor_rework_round": supervisor_rework_round,
                    "supervisor_rework_feedback": supervisor_rework_feedback,
                },
                runner=runner,
                remote=remote_workers,
                kanban_task_id=plan_sync_task_id,
            )
        )
        supervisor_statuses["worker_handoff"] = worker_supervision_status
        supervisor_findings["worker_handoff"] = str(
            _worker_supervision.get("display_result") or worker_supervision
        )
        worker_verdict = str(_worker_supervision.get("verdict") or "unknown")
        worker_check_status = str(_worker_supervision.get("status") or "failed")
        if worker_check_status == "completed" and worker_verdict == "pass":
            break
        if (
            worker_verdict == "corrective_action"
            and supervisor_rework_round < _HOSTED_REWORK_LIMIT
        ):
            supervisor_rework_round += 1
            supervisor_rework_feedback = "\n\n".join(
                item
                for item in (
                    str(_worker_supervision.get("display_result") or ""),
                    "整改要求：",
                    "\n".join(
                        str(item)
                        for item in (_worker_supervision.get("required_actions") or [])
                        if str(item).strip()
                    ),
                    "问题：",
                    "\n".join(
                        str(item)
                        for item in (_worker_supervision.get("findings") or [])
                        if str(item).strip()
                    ),
                )
                if str(item).strip()
            )
            for profile in worker_profiles:
                worker_statuses[profile] = ""
                worker_results[profile] = ""
            _persist_hosted_turn(
                conversation_id,
                turn_id,
                patch={
                    "stage": "worker_running",
                    "worker_status": "failed",
                    "worker_statuses": dict(worker_statuses),
                    "worker_results": dict(worker_results),
                    "supervisor_rework_round": supervisor_rework_round,
                    "supervisor_rework_feedback": supervisor_rework_feedback,
                },
                message={
                    "role": "assistant",
                    "name": _HERMES_SUPERVISOR_LABEL,
                    "content": (
                        f"监督者要求返工（第 {supervisor_rework_round} 轮）："
                        f"{supervisor_rework_feedback}"
                    ),
                    "status": "completed",
                    "kind": "message",
                    "meta": {
                        "role_stage": "supervisor.rework-request",
                        "base_role_stage": "supervisor",
                        "phase": "rework",
                        "message_key": f"{turn_id}:supervisor:rework:{supervisor_rework_round}",
                        "role_label": _HERMES_SUPERVISOR_LABEL,
                        "profile": "supervisor",
                        "final_report": False,
                    },
                },
            )
            if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
                return
            continue
        # Unknown/failed verdict, or corrective action after the rework limit:
        # the supervisor gate is authoritative and the turn must fail.
        _require_supervisor_pass(
            "Worker 交接",
            _worker_supervision,
            conversation_id=conversation_id,
            turn_id=turn_id,
        )
        break
    if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
        return

    reviewer_result = str(run.get("reviewer_result") or "")
    reviewer_status = str(run.get("reviewer_status") or "")
    reviewer_display_result = str(run.get("reviewer_display_result") or "")
    reviewer_control = _hosted_reviewer_control(reviewer_result)
    reviewer_revalidation = bool(reviewer_result and reviewer_control is None)
    reviewer_role_stage = "reviewer"
    if reviewer_revalidation:
        legacy_digest = hashlib.sha256(reviewer_result.encode("utf-8")).hexdigest()[:12]
        reviewer_role_stage = f"reviewer:protocol-revalidation:{legacy_digest}"
        reviewer_result = ""
        reviewer_status = ""
        reviewer_display_result = ""
        reviewer_control = None
    if reviewer_result and not reviewer_display_result:
        reviewer_display_result = _hosted_control_display(
            reviewer_result,
            kind="reviewer",
        )
    if not reviewer_result:
        reviewer_prompt = "\n".join(
            item
            for item in (
                "你正在 DBB3 唯一控制面的服务端托管工作流中。",
                f"你的 Profile：{reviewer_profile}",
                f"官方 Kanban 根任务：{task_id}"
                if task_id and not remote_workers
                else "",
                reviewer_kanban_instruction,
                "你是结果审阅者。基于执行者结果做验收、风险检查和通过或退回判断。",
                "允许使用 Skill、MCP 和工具做必要的独立抽样复核，但不要完整重做整个任务。",
                "正常的 Skill、MCP、命令和取证调用不属于过度执行；只有明显超出用户目标、增加风险或无效成本时才指出越界。",
                hosted_progress_protocol("Hermes 审阅员"),
                hosted_role_delivery_contract("Hermes 审阅员"),
                mention_priority_protocol("Hermes 审阅员"),
                hosted_intervention_context(
                    conversation_id,
                    turn_id,
                    role_stage="reviewer",
                ),
                "不要创建新的交付文件，也不要向用户做最终总结。",
                _hosted_reviewer_protocol_prompt(),
                *manager_plan_blocks,
                f"用户任务：{content}",
                "执行者提交：",
                worker_result,
                "监督者对 Worker 交接的检查：",
                worker_supervision,
            )
            if item
        )
        if remote_workers:
            reviewer_result, reviewer_status, _reviewer_state = _run_hosted_remote_role(
                conversation_id,
                turn_id,
                profile=reviewer_profile,
                role_stage=reviewer_role_stage,
                role_label=f"{reviewer_profile} · 审阅",
                prompt=reviewer_prompt,
                kanban_task_id=("" if remote_workers else reviewer_task_scope),
                start_text="我已收到执行结果，正在独立验收证据与风险。",
                artifact_required=False,
                delivery_context=artifact_instruction,
                attachment_context=attachment_context,
                connector_id=reviewer_connector_id,
            )
        else:
            reviewer_result, reviewer_status, _reviewer_state = _run_hosted_role(
                conversation_id,
                turn_id,
                profile=reviewer_profile,
                role_stage=reviewer_role_stage,
                role_label=f"{reviewer_profile} · 审阅",
                prompt=reviewer_prompt,
                runner=runner,
                kanban_task_id=("" if remote_workers else reviewer_task_scope),
                start_text="我已收到执行结果，正在独立验收证据与风险。",
                previous_state=(
                    None
                    if reviewer_revalidation
                    else (run.get("role_events") or {}).get("reviewer")
                ),
            )
        reviewer_display_result, reviewer_control = _persist_hosted_reviewer_display(
            conversation_id,
            turn_id,
            profile=reviewer_profile,
            role_stage=reviewer_role_stage,
            role_label=f"{reviewer_profile} · 审阅",
            raw_result=reviewer_result,
            status=reviewer_status,
            role_state=_reviewer_state,
        )
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "reviewer_result": reviewer_result,
                "reviewer_status": reviewer_status,
                "stage": "reviewing",
            },
        )
        if manager_plan.get("plan"):
            _persist_hosted_plan_snapshot(
                conversation_id,
                turn_id,
                manager_plan,
                stage="reviewing",
                worker_statuses=worker_statuses,
                reviewer_status=reviewer_status,
                reviewer_result=reviewer_result,
            )
        if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
            return

    rework_round = int(run.get("rework_round") or 0)
    rework_history = [
        dict(item)
        for item in run.get("rework_history") or []
        if isinstance(item, dict)
    ]
    while (
        reviewer_status == "completed"
        and _review_requests_rework(reviewer_result)
        and rework_round < _HOSTED_REWORK_LIMIT
    ):
        active_rework_round = rework_round + 1
        rework_history.append(
            {
                "round": active_rework_round,
                "reviewer_feedback": reviewer_display_result,
                "reviewer_control": reviewer_control or {},
                "worker_results_before": dict(worker_results),
                "requested_at": int(time.time() * 1000),
            }
        )
        _emit_rework_state_event(
            conversation_id,
            turn_id,
            phase="started",
            rework_round=active_rework_round,
            checkpoint_label="",
            feedback=reviewer_display_result,
        )
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "active_rework_round": active_rework_round,
                "rework_history": list(rework_history),
                "stage": "rework",
            },
            message={
                "role": "assistant",
                "name": reviewer_profile,
                "content": reviewer_display_result,
                "status": "completed",
                "kind": "message",
                "meta": {
                    "role_stage": f"reviewer:rework-request:{active_rework_round}",
                    "role_label": f"{reviewer_profile} · 退回返工",
                    "phase": "handoff",
                    "message_key": f"{turn_id}:reviewer:rework-request:{active_rework_round}",
                    "profile": reviewer_profile,
                    "handoff_to": worker_profiles,
                    "final_report": False,
                },
            },
        )
        if manager_plan.get("plan"):
            _persist_hosted_plan_snapshot(
                conversation_id,
                turn_id,
                manager_plan,
                stage="rework",
                worker_statuses={
                    **worker_statuses,
                    **{profile: "running" for profile in worker_profiles},
                },
                reviewer_status="",
                reviewer_result="",
            )
        if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
            return

        rework_check_id = f"rework_{active_rework_round}"
        rework_supervision, rework_supervision_status, _rework_supervision = (
            _run_hosted_supervisor_check(
                conversation_id,
                turn_id,
                check_id=rework_check_id,
                checkpoint_label=f"第 {active_rework_round} 轮返工",
                evidence={
                    "task_goal": content,
                    "reviewer_feedback": reviewer_result,
                    "worker_results_before": worker_results,
                    "rework_round": active_rework_round,
                },
                runner=runner,
                remote=remote_workers,
                kanban_task_id=plan_sync_task_id,
            )
        )
        supervisor_statuses[rework_check_id] = rework_supervision_status
        supervisor_findings[rework_check_id] = str(
            _rework_supervision.get("display_result") or rework_supervision
        )
        _require_supervisor_pass(
            f"第 {active_rework_round} 轮返工",
            _rework_supervision,
            conversation_id=conversation_id,
            turn_id=turn_id,
        )
        if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
            return
        supervised_rework_feedback = "\n\n".join(
            (
                reviewer_result,
                f"监督者返工检查：\n{rework_supervision}",
            )
        )

        round_results: dict[str, str] = {}
        round_statuses: dict[str, str] = {}
        with ThreadPoolExecutor(
            max_workers=len(worker_profiles),
            thread_name_prefix=f"hosted-rework-{turn_id[-8:]}-{active_rework_round}",
            initializer=_set_hosted_execution_generation,
            initargs=(execution_generation,),
        ) as executor:
            futures = {
                executor.submit(
                    execute_worker,
                    profile,
                    rework_feedback=supervised_rework_feedback,
                    rework_round=active_rework_round,
                ): profile
                for profile in worker_profiles
            }
            for future in as_completed(futures):
                profile, result, status, _worker_state = future.result()
                round_results[profile] = result
                round_statuses[profile] = status
        worker_results.update(round_results)
        worker_statuses.update(round_statuses)
        worker_result = "\n\n".join(
            f"## {profile}\n{worker_results.get(profile, '')}".strip()
            for profile in worker_profiles
        )
        worker_status = (
            "completed"
            if all(
                worker_statuses.get(profile) == "completed"
                for profile in worker_profiles
            )
            else "failed"
        )
        _emit_rework_state_event(
            conversation_id,
            turn_id,
            phase="dispatched",
            rework_round=active_rework_round,
            checkpoint_label="",
            feedback="",
        )
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "worker_result": worker_result,
                "worker_status": worker_status,
                "worker_results": dict(worker_results),
                "worker_statuses": dict(worker_statuses),
                "stage": "reviewing",
            },
        )
        if manager_plan.get("plan"):
            _persist_hosted_plan_snapshot(
                conversation_id,
                turn_id,
                manager_plan,
                stage="reviewing",
                worker_statuses=worker_statuses,
            )
        reviewer_prompt = "\n".join(
            item
            for item in (
                "你正在 DBB3 唯一控制面的服务端托管工作流中。",
                f"你的 Profile：{reviewer_profile}",
                f"官方 Kanban 根任务：{task_id}"
                if task_id and not remote_workers
                else "",
                reviewer_kanban_instruction,
                f"这是第 {active_rework_round} 轮返工后的重新验收。",
                "逐项核对上轮退回意见和新的执行证据。",
                hosted_progress_protocol("Hermes 审阅员"),
                hosted_role_delivery_contract("Hermes 审阅员"),
                mention_priority_protocol("Hermes 审阅员"),
                hosted_intervention_context(
                    conversation_id,
                    turn_id,
                    role_stage="reviewer",
                ),
                "不要创建新的交付文件，也不要向用户做最终总结。",
                _hosted_reviewer_protocol_prompt(),
                f"用户任务：{content}",
                "上轮退回意见：",
                reviewer_result,
                "返工后的执行者提交：",
                worker_result,
            )
            if item
        )
        if remote_workers:
            reviewer_result, reviewer_status, _reviewer_state = _run_hosted_remote_role(
                conversation_id,
                turn_id,
                profile=reviewer_profile,
                role_stage=f"reviewer:rework:{active_rework_round}",
                role_label=f"{reviewer_profile} · 返工复审",
                prompt=reviewer_prompt,
                kanban_task_id=("" if remote_workers else reviewer_task_scope),
                start_text=f"第 {active_rework_round} 轮返工已提交，正在重新验收。",
                artifact_required=False,
                delivery_context=artifact_instruction,
                attachment_context=attachment_context,
                rework_round=active_rework_round,
                connector_id=reviewer_connector_id,
            )
        else:
            reviewer_result, reviewer_status, _reviewer_state = _run_hosted_role(
                conversation_id,
                turn_id,
                profile=reviewer_profile,
                role_stage=f"reviewer:rework:{active_rework_round}",
                role_label=f"{reviewer_profile} · 返工复审",
                prompt=reviewer_prompt,
                runner=runner,
                kanban_task_id=("" if remote_workers else reviewer_task_scope),
                start_text=f"第 {active_rework_round} 轮返工已提交，正在重新验收。",
            )
        reviewer_display_result, reviewer_control = _persist_hosted_reviewer_display(
            conversation_id,
            turn_id,
            profile=reviewer_profile,
            role_stage=f"reviewer:rework:{active_rework_round}",
            role_label=f"{reviewer_profile} · 返工复审",
            raw_result=reviewer_result,
            status=reviewer_status,
            role_state=_reviewer_state,
        )
        rework_round = active_rework_round
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "reviewer_result": reviewer_result,
                "reviewer_control": reviewer_control or {},
                "reviewer_display_result": reviewer_display_result,
                "reviewer_status": reviewer_status,
                "active_rework_round": 0,
                "rework_round": rework_round,
                "stage": "reviewing",
            },
        )
        if manager_plan.get("plan"):
            _persist_hosted_plan_snapshot(
                conversation_id,
                turn_id,
                manager_plan,
                stage="reviewing",
                worker_statuses=worker_statuses,
                reviewer_status=reviewer_status,
                reviewer_result=reviewer_result,
            )
        if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
            return

    if reviewer_status == "completed" and _review_requests_rework(reviewer_result):
        reviewer_status = "failed"
        reviewer_display_result = (
            f"{reviewer_display_result}\n"
            f"已达到 {_HOSTED_REWORK_LIMIT} 轮自动返工上限，任务保留为未通过。"
        )
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "reviewer_result": reviewer_result,
                "reviewer_control": reviewer_control or {},
                "reviewer_display_result": reviewer_display_result,
                "reviewer_status": reviewer_status,
            },
        )
        if manager_plan.get("plan"):
            _persist_hosted_plan_snapshot(
                conversation_id,
                turn_id,
                manager_plan,
                stage="reporting",
                worker_statuses=worker_statuses,
                reviewer_status=reviewer_status,
                reviewer_result=reviewer_result,
            )

    review_supervision, review_supervision_status, _review_supervision = (
        _run_hosted_supervisor_check(
            conversation_id,
            turn_id,
            check_id="review_handoff",
            checkpoint_label="审阅与返工交接",
            evidence={
                "task_goal": content,
                "worker_results": worker_results,
                "worker_statuses": worker_statuses,
                "reviewer_result": reviewer_result,
                "reviewer_control": reviewer_control or {},
                "reviewer_display_result": reviewer_display_result,
                "reviewer_status": reviewer_status,
                "rework_history": rework_history,
            },
            runner=runner,
            remote=remote_workers,
            kanban_task_id=plan_sync_task_id,
        )
    )
    supervisor_statuses["review_handoff"] = review_supervision_status
    supervisor_findings["review_handoff"] = str(
        _review_supervision.get("display_result") or review_supervision
    )
    _require_supervisor_pass(
        "审阅与返工交接",
        _review_supervision,
        conversation_id=conversation_id,
        turn_id=turn_id,
    )
    if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
        return

    handoff_artifacts = (
        _hosted_turn_output_attachments(
            conversation_id,
            turn_id,
            int(run.get("started_at") or 0),
        )
        if artifact_required
        else []
    )
    handoff_failures = [
        f"{profile}: {worker_results.get(profile, '')}".strip()
        for profile in worker_profiles
        if worker_statuses.get(profile) != "completed"
    ]
    if reviewer_status != "completed":
        handoff_failures.append(f"reviewer: {reviewer_result}".strip())
    source_handoff = {
        "task_goal": content,
        "plan": list(manager_plan.get("plan") or []),
        "worker_results": dict(worker_results),
        "review_verdict": reviewer_result,
        "supervisor_review": review_supervision,
        "rework_history": list(rework_history),
        "artifacts": handoff_artifacts,
        "failures": handoff_failures,
    }
    manager_handoff = (
        dict(run.get("manager_handoff") or {})
        if isinstance(run.get("manager_handoff"), dict)
        else {}
    )
    if (remote_workers or manager_runner is not None) and not manager_handoff:
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={"stage": "manager_handoff"},
        )
        manager_handoff_prompt = "\n".join(
            (
                "你是 Hermes Manager。根据下方已经完成的执行与审阅记录生成结构化交接，不能重新执行任务，不能补写不存在的证据。",
                hosted_progress_protocol(_HERMES_MANAGER_LABEL),
                hosted_role_delivery_contract(_HERMES_MANAGER_LABEL),
                mention_priority_protocol(_HERMES_MANAGER_LABEL),
                hosted_intervention_context(
                    conversation_id,
                    turn_id,
                    role_stage="dispatcher",
                ),
                "服务端会固定 task_goal、plan、worker_results、review_verdict、rework_history、artifacts 和 failures；你无权覆盖这些字段。",
                '只输出一个 JSON 对象：{"suggested_conclusion":"..."}，不得附加正文或伪造权威字段。',
                json.dumps(source_handoff, ensure_ascii=False, default=str),
            )
        )
        if remote_workers:
            manager_handoff_result, manager_handoff_status, _handoff_state = _run_hosted_remote_role(
                conversation_id,
                turn_id,
                profile=_DBB3_MANAGER_PROFILE,
                role_stage="manager_handoff",
                role_label=f"{_HERMES_MANAGER_LABEL} · 交接",
                prompt=manager_handoff_prompt,
                kanban_task_id=plan_sync_task_id,
                start_text="正在整理执行、审阅、返工和产物证据。",
                artifact_required=False,
                delivery_context="Return only the requested JSON handoff.",
                attachment_context="",
                connector_id="dbb3-primary",
            )
        else:
            manager_handoff_result, manager_handoff_status, _handoff_state = _run_hosted_role(
                conversation_id,
                turn_id,
                profile=_DBB3_MANAGER_PROFILE,
                role_stage="manager_handoff",
                role_label=f"{_HERMES_MANAGER_LABEL} · 交接",
                prompt=manager_handoff_prompt,
                runner=manager_runner or runner,
                kanban_task_id=plan_sync_task_id,
                start_text="正在整理执行、审阅、返工和产物证据。",
            )
        if manager_handoff_status != "completed":
            raise RuntimeError(manager_handoff_result or f"{_HERMES_MANAGER_NAME} handoff failed")
        manager_handoff = _normalize_manager_handoff(
            manager_handoff_result,
            task_goal=content,
            plan=manager_plan,
            worker_results=worker_results,
            review_verdict=reviewer_result,
            rework_history=rework_history,
            artifacts=handoff_artifacts,
            failures=handoff_failures,
        )
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "manager_handoff": manager_handoff,
                "manager_handoff_result": manager_handoff_result,
                "stage": "reporting",
            },
        )
        if manager_plan.get("plan"):
            _persist_hosted_plan_snapshot(
                conversation_id,
                turn_id,
                manager_plan,
                stage="reporting",
                worker_statuses=worker_statuses,
                reviewer_status=reviewer_status,
                reviewer_result=reviewer_result,
            )
    elif not manager_handoff:
        manager_handoff = _normalize_manager_handoff(
            {},
            task_goal=content,
            plan=manager_plan,
            worker_results=worker_results,
            review_verdict=reviewer_result,
            rework_history=rework_history,
            artifacts=handoff_artifacts,
            failures=handoff_failures,
        )

    # Rebind cached or model-proposed handoffs to the current authoritative
    # server state. This also protects resumed pre-upgrade runs.
    manager_handoff = _normalize_manager_handoff(
        manager_handoff,
        task_goal=content,
        plan=manager_plan,
        worker_results=worker_results,
        review_verdict=reviewer_result,
        rework_history=rework_history,
        artifacts=handoff_artifacts,
        failures=handoff_failures,
    )
    _persist_hosted_turn(
        conversation_id,
        turn_id,
        patch={"manager_handoff": manager_handoff},
    )

    final_supervision, final_supervision_status, _final_supervision = (
        _run_hosted_supervisor_check(
            conversation_id,
            turn_id,
            check_id="final_report",
            checkpoint_label="最终汇报前",
            evidence={
                "manager_handoff": manager_handoff,
                "worker_status": worker_status,
                "reviewer_status": reviewer_status,
                "supervisor_statuses": supervisor_statuses,
                "supervisor_findings": supervisor_findings,
                "artifact_required": artifact_required,
                "artifacts": handoff_artifacts,
                # A final report must bind to artifacts only when this turn's
                # route actually requires a deliverable. Ordinary hosted
                # turns remain evidence-bound without inventing a file digest.
                "artifact_acceptance_required": bool(artifact_required),
            },
            runner=runner,
            remote=remote_workers,
            kanban_task_id=plan_sync_task_id,
        )
    )
    supervisor_statuses["final_report"] = final_supervision_status
    supervisor_findings["final_report"] = str(
        _final_supervision.get("display_result") or final_supervision
    )
    _require_supervisor_pass(
        "最终汇报前",
        _final_supervision,
        conversation_id=conversation_id,
        turn_id=turn_id,
    )
    if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
        return

    reporter_result = str(run.get("reporter_result") or "")
    reporter_status = str(run.get("reporter_status") or "")
    if not reporter_result:
        reporter_prompt = "\n".join(
            item
            for item in (
                "你是这个服务端托管任务唯一的最终汇报者。",
                f"你的 Profile：{reporter_profile}",
                f"官方 Kanban 根任务：{task_id}"
                if task_id and not remote_workers
                else "",
                reporter_kanban_instruction,
                "你只能根据 Hermes Manager 已验证的结构化交接生成一次用户答案。",
                "不得重新执行任务，不得调用工具补做工作，不得编造交接中缺失的结果或证据。",
                hosted_progress_protocol("Hermes 汇报员"),
                hosted_role_delivery_contract("Hermes 汇报员"),
                mention_priority_protocol("Hermes 汇报员"),
                hosted_intervention_context(
                    conversation_id,
                    turn_id,
                    role_stage="reporter",
                ),
                "清楚区分已完成、失败、未完成和需要用户决定的事项。",
                "Hermes Manager 结构化交接（截断到 8000 字符，完整证据在 role_events 中可审计）：",
                json.dumps(manager_handoff, ensure_ascii=False, default=str)[:8000],
                "监督者在最终汇报前的检查（截断到 4000 字符）：",
                str(final_supervision)[:4000],
                artifact_instruction,
            )
            if item
        )
        _persist_hosted_turn(
            conversation_id,
            turn_id,
            patch={
                "stage": "reporting",
                "participants": [
                    hosted_participant_descriptor(
                        reporter_profile,
                        role_stage="reporter",
                    ),
                ],
            },
        )
        reporter_result, reporter_status, _reporter_state = _run_hosted_role(
            conversation_id,
            turn_id,
            profile=reporter_profile,
            role_stage="reporter",
            role_label="Hermes · 最终汇报",
            prompt=reporter_prompt,
            runner=runner,
            kanban_task_id=("" if remote_workers else reporter_task_scope),
            start_text="执行与审阅信息已齐，正在整理唯一的最终汇报。",
            final_report=True,
            previous_state=(run.get("role_events") or {}).get("reporter"),
            visible=False,
        )

        # Reporter output is a candidate until the independent post-report
        # gate accepts it. Keep its role_event for audit, but do not expose a
        # draft message that may subsequently be rejected.
        with _STATE_LOCK:
            draft_state = load_single_state()
            draft_conversation = _conversation_by_id(draft_state, conversation_id)
            draft_messages = draft_conversation.get("messages") or []
            retained_messages = [
                item
                for item in draft_messages
                if not (
                    isinstance(item, dict)
                    and isinstance(item.get("meta"), dict)
                    and str(item["meta"].get("runtime_turn_id") or "") == turn_id
                    and (
                        str(item["meta"].get("role_stage") or "") == "reporter"
                        or str(item["meta"].get("role_stage") or "").startswith(
                            "reporter."
                        )
                    )
                )
            ]
            if len(retained_messages) != len(draft_messages):
                _rewrite_conversation_history_messages(
                    conversation_id,
                    lambda history_messages: [
                        item
                        for item in history_messages
                        if not (
                            isinstance(item.get("meta"), dict)
                            and str(item["meta"].get("runtime_turn_id") or "") == turn_id
                            and (
                                str(item["meta"].get("role_stage") or "") == "reporter"
                                or str(item["meta"].get("role_stage") or "").startswith(
                                    "reporter."
                                )
                            )
                        )
                    ],
                )
                draft_conversation["messages"] = retained_messages
                draft_conversation["updated_at"] = int(time.time() * 1000)
                save_single_state(draft_state)

    if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
        return

    # The attachment snapshot was captured once before the authoritative
    # manager handoff. Reporter is presentation-only and cannot publish files,
    # so reusing that immutable snapshot avoids a second TOCTOU lookup.
    attachments = list(handoff_artifacts)
    def artifact_identity(item: dict[str, Any]) -> tuple[str, str, int]:
        return (
            str(item.get("id") or ""),
            str(item.get("sha256") or ""),
            int(item.get("size") or 0),
        )
    artifacts_match = {
        artifact_identity(item)
        for item in handoff_artifacts
        if isinstance(item, dict)
    } == {
        artifact_identity(item)
        for item in attachments
        if isinstance(item, dict)
    }
    post_report_supervision, post_report_status, _post_report_supervision = (
        _run_hosted_supervisor_check(
            conversation_id,
            turn_id,
            check_id="post_report",
            checkpoint_label="最终汇报成稿",
            evidence={
                "authoritative_handoff": manager_handoff,
                "reporter_result": reporter_result,
                "reporter_status": reporter_status,
                "expected_artifacts": handoff_artifacts,
                "verified_attachments": attachments,
                "attachments_match_handoff": artifacts_match,
                "artifact_required": artifact_required,
            },
            runner=runner,
            remote=remote_workers,
            kanban_task_id=plan_sync_task_id,
            visible=False,
        )
    )
    supervisor_statuses["post_report"] = post_report_status
    supervisor_findings["post_report"] = str(
        _post_report_supervision.get("display_result") or post_report_supervision
    )
    _require_supervisor_pass(
        "最终汇报成稿",
        _post_report_supervision,
        conversation_id=conversation_id,
        turn_id=turn_id,
    )
    if _finish_hosted_turn_if_cancelled(conversation_id, turn_id):
        return

    missing_required_artifact = artifact_required and not attachments
    reporter_state_snapshot = (
        _reporter_state
        if "_reporter_state" in locals()
        else (run.get("role_events") or {}).get("reporter") or {}
    )
    final_status = (
        "completed"
        if (
            worker_status == reviewer_status == reporter_status == "completed"
            and all(status == "completed" for status in supervisor_statuses.values())
            and _hosted_supervisor_verdict(final_supervision) == "pass"
            and _hosted_supervisor_verdict(post_report_supervision) == "pass"
            and artifacts_match
            and not missing_required_artifact
        )
        else "failed"
    )
    if missing_required_artifact:
        reporter_result = "\n\n".join(
            item
            for item in (
                reporter_result,
                "The task required a deliverable file, but no verified file reached the account library.",
            )
            if item
        )
    with _STATE_LOCK:
        current_state = load_single_state()
        current_conversation = _conversation_by_id(current_state, conversation_id)
        current_run = (current_conversation.get("hosted_turns") or {}).get(turn_id)
        current_checks = (
            current_run.get("supervisor_checks")
            if isinstance(current_run, dict)
            and isinstance(current_run.get("supervisor_checks"), dict)
            else {}
        )
        supervisor_verdicts = {
            str(check_id): str(check.get("verdict") or "unknown")
            for check_id, check in current_checks.items()
            if isinstance(check, dict)
        }
    now = int(time.time() * 1000)
    if manager_plan.get("plan"):
        _persist_hosted_plan_snapshot(
            conversation_id,
            turn_id,
            manager_plan,
            stage="completed" if final_status == "completed" else "failed",
            worker_statuses=worker_statuses,
            reviewer_status=reviewer_status,
            reviewer_result=reviewer_result,
            reporter_status=reporter_status,
            final_status=final_status,
        )
    persisted_run = _persist_hosted_turn(
        conversation_id,
        turn_id,
        patch={
            "reporter_result": reporter_result,
            "reporter_status": reporter_status,
            "supervisor_statuses": dict(supervisor_statuses),
            "supervisor_verdicts": supervisor_verdicts,
            "status": final_status,
            "stage": "completed" if final_status == "completed" else "failed",
            "completed_at": now,
            "notification": _completion_notification_record(
                conversation_id,
                turn_id,
                final_status,
                reporter_result,
            ),
        },
        message={
            "role": "assistant",
            "name": reporter_profile,
            "content": reporter_result,
            "status": final_status,
            "kind": "message",
            "meta": {
                "role_stage": "reporter",
                "role_label": "Hermes · 最终汇报",
                "collapse_activities": True,
                "final_report": True,
                "attachments": attachments,
                "task_id": task_id,
                "activities": list(reporter_state_snapshot.get("activities") or []),
                "actual_model": str(reporter_state_snapshot.get("actual_model") or ""),
                "actual_provider": str(
                    reporter_state_snapshot.get("actual_provider") or ""
                ),
            },
        },
    )
    _schedule_persisted_terminal_notification(
        conversation_id,
        turn_id,
        persisted_run,
        fallback_result=reporter_result,
    )


def _next_hosted_turn_id(
    conversation_id: str,
    *,
    excluded: Optional[set[str]] = None,
) -> str:
    """Return the oldest durable unfinished turn for one conversation."""

    with _STATE_LOCK:
        state = load_single_state()
        conversation = next(
            (
                item
                for item in state.get("conversations") or []
                if isinstance(item, dict) and item.get("id") == conversation_id
            ),
            None,
        )
        # Deleting a conversation is also the cancellation boundary for its
        # serial hosted consumer. The consumer can race with deletion between
        # turns, so a missing record is a normal empty-queue result.
        if conversation is None:
            return ""
        candidates = [
            (
                int(run.get("created_at") or 0),
                index,
                str(candidate_turn_id),
            )
            for index, (candidate_turn_id, run) in enumerate(
                (conversation.get("hosted_turns") or {}).items()
            )
            if isinstance(run, dict)
            and str(run.get("status") or "queued") in {"queued", "running"}
            and not run.get("paused")
            and str(run.get("stage") or "") not in {"routing_pending", "routing_failed"}
            and str(candidate_turn_id) not in (excluded or set())
        ]
    if not candidates:
        return ""
    return min(candidates)[2]


def _hosted_turn_account_generation(conversation_id: str, turn_id: str) -> str:
    # Enqueue has already authenticated and captured this generation before
    # the worker is started. The immutable live projection is the same
    # ownership-scoped record used by the SSE route, so use it to avoid a
    # second full single.json read plus MobileDeviceStore SQLite open before
    # the first gateway prompt. Recovery paths without a live projection keep
    # the authoritative durable/store validation below.
    with _HOSTED_LIVE_STATE_LOCK:
        live_conversation = _HOSTED_LIVE_CONVERSATIONS.get(
            str(conversation_id or "").strip()
        )
        if isinstance(live_conversation, dict):
            live_generation = str(
                live_conversation.get("account_generation") or ""
            ).strip()
            live_run = (
                (live_conversation.get("hosted_turns") or {}).get(turn_id)
                if isinstance(live_conversation.get("hosted_turns"), dict)
                else None
            )
            run_generation = str(
                live_run.get("account_generation") or ""
            ).strip() if isinstance(live_run, dict) else ""
            if live_generation and (not run_generation or run_generation == live_generation):
                return live_generation
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            raise RuntimeError("Hosted turn record does not exist")
        owner_id = str(conversation.get("owner_id") or LOCAL_OWNER_ID)
        live_generation = _account_generation_for_owner(owner_id)
        conversation_generation = str(
            conversation.get("account_generation") or ""
        ).strip()
        run_generation = str(run.get("account_generation") or "").strip()
        if (
            (conversation_generation and conversation_generation != live_generation)
            or (run_generation and run_generation != live_generation)
        ):
            raise RuntimeError("stale hosted turn account generation")
        changed = False
        if not conversation_generation:
            conversation["account_generation"] = live_generation
            changed = True
        if not run_generation:
            run["account_generation"] = live_generation
            changed = True
        if changed:
            save_single_state(state)
        return live_generation


def _hosted_turn_mode(conversation_id: str, turn_id: str) -> str:
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            return "work"
        route_metadata = (
            run.get("route_metadata")
            if isinstance(run.get("route_metadata"), dict)
            else {}
        )
        mode = str(
            run.get("mode") or route_metadata.get("mode") or "work"
        ).lower()
        return "chat" if mode == "chat" else "work"


def _set_hosted_execution_generation(account_generation: str) -> None:
    _HOSTED_EXECUTION_GENERATION.value = str(account_generation or "").strip()


def start_hosted_workflow(conversation_id: str, turn_id: str) -> threading.Thread:
    del turn_id  # The per-conversation consumer selects the oldest durable turn.
    key = str(conversation_id)
    with _HOSTED_THREADS_LOCK:
        existing = _HOSTED_THREADS.get(key)
        if existing is not None and existing.is_alive():
            return existing

        def run_and_release() -> None:
            attempted_turn_ids: set[str] = set()
            try:
                while True:
                    current_turn_id = _next_hosted_turn_id(
                        conversation_id,
                        excluded=attempted_turn_ids,
                    )
                    if not current_turn_id:
                        break
                    attempted_turn_ids.add(current_turn_id)
                    _set_hosted_execution_generation(
                        _hosted_turn_account_generation(
                            conversation_id,
                            current_turn_id,
                        )
                    )
                    try:
                        with _hosted_conversation_execution_lock(conversation_id):
                            execute_hosted_workflow(
                                conversation_id,
                                current_turn_id,
                            )
                    except Exception as exc:
                        clean_error = sanitize_runtime_error(exc)
                        try:
                            failure_mode = _hosted_turn_mode(
                                conversation_id,
                                current_turn_id,
                            )
                            if failure_mode == "chat":
                                failure_message = {
                                    "role": "assistant",
                                    "name": "default",
                                    "content": f"对话运行失败：{clean_error}",
                                    "status": "failed",
                                    "kind": "message",
                                    "meta": {
                                        "role_stage": "chat",
                                        "base_role_stage": "chat",
                                        "role_label": "Hermes",
                                        "final_report": False,
                                    },
                                }
                            else:
                                failure_message = {
                                    "role": "assistant",
                                    "name": "default",
                                    "content": f"服务端任务失败：{clean_error}",
                                    "status": "failed",
                                    "kind": "message",
                                    "meta": {
                                        "role_stage": "reporter",
                                        "base_role_stage": "reporter",
                                        "role_label": "Hermes · 最终汇报",
                                        "final_report": True,
                                    },
                                }
                            persisted_run = _persist_hosted_turn(
                                conversation_id,
                                current_turn_id,
                                patch={
                                    "status": "failed",
                                    "stage": "failed",
                                    "error": clean_error,
                                    "completed_at": int(time.time() * 1000),
                                    "notification": _completion_notification_record(
                                        conversation_id,
                                        current_turn_id,
                                        "failed",
                                        clean_error,
                                    ),
                                },
                                message=failure_message,
                            )
                        except Exception:
                            persisted_run = {}
                        if persisted_run:
                            _schedule_persisted_terminal_notification(
                                conversation_id,
                                current_turn_id,
                                persisted_run,
                                fallback_result=clean_error,
                            )
            finally:
                _set_hosted_execution_generation("")
                with _HOSTED_THREADS_LOCK:
                    _HOSTED_THREADS.pop(key, None)
                try:
                    _finalize_pending_conversation_deletion(conversation_id)
                except Exception:
                    pass
                # A turn can be committed while the consumer is between its
                # final empty check and removal. Rescan after removal so that
                # this handoff window never strands durable queued work.
                try:
                    pending_turn_id = _next_hosted_turn_id(
                        conversation_id,
                        excluded=attempted_turn_ids,
                    )
                except Exception:
                    pending_turn_id = ""
                if pending_turn_id:
                    start_hosted_workflow(conversation_id, pending_turn_id)

        thread = threading.Thread(
            target=run_and_release,
            name=f"hermes-hosted-{conversation_id[-12:]}",
            daemon=True,
        )
        _HOSTED_THREADS[key] = thread
        thread.start()
        return thread


@contextmanager
def _hosted_conversation_execution_lock(conversation_id: str):
    """Serialize one conversation and reclaim idle lock objects safely."""
    key = str(conversation_id)
    with _HOSTED_CONVERSATION_LOCKS_LOCK:
        entry = _HOSTED_CONVERSATION_LOCKS.get(key)
        if entry is None:
            entry = _ConversationExecutionLock()
            _HOSTED_CONVERSATION_LOCKS[key] = entry
        entry.users += 1
    try:
        with entry.lock:
            yield
    finally:
        with _HOSTED_CONVERSATION_LOCKS_LOCK:
            entry.users -= 1
            if entry.users == 0 and _HOSTED_CONVERSATION_LOCKS.get(key) is entry:
                _HOSTED_CONVERSATION_LOCKS.pop(key, None)


def resume_unfinished_hosted_workflows(
    conversations: list[dict[str, Any]],
) -> None:
    for conversation in conversations:
        conversation_id = str(conversation.get("id") or "").strip()
        if not conversation_id:
            continue
        for turn_id, run in (conversation.get("hosted_turns") or {}).items():
            if not isinstance(run, dict):
                continue
            if run.get("status") in {"queued", "running"}:
                if str(run.get("stage") or "") in {"routing_pending", "routing_failed"}:
                    start_hosted_routing(conversation_id, str(turn_id))
                else:
                    start_hosted_workflow(conversation_id, str(turn_id))
                continue
            notification = run.get("notification")
            if (
                isinstance(notification, dict)
                and str(notification.get("state") or "queued")
                not in _MOBILE_NOTIFICATION_TERMINAL_STATUSES
            ):
                _schedule_mobile_completion_notification(
                    conversation_id,
                    str(turn_id),
                    str(notification.get("task_status") or run.get("status") or "failed"),
                    str(notification.get("result") or ""),
                )


def _room_by_id(state: dict[str, Any], room_id: str) -> dict[str, Any]:
    for room in state.get("rooms") or []:
        if room.get("id") == room_id:
            return room
    raise HTTPException(status_code=404, detail="群聊不存在")


def _configured_legacy_owner_id() -> str:
    """Return the only account allowed to adopt pre-account local data."""

    # Migration must be an explicit operator action. HERMES_OWNER_EMAIL is an
    # authentication setting and must not make a normal mobile account inherit
    # local development or E2E records merely by listing conversations.
    return os.environ.get("HERMES_LEGACY_OWNER_ID", "").strip()[:512]


def _legacy_owner_claim_allowed(existing_owner: str, owner_id: str) -> bool:
    """Require an explicit server-side binding before migrating local data."""

    existing = str(existing_owner or "").strip()
    requested = str(owner_id or "").strip()
    if existing not in {"", LOCAL_OWNER_ID} or not requested:
        return False
    if requested == LOCAL_OWNER_ID:
        return True
    configured = _configured_legacy_owner_id()
    return bool(configured and hmac.compare_digest(configured, requested))


def _claim_legacy_rooms_in_state(
    state: dict[str, Any],
    owner_id: str,
    *,
    account_generation: str = "",
    requested_room_id: str = "",
) -> bool:
    """Assign pre-account rooms once, without reopening claimed records."""

    normalized_owner = str(owner_id or "").strip()
    if not normalized_owner:
        return False
    generation = str(
        account_generation or _account_generation_for_owner(normalized_owner)
    ).strip()
    if requested_room_id:
        requested_room = _room_by_id(state, requested_room_id)
        requested_owner = str(requested_room.get("owner_id") or "").strip()
        requested_generation = str(
            requested_room.get("account_generation") or ""
        ).strip()
        if (
            requested_owner == normalized_owner
            and requested_generation == generation
        ):
            return False
        if requested_generation or not (
            _legacy_owner_claim_allowed(requested_owner, normalized_owner)
            or (
                requested_owner == normalized_owner
                and (
                    normalized_owner == LOCAL_OWNER_ID
                    or _configured_legacy_owner_id() == normalized_owner
                )
            )
        ):
            return False
    claimed = False
    for room in state.get("rooms") or []:
        if not isinstance(room, dict):
            continue
        existing_owner = str(room.get("owner_id") or "").strip()
        existing_generation = str(room.get("account_generation") or "").strip()
        if existing_owner == normalized_owner and existing_generation == generation:
            continue
        if existing_generation or not (
            _legacy_owner_claim_allowed(existing_owner, normalized_owner)
            or (
                existing_owner == normalized_owner
                and (
                    normalized_owner == LOCAL_OWNER_ID
                    or _configured_legacy_owner_id() == normalized_owner
                )
            )
        ):
            continue
        room["owner_id"] = normalized_owner
        room["account_generation"] = generation
        claimed = True
    return claimed


def _owned_room_in_state(
    state: dict[str, Any],
    room_id: str,
    owner_id: str,
    account_generation: str = "",
) -> dict[str, Any]:
    room = _room_by_id(state, room_id)
    existing_owner = str(room.get("owner_id") or "").strip()
    if existing_owner != owner_id:
        raise HTTPException(status_code=404, detail="Room not found")
    generation = str(
        account_generation or _account_generation_for_owner(owner_id)
    ).strip()
    if str(room.get("account_generation") or "").strip() != generation:
        raise HTTPException(status_code=404, detail="Room not found")
    return room


def _room_conversation_in_state(
    room: dict[str, Any],
    single_state: dict[str, Any],
    owner_id: str,
    account_generation: str = "",
) -> tuple[dict[str, Any], bool]:
    generation = str(
        account_generation
        or room.get("account_generation")
        or _account_generation_for_owner(owner_id)
    ).strip()
    if str(room.get("account_generation") or "").strip() != generation:
        raise HTTPException(status_code=404, detail="Room not found")
    conversation_id = str(room.get("conversation_id") or "").strip()
    if conversation_id:
        mapped = next(
            (
                item
                for item in single_state.get("conversations") or []
                if isinstance(item, dict) and item.get("id") == conversation_id
            ),
            None,
        )
        if mapped is not None:
            return _owned_conversation_in_state(
                single_state,
                conversation_id,
                owner_id,
            )
    room_id = str(room.get("id") or uuid.uuid4().hex[:12])
    conversation = create_single_conversation(
        "default",
        str(room.get("name") or "Collaboration room"),
    )
    conversation["id"] = f"chat_room_{room_id.removeprefix('room_')}"
    conversation["owner_id"] = owner_id
    conversation["account_generation"] = generation
    conversation["room_id"] = room_id
    conversation["source"] = "collaboration_room"
    conversation["messages"] = normalize_stored_conversation_messages(
        [
            item
            for item in room.get("messages") or []
            if isinstance(item, dict)
        ]
    )
    single_state.setdefault("conversations", []).insert(0, conversation)
    room["conversation_id"] = conversation["id"]
    room["messages"] = []
    return conversation, True


def _room_maps_to_deleting_conversation(
    room: dict[str, Any],
    single_state: dict[str, Any],
) -> bool:
    conversation_id = str(room.get("conversation_id") or "").strip()
    return bool(
        conversation_id
        and any(
            isinstance(item, dict)
            and item.get("id") == conversation_id
            and item.get("delete_requested")
            for item in single_state.get("conversations") or []
        )
    )


def _room_projection(
    room: dict[str, Any],
    single_state: dict[str, Any],
    *,
    summary: bool,
    offset: int = 0,
    limit: int | None = None,
) -> dict[str, Any]:
    projected = dict(room)
    projected.pop("owner_id", None)
    # Direct member mailboxes are fetched through their recipient-scoped
    # endpoint; never include private messages in a room snapshot.
    projected.pop("mailbox", None)
    projected["mailbox_count"] = len(room.get("mailbox") or []) if isinstance(room.get("mailbox"), list) else 0
    projected["dependencies"] = list(room.get("dependencies") or []) if isinstance(room.get("dependencies"), list) else []
    room_owner = str(room.get("owner_id") or "").strip()
    conversation_id = str(room.get("conversation_id") or "").strip()
    conversation = next(
        (
            item
            for item in single_state.get("conversations") or []
            if isinstance(item, dict)
            and item.get("id") == conversation_id
            and not item.get("delete_requested")
            and str(item.get("owner_id") or room_owner).strip()
            in {room_owner, LOCAL_OWNER_ID}
        ),
        None,
    )
    if isinstance(conversation, dict) and conversation.get("archived") and not summary:
        restored = _restore_archived_conversation(single_state, conversation_id)
        if restored is not None:
            conversation = restored
    if isinstance(conversation, dict) and not summary:
        # Room detail is the mobile transcript endpoint. Hydrate the full
        # sidecar here because the compact single-state index intentionally
        # keeps only a bounded tail.
        conversation = _hydrate_conversation_history(conversation)
    messages = (
        list(conversation.get("messages") or [])
        if isinstance(conversation, dict)
        else list(room.get("messages") or [])
    )
    summary_last: Optional[dict[str, Any]] = None
    total_messages = len(messages)
    if isinstance(conversation, dict):
        total_messages, summary_last = _conversation_history_summary(conversation)
    if summary:
        projected_messages = [summary_last] if summary_last else messages[-1:]
        projected["offset"] = max(0, total_messages - len(projected_messages))
        projected["limit"] = len(projected_messages) or 1
        projected["has_more"] = False
    else:
        safe_offset = max(0, int(offset or 0))
        safe_limit = None if limit is None else max(1, min(500, int(limit)))
        projected_messages = (
            messages[safe_offset:]
            if safe_limit is None
            else messages[safe_offset:safe_offset + safe_limit]
        )
        projected["offset"] = safe_offset
        projected["limit"] = safe_limit if safe_limit is not None else len(projected_messages)
        projected["has_more"] = safe_offset + len(projected_messages) < total_messages
    projected["messages"] = projected_messages
    projected["message_count"] = total_messages
    if isinstance(conversation, dict):
        projected["hosted_turns"] = _public_hosted_turns(
            conversation.get("hosted_turns")
        )
        projected["updated_at"] = max(
            int(projected.get("updated_at") or 0),
            int(conversation.get("updated_at") or 0),
        )
    return projected


def _public_hosted_turn(run: dict[str, Any]) -> dict[str, Any]:
    """Remove server-only execution paths and baselines from an API response."""

    projected = dict(run)
    user_delivery_context = str(projected.pop("user_delivery_context", "") or "").strip()
    for key in (
        "output_dir",
        "output_baseline",
        "output_baseline_captured_at",
        "room_request",
    ):
        projected.pop(key, None)
    if user_delivery_context:
        projected["delivery_context"] = user_delivery_context
    else:
        projected.pop("delivery_context", None)
    remote_runs = projected.get("remote_runs")
    if isinstance(remote_runs, dict):
        projected["remote_runs"] = {
            str(role): {
                key: value
                for key, value in remote.items()
                if key
                not in {
                    "delivery_context",
                    "attachment_context",
                    "claim_token",
                    "lease_owner",
                    "cancel_claim_token",
                    "cancel_lease_owner",
                }
            }
            for role, remote in remote_runs.items()
            if isinstance(remote, dict)
        }
    return projected


def _public_hosted_turns(hosted_turns: Any) -> dict[str, dict[str, Any]]:
    if not isinstance(hosted_turns, dict):
        return {}
    return {
        str(turn_id): _public_hosted_turn(run)
        for turn_id, run in hosted_turns.items()
        if isinstance(run, dict)
    }


def _public_conversation(conversation: dict[str, Any]) -> dict[str, Any]:
    projected = dict(conversation)
    # Append-only protocol/history collections have dedicated cursor endpoints.
    # Keeping them out of every snapshot prevents quadratic mobile payloads.
    for internal_key in (
        "hosted_events",
        "hosted_event_sequences",
        "hosted_event_terminals",
        "session_entries",
        "session_entry_quarantine",
        "session_entry_diagnostics",
        "history_message_count",
        "history_last_message",
        "history_session_entry_count",
        "history_complete",
    ):
        projected.pop(internal_key, None)
    projected["hosted_turns"] = _public_hosted_turns(
        conversation.get("hosted_turns")
    )
    # Conversation-level roster so clients render the team without scanning
    # every hosted turn. Additive; per-turn participants stay authoritative.
    projected["participants"] = _conversation_participants(conversation)
    return projected


def _conversation_by_id(
    state: dict[str, Any],
    conversation_id: str,
) -> dict[str, Any]:
    for conversation in state.get("conversations") or []:
        if conversation.get("id") == conversation_id:
            if not conversation.get("archived"):
                return conversation
            # The row is only an archive placeholder.  Resolve the durable
            # transcript before any owner check, mutation, or deletion so a
            # placeholder can never be treated as an empty conversation.
            break
    # Lazy restore of an archived conversation. The caller holds (or can
    # acquire) _STATE_LOCK; the lock is reentrant, so restoring under it is
    # safe and keeps the restore atomic with respect to other writers.
    restored = _restore_archived_conversation(state, conversation_id)
    if restored is not None:
        try:
            save_single_state(state)
        except Exception:
            # The in-memory restore already succeeded; a failed durable
            # write must not break the caller. The next mutation retries.
            pass
        return restored
    raise HTTPException(status_code=404, detail="单聊会话不存在")


def _owned_conversation_in_state(
    state: dict[str, Any],
    conversation_id: str,
    owner_id: str,
) -> tuple[dict[str, Any], bool]:
    """Resolve one conversation without disclosing another account's data."""

    conversation = _conversation_by_id(state, conversation_id)
    existing_owner = str(conversation.get("owner_id") or "").strip()
    changed = False
    if conversation.get("delete_requested"):
        raise HTTPException(status_code=404, detail="Conversation not found")
    if existing_owner != owner_id:
        if not _legacy_owner_claim_allowed(existing_owner, owner_id):
            raise HTTPException(status_code=404, detail="Conversation not found")
        conversation["owner_id"] = owner_id
        changed = True
    current_generation = _account_generation_for_owner(owner_id)
    stored_generation = str(conversation.get("account_generation") or "").strip()
    if stored_generation and stored_generation != current_generation:
        raise HTTPException(status_code=404, detail="Conversation not found")
    if not stored_generation:
        conversation["account_generation"] = current_generation
        for run in (conversation.get("hosted_turns") or {}).values():
            if isinstance(run, dict) and not run.get("account_generation"):
                run["account_generation"] = current_generation
        changed = True
    return conversation, changed


def _native_activity_projection(
    activity: dict[str, Any],
    *,
    message_model: str = "",
    message_provider: str = "",
) -> dict[str, Any]:
    """Add the stable native activity contract while retaining legacy keys."""
    activity = _redact_sensitive(activity)
    projected = dict(activity)
    started_at = activity.get("started_at")
    completed_at = activity.get("completed_at") or activity.get("ended_at")
    duration_ms = activity.get("duration_ms")
    if duration_ms is None and isinstance(activity.get("duration"), (int, float)):
        duration_ms = round(float(activity["duration"]) * 1000)
    if duration_ms is None and isinstance(started_at, (int, float)) and isinstance(completed_at, (int, float)):
        duration_ms = max(0, int(completed_at) - int(started_at))
    kind = str(activity.get("kind") or activity.get("category") or "status")
    name = str(activity.get("name") or activity.get("summary") or kind)
    detail = activity.get("detail")
    if detail in (None, ""):
        detail = activity.get("output") or activity.get("preview") or activity.get("input") or ""
    projected.update(
        {
            "kind": kind,
            "status": str(activity.get("status") or "completed"),
            "summary": str(activity.get("summary") or name),
            "detail": detail,
            "tool_name": str(activity.get("tool_name") or (name if kind == "tool" else "")),
            "model": str(activity.get("model") or message_model),
            "provider": str(activity.get("provider") or message_provider),
            "started_at": started_at,
            "completed_at": completed_at,
            "duration_ms": duration_ms,
            "duration": (
                round(float(duration_ms) / 1000, 3)
                if isinstance(duration_ms, (int, float))
                else activity.get("duration")
            ),
        }
    )
    return projected


def _project_native_message(message: dict[str, Any]) -> dict[str, Any]:
    """Mirror sender, role, time, model, handoff, and activities at top level."""
    meta = dict(message.get("meta") or {})
    canonical_role = str(message.get("role") or "assistant")
    default_stage = canonical_role if canonical_role in {"user", "system"} else "chat"
    stage = str(meta.get("base_role_stage") or meta.get("role_stage") or default_stage)
    base_stage = stage.split(":", 1)[0]
    logical_role = {
        "dispatch": "dispatcher",
        "workflow": "dispatcher",
        "worker": "worker",
        "reviewer": "reviewer",
        "reporter": "reporter",
        "chat": "hermes",
        "user": "user",
        "system": "system",
    }.get(base_stage, base_stage or "hermes")
    if base_stage.startswith("manager"):
        logical_role = "dispatcher"
    profile = str(meta.get("profile") or message.get("name") or "default")
    model = str(meta.get("actual_model") or message.get("model") or "")
    provider = str(meta.get("actual_provider") or message.get("provider") or "")
    created_at = message.get("created_at") or int(time.time() * 1000)
    updated_at = message.get("updated_at") or created_at
    message_status = str(message.get("status") or "completed")
    terminal = message_status in {"completed", "failed", "cancelled", "blocked"}
    activities = [
        _native_activity_projection(item, message_model=model, message_provider=provider)
        for item in meta.get("activities") or []
        if isinstance(item, dict)
    ]
    if terminal:
        terminal_activity_status = "completed" if message_status == "completed" else message_status
        for activity in activities:
            if str(activity.get("status") or "") in {
                "pending", "queued", "running", "starting", "streaming"
            }:
                activity["status"] = terminal_activity_status
                activity["completed_at"] = updated_at
    meta["activities"] = activities
    handoff_to = meta.get("handoff_to") or []
    if isinstance(handoff_to, str):
        handoff_to = [handoff_to]
    completed_at = message.get("completed_at") or meta.get("completed_at")
    if terminal and completed_at is None:
        completed_at = updated_at
    started_at = message.get("started_at") or meta.get("started_at") or created_at
    duration_ms = message.get("duration_ms")
    if not isinstance(duration_ms, (int, float)):
        duration_ms = meta.get("duration_ms")
    if (
        not isinstance(duration_ms, (int, float))
        and isinstance(started_at, (int, float))
        and isinstance(completed_at, (int, float))
    ):
        duration_ms = max(0, int(completed_at) - int(started_at))
    role_label = str(meta.get("role_label") or "")
    sender_id = str(meta.get("sender_id") or profile or logical_role)
    sender_name = str(
        meta.get("sender_name")
        or role_label
        or message.get("name")
        or profile
    )
    member_id = str(meta.get("member_id") or "")
    if not member_id:
        # Hosted stage events attribute to a canonical roster member; plain
        # chat/user/system messages keep their sender identity unchanged.
        member_id = (
            hosted_member_id(profile, stage)
            if canonical_role != "user"
            and logical_role in {"dispatcher", "worker", "reviewer", "reporter", "supervisor"}
            else sender_id
        )
    model_display = " · ".join(item for item in (provider, model) if item)
    copy_context = {
        "version": 1,
        "sender": {
            "id": sender_id,
            "name": sender_name,
            "role": logical_role,
            "profile": profile,
            "member_id": member_id,
        },
        "model": {
            "provider": provider,
            "name": model,
            "display_name": model_display,
        },
        "workflow": {
            "stage": stage,
            "label": role_label,
            "status": message_status,
            "handoff_to": list(handoff_to),
        },
        "timing": {
            "created_at": created_at,
            "started_at": started_at,
            "completed_at": completed_at,
            "duration_ms": duration_ms,
        },
    }
    message.update(
        {
            "sender_id": sender_id,
            "sender_name": sender_name,
            "member_id": member_id,
            # Keep the canonical chat role (assistant/user/system) intact;
            # native clients read the participant role from sender_role.
            "role": canonical_role,
            "collaboration_role": logical_role,
            "sender_role": logical_role,
            "role_stage": stage,
            "role_label": role_label,
            "profile": profile,
            "avatar": str(meta.get("avatar") or f"role:{logical_role}"),
            "status": message_status,
            "model": model,
            "provider": provider,
            "model_display": model_display,
            "handoff_to": list(handoff_to),
            "created_at": created_at,
            "updated_at": updated_at,
            "started_at": started_at,
            "completed_at": completed_at,
            "duration_ms": duration_ms,
            "activity_count": len(activities),
            "activities": activities,
            "copy_context": copy_context,
            "meta": meta,
        }
    )
    return message


def _append_message(
    room: dict[str, Any],
    *,
    role: str,
    name: str,
    content: str,
    status: str = "completed",
    kind: str = "message",
    meta: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    message = {
        "id": f"msg_{uuid.uuid4().hex[:14]}",
        "role": role,
        "name": name,
        "content": content,
        "status": status,
        "kind": kind,
        "created_at": int(time.time() * 1000),
    }
    if meta:
        message["meta"] = meta
    _project_native_message(message)
    messages = room.setdefault("messages", [])
    messages.append(message)
    room["updated_at"] = message["created_at"]
    if "hosted_turns" in room:
        message_meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
        turn_id = str(
            message_meta.get("runtime_turn_id")
            or message_meta.get("turn_id")
            or message["id"]
        )
        role_stage = str(message_meta.get("role_stage") or role or "chat")
        append_session_entry(
            room,
            entry_type="message",
            idempotency_key=f"message:{message['id']}",
            payload={
                "message_id": message["id"],
                "role": role,
                "name": name,
                "content": content,
                "status": status,
                "kind": kind,
                "turn_id": turn_id,
                "role_stage": role_stage,
            },
            occurred_at=message["created_at"],
        )
        _append_attachment_session_entries(
            room,
            turn_id=turn_id,
            role_stage=role_stage,
            attachments=message_meta.get("attachments"),
            direction=("input" if role == "user" else "output"),
            occurred_at=message["created_at"],
        )
        append_hosted_event(
            room,
            conversation_id=str(room.get("id") or "conversation"),
            turn_id=turn_id,
            role_stage=role_stage,
            event_type="message.completed" if status in _HOSTED_TERMINAL_STATUSES else "message.started",
            entity_id=message["id"],
            idempotency_key=f"message-event:{message['id']}:{status}",
            account_generation=_account_generation_for_owner(
                str(room.get("owner_id") or LOCAL_OWNER_ID)
            ),
            payload={
                "entity_id": message["id"],
                "role": role,
                "name": name,
                "content": content,
                "status": status,
                "kind": kind,
            },
            occurred_at=message["created_at"],
        )
    return message


