def _validate_connector_claim(claimed: Any, authenticated: str) -> None:
    normalized = str(claimed or "").strip()[:128]
    if normalized and normalized != authenticated:
        raise HTTPException(status_code=403, detail="Connector identity mismatch")


def _require_remote_run_claim(
    remote_run: dict[str, Any],
    *,
    connector_id: str,
    claim_token: Any,
    now: Optional[int] = None,
) -> None:
    """Require the current per-claim secret and a live lease for mutation."""

    supplied = str(claim_token or "").strip()
    expected = str(remote_run.get("claim_token") or "").strip()
    owner = str(remote_run.get("lease_owner") or "").strip()
    if str(remote_run.get("status") or "") in _REMOTE_TERMINAL_STATUSES:
        raise _connector_conflict(
            "terminal_sealed",
            "Remote run terminal state is sealed",
        )
    if (
        not supplied
        or not expected
        or owner != connector_id
        or not hmac.compare_digest(supplied, expected)
    ):
        raise _connector_conflict("claim_lost", "Remote run claim was lost")
    instant = int(time.time() * 1000) if now is None else int(now)
    if _nonnegative_int(remote_run.get("lease_until")) <= instant:
        # An awaiting run is parked on a human decision: a long think time
        # must not 409 the resume checkpoint purely on lease expiry (the
        # secret token above already proved the claim). Lease expiry stays
        # fatal for actively executing runs so stale claims are arbitrated.
        if str(remote_run.get("status") or "") != "awaiting_input":
            raise _connector_conflict("lease_expired", "Remote run lease expired")


def _seal_remote_run_claim(
    remote_run: dict[str, Any],
    *,
    now: Optional[int] = None,
) -> None:
    """Permanently retire execution and cancellation claims after termination."""

    instant = int(time.time() * 1000) if now is None else int(now)
    token = str(remote_run.pop("claim_token", "") or "")
    if token:
        remote_run["sealed_claim_sha256"] = hashlib.sha256(
            token.encode("utf-8")
        ).hexdigest()
    remote_run.pop("lease_owner", None)
    remote_run.pop("cancel_claim_token", None)
    remote_run.pop("cancel_lease_owner", None)
    remote_run["lease_until"] = 0
    remote_run["cancel_lease_until"] = 0
    remote_run["claim_sealed_at"] = instant


def _require_active_remote_artifact_claim(
    hosted: dict[str, Any],
    remote_run: dict[str, Any],
    *,
    connector_id: str,
    claim_token: Any,
    now: Optional[int] = None,
) -> None:
    """Require an active non-cancelling run before accepting an artifact."""

    hosted_status = str(hosted.get("status") or "queued").strip().lower()
    hosted_stage = str(hosted.get("stage") or "").strip().lower()
    remote_status = str(remote_run.get("status") or "queued").strip().lower()
    if (
        hosted_status in _HOSTED_TERMINAL_STATUSES
        or hosted_status in {"cancelling", "cancel_requested"}
        or hosted_stage in {"cancelling", "cancel_requested", "cancelled"}
        or _coerce_flag(hosted.get("cancel_requested"))
        or _coerce_flag(remote_run.get("cancel_requested"))
        or remote_status not in _REMOTE_ARTIFACT_ACTIVE_STATUSES
    ):
        reason = (
            "terminal_sealed"
            if remote_status in _REMOTE_TERMINAL_STATUSES
            else "claim_lost"
        )
        raise _connector_conflict(
            reason,
            "Remote run is not active for artifact upload",
        )
    _require_remote_run_claim(
        remote_run,
        connector_id=connector_id,
        claim_token=claim_token,
        now=now,
    )


def _validate_connector_batch(
    body: ConnectorPullBody,
    authenticated: str,
) -> tuple[str, int, int]:
    _validate_connector_claim(body.connector_id, authenticated)
    limit = max(1, min(int(body.limit or 1), _MAX_REMOTE_RUNS_PER_PULL))
    lease_seconds = max(5, min(int(body.lease_seconds or _REMOTE_RUN_LEASE_SECONDS), 900))
    return authenticated, limit, lease_seconds


def _remote_run_for_connector(
    request: Request,
    remote_run_id: str,
    *,
    enforce_account_boundary: bool = True,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    connector_id = _require_connector(request)
    _advance_remote_run_deadline(remote_run_id)
    with _STATE_LOCK:
        state = load_single_state()
        location = _remote_run_location(state, remote_run_id)
        if location is None:
            raise HTTPException(status_code=404, detail="Remote run not found")
        conversation, hosted, _role_key, remote_run = location
        if _remote_run_connector_id(remote_run) != connector_id:
            raise HTTPException(status_code=404, detail="Remote run not found")
        if enforce_account_boundary:
            _require_connector_account_boundary(conversation, remote_run)
        return conversation, hosted, remote_run


def _remote_run_connector_payload(remote_run: dict[str, Any]) -> dict[str, Any]:
    payload = _remote_run_public(remote_run)
    payload["remote_run_id"] = payload.pop("id", "")
    # Durable steers ride along with the pull payload so an answer the user
    # sent while the connector's SSE stream was down is still delivered on
    # the next poll cycle.
    pending_steers = remote_run.get("pending_steers")
    if isinstance(pending_steers, list) and pending_steers:
        payload["pending_steers"] = [
            {
                **dict(item),
                # SSE delivery uses "steer_id"; keep both keys so the
                # connector's dedupe applies across both channels.
                "steer_id": str(item.get("id") or ""),
            }
            for item in pending_steers
            if isinstance(item, dict)
        ]
    return payload


@router.get("/connector/runs/{remote_run_id}")
def connector_get_run(remote_run_id: str, request: Request):
    """Return authoritative claim/terminal state for conflict reconciliation."""

    connector_id = _require_connector(request)
    _rate_limit_connector(request, connector_id, "run")
    _conversation, _hosted, remote_run = _remote_run_for_connector(
        request,
        remote_run_id,
        # The reconciliation view carries the same goal/context payload as
        # the pull, so it must enforce the identical account-generation
        # boundary — a deleted-era run is a conflict, not readable state.
        enforce_account_boundary=True,
    )
    return {"run": _remote_run_connector_payload(remote_run)}


def _sanitize_remote_activities(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        return []
    sanitized: list[dict[str, Any]] = []
    for item in value[:200]:
        if not isinstance(item, dict):
            continue
        clean = _redact_sensitive(dict(item))
        for key in ("output", "detail", "result", "input", "args", "summary"):
            if key in clean and isinstance(clean[key], str):
                clean[key] = clean[key][:12000]
        sanitized.append(clean)
    return sanitized


def _sanitize_remote_subagents(value: Any) -> list[dict[str, Any]]:
    """Bound and redact worker-delegated subagent records (agent team)."""
    if not isinstance(value, list):
        return []
    sanitized: list[dict[str, Any]] = []
    for item in value[:50]:
        if not isinstance(item, dict):
            continue
        clean = _redact_sensitive(dict(item))
        for key in ("goal", "summary"):
            if key in clean and isinstance(clean[key], str):
                clean[key] = clean[key][:4000]
        sanitized.append(clean)
    return sanitized


def _apply_remote_checkpoint(
    remote_run_id: str,
    payload: dict[str, Any],
) -> tuple[dict[str, Any], bool]:
    payload = _redact_sensitive(payload)
    status = str(payload.get("status") or "").strip().lower()
    terminal = _coerce_flag(payload.get("terminal"))
    if status not in {"running", "awaiting_input", "completed", "failed", "cancelled", "timed_out"}:
        raise HTTPException(status_code=422, detail="Invalid remote run status")
    expected_terminal = status in _REMOTE_TERMINAL_STATUSES
    if terminal != expected_terminal:
        raise HTTPException(status_code=422, detail="terminal does not match status")
    try:
        cursor = int(payload.get("checkpoint_cursor") or 0)
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=422, detail="checkpoint_cursor must be an integer") from exc
    if cursor < 0:
        raise HTTPException(status_code=422, detail="checkpoint_cursor must be non-negative")

    now = int(time.time() * 1000)
    with _STATE_LOCK:
        state = load_single_state()
        deadline_changes = _advance_remote_run_deadlines(state, now=now)
        if deadline_changes:
            save_single_state(state)
        location = _remote_run_location(state, remote_run_id)
        if location is None:
            raise HTTPException(status_code=404, detail="Remote run not found")
        conversation, hosted, role_key, remote_run = location
        conversation_id = str(conversation.get("id") or "")
        turn_id = str(hosted.get("turn_id") or "")
        _require_connector_account_boundary(conversation, remote_run)
        connector_id = str(payload.get("connector_id") or "").strip()[:128]
        _require_remote_run_claim(
            remote_run,
            connector_id=connector_id,
            claim_token=payload.get("claim_token"),
            now=now,
        )
        hosted_status = str(hosted.get("status") or "queued")
        current_status = str(remote_run.get("status") or "queued")
        current_cursor = _nonnegative_int(remote_run.get("checkpoint_cursor"))
        if (
            hosted_status in _HOSTED_TERMINAL_STATUSES
            or _coerce_flag(hosted.get("cancel_requested"))
            or _coerce_flag(remote_run.get("cancel_requested"))
        ) and status not in {"cancelled", "timed_out"}:
            raise _connector_conflict(
                "claim_lost",
                "Remote run cancellation already won; late checkpoint rejected",
            )
        if current_status in _REMOTE_TERMINAL_STATUSES:
            return dict(remote_run), False
        if (
            status == "completed"
            and _coerce_flag(remote_run.get("artifact_required"))
            and not any(
                isinstance(item, dict) and item.get("id")
                for item in remote_run.get("artifacts") or []
            )
        ):
            raise _connector_conflict(
                "artifact_required",
                "Required artifact must be uploaded before completion",
            )
        if cursor < current_cursor:
            return dict(remote_run), False
        remote_run.update(
            {
                "status": status,
                "checkpoint_cursor": cursor,
                "summary": str(payload.get("summary") or "")[:20000],
                "result": str(payload.get("result") or "")[:50000],
                "error": str(payload.get("error") or "")[:4000],
                "activities": _sanitize_remote_activities(payload.get("activities")),
                "subagents": _sanitize_remote_subagents(payload.get("subagents")),
                "context_used_percent": _positive_int_or_none(
                    payload.get("context_used_percent")
                ),
                "updated_at": now,
            }
        )
        for key in ("remote_task_id", "root_task_id", "session_id", "actual_model", "actual_provider"):
            value = str(payload.get(key) or "").strip()
            if value:
                remote_run[key] = value[:512]
        observed_at = str(payload.get("observed_at") or "").strip()
        if observed_at:
            remote_run["observed_at"] = observed_at[:128]
        if status == "running":
            remote_run.setdefault("started_at", now)
            lease_seconds = max(
                5,
                min(
                    int(payload.get("lease_seconds") or _REMOTE_RUN_LEASE_SECONDS),
                    900,
                ),
            )
            remote_run["lease_until"] = now + lease_seconds * 1000
            # The member resumed after an awaiting choice: clear the parked
            # flags so a later needs_input can re-enter awaiting cleanly.
            # Durable steers are cleared per-ack: the connector reports the
            # ids it applied, so a second answer that arrived while the first
            # was being consumed survives for the next pull.
            remote_run.pop("awaiting_input", None)
            remote_run.pop("choice_options", None)
            applied_steer_ids = {
                str(item).strip()[:64]
                for item in (payload.get("applied_steer_ids") or [])
                if str(item).strip()
            }
            pending_steers = remote_run.get("pending_steers")
            if isinstance(pending_steers, list) and pending_steers:
                if applied_steer_ids:
                    kept = [
                        item
                        for item in pending_steers
                        if isinstance(item, dict)
                        and str(item.get("id") or "") not in applied_steer_ids
                    ]
                    if kept:
                        remote_run["pending_steers"] = kept
                    else:
                        remote_run.pop("pending_steers", None)
                else:
                    # Older connectors do not report acks: the resume itself
                    # proves the awaiting answer was consumed.
                    remote_run.pop("pending_steers", None)
        was_awaiting = _coerce_flag(remote_run.get("awaiting_input"))
        if status == "awaiting_input":
            # Worker asked a human a question. Surface a choice card: parse
            # A./B./C. options from the block reason so the mobile client can
            # render selectable options plus a custom input.
            remote_run["awaiting_input"] = True
            options = _parse_choice_options(
                str(payload.get("summary") or remote_run.get("summary") or "")
            )
            remote_run["choice_options"] = options
            # Parked while a human decides: give the claim a floor far above
            # the normal execution window so a long think time does not
            # expire the claim before the answer arrives. The connector's
            # pull cycle can still re-lease it if the user takes even longer.
            remote_run["lease_until"] = now + max(
                int(payload.get("lease_seconds") or _REMOTE_RUN_LEASE_SECONDS),
                _REMOTE_AWAITING_LEASE_SECONDS,
            ) * 1000
            # The overall deadline must not fire while the human is still
            # thinking — otherwise a slow answer gets hard-cancelled by the
            # timeout sweep (the very thing the awaiting lease prevents for
            # the claim).
            deadline_at = _positive_int(remote_run.get("deadline_at"))
            remote_run["deadline_at"] = max(
                deadline_at or 0,
                now + _REMOTE_AWAITING_LEASE_SECONDS * 1000,
            )
        entered_awaiting = (
            status == "awaiting_input" and not was_awaiting
        )
        if entered_awaiting:
            # Emit awaiting.choice exactly once per awaiting entry so the
            # mobile client renders the decision card. The idempotency key is
            # stable per remote run + cursor: connector retries of this same
            # checkpoint dedupe, and a fresh question (new cursor, after the
            # worker resumed and re-asked) emits a new card.
            summary_text = str(
                payload.get("summary") or remote_run.get("summary") or ""
            )
            append_hosted_event(
                conversation,
                conversation_id=conversation_id,
                turn_id=turn_id,
                role_stage=role_key,
                event_type="awaiting.choice",
                entity_id=f"awaiting:{remote_run_id}",
                idempotency_key=f"awaiting-choice:{remote_run_id}:{cursor}",
                account_generation=_account_generation_for_owner(
                    str(conversation.get("owner_id") or LOCAL_OWNER_ID)
                ),
                payload={
                    "question": _strip_choice_options(summary_text),
                    "options": list(remote_run.get("choice_options") or []),
                    "remote_run_id": str(remote_run.get("id") or ""),
                    "profile": str(remote_run.get("profile") or role_key or ""),
                },
            )
        if expected_terminal:
            remote_run["completed_at"] = now
            remote_run.pop("pending_steers", None)
            _seal_remote_run_claim(remote_run, now=now)
        if status == "cancelled":
            remote_run["cancel_requested"] = True
        save_single_state(state)
        persisted = dict(remote_run)
        role_label = f"{remote_run.get('profile') or role_key} · 执行"
        schedule_awaiting_push = entered_awaiting
        awaiting_question = (
            _strip_choice_options(
                str(payload.get("summary") or remote_run.get("summary") or "")
            )
            if entered_awaiting
            else ""
        )
        resumed_from_awaiting = status == "running" and was_awaiting
    _notify_hosted_update(conversation_id)
    if schedule_awaiting_push:
        # Background-exit UX: a parked member is the highest-priority signal.
        # If the app is open the dispatcher suppresses the push (presence);
        # the moment it leaves, the push fires within seconds.
        _schedule_mobile_awaiting_notification(
            conversation_id,
            turn_id,
            awaiting_question,
        )
    elif resumed_from_awaiting or expected_terminal:
        # The answer landed (or the run ended unanswered): retire the push.
        _cancel_pending_awaiting_notification(conversation_id, turn_id)
    _remote_run_state_message(
        conversation_id,
        turn_id,
        persisted,
        role_label=role_label,
    )
    if expected_terminal:
        _finalize_pending_conversation_deletion(conversation_id)
        # Wake the connector immediately: the server may create the next
        # role run right after this checkpoint, and pushing here lets the
        # connector poll it within its next cycle instead of a full interval.
        _push_connector_event(
            str(persisted.get("connector_id") or ""),
            {"type": "run.terminal", "remote_run_id": str(persisted.get("id") or "")},
        )
    # Any terminal checkpoint on a cancel-requested run (cancelled via
    # cancel-ack, or timed_out via the force-terminal sweep) must drive the
    # turn-level finisher — the workflow thread that originally observed the
    # run may already be gone.
    if expected_terminal and _coerce_flag(persisted.get("cancel_requested")):
        _finish_hosted_turn_if_cancelled(conversation_id, turn_id)
    return persisted, True


def _connector_relative_path(value: str) -> str:
    decoded = unquote(str(value or "").replace("\x00", "")).replace("\\", "/")
    if not decoded or decoded.startswith("/") or re.match(r"^[A-Za-z]:", decoded):
        raise HTTPException(status_code=422, detail="relative_path must be relative")
    parts = [part for part in decoded.split("/") if part not in {"", "."}]
    if not parts or any(part == ".." for part in parts):
        raise HTTPException(status_code=422, detail="relative_path is invalid")
    return "/".join(parts)[:1024]


# Connector push channel: each connected connector holds a queue here; run
# lifecycle events (created / terminal) are pushed so the connector can react
# immediately instead of waiting for its next poll cycle. This collapses role
# switch latency from one or two poll intervals down to ~1s on the wire.
_CONNECTOR_STREAM_QUEUES: dict[str, set["queue.Queue"]] = {}
_CONNECTOR_STREAM_COUNTS: dict[str, int] = {}
_CONNECTOR_STREAM_HISTORY: dict[str, deque[dict[str, Any]]] = {}
_CONNECTOR_STREAM_SEQUENCE = 0
_CONNECTOR_STREAM_HISTORY_MAX = 200
_CONNECTOR_STREAM_LOCK = threading.Lock()
_CONNECTOR_METRICS_LOCK = threading.Lock()
_CONNECTOR_METRICS: dict[str, dict[str, int]] = {}


def _record_connector_metric(connector_id: str, action: str) -> None:
    normalized = str(connector_id or "").strip()[:128]
    action = str(action or "").strip()[:64] or "unknown"
    if not normalized:
        return
    with _CONNECTOR_METRICS_LOCK:
        bucket = _CONNECTOR_METRICS.setdefault(normalized, {})
        bucket[action] = int(bucket.get(action) or 0) + 1


def _audit_connector(connector_id: str, event_name: str, **fields: Any) -> None:
    """Append an append-only connector operation audit line (best effort)."""
    try:
        from hermes_cli.dashboard_auth.audit import AuditEvent, audit_log

        audit_log(
            AuditEvent[event_name],
            connector_id=str(connector_id or "")[:128],
            **fields,
        )
    except Exception:
        # Audit is observability, never a request blocker.
        pass


def _push_connector_event(connector_id: str, event: dict[str, Any]) -> None:
    global _CONNECTOR_STREAM_SEQUENCE
    normalized = str(connector_id or "").strip()[:128]
    if not normalized:
        return
    with _CONNECTOR_STREAM_LOCK:
        _CONNECTOR_STREAM_SEQUENCE += 1
        event_id = str(_CONNECTOR_STREAM_SEQUENCE)
        stamped = dict(event)
        stamped["id"] = event_id
        stamped["event_id"] = event_id
        history = _CONNECTOR_STREAM_HISTORY.setdefault(
            normalized,
            deque(maxlen=_CONNECTOR_STREAM_HISTORY_MAX),
        )
        history.append(dict(stamped))
        stream_queues = tuple(_CONNECTOR_STREAM_QUEUES.get(normalized, ()))
    # A reconnect can overlap the old SSE request briefly.  Fan out to every
    # live subscription instead of replacing the previous queue and silently
    # losing its wake event.  Bounded queues keep a stalled client from
    # retaining an unbounded lifecycle backlog in the server process.
    for stream_queue in stream_queues:
        try:
            stream_queue.put_nowait(dict(stamped))
        except queue.Full:
            try:
                stream_queue.get_nowait()
                stream_queue.put_nowait(dict(stamped))
            except Exception:
                pass
        except Exception:
            pass


@router.get("/connector/stream")
def connector_stream(request: Request):
    """Long-lived SSE channel for one connector.

    The connector subscribes with its connector token; the server pushes
    ``run.created`` / ``run.terminal`` events so the connector can poll
    immediately. Heartbeats every 25s keep intermediaries from closing the
    stream.  Each event carries an ``id`` so a reconnecting connector can send
    ``Last-Event-ID`` and receive events that arrived while it was offline.
    """
    connector_id = _require_connector(request)
    _rate_limit_connector(request, connector_id, "stream")
    last_event_id = str(request.headers.get("last-event-id") or "").strip()
    stream_queue: "queue.Queue" = queue.Queue(maxsize=32)
    with _CONNECTOR_STREAM_LOCK:
        active = _CONNECTOR_STREAM_COUNTS.get(connector_id, 0)
        if active >= _SSE_MAX_CONNECTIONS_PER_CONNECTOR:
            raise HTTPException(
                status_code=429,
                detail="Too many active connector streams",
            )
        _CONNECTOR_STREAM_COUNTS[connector_id] = active + 1
        _CONNECTOR_STREAM_QUEUES.setdefault(connector_id, set()).add(stream_queue)

    def event_stream():
        try:
            yield "event: connected\ndata: {\"type\":\"connected\"}\n\n"
            # Replay events that arrived while the previous stream was down.
            if last_event_id:
                try:
                    resume_after = int(last_event_id)
                except (TypeError, ValueError):
                    resume_after = 0
                with _CONNECTOR_STREAM_LOCK:
                    replay = list(_CONNECTOR_STREAM_HISTORY.get(connector_id, ()))
                for event in replay:
                    try:
                        if int(event.get("id") or 0) > resume_after:
                            yield (
                                f"id: {event['id']}\n"
                                "data: "
                                + json.dumps(
                                    event,
                                    ensure_ascii=False,
                                    separators=(",", ":"),
                                )
                                + "\n\n"
                            )
                    except (TypeError, ValueError):
                        continue
            started = time.monotonic()
            while True:
                try:
                    event = stream_queue.get(timeout=25)
                except Exception:
                    if time.monotonic() - started > _SSE_MAX_IDLE_SECONDS:
                        yield ": idle-timeout\n\n"
                        return
                    yield ": keepalive\n\n"
                    continue
                event_id = str(event.get("id") or "")
                yield (
                    (f"id: {event_id}\n" if event_id else "")
                    + "data: "
                    + json.dumps(
                        event,
                        ensure_ascii=False,
                        separators=(",", ":"),
                    )
                    + "\n\n"
                )
        finally:
            with _CONNECTOR_STREAM_LOCK:
                stream_queues = _CONNECTOR_STREAM_QUEUES.get(connector_id)
                if stream_queues is not None:
                    stream_queues.discard(stream_queue)
                    if not stream_queues:
                        _CONNECTOR_STREAM_QUEUES.pop(connector_id, None)
                remaining = max(0, _CONNECTOR_STREAM_COUNTS.get(connector_id, 1) - 1)
                if remaining:
                    _CONNECTOR_STREAM_COUNTS[connector_id] = remaining
                else:
                    _CONNECTOR_STREAM_COUNTS.pop(connector_id, None)

    return StreamingResponse(
        event_stream(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )


@router.get("/connector/health")
def connector_health(request: Request):
    connector_id = _require_connector(request)
    _rate_limit_connector(request, connector_id, "health")
    return {
        "ok": True,
        "connector_id": connector_id,
        "contract_version": _REMOTE_CONTRACT_VERSION,
        "server_time": int(time.time() * 1000),
        "max_artifact_bytes": _MAX_ATTACHMENT_BYTES,
        "capabilities": [
            "pull",
            "ack",
            "checkpoint",
            "cancel",
            "artifact-upload",
            "attachment-download",
            "metrics",
        ],
    }


@router.get("/connector/metrics")
def connector_metrics(request: Request) -> dict[str, Any]:
    """Return process-local connector operation counters for observability."""
    connector_id = _require_connector(request)
    _rate_limit_connector(request, connector_id, "metrics")
    with _CONNECTOR_METRICS_LOCK:
        counts = deepcopy(_CONNECTOR_METRICS.get(connector_id, {}))
    return {
        "connector_id": connector_id,
        "metrics": counts,
        "server_time": int(time.time() * 1000),
    }


def _deployment_sqlite_health(
    conn: Any,
    *,
    code_schema_version: int,
    required_tables: tuple[str, ...] = (),
    required_triggers: tuple[str, ...] = (),
) -> dict[str, Any]:
    db_user_version = int(conn.execute("PRAGMA user_version").fetchone()[0])
    integrity = str(conn.execute("PRAGMA integrity_check").fetchone()[0])
    schema_rows = conn.execute(
        "SELECT type,name,tbl_name,COALESCE(sql,'') AS sql "
        "FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' "
        "ORDER BY type,name"
    ).fetchall()
    schema_records = [
        [str(row[0]), str(row[1]), str(row[2]), str(row[3])]
        for row in schema_rows
    ]
    tables = {record[1] for record in schema_records if record[0] == "table"}
    triggers = {record[1] for record in schema_records if record[0] == "trigger"}
    compatible = (
        db_user_version == int(code_schema_version)
        and integrity == "ok"
        and set(required_tables).issubset(tables)
        and set(required_triggers).issubset(triggers)
    )
    return {
        "ok": compatible,
        "code_schema_version": int(code_schema_version),
        "db_user_version": db_user_version,
        "integrity_check": integrity,
        "schema_sha256": hashlib.sha256(
            json.dumps(
                schema_records,
                ensure_ascii=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest(),
        "required_tables": list(required_tables),
        "required_triggers": list(required_triggers),
    }


@router.get("/connector/deployment-health")
def connector_deployment_health(request: Request) -> dict[str, Any]:
    """Prove release identity and every deployment-owned SQLite schema."""

    connector = connector_health(request)
    backend = _backend_api()

    library = _file_library()
    with library.connection() as cloud_conn:
        cloud = _deployment_sqlite_health(
            cloud_conn,
            code_schema_version=backend.CLOUD_FILE_SCHEMA_VERSION,
            required_tables=("account_files", "file_install_intents"),
        )
    mobile_conn = backend.MobileDeviceStore().connect()
    try:
        mobile = _deployment_sqlite_health(
            mobile_conn,
            code_schema_version=backend.MOBILE_DEVICE_SCHEMA_VERSION,
            required_tables=(
                "mobile_devices",
                "mobile_sessions",
                "mobile_account_deletion_outbox",
            ),
        )
    finally:
        mobile_conn.close()
    managed_conn = backend.connect_managed_installations_database(
        backend.managed_installations_db_path()
    )
    try:
        managed = _deployment_sqlite_health(
            managed_conn,
            code_schema_version=backend.MANAGED_INSTALLATIONS_SCHEMA_VERSION,
            required_tables=(
                "managed_installations",
                "managed_installation_targets",
                "managed_resource_catalog",
                "managed_resource_events",
            ),
            required_triggers=("managed_installation_source_lock_immutable",),
        )
        managed["catalog_rows"] = int(
            managed_conn.execute(
                "SELECT COUNT(*) FROM managed_resource_catalog"
            ).fetchone()[0]
        )
    finally:
        managed_conn.close()

    manifest_path = Path(__file__).with_name("manifest.json")
    manifest_bytes = manifest_path.read_bytes()
    manifest = json.loads(manifest_bytes.decode("utf-8"))
    databases = {
        "cloud_files": cloud,
        "mobile_auth": mobile,
        "managed_resources": managed,
    }
    release: dict[str, str] = {}
    evidence_path = Path(
        os.environ.get(
            "HERMES_RELEASE_EVIDENCE_FILE",
            "/var/lib/hermes-agent-release/release-evidence.json",
        )
    )
    if evidence_path.is_file() and not evidence_path.is_symlink():
        try:
            evidence = json.loads(evidence_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError):
            evidence = {}
        if (
            isinstance(evidence, dict)
            and evidence.get("schema") == "hermes.release-evidence.v1"
            and evidence.get("phase") == "committed"
        ):
            commit = str(evidence.get("commit") or "")
            if re.fullmatch(r"[0-9a-f]{40}", commit):
                release = {
                    "commit": commit,
                    "version": str(evidence.get("version") or ""),
                    "manifest_sha256": str(
                        evidence.get("manifest_sha256") or ""
                    ),
                    "deployed_at": str(evidence.get("deployed_at") or ""),
                }
    return {
        **connector,
        "ok": _coerce_flag(connector.get("ok")) and all(
            item.get("ok") is True for item in databases.values()
        ),
        "manifest_version": str(manifest.get("version") or ""),
        "manifest_sha256": hashlib.sha256(manifest_bytes).hexdigest(),
        "managed_catalog_readable": managed.get("catalog_rows") is not None,
        "release": release,
        "databases": databases,
    }


def _connector_run_attachments(
    conversation: dict[str, Any],
    hosted: dict[str, Any],
) -> list[dict[str, Any]]:
    owner_id = str(conversation.get("owner_id") or LOCAL_OWNER_ID)
    account_generation = str(
        hosted.get("account_generation")
        or conversation.get("account_generation")
        or ""
    ).strip()
    if not account_generation:
        return []
    records: list[dict[str, Any]] = []
    for file_id in list(dict.fromkeys(hosted.get("attachment_ids") or []))[:32]:
        record = _file_library().get_file(
            owner_id,
            str(file_id),
            account_generation=account_generation,
        )
        if record is None or record.get("status") != "available":
            continue
        records.append(
            {
                "id": str(record.get("id") or ""),
                "name": str(record.get("name") or "attachment"),
                "sha256": str(record.get("sha256") or ""),
                "mime_type": str(
                    record.get("mime_type") or "application/octet-stream"
                ),
                "size": int(record.get("size") or 0),
                "download_url": (
                    "/connector/runs/"
                    f"{quote(str(hosted.get('turn_id') or ''), safe='')}"
                    f"/attachments/{quote(str(record.get('id') or ''), safe='')}"
                ),
            }
        )
    return records


@router.get("/connector/runs/{remote_run_id}/attachments")
def connector_list_run_attachments(remote_run_id: str, request: Request):
    connector_id = _require_connector(request)
    _rate_limit_connector(request, connector_id, "attachments")
    conversation, hosted, _remote_run = _remote_run_for_connector(
        request,
        remote_run_id,
    )
    attachments = _connector_run_attachments(conversation, hosted)
    for attachment in attachments:
        attachment["download_url"] = (
            f"/connector/runs/{quote(remote_run_id, safe='')}"
            f"/attachments/{quote(str(attachment['id']), safe='')}"
        )
    return {"attachments": attachments}


@router.get("/connector/runs/{remote_run_id}/attachments/{file_id}")
def connector_download_run_attachment(
    remote_run_id: str,
    file_id: str,
    request: Request,
):
    connector_id = _require_connector(request)
    _rate_limit_connector(request, connector_id, "attachment-download")
    conversation, hosted, _remote_run = _remote_run_for_connector(
        request,
        remote_run_id,
    )
    allowed = {
        str(item)
        for item in hosted.get("attachment_ids") or []
        if str(item).startswith("file_")
    }
    if file_id not in allowed:
        raise HTTPException(status_code=404, detail="Attachment not found")
    owner_id = str(conversation.get("owner_id") or LOCAL_OWNER_ID)
    account_generation = str(
        hosted.get("account_generation")
        or conversation.get("account_generation")
        or ""
    ).strip()
    if not account_generation:
        raise HTTPException(status_code=404, detail="Attachment not found")
    try:
        record, path = _file_library().resolve_download(
            owner_id,
            file_id,
            account_generation=account_generation,
        )
    except (KeyError, FileNotFoundError, ValueError) as exc:
        raise HTTPException(status_code=404, detail="Attachment not found") from exc
    _audit_connector(
        connector_id,
        "CONNECTOR_DOWNLOAD",
        remote_run_id=remote_run_id,
        file_id=file_id,
        sha256=str(record.get("sha256") or "")[:64],
    )
    return FileResponse(
        path=str(path),
        filename=str(record["name"]),
        media_type=str(record["mime_type"]),
        headers={
            "Cache-Control": "private, no-store",
            "ETag": f'"{record["sha256"]}"',
            "X-Content-SHA256": str(record["sha256"]),
            "X-Content-Type-Options": "nosniff",
        },
    )


@router.post("/connector/runs/pull")
def connector_pull_runs(payload: ConnectorPullBody, request: Request):
    authenticated = _require_connector(request)
    _rate_limit_connector(request, authenticated, "pull")
    connector_id, limit, lease_seconds = _validate_connector_batch(payload, authenticated)
    now = int(time.time() * 1000)
    lease_until = now + lease_seconds * 1000
    selected: list[dict[str, Any]] = []
    changed_conversation_ids: set[str] = set()
    changed = False
    with _STATE_LOCK:
        state = load_single_state()
        deadline_changes = _advance_remote_run_deadlines(state, now=now)
        if deadline_changes:
            changed_conversation_ids.update(deadline_changes)
            changed = True
        for conversation in state.get("conversations") or []:
            if not isinstance(conversation, dict):
                continue
            for hosted in (conversation.get("hosted_turns") or {}).values():
                if not isinstance(hosted, dict):
                    continue
                for remote_run in (hosted.get("remote_runs") or {}).values():
                    if not isinstance(remote_run, dict):
                        continue
                    profile = str(remote_run.get("profile") or "")
                    if profile not in _REMOTE_RUN_PROFILES:
                        continue
                    if _remote_run_connector_id(remote_run) != connector_id:
                        continue
                    try:
                        _require_connector_account_boundary(conversation, remote_run)
                    except HTTPException as exc:
                        # Deleted generations are immutable. Exclude the work
                        # without trying to mutate its tombstoned conversation.
                        if not (
                            isinstance(exc.detail, dict)
                            and exc.detail.get("reason") == "generation_deleted"
                        ):
                            raise
                        continue
                    status = str(remote_run.get("status") or "queued")
                    old_lease = _nonnegative_int(remote_run.get("lease_until"))
                    reawaken_awaiting = (
                        status == "awaiting_input" and old_lease <= now
                    )
                    if (
                        status not in {"queued", "leased", "running"}
                        and not reawaken_awaiting
                    ):
                        continue
                    if _coerce_flag(remote_run.get("cancel_requested")):
                        continue
                    if status in {"leased", "running"} and old_lease > now:
                        continue
                    remote_run.update(
                        {
                            # A running item must remain visibly running while
                            # the connector renews its lease to poll terminal
                            # Kanban state. Only pre-ack work is marked leased.
                            # An awaiting item whose lease lapsed keeps its
                            # awaiting state: the mobile decision card stays
                            # visible and the answer can still be delivered.
                            "status": (
                                "awaiting_input"
                                if reawaken_awaiting
                                else ("running" if status == "running" else "leased")
                            ),
                            "lease_owner": connector_id,
                            "claim_token": secrets.token_urlsafe(32),
                            "lease_until": lease_until,
                            "updated_at": now,
                        }
                    )
                    selected.append(_remote_run_connector_payload(remote_run))
                    changed_conversation_ids.add(str(conversation.get("id") or ""))
                    changed = True
                    if len(selected) >= limit:
                        break
                if len(selected) >= limit:
                    break
            if len(selected) >= limit:
                break
        if changed:
            save_single_state(state)
    if changed:
        for changed_conversation_id in changed_conversation_ids:
            _notify_hosted_update(changed_conversation_id)
    _audit_connector(
        authenticated,
        "CONNECTOR_PULL",
        count=len(selected),
        remote_run_ids=[str(item.get("remote_run_id") or "") for item in selected][:20],
    )
    return {"runs": selected, "server_time": now}


@router.post("/connector/runs/{remote_run_id}/ack")
def connector_ack_run(remote_run_id: str, payload: ConnectorAckBody, request: Request):
    conversation, hosted, _remote_run = _remote_run_for_connector(request, remote_run_id)
    connector_id = _require_connector(request)
    _rate_limit_connector(request, connector_id, "ack")
    _validate_connector_claim(payload.connector_id, connector_id)
    now = int(time.time() * 1000)
    with _STATE_LOCK:
        state = load_single_state()
        location = _remote_run_location(state, remote_run_id)
        if location is None:
            raise HTTPException(status_code=404, detail="Remote run not found")
        current_conversation, _hosted, _role_key, record = location
        _require_connector_account_boundary(current_conversation, record)
        _require_remote_run_claim(
            record,
            connector_id=connector_id,
            claim_token=payload.claim_token,
            now=now,
        )
        expected_key = str(record.get("idempotency_key") or "")
        supplied_key = str(payload.idempotency_key or "")
        if supplied_key and supplied_key != expected_key:
            raise _connector_conflict(
                "claim_lost",
                "Remote run idempotency key does not match the active claim",
            )
        supplied_task = str(payload.remote_task_id or "").strip()
        existing_task = str(record.get("remote_task_id") or "").strip()
        if supplied_task and existing_task and supplied_task != existing_task:
            raise _connector_conflict(
                "claim_lost",
                "Remote task does not match the active claim",
            )
        if str(record.get("status") or "") in _REMOTE_TERMINAL_STATUSES:
            return {"run": _remote_run_connector_payload(record), "applied": False}
        record.update(
            {
                "status": "running",
                "started_at": _nonnegative_int(record.get("started_at"), now) or now,
                "updated_at": now,
                "lease_owner": connector_id,
                "lease_until": now + max(5, min(int(payload.lease_seconds or _REMOTE_RUN_LEASE_SECONDS), 900)) * 1000,
            }
        )
        for key in ("remote_task_id", "root_task_id", "session_id"):
            value = str(getattr(payload, key) or "").strip()
            if value:
                record[key] = value[:512]
        save_single_state(state)
        persisted = dict(record)
    _notify_hosted_update(str(conversation.get("id") or ""))
    _remote_run_state_message(
        str(conversation.get("id") or ""),
        str(hosted.get("turn_id") or ""),
        persisted,
        role_label=f"{persisted.get('profile') or 'worker'} · 执行",
    )
    _audit_connector(
        connector_id,
        "CONNECTOR_ACK",
        remote_run_id=remote_run_id,
        root_task_id=str(payload.root_task_id or "")[:256],
    )
    return {"run": _remote_run_connector_payload(persisted), "applied": True}


