@router.post("/connector/cancellations/pull")
def connector_pull_cancellations(payload: ConnectorPullBody, request: Request):
    authenticated = _require_connector(request)
    _rate_limit_connector(request, authenticated, "cancellations/pull")
    connector_id, limit, lease_seconds = _validate_connector_batch(payload, authenticated)
    now = int(time.time() * 1000)
    selected: list[dict[str, Any]] = []
    changed_conversation_ids: set[str] = set()
    changed = False
    with _STATE_LOCK:
        state = load_single_state()
        deadline_changes = _advance_remote_run_deadlines(state, now=now)
        if deadline_changes:
            changed_conversation_ids.update(deadline_changes)
            changed = True
        for conversation in state.get("conversations") or []:
            if not isinstance(conversation, dict):
                continue
            for hosted in (conversation.get("hosted_turns") or {}).values():
                if not isinstance(hosted, dict):
                    continue
                for remote_run in (hosted.get("remote_runs") or {}).values():
                    if not isinstance(remote_run, dict) or str(remote_run.get("status") or "") in _REMOTE_TERMINAL_STATUSES:
                        continue
                    if not (
                        _coerce_flag(hosted.get("cancel_requested"))
                        or _coerce_flag(remote_run.get("cancel_requested"))
                    ):
                        continue
                    if _remote_run_connector_id(remote_run) != connector_id:
                        continue
                    try:
                        _require_connector_account_boundary(conversation, remote_run)
                    except HTTPException as exc:
                        if not (
                            isinstance(exc.detail, dict)
                            and exc.detail.get("reason") == "generation_deleted"
                        ):
                            raise
                        continue
                    old_lease = _nonnegative_int(remote_run.get("cancel_lease_until"))
                    if old_lease > now:
                        continue
                    claim_token = secrets.token_urlsafe(32)
                    remote_run["cancel_lease_owner"] = connector_id
                    remote_run["cancel_lease_until"] = now + lease_seconds * 1000
                    # Cancellation becomes the sole mutation owner and
                    # invalidates the execution worker's previous claim.
                    remote_run["lease_owner"] = connector_id
                    remote_run["lease_until"] = now + lease_seconds * 1000
                    remote_run["claim_token"] = claim_token
                    remote_run["status"] = "cancelling"
                    remote_run["updated_at"] = now
                    changed_conversation_ids.add(str(conversation.get("id") or ""))
                    selected.append(
                        {
                            "remote_run_id": remote_run.get("id"),
                            "remote_task_id": remote_run.get("remote_task_id", ""),
                            "root_task_id": remote_run.get("root_task_id", ""),
                            "checkpoint_cursor": _nonnegative_int(
                                remote_run.get("checkpoint_cursor")
                            ),
                            "claim_token": claim_token,
                            "reason": (
                                remote_run.get("cancel_reason")
                                or hosted.get("cancel_reason")
                                or "用户取消"
                            ),
                            "requested_at": (
                                remote_run.get("cancel_requested_at")
                                or hosted.get("cancel_requested_at")
                                or now
                            ),
                            "kind": str(remote_run.get("cancel_kind") or "turn"),
                            "intervention_id": str(
                                remote_run.get("cancel_intervention_id") or ""
                            ),
                        }
                    )
                    changed = True
                    if len(selected) >= limit:
                        break
                if len(selected) >= limit:
                    break
            if len(selected) >= limit:
                break
        if changed:
            save_single_state(state)
    if changed:
        for changed_conversation_id in changed_conversation_ids:
            _notify_hosted_update(changed_conversation_id)
    _audit_connector(
        authenticated,
        "CONNECTOR_CANCEL",
        count=len(selected),
        remote_run_ids=[str(item.get("remote_run_id") or "") for item in selected][:20],
    )
    return {"cancellations": selected, "server_time": now}


@router.post("/connector/runs/{remote_run_id}/cancel-ack")
def connector_cancel_ack(remote_run_id: str, payload: ConnectorCancelAckBody, request: Request):
    connector_id = _require_connector(request)
