@router.post("/single/conversations/{conversation_id}/attachments")
async def upload_conversation_attachment(
    conversation_id: str,
    request: Request,
):
    owner_id, conversation = _owned_conversation(request, conversation_id)
    account_generation = _account_generation_for_request(request, owner_id)
    try:
        filename = safe_attachment_name(
            unquote(request.headers.get("x-filename", ""))
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    upload_id = str(request.headers.get("x-upload-id") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9._:-]{8,256}", upload_id):
        raise HTTPException(status_code=422, detail="Invalid X-Upload-ID")
    expected_bytes, expected_sha = _attachment_upload_contract(request)
    uploads_dir = _conversation_file_dir(conversation_id, "uploads")
    total = 0
    origin_key = f"conversation-upload:{conversation_id}:{upload_id}"
    temp = uploads_dir / f".{filename}.{uuid.uuid4().hex}.upload"
    try:
        with temp.open("wb") as handle:
            async for chunk in request.stream():
                if not chunk:
                    continue
                total += len(chunk)
                if total > _MAX_ATTACHMENT_BYTES:
                    raise HTTPException(status_code=413, detail="附件不能超过 64 MB")
                handle.write(chunk)
        if expected_bytes is not None and total != expected_bytes:
            raise HTTPException(status_code=400, detail="Content-Length does not match request body")
        actual_sha = _sha256_path(temp)
        if expected_sha and actual_sha != expected_sha:
            raise HTTPException(status_code=422, detail="X-Content-SHA256 does not match request body")
        existing = _file_library().get_file_by_origin(
            owner_id,
            origin_key,
            account_generation=account_generation,
        )
        if (
            existing is not None
            and existing.get("status") == "available"
            and str(existing.get("sha256") or "") != actual_sha
        ):
            raise HTTPException(
                status_code=409,
                detail="X-Upload-ID was already used with different content",
            )
        record = _file_library().ingest_file(
            owner_id,
            temp,
            account_generation=account_generation,
            name=filename,
            source="user_upload",
            conversation_id=conversation_id,
            message_id=request.headers.get("x-message-id", ""),
            turn_id=request.headers.get("x-turn-id", ""),
            profile=request.headers.get("x-profile", "")
            or str(conversation.get("profile") or ""),
            origin_key=origin_key,
            mime_type=request.headers.get("content-type", ""),
            allowed_roots=[uploads_dir],
        )
    except (FileExistsError, BlockingIOError) as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except PermissionError as exc:
        raise HTTPException(status_code=410, detail="Account was deleted") from exc
    finally:
        temp.unlink(missing_ok=True)
    return {"attachment": _library_attachment(record)}


@router.get(
    "/single/conversations/{conversation_id}/attachments/"
    "{bucket}/{relative_path:path}"
)
def download_conversation_attachment(
    conversation_id: str,
    bucket: str,
    relative_path: str,
    request: Request,
    preview: bool = False,
):
    _owned_conversation(request, conversation_id)
    root = _conversation_file_dir(conversation_id, bucket).resolve()
    target = (root / relative_path).resolve()
    if not target.is_relative_to(root):
        raise HTTPException(status_code=403, detail="附件路径越界")
    if not target.is_file():
        raise HTTPException(status_code=404, detail="附件不存在")
    digest = _sha256_path(target)
    return FileResponse(
        path=str(target),
        filename=target.name,
        media_type=mimetypes.guess_type(target.name)[0]
        or "application/octet-stream",
        content_disposition_type="inline" if preview else "attachment",
        headers={
            "Cache-Control": "private, no-store",
            "ETag": f'"{digest}"',
            "X-Content-SHA256": digest,
            "X-Content-Type-Options": "nosniff",
        },
    )


@router.post("/single/conversations/{conversation_id}/record")
def record_single_message(
    conversation_id: str,
    payload: RecordMessageBody,
    request: Request = None,
):
    if not payload.content.strip():
        raise HTTPException(status_code=400, detail="消息不能为空")
    with _STATE_LOCK:
        state = load_single_state()
        conversation, _claimed = _owned_conversation_in_state(
            state,
            conversation_id,
            owner_id_from_request(request),
        )
        runtime_session_id = str(
            payload.meta.get("runtime_session_id") or ""
        ).strip()
        runtime_turn_id = str(
            payload.meta.get("runtime_turn_id") or ""
        ).strip()
        message = None
        if payload.role == "assistant" and (runtime_turn_id or runtime_session_id):
            message = next(
                (
                    item
                    for item in conversation.get("messages") or []
                    if isinstance(item.get("meta"), dict)
                    and (
                        item["meta"].get("runtime_turn_id") == runtime_turn_id
                        if runtime_turn_id
                        else item["meta"].get("runtime_session_id")
                        == runtime_session_id
                    )
                ),
                None,
            )
        if message is None:
            message = _append_message(
                conversation,
                role=payload.role,
                name=payload.name,
                content=payload.content.strip(),
                status=payload.status,
                kind=payload.kind,
                meta=payload.meta,
            )
        else:
            message.update(
                {
                    "role": payload.role,
                    "name": payload.name,
                    "content": payload.content.strip(),
                    "status": payload.status,
                    "kind": payload.kind,
                    "meta": {**message.get("meta", {}), **payload.meta},
                    "created_at": int(time.time() * 1000),
                }
            )
            conversation["updated_at"] = message["created_at"]
        if runtime_session_id:
            for run in (conversation.get("runtime_runs") or {}).values():
                same_turn = (
                    run.get("turn_id") == runtime_turn_id
                    if runtime_turn_id
                    else run.get("session_id") == runtime_session_id
                )
                if same_turn:
                    run["status"] = "completed"
                    run["completed_at"] = message["created_at"]
                    run["updated_at"] = message["created_at"]
        if (
            payload.role == "user"
            and conversation.get("title") in {"", "新对话", None}
        ):
            conversation["title"] = summarize_task_title(payload.content)
        save_single_state(state)
        owner_id = str(conversation.get("owner_id") or "").strip()
        account_generation = _account_generation_for_conversation(conversation)
        profile = str(conversation.get("profile") or payload.name or "").strip()
        attachment_ids = _attachment_file_ids(message.get("meta"))
    if owner_id and attachment_ids:
        _file_library().update_links(
            owner_id,
            attachment_ids,
            account_generation=account_generation,
            conversation_id=conversation_id,
            message_id=str(message.get("id") or ""),
            turn_id=runtime_turn_id,
            profile=profile,
        )
    return {"message": message}


@router.post("/single/conversations/{conversation_id}/runtime-session")
def save_runtime_session(
    conversation_id: str,
    payload: RuntimeSessionBody,
    request: Request = None,
):
    with _STATE_LOCK:
        state = load_single_state()
        conversation, _claimed = _owned_conversation_in_state(
            state,
            conversation_id,
            owner_id_from_request(request),
        )
        if payload.status == "running":
            try:
                baseline_message_count = len(
                    _load_runtime_messages(payload.profile, payload.session_id)
                )
            except Exception:
                baseline_message_count = 0
            mark_conversation_runtime_run(
                conversation,
                payload.profile,
                payload.session_id,
                turn_id=payload.turn_id,
                baseline_message_count=baseline_message_count,
            )
        else:
            set_conversation_runtime_session(
                conversation,
                payload.profile,
                payload.session_id,
            )
        runtime_sessions = conversation.get("runtime_sessions") or {}
        save_single_state(state)
    return {"runtime_sessions": runtime_sessions}


def _hosted_event_stream_frame(
    conversation: dict[str, Any],
    *,
    delivered_cursor: int,
    include_snapshot: bool,
    limit: int = 500,
) -> tuple[dict[str, Any], bool]:
    page = hosted_event_page(conversation, delivered_cursor, limit=limit)
    current_cursor = page.next_cursor
    envelope: dict[str, Any] = {
        "cursor": current_cursor,
        "min_cursor": page.min_cursor,
        "has_gap": page.has_gap,
        "reset_cursor": page.reset_cursor,
        "reset_reason": page.reset_reason,
        "events": page.events,
        "snapshot_cursor": max(0, int(conversation.get("event_cursor") or 0)),
        "account_generation": _hosted_event_account_generation(conversation),
    }
    if (
        include_snapshot
        or page.has_gap
        or not page.events
    ):
        envelope["conversation"] = _public_conversation(conversation)
    has_more = current_cursor < max(
        0,
        int(conversation.get("hosted_event_cursor") or 0),
    )
    return envelope, has_more


def _live_hosted_event_stream_frame(
    conversation_id: str,
    owner_id: str,
    *,
    delivered_cursor: int,
    include_snapshot: bool,
    limit: int = 500,
) -> Optional[tuple[dict[str, Any], bool]]:
    """Build an SSE frame without contending on the durable state lock."""

    conversation = _live_conversation_snapshot(conversation_id, owner_id)
    if conversation is None:
        return None
    return _hosted_event_stream_frame(
        conversation,
        delivered_cursor=delivered_cursor,
        include_snapshot=include_snapshot,
        limit=limit,
    )


@router.get("/single/conversations/{conversation_id}/hosted-events")
async def stream_hosted_conversation_events(
    conversation_id: str,
    request: Request,
):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    expected_account_generation = str(
        request.query_params.get("expected_account_generation") or ""
    ).strip()
    if (
        expected_account_generation
        and expected_account_generation != account_generation
    ):
        raise HTTPException(
            status_code=409,
            detail="hosted event account generation changed",
        )
    cursor_value = request.query_params.get("cursor") or request.headers.get(
        "last-event-id",
        "0",
    )
    try:
        requested_cursor = max(0, int(cursor_value or 0))
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=422, detail="cursor must be a non-negative integer") from exc
    # The live projection already proves ownership for an active conversation.
    # Avoid taking the account-state lock on every reconnect: the durable JSON
    # may be undergoing a large checkpoint while the SSE headers need to leave
    # immediately. Missing/stale projections still use the authoritative
    # ownership check below.
    live_conversation = _live_conversation_snapshot(conversation_id, owner_id)
    live_generation = str(
        (live_conversation or {}).get("account_generation") or ""
    ).strip()
    if (
        live_conversation is not None
        and live_generation
        and live_generation != account_generation
    ):
        raise HTTPException(status_code=404, detail="Conversation not found")
    if live_conversation is None:
        with _STATE_LOCK:
            state = load_single_state()
            _conversation, claimed = _owned_conversation_in_state(
                state,
                conversation_id,
                owner_id,
            )
            if claimed:
                save_single_state(state)

    async def event_stream():
        revision = _hosted_update_revision(conversation_id)
        delivered_cursor = requested_cursor
        # Reconnects from the iOS client usually carry the current event
        # cursor.  Prefer the immutable in-memory projection so a large
        # account JSON rewrite cannot delay response headers or the first
        # live delta.  A full snapshot remains mandatory for cursor zero and
        # gap recovery.
        live_conversation = _live_conversation_snapshot(conversation_id, owner_id)
        if live_conversation is not None:
            conversation = live_conversation
            envelope, has_more_events = _hosted_event_stream_frame(
                conversation,
                delivered_cursor=delivered_cursor,
                include_snapshot=delivered_cursor <= 0,
                limit=500,
            )
        else:
            with _STATE_LOCK:
                state = _load_single_state_for_event_stream()
                conversation, _claimed = _owned_conversation_in_state(
                    state,
                    conversation_id,
                    owner_id,
                )
                envelope, has_more_events = _hosted_event_stream_frame(
                    conversation,
                    delivered_cursor=delivered_cursor,
                    include_snapshot=delivered_cursor <= 0,
                    limit=500,
                )
        if (
            delivered_cursor > 0
            and not envelope.get("events")
            and not envelope.get("has_gap")
            and not has_more_events
        ):
            # A reconnect that is already caught up only needs a flushed
            # comment. State-only revisions later in this stream still use
            # the authoritative snapshot branch below.
            envelope.pop("conversation", None)
        while True:
            current_cursor = int(envelope["cursor"])
            if envelope.get("conversation") is not None or envelope.get("events"):
                yield (
                    f"id: {current_cursor}\n"
                    "event: conversation\n"
                    f"data: {json.dumps(envelope, ensure_ascii=False, separators=(',', ':'))}\n\n"
                )
            else:
                # Do not send an empty JSON envelope: the native parser quite
                # correctly treats that as malformed.  A comment flushes the
                # response and keeps the SSE connection alive without
                # serializing a redundant full snapshot.
                yield ": connected\n\n"
            delivered_cursor = current_cursor
            if has_more_events:
                live_frame = _live_hosted_event_stream_frame(
                    conversation_id,
                    owner_id,
                    delivered_cursor=delivered_cursor,
                    include_snapshot=False,
                    limit=500,
                )
                if live_frame is not None:
                    envelope, has_more_events = live_frame
                else:
                    with _STATE_LOCK:
                        state = _load_single_state_for_event_stream()
                        conversation, _claimed = _owned_conversation_in_state(
                            state,
                            conversation_id,
                            owner_id,
                        )
                        envelope, has_more_events = _hosted_event_stream_frame(
                            conversation,
                            delivered_cursor=delivered_cursor,
                            include_snapshot=False,
                            limit=500,
                        )
                continue
            break

        while not await request.is_disconnected():
            next_revision = await asyncio.to_thread(
                _wait_for_hosted_update,
                revision,
                15.0,
                conversation_id,
            )
            if next_revision == revision:
                yield ": keepalive\n\n"
                continue
            revision = next_revision
            live_frame = _live_hosted_event_stream_frame(
                conversation_id,
                owner_id,
                delivered_cursor=delivered_cursor,
                # Live token/tool/reasoning batches are event-only. State-only
                # updates and terminal boundaries still receive an
                # authoritative snapshot in _hosted_event_stream_frame.
                include_snapshot=False,
                limit=500,
            )
            if live_frame is not None:
                envelope, has_more_events = live_frame
            else:
                with _STATE_LOCK:
                    state = _load_single_state_for_event_stream()
                    conversation, _claimed = _owned_conversation_in_state(
                        state,
                        conversation_id,
                        owner_id,
                    )
                    envelope, has_more_events = _hosted_event_stream_frame(
                        conversation,
                        delivered_cursor=delivered_cursor,
                        include_snapshot=False,
                        limit=500,
                    )
            current_cursor = int(envelope["cursor"])
            payload = json.dumps(
                envelope,
                ensure_ascii=False,
                separators=(",", ":"),
            )
            yield (
                f"id: {current_cursor}\n"
                "event: conversation\n"
                f"data: {payload}\n\n"
            )
            delivered_cursor = current_cursor
            while has_more_events:
                live_frame = _live_hosted_event_stream_frame(
                    conversation_id,
                    owner_id,
                    delivered_cursor=delivered_cursor,
                    include_snapshot=False,
                    limit=500,
                )
                if live_frame is not None:
                    envelope, has_more_events = live_frame
                else:
                    with _STATE_LOCK:
                        state = _load_single_state_for_event_stream()
                        conversation, _claimed = _owned_conversation_in_state(
                            state,
                            conversation_id,
                            owner_id,
                        )
                        envelope, has_more_events = _hosted_event_stream_frame(
                            conversation,
                            delivered_cursor=delivered_cursor,
                            include_snapshot=False,
                            limit=500,
                        )
                current_cursor = int(envelope["cursor"])
                payload = json.dumps(
                    envelope,
                    ensure_ascii=False,
                    separators=(",", ":"),
                )
                yield (
                    f"id: {current_cursor}\n"
                    "event: conversation\n"
                    f"data: {payload}\n\n"
                )
                delivered_cursor = current_cursor

    async def presence_tracked_stream():
        # Track watcher presence so the APNs dispatcher suppresses pushes
        # while the user watches live and fires them the moment the app
        # leaves (background exit → instant completion notification).
        _sse_presence_enter(conversation_id)
        try:
            async for frame in event_stream():
                yield frame
        finally:
            _sse_presence_leave(conversation_id)

    return StreamingResponse(
        presence_tracked_stream(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache, no-transform",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )


@router.get("/single/conversations/{conversation_id}/session-entries")
def list_conversation_session_entries(
    conversation_id: str,
    request: Request,
    cursor: int = 0,
    limit: int = 500,
):
    owner_id = owner_id_from_request(request)
    if cursor < 0:
        raise HTTPException(status_code=422, detail="cursor must be non-negative")
    if limit < 1 or limit > 2_000:
        raise HTTPException(status_code=422, detail="limit must be between 1 and 2000")
    with _STATE_LOCK:
        state = load_single_state()
        conversation, claimed = _owned_conversation_in_state(
            state,
            conversation_id,
            owner_id,
        )
        conversation = _hydrate_conversation_history(conversation)
        if claimed:
            save_single_state(state)
        authoritative_cursor = max(
            0, int(conversation.get("session_entry_cursor") or 0)
        )
        reset_cursor = cursor > authoritative_cursor
        entries = (
            []
            if reset_cursor
            else entries_after(conversation, cursor, limit=limit)
        )
        next_cursor = (
            authoritative_cursor
            if reset_cursor
            else int(entries[-1].get("cursor") or cursor)
            if entries
            else authoritative_cursor
        )
        return {
            "schema_version": "hermes.session-entry.v1",
            "account_generation": _account_generation_for_owner(owner_id),
            "cursor": next_cursor,
            "reset_cursor": reset_cursor,
            "reset_reason": "future_cursor" if reset_cursor else "",
            "leaf_entry_id": str(conversation.get("session_entry_leaf_id") or ""),
            "entries": entries,
        }


def _hosted_route_parameters(
    *,
    route_metadata: Any,
    content: str = "",
    requested_mode: str = "",
    requested_profiles: Optional[list[str]] = None,
    requested_artifact: bool = False,
) -> tuple[dict[str, Any], str, list[str], bool]:
    route = dict(route_metadata) if isinstance(route_metadata, dict) else {}
    mode = str(requested_mode or route.get("mode") or "work").strip().lower()
    if mode not in {"chat", "work"}:
        raise HTTPException(status_code=400, detail="mode must be chat or work")
    selected_profiles = list(requested_profiles or route.get("profiles") or [])
    if mode == "chat":
        selected_profile = next(
            (str(item).strip() for item in selected_profiles if str(item).strip()),
            "default",
        )
        known_profiles = {str(item.get("name") or "") for item in available_profiles()}
        if selected_profile not in known_profiles:
            raise HTTPException(status_code=400, detail="Hermes Profile does not exist")
        selected_profiles = [selected_profile]
        route["profiles"] = selected_profiles
    else:
        requested_workers = [
            profile
            for profile in selected_profiles
            if collaboration_role(profile) == "worker"
        ]
        worker_profiles, constraints = _constrained_worker_profiles(
            content,
            profiles=requested_workers,
            targets=[str(item).lower() for item in route.get("targets") or []],
        )
        if not worker_profiles:
            raise HTTPException(
                status_code=422,
                detail="No eligible worker target remains after applying placement constraints",
            )
        route["target_constraints"] = constraints
        route["targets"] = [
            profile.removesuffix("-worker") for profile in worker_profiles
        ]
        route["profiles"] = ["default", *worker_profiles, "reviewer"]
        selected_profiles = list(
            dict.fromkeys(["default", *worker_profiles, "reviewer"])
        )
    artifact = route.get("artifact")
    artifact = dict(artifact) if isinstance(artifact, dict) else {}
    artifact_required = (
        _coerce_flag(requested_artifact)
        or _coerce_flag(route.get("artifact_required"))
        or str(artifact.get("decision") or "").lower() == "required"
    )
    return route, mode, selected_profiles, artifact_required


def _enqueue_payload_fingerprint(
    payload: EnqueueHostedTurnBody,
    *,
    message_content: str,
) -> str:
    canonical = {
        "turn_id": payload.turn_id.strip(),
        "message": payload.message,
        "message_content": message_content,
        "recent_messages": payload.recent_messages,
        "attachment_ids": list(dict.fromkeys(payload.attachment_ids)),
        "attachment_context": payload.attachment_context,
        "delivery_context": payload.delivery_context,
        "create_conversation_if_missing": bool(
            getattr(payload, "create_conversation_if_missing", False)
        ),
        "conversation_profile": str(
            getattr(payload, "conversation_profile", "") or ""
        ).strip(),
        "conversation_title": str(
            getattr(payload, "conversation_title", "") or ""
        ).strip(),
        "required_provider": str(
            getattr(payload, "required_provider", "") or ""
        ).strip(),
        "required_model": str(
            getattr(payload, "required_model", "") or ""
        ).strip(),
    }
    return hashlib.sha256(
        json.dumps(
            canonical,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _required_runtime_binding(
    profile: str,
    *,
    required_provider: str,
    required_model: str,
) -> dict[str, Any]:
    required_provider = str(required_provider or "").strip()
    required_model = str(required_model or "").strip()
    if bool(required_provider) != bool(required_model):
        raise HTTPException(
            status_code=422,
            detail="required_provider and required_model must be supplied together",
        )
    record = next(
        (
            item
            for item in available_profiles()
            if str(item.get("name") or "").strip() == profile
        ),
        None,
    )
    if record is None:
        raise HTTPException(status_code=400, detail="Hermes Profile does not exist")
    actual_provider = str(record.get("provider") or "").strip()
    actual_model = str(record.get("model") or "").strip()
    verified = bool(required_provider and required_model)
    if verified and (
        actual_provider.casefold() != required_provider.casefold()
        or actual_model.casefold() != required_model.casefold()
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Behavior evaluation runtime mismatch: "
                f"profile {profile!r} resolves to {actual_provider}/{actual_model}, "
                f"not {required_provider}/{required_model}"
            ),
        )
    return {
        "profile": profile,
        "provider": actual_provider,
        "model": actual_model,
        "verified": verified,
    }


def _enqueued_turn_response(
    conversation: dict[str, Any],
    request_record: dict[str, Any],
    *,
    replayed: bool,
) -> dict[str, Any]:
    messages = [
        item
        for item in conversation.get("messages") or []
        if isinstance(item, dict)
    ]
    message_id = str(request_record.get("message_id") or "")
    route_message_id = str(request_record.get("route_message_id") or "")
    user_message = next(
        (item for item in messages if str(item.get("id") or "") == message_id),
        {},
    )
    route_message = next(
        (
            item
            for item in messages
            if str(item.get("id") or "") == route_message_id
        ),
        {},
    )
    turn_id = str(request_record.get("turn_id") or "")
    hosted = (conversation.get("hosted_turns") or {}).get(turn_id)
    if not isinstance(hosted, dict):
        hosted = {}
    error = None
    if str(hosted.get("status") or "") == "failed" and hosted.get("error"):
        error = {
            "code": str(hosted.get("error_code") or "hosted_turn_failed"),
            "message": str(hosted.get("error") or "Hermes 执行失败"),
            "retryable": _coerce_flag(hosted.get("retryable")),
        }
    return {
        "accepted": _coerce_flag(request_record.get("accepted", True), default=True),
        "replayed": replayed,
        "request_id": str(request_record.get("request_id") or ""),
        "conversation_id": str(conversation.get("id") or ""),
        "message": user_message,
        "route": dict(request_record.get("route") or {}),
        "route_message": route_message or None,
        "hosted_turn": _public_hosted_turn(hosted),
        "error": error,
    }


def _complete_pending_hosted_route(conversation_id: str, turn_id: str) -> bool:
    """Claim and resolve one durable route-outbox item."""

    claim_token = uuid.uuid4().hex
    now = int(time.time() * 1000)
    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        outbox = conversation.get("route_outbox")
        item = outbox.get(turn_id) if isinstance(outbox, dict) else None
        if not isinstance(run, dict) or not isinstance(item, dict):
            return False
        if run.get("status") in _HOSTED_TERMINAL_STATUSES:
            outbox.pop(turn_id, None)
            save_single_state(state)
            return False
        live_generation = _account_generation_for_owner(
            str(conversation.get("owner_id") or LOCAL_OWNER_ID)
        )
        if str(item.get("account_generation") or "") != live_generation:
            return False
        if (
            str(item.get("state") or "pending") == "inflight"
            and int(item.get("lease_expires_at") or 0) > now
        ):
            return False
        item.update(
            {
                "state": "inflight",
                "claim_token": claim_token,
                "lease_expires_at": now + 60_000,
                "attempt": int(item.get("attempt") or 0) + 1,
                "updated_at": now,
            }
        )
        save_single_state(state)
        item_snapshot = deepcopy(item)

    try:
        route = route_message(
            RouteMessageBody(
                content=str(item_snapshot.get("content") or ""),
                mode="auto",
                recent_messages=[
                    dict(value)
                    for value in item_snapshot.get("recent_messages") or []
                    if isinstance(value, dict)
                ],
                attachments=[
                    dict(value)
                    for value in item_snapshot.get("attachments") or []
                    if isinstance(value, dict)
                ],
            )
        )
        route, mode, selected_profiles, artifact_required = _hosted_route_parameters(
            route_metadata=route,
            content=str(item_snapshot.get("content") or ""),
            requested_mode=str(route.get("mode") or ""),
            requested_profiles=(
                [str(item_snapshot.get("conversation_profile") or "default")]
                if str(route.get("mode") or "").strip().lower() == "chat"
                else list(route.get("profiles") or [])
            ),
            requested_artifact=_coerce_flag(route.get("artifact_required")),
        )
    except Exception as exc:
        clean_error = sanitize_runtime_error(exc)
        with _STATE_LOCK:
            state = load_single_state()
            conversation = _conversation_by_id(state, conversation_id)
            run = (conversation.get("hosted_turns") or {}).get(turn_id)
            outbox = conversation.get("route_outbox")
            item = outbox.get(turn_id) if isinstance(outbox, dict) else None
            if (
                isinstance(run, dict)
                and isinstance(item, dict)
                and hmac.compare_digest(
                    str(item.get("claim_token") or ""), claim_token
                )
            ):
                failed_at = int(time.time() * 1000)
                item.update(
                    {
                        "state": "retryable",
                        "last_error": clean_error,
                        "next_attempt_at": failed_at + min(
                            30_000, 1_000 * (2 ** min(5, int(item.get("attempt") or 1)))
                        ),
                        "lease_expires_at": 0,
                        "updated_at": failed_at,
                    }
                )
                run.update(
                    {
                        "stage": "routing_failed",
                        "routing_error": clean_error,
                        "retryable": True,
                        "updated_at": failed_at,
                    }
                )
                save_single_state(state)
        _notify_hosted_update(conversation_id)
        return False

    output_dir = _hosted_turn_output_dir(conversation_id, turn_id).resolve()
    prewarm_started = False
    user_delivery_context = str(item_snapshot.get("delivery_context") or "").strip()
    delivery_context = user_delivery_context
    if artifact_required:
        delivery_context = "\n".join(
            value
            for value in (
                delivery_context,
                f"Absolute output directory: `{output_dir}`.",
                "Write every generated deliverable to this exact directory, but mention only file names in user-facing text.",
            )
            if value
        )

    with _STATE_LOCK:
        state = load_single_state()
        conversation = _conversation_by_id(state, conversation_id)
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        outbox = conversation.get("route_outbox")
        item = outbox.get(turn_id) if isinstance(outbox, dict) else None
        if (
            not isinstance(run, dict)
            or not isinstance(item, dict)
            or not hmac.compare_digest(str(item.get("claim_token") or ""), claim_token)
            or run.get("status") in _HOSTED_TERMINAL_STATUSES
        ):
            return False
        completed_at = int(time.time() * 1000)
        route_message_id = str(item.get("route_message_id") or "")
        messages = conversation.setdefault("messages", [])
        if not any(
            isinstance(message, dict)
            and str(message.get("id") or "") == route_message_id
            for message in messages
        ):
            route_record = _append_message(
                conversation,
                role="system",
                name=str(route.get("label") or "任务路由"),
                content=str(route.get("reason") or "已完成任务路由。"),
                status="completed",
                kind="route",
                meta={
                    "artifact_required": artifact_required,
                    "confidence": route.get("confidence"),
                    "lock_level": route.get("lock_level"),
                    "mode": mode,
                    "profiles": selected_profiles,
                    "source": route.get("source"),
                    "runtime_turn_id": turn_id,
                },
            )
            route_record["id"] = route_message_id
            _project_native_message(route_record)
        run.update(
            {
                "status": "queued",
                "stage": "accepted",
                "title": str(route.get("title") or "").strip()
                or summarize_task_title(str(run.get("content") or "")),
                "profiles": selected_profiles,
                "artifact_required": artifact_required,
                "artifact_producer_profiles": _artifact_producer_profiles(
                    route, selected_profiles, required=artifact_required
                ),
                "artifact": dict(route.get("artifact") or {}),
                "mode": mode,
                "route_metadata": route,
                "delivery_context": delivery_context,
                "user_delivery_context": user_delivery_context,
                "output_dir": str(output_dir),
                "routing_completed_at": completed_at,
                "retryable": False,
                "routing_error": "",
                "updated_at": completed_at,
            }
        )
        if mode == "work":
            append_hosted_event(
                conversation,
                conversation_id=conversation_id,
                turn_id=turn_id,
                role_stage="manager",
                event_type="role.handoff",
                entity_id=f"{turn_id}:collaboration-lift",
                idempotency_key=f"turn:{turn_id}:collaboration-lift",
                account_generation=str(run.get("account_generation") or ""),
                payload={
                    "entity_id": f"{turn_id}:collaboration-lift",
                    "action": "collaboration_lift",
                    "from_role": "chat",
                    "to_role": "manager",
                },
                occurred_at=completed_at,
            )
        request_id = str(item.get("request_id") or "")
        request_record = (conversation.get("enqueue_requests") or {}).get(request_id)
        if isinstance(request_record, dict):
            request_record.update(
                {
                    "route": route,
                    "route_message_id": route_message_id,
                    "routing_state": "completed",
                    "routing_completed_at": completed_at,
                }
            )
        outbox.pop(turn_id, None)
        if not outbox:
            conversation.pop("route_outbox", None)
        conversation["updated_at"] = completed_at
        save_single_state(state)
    _notify_hosted_update(conversation_id)
    start_hosted_workflow(conversation_id, turn_id)
    return True


def start_hosted_routing(conversation_id: str, turn_id: str) -> threading.Thread:
    key = f"{conversation_id}:{turn_id}"
    with _HOSTED_ROUTING_THREADS_LOCK:
        existing = _HOSTED_ROUTING_THREADS.get(key)
        if existing is not None and existing.is_alive():
            return existing

        def run_and_release() -> None:
            try:
                for _ in range(5):
                    if _complete_pending_hosted_route(conversation_id, turn_id):
                        return
                    with _STATE_LOCK:
                        state = load_single_state()
                        conversation = _conversation_by_id(state, conversation_id)
                        item = (conversation.get("route_outbox") or {}).get(turn_id)
                        run = (conversation.get("hosted_turns") or {}).get(turn_id)
                        if (
                            not isinstance(item, dict)
                            or not isinstance(run, dict)
                            or run.get("status") in _HOSTED_TERMINAL_STATUSES
                            or str(item.get("state") or "") != "retryable"
                        ):
                            return
                        delay = max(
                            0.0,
                            (int(item.get("next_attempt_at") or 0) - int(time.time() * 1000))
                            / 1000,
                        )
                    time.sleep(min(30.0, delay))
            finally:
                with _HOSTED_ROUTING_THREADS_LOCK:
                    _HOSTED_ROUTING_THREADS.pop(key, None)

        thread = threading.Thread(
            target=run_and_release,
            name=f"hermes-route-{turn_id[-12:]}",
            daemon=True,
        )
        _HOSTED_ROUTING_THREADS[key] = thread
        thread.start()
        return thread


@router.post("/single/conversations/{conversation_id}/enqueue", status_code=202)
def enqueue_hosted_turn(
    conversation_id: str,
    payload: EnqueueHostedTurnBody,
    request: Request,
):
    try:
        conversation_id = _safe_conversation_id(conversation_id)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    request_id = payload.request_id.strip()[:256]
    turn_id = payload.turn_id.strip()[:256]
    if not request_id:
        raise HTTPException(status_code=400, detail="request_id is required")
    if not turn_id:
        raise HTTPException(status_code=400, detail="turn_id is required")
    message_source = dict(payload.message or {})
    original_message_content = _message_content_text(message_source)
    if not original_message_content:
        raise HTTPException(status_code=400, detail="消息不能为空")
    if str(message_source.get("role") or "user").strip().lower() != "user":
        raise HTTPException(status_code=422, detail="message.role must be user")
    # Hermes slash directives: /plan (investigate + plan only, no dispatch)
    # and /goal (set the turn goal as the highest-priority objective).
    slash_directive, slash_argument, message_content = _parse_slash_directive(
        original_message_content
    )
    attachment_ids = list(
        dict.fromkeys(str(item).strip() for item in payload.attachment_ids)
    )
    if len(attachment_ids) > 32 or any(
        not item.startswith("file_") for item in attachment_ids
    ):
        raise HTTPException(status_code=422, detail="Invalid attachment_ids")
    # Classify before the first prewarm.  A new conversation has no durable
    # row yet, so this is the only point where the enqueue request can tell the
    # persistent official gateway that a trivial chat session may skip the
    # MCP readiness join. Tool discovery is optional for plain chat; the
    # configured model reasoning policy remains enabled and is never changed
    # by this route decision.
    deterministic_route = classify_user_intent(message_content)
    if slash_directive:
        # /plan and /goal always route to the full manager workflow: the
        # directive needs a planner, not a plain chat answer.
        deterministic_route = {
            "mode": "work",
            "lock_level": "hard_work",
            "source": "slash-directive",
            "slash_command": slash_directive,
            "slash_argument": slash_argument,
        }
    fast_chat_prewarm = (
        str(deterministic_route.get("mode") or "").strip().lower() == "chat"
        and str(deterministic_route.get("lock_level") or "").strip().lower()
        == "hard_chat"
        and not _coerce_flag(deterministic_route.get("artifact_required"))
        and not _coerce_flag(deterministic_route.get("needs_tools"))
        and not any(
            str(item).strip()
            for item in deterministic_route.get("capability_hints") or []
        )
        and not attachment_ids
    )
    prewarm_allow_tools = not fast_chat_prewarm
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    fingerprint = _enqueue_payload_fingerprint(
        payload,
        message_content=message_content,
    )
    # A first message creates its conversation atomically, so there is no
    # durable row from which the normal prewarm hook can start. Begin the
    # same gateway/session build before the initial state read; the request's
    # durable create and route classification then overlap the cold startup.
    if bool(getattr(payload, "create_conversation_if_missing", False)):
        _prewarm_hosted_chat({
            "id": conversation_id,
            "owner_id": owner_id,
            "account_generation": account_generation,
            "profile": str(
                getattr(payload, "conversation_profile", "") or "default"
            ).strip() or "default",
            "runtime_sessions": {},
        }, allow_tools=prewarm_allow_tools)

    route_attachments: list[dict[str, Any]] = []
    replay_response: Optional[dict[str, Any]] = None
    prewarm_conversation: dict[str, Any]
    with _STATE_LOCK:
        state = load_single_state()
        existing_conversation = next(
            (
                item
                for item in state.get("conversations") or []
                if isinstance(item, dict)
                and str(item.get("id") or "") == conversation_id
            ),
            None,
        )
        if existing_conversation is None:
            if not bool(getattr(payload, "create_conversation_if_missing", False)):
                raise HTTPException(status_code=404, detail="Conversation not found")
            conversation = None
            conversation_profile = str(
                getattr(payload, "conversation_profile", "") or "default"
            ).strip() or "default"
        else:
            conversation, _claimed = _owned_conversation_in_state(
                state,
                conversation_id,
                owner_id,
            )
            conversation_profile = (
                str(conversation.get("profile") or "default").strip() or "default"
            )
        # Start the official 0.20 gateway before the second durable-state
        # transaction and before routing. For a brand-new chat there is no
        # server conversation yet, so use the same stable id/profile context
        # that the create-if-missing enqueue will persist moments later.
        prewarm_conversation = conversation or {
            "id": conversation_id,
            "owner_id": owner_id,
            "account_generation": account_generation,
            "profile": conversation_profile,
            "runtime_sessions": {},
        }
        runtime_binding = _required_runtime_binding(
            conversation_profile,
            required_provider=str(
                getattr(payload, "required_provider", "") or ""
            ),
            required_model=str(
                getattr(payload, "required_model", "") or ""
            ),
        )
        requests = conversation.get("enqueue_requests") if conversation is not None else None
        requests = requests if isinstance(requests, dict) else {}
        existing_request = requests.get(request_id)
        if isinstance(existing_request, dict):
            if str(existing_request.get("fingerprint") or "") != fingerprint:
                raise HTTPException(
                    status_code=409,
                    detail="request_id was already used with a different payload",
                )
            replay_response = _enqueued_turn_response(
                conversation,
                existing_request,
                replayed=True,
            )
        else:
            for file_id in attachment_ids:
                file_record = _file_library().get_file(
                    owner_id,
                    file_id,
                    account_generation=account_generation,
                )
                if file_record is None or file_record.get("status") != "available":
                    raise HTTPException(status_code=404, detail="Attachment not found")
                route_attachments.append(
                    {
                        "id": file_id,
                        "name": str(file_record.get("name") or "attachment"),
                        "mime_type": str(
                            file_record.get("mime_type")
                            or "application/octet-stream"
                        ),
                        "size": int(file_record.get("size") or 0),
                    }
                )
    if replay_response is None or str(
        (replay_response.get("hosted_turn") or {}).get("status") or ""
    ) not in _HOSTED_TERMINAL_STATUSES:
        _prewarm_hosted_chat(
            prewarm_conversation,
            allow_tools=prewarm_allow_tools,
        )
    if replay_response is not None:
        replay_response["runtime_binding"] = runtime_binding
        hosted = replay_response.get("hosted_turn")
        if isinstance(hosted, dict) and str(hosted.get("status") or "") not in _HOSTED_TERMINAL_STATUSES:
            if str(hosted.get("stage") or "") in {"routing_pending", "routing_failed"}:
                start_hosted_routing(conversation_id, turn_id)
            else:
                start_hosted_workflow(conversation_id, turn_id)
        if attachment_ids:
            _file_library().update_links(
                owner_id,
                attachment_ids,
                account_generation=account_generation,
                conversation_id=conversation_id,
                message_id=str((replay_response.get("message") or {}).get("id") or ""),
                turn_id=turn_id,
                profile=str((replay_response.get("hosted_turn") or {}).get("profile") or "default"),
            )
        return replay_response

    hard_chat_route: Optional[dict[str, Any]] = None
    hard_chat_profiles: list[str] = []
    hard_chat_artifact_required = False
    if (
        str(deterministic_route.get("mode") or "") == "chat"
        and str(deterministic_route.get("lock_level") or "") == "hard_chat"
    ):
        (
            hard_chat_route,
            _hard_chat_mode,
            hard_chat_profiles,
            hard_chat_artifact_required,
        ) = _hosted_route_parameters(
            route_metadata=deterministic_route,
            content=message_content,
            requested_mode="chat",
            requested_profiles=[conversation_profile],
            requested_artifact=_coerce_flag(
                deterministic_route.get("artifact_required")
            ),
        )

    output_dir = _hosted_turn_output_dir(conversation_id, turn_id).resolve()

    with _STATE_LOCK:
        state = load_single_state()
        existing_conversation = next(
            (
                item
                for item in state.get("conversations") or []
                if isinstance(item, dict)
                and str(item.get("id") or "") == conversation_id
            ),
            None,
        )
        if existing_conversation is None:
            if not bool(getattr(payload, "create_conversation_if_missing", False)):
                raise HTTPException(status_code=404, detail="Conversation not found")
            conversation = create_single_conversation(
                conversation_profile,
                str(getattr(payload, "conversation_title", "") or "").strip(),
            )
            conversation["id"] = conversation_id
            conversation["owner_id"] = owner_id
            conversation["account_generation"] = account_generation
            state.setdefault("conversations", []).insert(0, conversation)
        else:
            conversation, _claimed = _owned_conversation_in_state(
                state,
                conversation_id,
                owner_id,
            )
        requests = conversation.get("enqueue_requests")
        if not isinstance(requests, dict):
            requests = {}
            conversation["enqueue_requests"] = requests
        existing_request = requests.get(request_id)
        if isinstance(existing_request, dict):
            if str(existing_request.get("fingerprint") or "") != fingerprint:
                raise HTTPException(
                    status_code=409,
                    detail="request_id was already used with a different payload",
                )
            response = _enqueued_turn_response(
                conversation,
                existing_request,
                replayed=True,
            )
            accepted = False
        else:
            for file_id in attachment_ids:
                file_record = _file_library().get_file(
                    owner_id,
                    file_id,
                    account_generation=account_generation,
                )
                if file_record is None or file_record.get("status") != "available":
                    raise HTTPException(status_code=404, detail="Attachment not found")
            if isinstance((conversation.get("hosted_turns") or {}).get(turn_id), dict):
                raise HTTPException(
                    status_code=409,
                    detail="turn_id already exists outside this request",
                )
            message_id = str(message_source.get("id") or request_id).strip()[:256] or request_id
            messages = conversation.setdefault("messages", [])
            duplicate_message = next(
                (
                    item
                    for item in messages
                    if isinstance(item, dict)
                    and str(item.get("id") or "") == message_id
                ),
                None,
            )
            if duplicate_message is not None:
                raise HTTPException(
                    status_code=409,
                    detail="message id already exists outside this request",
                )
            user_message = _append_message(
                conversation,
                role="user",
                name=str(message_source.get("name") or "user"),
                content=original_message_content,
                status=str(message_source.get("status") or "completed"),
                kind=str(message_source.get("kind") or "message"),
                meta=dict(message_source.get("meta") or {}),
            )
            user_message["id"] = message_id
            supplied_created_at = message_source.get("created_at")
            if isinstance(supplied_created_at, (int, float)):
                user_message["created_at"] = int(supplied_created_at)
                user_message["updated_at"] = int(
                    message_source.get("updated_at") or supplied_created_at
                )
            _project_native_message(user_message)
            route_message_id = f"route_{hashlib.sha256(request_id.encode('utf-8')).hexdigest()[:20]}"
            if any(
                isinstance(item, dict)
                and str(item.get("id") or "") == route_message_id
                for item in messages
            ):
                raise HTTPException(
                    status_code=409,
                    detail="route message id already exists outside this request",
                )
            hosted = create_hosted_turn_record(
                conversation,
                turn_id=turn_id,
                user_message_id=message_id,
                content=message_content,
                title=summarize_task_title(message_content),
                profiles=hard_chat_profiles,
                artifact_required=hard_chat_artifact_required,
                attachment_context=payload.attachment_context,
                delivery_context=payload.delivery_context,
                user_delivery_context=payload.delivery_context,
                mode="chat" if hard_chat_route is not None else "pending",
                route_metadata=(
                    hard_chat_route
                    if hard_chat_route is not None
                    else {
                        "mode": "pending",
                        "lock_level": "pending",
                        "source": "route-outbox",
                        "slash_command": slash_directive,
                        "slash_argument": slash_argument,
                    }
                ),
                output_dir=str(output_dir),
                attachment_ids=attachment_ids,
            )
            if slash_directive:
                # Persist the directive on the run record itself: the router
                # may rewrite route_metadata, and the workflow must not lose
                # the /plan // /goal semantics mid-routing.
                hosted.update(
                    {
                        "slash_command": slash_directive,
                        "slash_argument": slash_argument,
                    }
                )
            if hard_chat_route is not None:
                routed_at = int(time.time() * 1000)
                hosted.update(
                    {
                        "mode": "chat",
                        "stage": "accepted",
                        "profiles": hard_chat_profiles,
                        "artifact_required": hard_chat_artifact_required,
                        "artifact_producer_profiles": [],
                        "routing_requested_at": routed_at,
                        "routing_completed_at": routed_at,
                    }
                )
            else:
                hosted.update(
                    {
                        "mode": "pending",
                        "stage": "routing_pending",
                        "profiles": [],
                        "routing_requested_at": int(time.time() * 1000),
                    }
                )
            pending_cancellations = conversation.get("pending_turn_cancellations")
            pending_cancellations = (
                pending_cancellations
                if isinstance(pending_cancellations, dict)
                else {}
            )
            pending_cancellation = pending_cancellations.pop(turn_id, None)
            if isinstance(pending_cancellation, dict):
                now = int(time.time() * 1000)
                hosted.update(
                    {
                        "status": "cancelled",
                        "stage": "cancelled",
                        "cancel_requested": True,
                        "cancel_reason": str(
                            pending_cancellation.get("cancel_reason") or "用户取消"
                        ),
                        "cancel_requested_at": int(
                            pending_cancellation.get("cancel_requested_at") or now
                        ),
                        "cancelled_at": now,
                        "completed_at": now,
                        "updated_at": now,
                    }
                )
                hosted.setdefault("terminal_commit_id", f"terminal_{uuid.uuid4().hex}")
                hosted.setdefault("terminal_committed_at", now)
                _append_canonical_turn_terminal(
                    conversation,
                    conversation_id=conversation_id,
                    turn_id=turn_id,
                    run=hosted,
                    occurred_at=now,
                )
            if conversation.get("title") in {"", "新对话", None}:
                conversation["title"] = summarize_task_title(message_content)
            now = int(time.time() * 1000)
            pending_route = (
                hard_chat_route
                if hard_chat_route is not None
                else {
                    "mode": "pending",
                    "confidence": 0.0,
                    "lock_level": "pending",
                    "capability_hints": [],
                    "rationale_codes": ["route.accepted_pending"],
                    "source": "route-outbox",
                    "profiles": [],
                }
            )
            request_record = {
                "request_id": request_id,
                "fingerprint": fingerprint,
                "turn_id": turn_id,
                "message_id": message_id,
                "route_message_id": "",
                "route": pending_route,
                "routing_state": (
                    "completed" if hard_chat_route is not None else "pending"
                ),
                "accepted": not isinstance(pending_cancellation, dict),
                "created_at": now,
            }
            if hard_chat_route is not None:
                request_record["routing_completed_at"] = now
            requests[request_id] = request_record
            if (
                not isinstance(pending_cancellation, dict)
                and hard_chat_route is None
            ):
                route_outbox = conversation.get("route_outbox")
                if not isinstance(route_outbox, dict):
                    route_outbox = {}
                    conversation["route_outbox"] = route_outbox
                route_outbox[turn_id] = {
                    "turn_id": turn_id,
                    "request_id": request_id,
                    "route_message_id": route_message_id,
                    "account_generation": account_generation,
                    "state": "pending",
                    "attempt": 0,
                    "next_attempt_at": 0,
                    "content": message_content,
                    "conversation_profile": conversation_profile,
                    "recent_messages": [
                        dict(item)
                        for item in payload.recent_messages[-20:]
                        if isinstance(item, dict)
                    ],
                    "attachments": route_attachments,
                    "delivery_context": payload.delivery_context.strip(),
                    "created_at": now,
                    "updated_at": now,
                }
            if len(requests) > 2000:
                oldest = sorted(
                    requests,
                    key=lambda key: int((requests.get(key) or {}).get("created_at") or 0),
                )[: len(requests) - 2000]
                for key in oldest:
                    requests.pop(key, None)
            # Start the official 0.20 gateway while the durable enqueue is
            # being written.  The write is intentionally still synchronous,
            # but its JSON/atomic-I/O cost now overlaps agent imports and MCP
            # tool registration instead of delaying the first prompt.
            if not isinstance(pending_cancellation, dict):
                _prewarm_hosted_chat(
                    conversation,
                    allow_tools=prewarm_allow_tools,
                )
                prewarm_started = True
            save_single_state(state)
            response = _enqueued_turn_response(
                conversation,
                request_record,
                replayed=False,
            )
            accepted = True
    if attachment_ids:
        _file_library().update_links(
            owner_id,
            attachment_ids,
            account_generation=account_generation,
            conversation_id=conversation_id,
            message_id=str((response.get("message") or {}).get("id") or ""),
            turn_id=turn_id,
            profile=str(conversation.get("profile") or "default"),
        )
    hosted_response = response.get("hosted_turn") or {}
    if str(hosted_response.get("status") or "") not in _HOSTED_TERMINAL_STATUSES:
        if not prewarm_started:
            _prewarm_hosted_chat(
                conversation,
                allow_tools=prewarm_allow_tools,
            )
        if str(hosted_response.get("stage") or "") in {
            "routing_pending",
            "routing_failed",
        }:
            start_hosted_routing(conversation_id, turn_id)
        else:
            start_hosted_workflow(conversation_id, turn_id)
    if accepted:
        _notify_hosted_update(conversation_id)
    response["runtime_binding"] = runtime_binding
    return response


@router.post("/single/conversations/{conversation_id}/hosted-turns")
def create_hosted_turn(
    conversation_id: str,
    payload: HostedTurnBody,
    request: Request,
):
    turn_id = payload.turn_id.strip()
    if not turn_id:
        raise HTTPException(status_code=400, detail="turn_id 不能为空")
    if not payload.content.strip():
        raise HTTPException(status_code=400, detail="任务内容不能为空")
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_single_state()
        conversation, claimed = _owned_conversation_in_state(
            state,
            conversation_id,
            owner_id,
        )
        conversation_profile = str(
            conversation.get("profile") or "default"
        ).strip() or "default"
        if claimed:
            save_single_state(state)
    requested_mode = str(
        payload.mode
        or (
            payload.route_metadata.get("mode")
            if isinstance(payload.route_metadata, dict)
            else ""
        )
        or "work"
    ).strip().lower()
    route_metadata, mode, selected_profiles, artifact_required = _hosted_route_parameters(
        route_metadata=payload.route_metadata,
        content=payload.content,
        requested_mode=payload.mode,
        requested_profiles=(
            [conversation_profile]
            if requested_mode == "chat"
            else payload.profiles
        ),
        requested_artifact=payload.artifact_required,
    )
    attachment_ids = list(
        dict.fromkeys(str(item).strip() for item in payload.attachment_ids)
    )
    if len(attachment_ids) > 32 or any(
        not item.startswith("file_") for item in attachment_ids
    ):
        raise HTTPException(status_code=422, detail="Invalid attachment_ids")
    output_dir = _hosted_turn_output_dir(conversation_id, turn_id).resolve()
    delivery_context = payload.delivery_context.strip()
    if artifact_required:
        delivery_context = "\n".join(
            item
            for item in (
                delivery_context,
                f"Absolute output directory: `{output_dir}`.",
                "Write every generated deliverable to this exact directory, but mention only file names in user-facing text.",
            )
            if item
        )
    with _STATE_LOCK:
        state = load_single_state()
        conversation, _claimed = _owned_conversation_in_state(
            state,
            conversation_id,
            owner_id,
        )
        for file_id in attachment_ids:
            file_record = _file_library().get_file(
                owner_id,
                file_id,
                account_generation=account_generation,
            )
            if file_record is None or file_record.get("status") != "available":
                raise HTTPException(status_code=404, detail="Attachment not found")
        run = create_hosted_turn_record(
            conversation,
            turn_id=turn_id,
            content=payload.content,
            title=payload.title,
            profiles=selected_profiles,
            artifact_required=artifact_required,
            attachment_context=payload.attachment_context,
            delivery_context=delivery_context,
            user_delivery_context=payload.delivery_context,
            mode=mode,
            route_metadata=route_metadata,
            output_dir=str(output_dir),
            attachment_ids=attachment_ids,
        )
        save_single_state(state)
    if attachment_ids:
        _file_library().update_links(
            owner_id,
            attachment_ids,
            account_generation=account_generation,
            conversation_id=conversation_id,
            turn_id=turn_id,
            profile=str(conversation.get("profile") or "default"),
        )
    if str(run.get("status") or "") not in _HOSTED_TERMINAL_STATUSES:
        start_hosted_workflow(conversation_id, turn_id)
    return {"hosted_turn": _public_hosted_turn(run)}


@router.post(
    "/single/conversations/{conversation_id}/hosted-turns/{turn_id}/cancel"
)
def cancel_hosted_turn(
    conversation_id: str,
    turn_id: str,
    payload: HostedTurnCancellationBody,
    request: Request = None,
):
    _owned_conversation(request, conversation_id)
    try:
        run = request_hosted_turn_cancellation(
            conversation_id,
            turn_id,
            reason=payload.reason,
            request_id=payload.request_id,
        )
    except RuntimeError as exc:
        raise HTTPException(status_code=404, detail=str(exc)) from exc
    return {"hosted_turn": _public_hosted_turn(run)}


@router.get(
    "/single/conversations/{conversation_id}/hosted-turns/{turn_id}/subagents"
)
def list_hosted_subagents(
    conversation_id: str,
    turn_id: str,
    request: Request,
):
    owner_id, conversation = _owned_conversation(request, conversation_id)
    run = (conversation.get("hosted_turns") or {}).get(turn_id)
    if not isinstance(run, dict):
        raise HTTPException(status_code=404, detail="Hosted turn not found")
    generation = _account_generation_for_request(request, owner_id)
    try:
        result = control_hosted_subagents(
            conversation_id,
            owner_id=owner_id,
            account_generation=generation,
            action="list",
        )
    except (ValueError, RuntimeError) as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    return {
        "turn_id": turn_id,
        "account_generation": generation,
        "subagents": result.get("subagents") or [],
    }


@router.get(
    "/single/conversations/{conversation_id}/hosted-turns/{turn_id}/trajectory"
)
def get_hosted_turn_trajectory(
    conversation_id: str,
    turn_id: str,
    request: Request,
):
    """Return a bounded Codex-Trajectory-shaped view of one Hosted turn."""

    owner_id, conversation = _owned_conversation(request, conversation_id)
    run = (conversation.get("hosted_turns") or {}).get(turn_id)
    if not isinstance(run, dict):
        raise HTTPException(status_code=404, detail="Hosted turn not found")
    generation = _account_generation_for_request(request, owner_id)
    detail = str(
        request.query_params.get("detailLevel")
        or request.query_params.get("detail_level")
        or "summary"
    ).strip().lower()
    raw_limit = request.query_params.get("maxRecords") or request.query_params.get("max_records")
    try:
        max_records = (
            TRAJECTORY_DEFAULT_MAX_RECORDS
            if raw_limit in {None, ""}
            else int(str(raw_limit))
        )
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=422, detail="maxRecords must be an integer") from exc
    if detail not in {"summary", "full"}:
        raise HTTPException(status_code=422, detail="detailLevel must be summary or full")
    if not 50 <= max_records <= TRAJECTORY_MAX_RECORDS:
        raise HTTPException(
            status_code=422,
            detail=f"maxRecords must be between 50 and {TRAJECTORY_MAX_RECORDS}",
        )
    events = [
        event
        for event in (conversation.get("hosted_events") or [])
        if isinstance(event, dict)
        and str(event.get("turn_id") or "") == turn_id
        and str(event.get("account_generation") or "") == generation
    ]
    route = run.get("route_metadata") if isinstance(run.get("route_metadata"), dict) else {}
    trajectory = project_hosted_trajectory(
        events,
        session_id=turn_id,
        title=str(run.get("title") or run.get("content") or "Hermes hosted task"),
        model=str(route.get("model") or "") or None,
        detail_level=detail,
        max_records=max_records,
    )
    return {
        "turn_id": turn_id,
        "account_generation": generation,
        "trajectory": trajectory,
    }


def _control_hosted_subagent(
    conversation_id: str,
    turn_id: str,
    subagent_id: str,
    request: Request,
    *,
    action: str,
    payload: HostedSubagentControlBody,
) -> dict[str, Any]:
    normalized_id = str(subagent_id or "").strip()[:256]
    if not normalized_id:
        raise HTTPException(status_code=422, detail="subagent_id is required")
    owner_id, conversation = _owned_conversation(request, conversation_id)
    run = (conversation.get("hosted_turns") or {}).get(turn_id)
    if not isinstance(run, dict):
        raise HTTPException(status_code=404, detail="Hosted turn not found")
    generation = _account_generation_for_request(request, owner_id)
    message = str(payload.message or "").strip()
    request_id = str(payload.request_id or "").strip()[:256]
    if not request_id:
        request_id = f"subagent:{action}:{turn_id}:{normalized_id}:{uuid.uuid4().hex[:12]}"
    with _SUBAGENT_CONTROL_LOCK:
        # Check the durable request ledger before calling the real gateway.
        # A retry must not send a second steer/stop to a live child merely
        # because the first HTTP response was lost.
        with _STATE_LOCK:
            state = load_single_state()
            persisted_conversation = _conversation_by_id(state, conversation_id)
            persisted_run = (persisted_conversation.get("hosted_turns") or {}).get(turn_id)
            if not isinstance(persisted_run, dict):
                raise HTTPException(status_code=404, detail="Hosted turn not found")
            controls = persisted_run.get("subagent_controls")
            controls = controls if isinstance(controls, list) else []
            existing = next(
                (
                    item for item in controls
                    if isinstance(item, dict)
                    and str(item.get("request_id") or "") == request_id
                ),
                None,
            )
        if existing is not None:
            existing_target = str(
                existing.get("subagent_id") or existing.get("entity_id") or ""
            )
            if (
                str(existing.get("control_action") or "") != action
                or existing_target != normalized_id
            ):
                raise HTTPException(
                    status_code=409,
                    detail="request_id is already bound to another subagent control",
                )
            return {
                "accepted": True,
                "replayed": True,
                "turn_id": turn_id,
                "subagent_id": normalized_id,
                "action": action,
                "control": {
                    "status": existing.get("control_status") or "accepted",
                    "replayed": True,
                },
            }
        if str(persisted_run.get("status") or "") in _HOSTED_TERMINAL_STATUSES:
            raise HTTPException(status_code=409, detail="Hosted turn is already terminal")
        if action == "steer" and not message:
            raise HTTPException(status_code=422, detail="message is required")
        result = control_hosted_subagents(
            conversation_id,
            owner_id=owner_id,
            account_generation=generation,
            action=action,
            subagent_id=normalized_id,
            message=message[:2000],
        )
        accepted = (
            result.get("status") == "queued"
            if action == "steer"
            else bool(result.get("found"))
        )
        if not accepted:
            raise HTTPException(status_code=409, detail="Subagent is not controllable")
        now = int(time.time() * 1000)
        event_payload: dict[str, Any] = {
            "entity_id": normalized_id,
            "subagent_id": normalized_id,
            "control_action": action,
            "control_status": "queued" if action == "steer" else "stop_requested",
            "request_id": request_id,
        }
        if action == "steer":
            event_payload.update(
                {
                    "message_chars": len(message),
                    "message_digest": hashlib.sha256(message.encode("utf-8")).hexdigest(),
                }
            )
        else:
            reason = str(payload.reason or "user requested stop").strip()[:500]
            event_payload["reason"] = reason
        with _STATE_LOCK:
            state = load_single_state()
            persisted_conversation = _conversation_by_id(state, conversation_id)
            persisted_run = (persisted_conversation.get("hosted_turns") or {}).get(turn_id)
            if not isinstance(persisted_run, dict):
                raise HTTPException(status_code=404, detail="Hosted turn not found")
            persisted_run.setdefault("subagent_controls", []).append(event_payload)
            persisted_run["updated_at"] = now
            append_hosted_event(
                persisted_conversation,
                conversation_id=conversation_id,
                turn_id=turn_id,
                role_stage="subagent",
                event_type="subagent.progress",
                entity_id=normalized_id,
                idempotency_key=request_id,
                account_generation=generation,
                payload=event_payload,
                occurred_at=now,
            )
            persisted_conversation["updated_at"] = now
            save_single_state(state)
    _notify_hosted_update(conversation_id)
    return {
        "accepted": True,
        "turn_id": turn_id,
        "subagent_id": normalized_id,
        "action": action,
        "control": result,
    }


