@router.post(
    "/single/conversations/{conversation_id}/hosted-turns/{turn_id}/interventions"
)
def intervene_hosted_turn(
    conversation_id: str,
    turn_id: str,
    payload: HostedTurnInterventionBody,
    request: Request,
):
    content = payload.content.strip()
    targets = mentioned_collaboration_roles(content)
    target_profiles = _mentioned_collaboration_profiles(content)
    if not content:
        raise HTTPException(status_code=400, detail="干预内容不能为空")
    if not targets:
        raise HTTPException(status_code=422, detail="干预消息必须 @ 一个群聊成员")
    delivery = str(payload.delivery or "steer").strip().lower()
    queue_mode = str(payload.queue_mode or "one_at_a_time").strip().lower()
    if delivery not in {"steer", "follow_up"}:
        raise HTTPException(
            status_code=422,
            detail="delivery must be steer or follow_up",
        )
    if queue_mode not in {"one_at_a_time", "all_at_once"}:
        raise HTTPException(
            status_code=422,
            detail="queue_mode must be one_at_a_time or all_at_once",
        )
    message_id = payload.message_id.strip()[:256] or f"intervention_{uuid.uuid4().hex[:20]}"
    idempotency_fingerprint = hashlib.sha256(
        json.dumps(
            {
                "content": content,
                "turn_id": turn_id,
                "targets": sorted(targets),
                "target_profiles": sorted(target_profiles),
                "kind": "intervention",
                "delivery": delivery,
                "queue_mode": queue_mode,
            },
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    owner_id = owner_id_from_request(request)
    with _STATE_LOCK:
        state = load_single_state()
        conversation, _claimed = _owned_conversation_in_state(
            state,
            conversation_id,
            owner_id,
        )
        run = (conversation.get("hosted_turns") or {}).get(turn_id)
        if not isinstance(run, dict):
            raise HTTPException(status_code=404, detail="托管任务不存在")
        interventions = run.get("interventions")
        if not isinstance(interventions, list):
            interventions = []
            run["interventions"] = interventions
        replay_intervention = next(
            (
                item
                for item in interventions
                if isinstance(item, dict) and str(item.get("id") or "") == message_id
            ),
            None,
        )
        replay_message = next(
            (
                item
                for item in conversation.get("messages") or []
                if isinstance(item, dict) and str(item.get("id") or "") == message_id
            ),
            None,
        )
        if isinstance(replay_intervention, dict):
            replay_meta = (
                replay_message.get("meta")
                if isinstance(replay_message, dict)
                and isinstance(replay_message.get("meta"), dict)
                else {}
            )
            stored_fingerprint = str(
                replay_intervention.get("idempotency_fingerprint") or ""
            )
            replay_matches = bool(
                isinstance(replay_message, dict)
                and str(replay_message.get("content") or "") == content
                and replay_meta.get("intervention") is True
                and str(replay_meta.get("runtime_turn_id") or "") == turn_id
                and (
                    hmac.compare_digest(stored_fingerprint, idempotency_fingerprint)
                    if stored_fingerprint
                    else (
                        str(replay_intervention.get("content") or "") == content
                        and sorted(
                            str(item)
                            for item in replay_intervention.get("targets") or []
                        )
                        == sorted(targets)
                        and sorted(
                            str(item)
                            for item in replay_intervention.get("target_profiles") or []
                        )
                        == sorted(target_profiles)
                    )
                )
            )
            if not replay_matches:
                raise HTTPException(
                    status_code=409,
                    detail="message_id 已用于另一条干预消息",
                )
            return {
                "accepted": True,
                "replayed": True,
                "message": replay_message,
                "targets": targets,
                "hosted_turn": _public_hosted_turn(run),
            }
        if isinstance(replay_message, dict):
            raise HTTPException(
                status_code=409,
                detail="message_id 已用于会话中的另一条消息",
            )
        if str(run.get("status") or "queued") in _HOSTED_TERMINAL_STATUSES:
            raise HTTPException(status_code=409, detail="托管任务已经结束")
        active_matches = [
            dict(item)
            for item in (run.get("active_roles") or {}).values()
            if isinstance(item, dict)
            and _intervention_matches_role(
                {
                    "targets": targets,
                    "target_profiles": target_profiles,
                },
                role_stage=str(item.get("role_stage") or ""),
                profile=str(item.get("profile") or ""),
            )
        ]
        if len(active_matches) > 1 and not target_profiles:
            raise HTTPException(
                status_code=409,
                detail="该角色当前有多个执行实例，请 @ 具体成员",
            )
        existing = next(
            (
                item
                for item in interventions
                if isinstance(item, dict) and str(item.get("id") or "") == message_id
            ),
            None,
        )
        message_with_id = next(
            (
                item
                for item in conversation.get("messages") or []
                if isinstance(item, dict) and str(item.get("id") or "") == message_id
            ),
            None,
        )
        if isinstance(existing, dict):
            existing_fingerprint = str(existing.get("idempotency_fingerprint") or "")
            if existing_fingerprint:
                matches_existing = hmac.compare_digest(
                    existing_fingerprint,
                    idempotency_fingerprint,
                )
            else:
                matches_existing = (
                    str(existing.get("content") or "") == content
                    and sorted(str(item) for item in existing.get("targets") or [])
                    == sorted(targets)
                    and sorted(
                        str(item) for item in existing.get("target_profiles") or []
                    )
                    == sorted(target_profiles)
                )
            message_meta = (
                message_with_id.get("meta")
                if isinstance(message_with_id, dict)
                and isinstance(message_with_id.get("meta"), dict)
                else {}
            )
            matches_message = bool(
                isinstance(message_with_id, dict)
                and str(message_with_id.get("content") or "") == content
                and message_meta.get("intervention") is True
                and str(message_meta.get("runtime_turn_id") or "") == turn_id
            )
            if not matches_existing or not matches_message:
                raise HTTPException(
                    status_code=409,
                    detail="message_id 已用于另一条干预消息",
                )
            message = message_with_id
        else:
            if isinstance(message_with_id, dict):
                raise HTTPException(
                    status_code=409,
                    detail="message_id 已用于会话中的另一条消息",
                )
            now = int(time.time() * 1000)
            intervention = {
                "id": message_id,
                "content": content,
                "targets": targets,
                "target_profiles": target_profiles,
                "status": "pending",
                "delivery": delivery,
                "queue_mode": queue_mode,
                "queued_for_future_stage": not bool(active_matches),
                "idempotency_fingerprint": idempotency_fingerprint,
                "created_at": now,
                "updated_at": now,
            }
            interventions.append(intervention)
            message = _append_message(
                conversation,
                role="user",
                name="用户",
                content=content,
                status="completed",
                meta={
                    "intervention": True,
                    "intervention_for": targets,
                    "intervention_profiles": target_profiles,
                    "runtime_turn_id": turn_id,
                    "idempotency_fingerprint": idempotency_fingerprint,
                },
            )
            message["id"] = message_id
            _project_native_message(message)
            active_remote_ids = {
                str(item.get("remote_run_id") or "")
                for item in active_matches
                if isinstance(item, dict)
                and str(item.get("execution") or "") == "remote"
            }
            dispatched_to: list[str] = []
            for remote_run in (run.get("remote_runs") or {}).values():
                if not isinstance(remote_run, dict):
                    continue
                remote_id = str(remote_run.get("id") or "")
                remote_status = str(remote_run.get("status") or "queued")
                if remote_status in _REMOTE_TERMINAL_STATUSES:
                    continue
                if remote_id not in active_remote_ids:
                    continue
                if not _intervention_matches_role(
                    intervention,
                    role_stage=str(remote_run.get("role_stage") or ""),
                    profile=str(remote_run.get("profile") or ""),
                ):
                    continue
                if delivery != "steer":
                    continue
                if remote_status == "awaiting_input":
                    # The member asked the user a question and is parked in
                    # needs_input. The user's answer (choice or custom text)
                    # steers the worker: persist the steer durably on the run
                    # (survives a lost push / connector reconnect — the pull
                    # payload re-delivers it), then push run.steer so the
                    # connector unblocks the task with the answer injected as
                    # a comment; the worker resumes with the decision.
                    steer_id = f"steer_{uuid.uuid4().hex[:16]}"
                    pending_steers = remote_run.get("pending_steers")
                    if not isinstance(pending_steers, list):
                        pending_steers = []
                        remote_run["pending_steers"] = pending_steers
                    pending_steers.append(
                        {
                            "id": steer_id,
                            "text": content[:2000],
                            "created_at": now,
                        }
                    )
                    del pending_steers[:-8]
                    try:
                        _push_connector_event(
                            _remote_run_connector_id(remote_run),
                            {
                                "type": "run.steer",
                                "remote_run_id": remote_id,
                                "steer_id": steer_id,
                                "text": content[:2000],
                            },
                        )
                        remote_run["steered_at"] = now
                        dispatched_to.append(remote_id)
                    except Exception:
                        logger.exception("run.steer push failed")
                    continue
                remote_run.update(
                    {
                        "cancel_requested": True,
                        "cancel_kind": "intervention",
                        "cancel_intervention_id": message_id,
                        "cancel_reason": content[:1000],
                        "cancel_requested_at": now,
                        "cancel_force_terminal_at": (
                            now + _REMOTE_USER_CANCEL_FORCE_SECONDS * 1000
                        ),
                        "updated_at": now,
                    }
                )
                dispatched_to.append(remote_id)
            if dispatched_to:
                intervention["cancel_dispatched_to"] = dispatched_to
            append_hosted_event(
                conversation,
                conversation_id=conversation_id,
                turn_id=turn_id,
                role_stage="intervention",
                event_type="intervention.queued",
                entity_id=message_id,
                idempotency_key=f"intervention:{message_id}:queued",
                account_generation=_account_generation_for_owner(owner_id),
                payload={
                    "entity_id": message_id,
                    "targets": targets,
                    "target_profiles": target_profiles,
                    "delivery": delivery,
                    "queue_mode": queue_mode,
                    "queued_for_future_stage": not bool(active_matches),
                },
                occurred_at=now,
            )
            run["updated_at"] = now
            conversation["updated_at"] = now
            save_single_state(state)
    _notify_hosted_update(conversation_id)
    return {
        "accepted": True,
        "message": message,
        "targets": targets,
        "hosted_turn": _public_hosted_turn(run),
    }


def _conversation_deletion_ready(conversation: dict[str, Any]) -> bool:
    """Return true once no local or remote work still needs cancellation state."""

    for run in (conversation.get("hosted_turns") or {}).values():
        if not isinstance(run, dict):
            continue
        if str(run.get("status") or "queued") not in _HOSTED_TERMINAL_STATUSES:
            return False
        if any(
            isinstance(remote, dict)
            and str(remote.get("status") or "queued")
            not in _REMOTE_TERMINAL_STATUSES
            for remote in (run.get("remote_runs") or {}).values()
        ):
            return False
    return True


def _remove_room_index_for_conversation(
    conversation_id: str,
    owner_id: str,
) -> bool:
    """Remove the room alias so a deleted chat cannot be recreated by room ID."""

    room_state = load_state()
    rooms = room_state.get("rooms") or []
    kept: list[dict[str, Any]] = []
    removed = False
    for room in rooms:
        if not isinstance(room, dict):
            continue
        room_owner = str(room.get("owner_id") or "").strip()
        matches_owner = room_owner == owner_id or _legacy_owner_claim_allowed(
            room_owner,
            owner_id,
        )
        if room.get("conversation_id") == conversation_id and matches_owner:
            removed = True
            continue
        kept.append(room)
    if removed:
        room_state["rooms"] = kept
        save_state(room_state)
    return removed


def _finalize_pending_conversation_deletion(conversation_id: str) -> bool:
    """Purge a hidden deletion tombstone after workers no longer need it."""

    runtime_sessions: list[tuple[str, str]] = []
    owner_id = ""
    account_generation = ""
    with _STATE_LOCK:
        state = load_single_state()
        conversation = next(
            (
                item
                for item in state.get("conversations") or []
                if isinstance(item, dict) and item.get("id") == conversation_id
            ),
            None,
        )
        if (
            not isinstance(conversation, dict)
            or not conversation.get("delete_requested")
            or not _conversation_deletion_ready(conversation)
        ):
            return False
        runtime_sessions = [
            (str(profile), str(session_id))
            for profile, session_id in (
                conversation.get("runtime_sessions") or {}
            ).items()
            if str(session_id or "").strip()
        ]
        owner_id = str(conversation.get("owner_id") or LOCAL_OWNER_ID)
        account_generation = _account_generation_for_conversation(conversation)
        # Remove the room alias while the tombstone is still present.  If the
        # separate room store is temporarily unavailable, retain the
        # tombstone and retry; otherwise a later room request could recreate a
        # fresh linked conversation after this row is dropped.
        try:
            _remove_room_index_for_conversation(conversation_id, owner_id)
        except Exception:
            return False
        # Runtime session databases are outside the collaboration document.
        # Keep the tombstone authoritative until every mapped session is
        # deleted (or confirmed already absent), so a transient SQLite or
        # filesystem failure remains retryable instead of silently orphaning
        # the user's transcript after the conversation row is removed.
        for profile, session_id in runtime_sessions:
            try:
                if not _delete_runtime_session(profile, session_id):
                    return False
            except Exception:
                logging.getLogger(__name__).exception(
                    "Failed to delete runtime session %s:%s",
                    profile,
                    session_id,
                )
                return False
        # Account-file rows are a separate durable store.  Remove them before
        # dropping the conversation tombstone so a crash leaves a retryable
        # deletion intent rather than an orphaned file index/object.
        try:
            _file_library().delete_conversation(
                owner_id,
                conversation_id,
                account_generation=account_generation,
            )
        except Exception:
            return False
        # The transcript sidecar lives under the conversation file root. It
        # must be removed while the deletion tombstone is still present so a
        # crash or filesystem failure leaves a retryable intent instead of an
        # orphaned cloud transcript.
        try:
            files_root = conversation_files_root(conversation_id)
            if files_root.exists():
                shutil.rmtree(files_root)
            if files_root.exists():
                return False
        except (OSError, ValueError):
            return False
        archive_target = _conversation_archive_path(conversation_id)
        if archive_target is None:
            return False
        try:
            if archive_target.exists():
                archive_target.unlink()
            if archive_target.exists():
                return False
        except OSError:
            return False
        # Durable cross-device tombstone: the row is about to disappear, so
        # record the deletion for other devices' list syncs (bounded TTL).
        _record_deletion_tombstone(state, conversation)
        previous_conversations = state.get("conversations")
        state["conversations"] = [
            item
            for item in state.get("conversations") or []
            if item.get("id") != conversation_id
        ]
        try:
            save_single_state(state)
        except Exception:
            # The durable tombstone remains in the on-disk state when the
            # atomic commit fails. Restore the caller's in-memory view too so
            # a retry in the same process cannot observe a phantom deletion.
            if isinstance(previous_conversations, list):
                state["conversations"] = previous_conversations
            return False
    release_hosted_gateway_conversation(
        conversation_id,
        owner_id=owner_id,
        account_generation=account_generation,
    )
    return True


@router.delete("/single/conversations/{conversation_id}")
def delete_single_conversation(
    conversation_id: str,
    request: Request = None,
):
    pending_turn_ids: list[str] = []
    owner_id = owner_id_from_request(request)
    with _STATE_LOCK:
        state = load_single_state()
        existing = _conversation_by_id(state, conversation_id)
        already_pending = bool(existing.get("delete_requested"))
        now = int(time.time() * 1000)
        if already_pending:
            # Deletion is an idempotent, retryable operation.  A prior request
            # may have committed the tombstone but failed while removing the
            # room/index, account files, archive, or sidecar.  Do not turn
            # that durable pending intent into a misleading 404.
            existing_owner = str(existing.get("owner_id") or "").strip()
            if existing_owner != owner_id:
                if not _legacy_owner_claim_allowed(existing_owner, owner_id):
                    raise HTTPException(status_code=404, detail="Conversation not found")
                existing["owner_id"] = owner_id
            current_generation = _account_generation_for_owner(owner_id)
            stored_generation = str(existing.get("account_generation") or "").strip()
            if stored_generation and stored_generation != current_generation:
                raise HTTPException(status_code=404, detail="Conversation not found")
            if not stored_generation:
                existing["account_generation"] = current_generation
            conversation = existing
        else:
            conversation, _claimed = _owned_conversation_in_state(
                state,
                conversation_id,
                owner_id,
            )
            conversation.update(
                {
                    "delete_requested": True,
                    "delete_requested_at": now,
                    "updated_at": now,
                }
            )
            # The tombstone (and any cancellation flags below) is committed
            # before touching the separate room index.  If the latter fails,
            # the next request can still locate and retry this conversation by
            # its room_id.
        for turn_id, run in (conversation.get("hosted_turns") or {}).items():
            if not isinstance(run, dict):
                continue
            has_active_remote = any(
                isinstance(remote, dict)
                and str(remote.get("status") or "queued")
                not in _REMOTE_TERMINAL_STATUSES
                for remote in (run.get("remote_runs") or {}).values()
            )
            if (
                str(run.get("status") or "queued")
                not in _HOSTED_TERMINAL_STATUSES
                or has_active_remote
            ):
                run.update(
                    {
                        "cancel_requested": True,
                        "cancel_reason": "conversation_deleted",
                        "cancel_requested_at": now,
                        "updated_at": now,
                    }
                )
                pending_turn_ids.append(str(turn_id))
        save_single_state(state)
    try:
        _remove_room_index_for_conversation(conversation_id, owner_id)
    except Exception as exc:
        _notify_hosted_update(conversation_id)
        for turn_id in pending_turn_ids:
            start_hosted_workflow(conversation_id, turn_id)
        raise HTTPException(
            status_code=503,
            detail={
                "reason": "conversation_deletion_pending",
                "message": "Conversation deletion is pending; retry.",
            },
        ) from exc
    _notify_hosted_update(conversation_id)
    if not _finalize_pending_conversation_deletion(conversation_id):
        for turn_id in pending_turn_ids:
            start_hosted_workflow(conversation_id, turn_id)
        raise HTTPException(
            status_code=503,
            detail={
                "reason": "conversation_deletion_pending",
                "message": "Conversation deletion is pending; retry.",
            },
        )
    return {"ok": True}


@router.post("/single/conversations/{conversation_id}/messages")
async def send_single_message(
    conversation_id: str,
    payload: SendSingleMessageBody,
    request: Request = None,
):
    content = payload.content.strip()
    if not content:
        raise HTTPException(status_code=400, detail="消息不能为空")

    with _STATE_LOCK:
        state = load_single_state()
        conversation, _claimed = _owned_conversation_in_state(
            state,
            conversation_id,
            owner_id_from_request(request),
        )
        profile = str(conversation.get("profile") or "default")
        user_message = _append_message(
            conversation,
            role="user",
            name="用户",
            content=content,
        )
        if conversation.get("title") in {"", "新对话", None}:
            conversation["title"] = summarize_task_title(content)
        prompt = build_single_prompt(
            conversation,
            profile,
            content,
            exclude_message_id=str(user_message.get("id") or ""),
        )
        save_single_state(state)

    try:
        reply = await asyncio.to_thread(run_single_turn, profile, prompt)
        status = "completed"
    except Exception as exc:
        reply = f"执行失败：{str(exc)}"
        status = "failed"

    with _STATE_LOCK:
        state = load_single_state()
        conversation, _claimed = _owned_conversation_in_state(
            state,
            conversation_id,
            owner_id_from_request(request),
        )
        message = _append_message(
            conversation,
            role="assistant",
            name=profile,
            content=reply,
            status=status,
        )
        save_single_state(state)
    return {"ok": status == "completed", "message": message}


@router.get("/rooms")
def get_rooms(request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        claimed = _claim_legacy_rooms_in_state(
            state,
            owner_id,
            account_generation=account_generation,
        )
        single_state = load_single_state()
        rooms = [
            room
            for room in state.get("rooms") or []
            if (
                str(room.get("owner_id") or "") == owner_id
                or _room_is_member(room, owner_id)
            )
            and str(room.get("account_generation") or "") == account_generation
            and not _room_maps_to_deleting_conversation(room, single_state)
        ]
        # Older room records predate the linked SingleConversation index and
        # kept their transcript directly on the room. Materialize that link
        # while listing so the mobile cache can download the complete history
        # even when the user has never sent a new message in the room.
        migrated = False
        for room in rooms:
            _conversation, created = _room_conversation_in_state(
                room,
                single_state,
                owner_id,
                account_generation,
            )
            migrated = migrated or created
        if migrated:
            save_single_state(single_state)
            save_state(state)
        elif claimed:
            save_state(state)
        summaries = []
        for room in rooms:
            projection = _room_projection(room, single_state, summary=True)
            projection["agents"] = _room_agents_projection(room)
            projection["members"] = _room_members(
                room, str(room.get("owner_id") or owner_id)
            )
            projection["can_mention_all"] = True
            projection["can_manage"] = str(room.get("owner_id") or "") == owner_id
            summaries.append(projection)
    return {"rooms": summaries}


@router.post("/rooms")
def create_room(payload: CreateRoomBody, request: Request):
    known = {item["name"] for item in available_profiles()}
    selected = [name for name in payload.profiles if name in known]
    if not selected:
        raise HTTPException(status_code=400, detail="至少选择一个 Hermes Profile")
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        single_state = load_single_state()
        room = create_room_record(
            payload.name,
            selected,
            owner_id,
            account_generation,
        )
        requested_code = payload.invite_code.strip()
        if requested_code:
            room["invite_code"] = requested_code[:64]
        if payload.workspace.strip():
            room["workspace"] = payload.workspace.strip()[:500]
        if isinstance(payload.summary, dict) and payload.summary:
            room["summary_config"] = {
                key: payload.summary[key]
                for key in _ROOM_SUMMARY_FIELDS
                if key in payload.summary
            }
        if isinstance(payload.settings, dict) and payload.settings:
            room["settings"] = {
                key: payload.settings[key]
                for key in _ROOM_SETTINGS_FIELDS
                if key in payload.settings
            }
        room["members"] = [_room_owner_member(room, owner_id)]
        _room_conversation_in_state(
            room,
            single_state,
            owner_id,
            account_generation,
        )
        state["rooms"].insert(0, room)
        save_single_state(single_state)
        save_state(state)
        projection = _room_projection(room, single_state, summary=False)
        projection["agents"] = _room_agents_projection(room)
        projection["members"] = _room_members(room, owner_id)
        projection["can_mention_all"] = True
    return {"room": projection}


@router.get("/rooms/{room_id}")
def get_room(room_id: str, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        claimed = _claim_legacy_rooms_in_state(
            state,
            owner_id,
            account_generation=account_generation,
            requested_room_id=room_id,
        )
        room = _accessible_room_in_state(
            state,
            room_id,
            owner_id,
            account_generation,
        )
        single_state = load_single_state()
        if _room_maps_to_deleting_conversation(room, single_state):
            raise HTTPException(status_code=404, detail="Room not found")
        _conversation, migrated = _room_conversation_in_state(
            room,
            single_state,
            owner_id,
            account_generation,
        )
        if migrated:
            save_single_state(single_state)
            save_state(state)
        elif claimed:
            save_state(state)
        raw_offset = request.query_params.get("offset")
        raw_limit = request.query_params.get("limit")
        try:
            offset = max(0, int(raw_offset or 0))
        except (TypeError, ValueError):
            offset = 0
        try:
            limit = max(1, min(500, int(raw_limit))) if raw_limit else None
        except (TypeError, ValueError):
            limit = None
        return _room_detail_response(
            room,
            single_state,
            owner_id,
            offset=offset,
            limit=limit,
        )


@router.get("/rooms/{room_id}/mailbox")
def get_room_mailbox(room_id: str, request: Request, recipient_id: str = "", after_id: str = "", limit: int = 100):
    """Read direct member messages without broadcasting the room mailbox."""

    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    recipient = str(recipient_id or "").strip()[:256]
    if not recipient:
        raise HTTPException(status_code=400, detail="recipient_id is required")
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        messages = read_mailbox(
            room.get("mailbox") or [],
            recipient,
            account_generation,
            after_id=str(after_id or "").strip()[:256],
            limit=limit,
        )
    return {"room_id": room_id, "recipient_id": recipient, "messages": messages}


@router.post("/rooms/{room_id}/mailbox")
def send_room_mailbox_message(room_id: str, payload: MailboxMessageBody, request: Request):
    """Append one idempotent, generation-bound direct member message."""

    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    sender = str(payload.sender_id or "").strip()[:256]
    recipient = str(payload.recipient_id or "").strip()[:256]
    if not sender or not recipient or sender == recipient:
        raise HTTPException(status_code=400, detail="sender_id and recipient_id must be distinct")
    if len(json.dumps(payload.body, ensure_ascii=False, default=str)) > 64_000:
        raise HTTPException(status_code=413, detail="mailbox body is too large")
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        member_ids = {hosted_member_id(profile) for profile in room.get("profiles") or []}
        member_ids.update({"user", owner_id})
        if sender not in member_ids or recipient not in member_ids:
            raise HTTPException(status_code=403, detail="sender or recipient is not a room member")
        mailbox = room.setdefault("mailbox", [])
        record = append_mailbox(
            mailbox,
            MailboxMessage(
                sender_id=sender,
                recipient_id=recipient,
                body=dict(payload.body),
                idempotency_key=str(payload.idempotency_key or "").strip()[:256],
                account_generation=account_generation,
            ),
        )
        room["updated_at"] = int(time.time() * 1000)
        save_state(state)
    return {"ok": True, "message": record}


@router.get("/rooms/{room_id}/dependencies")
def get_room_dependencies(room_id: str, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        nodes = [
            CollaborationDependency(
                node_id=str(item.get("node_id") or ""),
                requires=tuple(str(value) for value in item.get("requires") or ()),
                acceptance_contract=str(item.get("acceptance_contract") or ""),
                conflict_key=str(item.get("conflict_key") or ""),
                budget=dict(item.get("budget") or {}),
                state=str(item.get("state") or "pending"),
            )
            for item in room.get("dependencies") or []
            if isinstance(item, dict)
        ]
        graph = DependencyGraph(nodes)
    return {"room_id": room_id, "nodes": graph.snapshot(), "ready": graph.ready()}


@router.put("/rooms/{room_id}/dependencies")
def put_room_dependencies(room_id: str, payload: DependencyGraphBody, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    if len(payload.nodes) > 256:
        raise HTTPException(status_code=413, detail="dependency graph is too large")
    try:
        nodes = [
            CollaborationDependency(
                node_id=str(item.get("node_id") or "").strip()[:256],
                requires=tuple(str(value).strip()[:256] for value in item.get("requires") or ()),
                acceptance_contract=str(item.get("acceptance_contract") or "")[:2000],
                conflict_key=str(item.get("conflict_key") or "")[:256],
                budget={str(key): max(0, int(value)) for key, value in dict(item.get("budget") or {}).items()},
                state=str(item.get("state") or "pending"),
            )
            for item in payload.nodes
        ]
        graph = DependencyGraph(nodes)
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail=f"invalid dependency graph: {exc}") from exc
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        room["dependencies"] = graph.snapshot()
        room["updated_at"] = int(time.time() * 1000)
        save_state(state)
    return {"ok": True, "room_id": room_id, "nodes": graph.snapshot(), "ready": graph.ready()}


@router.delete("/rooms/{room_id}")
def delete_room(room_id: str, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    linked_conversation_id = ""
    pending_conversation_id = ""
    with _STATE_LOCK:
        state = load_state()
        try:
            claimed = _claim_legacy_rooms_in_state(
                state,
                owner_id,
                account_generation=account_generation,
                requested_room_id=room_id,
            )
        except HTTPException as exc:
            if exc.status_code != 404:
                raise
            # The room alias may already be gone while its linked deletion
            # tombstone is still retryable; defer to the lookup below.
            claimed = False
        try:
            room = _owned_room_in_state(
                state,
                room_id,
                owner_id,
                account_generation,
            )
        except HTTPException as exc:
            if exc.status_code != 404:
                raise
            # The first delete request removes the room alias before the
            # linked conversation is physically purged.  Locate that durable
            # tombstone by room_id so a retry cannot be mistaken for a fully
            # deleted 404 and acknowledged by the mobile outbox.
            single_state = load_single_state()
            pending = next(
                (
                    item
                    for item in single_state.get("conversations") or []
                    if isinstance(item, dict)
                    and item.get("delete_requested")
                    and (
                        str(item.get("room_id") or "").strip() == room_id
                        or str(item.get("id") or "").strip()
                        == f"chat_room_{str(room_id).removeprefix('room_')}"
                    )
                    and str(item.get("owner_id") or "").strip() == owner_id
                    and str(item.get("account_generation") or "").strip()
                    == account_generation
                ),
                None,
            )
            if not isinstance(pending, dict):
                raise
            pending_conversation_id = str(pending.get("id") or "").strip()
        else:
            if claimed:
                save_state(state)
            linked_conversation_id = str(room.get("conversation_id") or "").strip()
            if not linked_conversation_id:
                before = len(state.get("rooms") or [])
                state["rooms"] = [
                    item
                    for item in state.get("rooms") or []
                    if item.get("id") != room_id
                ]
                if len(state["rooms"]) == before:
                    raise HTTPException(status_code=404, detail="群聊不存在")
                save_state(state)
                return {"ok": True}

    if pending_conversation_id:
        if _finalize_pending_conversation_deletion(pending_conversation_id):
            return {"ok": True}
        raise HTTPException(
            status_code=503,
            detail={
                "reason": "conversation_deletion_pending",
                "message": "Conversation deletion is pending; retry.",
            },
        )

    if linked_conversation_id:
        try:
            return delete_single_conversation(linked_conversation_id, request)
        except HTTPException as exc:
            if exc.status_code != 404:
                raise

    # A legacy room can outlive its linked conversation.  Remove only the
    # already-owner-checked room index; never turn an unrelated 404 into a
    # cross-account deletion.
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(
            state,
            room_id,
            owner_id,
            account_generation,
        )
        state["rooms"] = [
            item for item in state.get("rooms") or [] if item.get("id") != room_id
        ]
        save_state(state)
    return {"ok": True}


@router.post("/rooms/{room_id}/messages")
def send_message(room_id: str, payload: SendMessageBody, request: Request):
    content = payload.content.strip()
    if not content:
        raise HTTPException(status_code=400, detail="Message cannot be empty")
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    request_id = payload.request_id.strip()[:256] or f"room-request-{uuid.uuid4().hex}"
    turn_id = payload.turn_id.strip()[:256] or (
        "room-turn-"
        + hashlib.sha256(request_id.encode("utf-8")).hexdigest()[:32]
    )

    with _STATE_LOCK:
        state = load_state()
        _claim_legacy_rooms_in_state(
            state,
            owner_id,
            account_generation=account_generation,
            requested_room_id=room_id,
        )
        room = _accessible_room_in_state(
            state,
            room_id,
            owner_id,
            account_generation,
        )
        known_profiles = set(room.get("profiles") or [])
        requested = payload.profiles or list(room.get("profiles") or [])
        mention_profiles = _resolve_room_mention_profiles(
            room,
            payload.mentions,
            known_profiles,
        )
        if mention_profiles is not None:
            requested = mention_profiles
        targets = collaboration_execution_order(
            [name for name in requested if name in known_profiles]
        )
        if not targets:
            raise HTTPException(status_code=400, detail="No executable room member")
        fingerprint = hashlib.sha256(
            json.dumps(
                {"content": content, "profiles": targets, "turn_id": turn_id},
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        single_state = load_single_state()
        room_owner_id = str(room.get("owner_id") or owner_id)
        conversation, _created = _room_conversation_in_state(
            room,
            single_state,
            room_owner_id,
            account_generation,
        )
        room_requests = room.get("hosted_requests")
        if not isinstance(room_requests, dict):
            room_requests = {}
            room["hosted_requests"] = room_requests
        existing = room_requests.get(request_id)
        if not isinstance(existing, dict):
            # The conversation and room indexes live in separate atomic files.
            # If the process stopped after the conversation commit, recover the
            # room-side idempotency record from the hosted turn before appending
            # another user message.
            recovered_run = (conversation.get("hosted_turns") or {}).get(turn_id)
            recovered_request = (
                recovered_run.get("room_request")
                if isinstance(recovered_run, dict)
                else None
            )
            if (
                isinstance(recovered_request, dict)
                and str(recovered_request.get("request_id") or "") == request_id
                and str(recovered_request.get("room_id") or "") == room_id
            ):
                existing = {
                    "fingerprint": str(recovered_request.get("fingerprint") or ""),
                    "message_id": str(recovered_request.get("message_id") or request_id),
                    "turn_id": turn_id,
                    "created_at": int(
                        recovered_request.get("created_at")
                        or recovered_run.get("created_at")
                        or time.time() * 1000
                    ),
                }
                room_requests[request_id] = existing
        if isinstance(existing, dict):
            if str(existing.get("fingerprint") or "") != fingerprint:
                raise HTTPException(
                    status_code=409,
                    detail="request_id was already used with a different payload",
                )
            existing_turn_id = str(existing.get("turn_id") or turn_id)
            hosted = (conversation.get("hosted_turns") or {}).get(existing_turn_id) or {}
            message = next(
                (
                    item
                    for item in conversation.get("messages") or []
                    if str(item.get("id") or "") == str(existing.get("message_id") or "")
                ),
                {},
            )
            response = {
                "accepted": True,
                "replayed": True,
                "request_id": request_id,
                "turn_id": existing_turn_id,
                "conversation_id": conversation["id"],
                "message": message,
                "messages": [message] if message else [],
                "hosted_turn": _public_hosted_turn(hosted),
            }
            save_single_state(single_state)
            save_state(state)
        else:
            artifact_required = requires_artifact_delivery(content)
            worker_targets = [
                profile.removesuffix("-worker")
                for profile in targets
                if collaboration_role(profile) == "worker"
            ]
            route_metadata, mode, selected_profiles, artifact_required = (
                _hosted_route_parameters(
                    route_metadata={
                        "mode": "work",
                        "profiles": targets,
                        "targets": worker_targets,
                        "artifact_required": artifact_required,
                        "artifact": {
                            "decision": "required" if artifact_required else "none",
                            "types": [],
                            "reason": "Explicit collaboration room request",
                        },
                    },
                    content=content,
                    requested_mode="work",
                    requested_profiles=targets,
                    requested_artifact=artifact_required,
                )
            )
            if any(
                isinstance(item, dict)
                and str(item.get("id") or "") == request_id
                for item in conversation.get("messages") or []
            ):
                raise HTTPException(
                    status_code=409,
                    detail="message_id 已用于会话中的另一条消息",
                )
            message_meta: dict[str, Any] = {
                "room_id": room_id,
                "request_id": request_id,
                "sender_id": owner_id,
            }
            normalized_mentions = _normalized_room_mentions(payload.mentions)
            if normalized_mentions:
                message_meta["mentions"] = normalized_mentions
            user_message = _append_message(
                conversation,
                role="user",
                name="User",
                content=content,
                meta=message_meta,
            )
            user_message["id"] = request_id
            _project_native_message(user_message)
            run = create_hosted_turn_record(
                conversation,
                turn_id=turn_id,
                user_message_id=request_id,
                content=content,
                title=summarize_task_title(content),
                profiles=selected_profiles,
                artifact_required=artifact_required,
                mode=mode,
                route_metadata=route_metadata,
                output_dir=str(
                    _hosted_turn_output_dir(conversation["id"], turn_id).resolve()
                ),
            )
            run["room_request"] = {
                "room_id": room_id,
                "request_id": request_id,
                "fingerprint": fingerprint,
                "message_id": request_id,
                "created_at": int(time.time() * 1000),
            }
            room_requests[request_id] = {
                "fingerprint": fingerprint,
                "message_id": request_id,
                "turn_id": turn_id,
                "created_at": int(time.time() * 1000),
            }
            room["updated_at"] = int(time.time() * 1000)
            save_single_state(single_state)
            save_state(state)
            response = {
                "accepted": True,
                "replayed": False,
                "request_id": request_id,
                "turn_id": turn_id,
                "conversation_id": conversation["id"],
                "message": user_message,
                "messages": [user_message],
                "hosted_turn": _public_hosted_turn(run),
            }
    start_hosted_workflow(str(response["conversation_id"]), str(response["turn_id"]))
    _notify_hosted_update(str(response["conversation_id"]))
    return response


@router.post("/rooms/{room_id}/hosted-turns/{turn_id}/cancel")
def cancel_room_hosted_turn(
    room_id: str,
    turn_id: str,
    payload: HostedTurnCancellationBody,
    request: Request,
):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        if _claim_legacy_rooms_in_state(
            state,
            owner_id,
            account_generation=account_generation,
            requested_room_id=room_id,
        ):
            save_state(state)
        room = _owned_room_in_state(
            state,
            room_id,
            owner_id,
            account_generation,
        )
        conversation_id = str(room.get("conversation_id") or "")
        single_state = load_single_state()
        _conversation, claimed = _owned_conversation_in_state(
            single_state,
            conversation_id,
            owner_id,
        )
        if claimed:
            save_single_state(single_state)
    try:
        hosted = request_hosted_turn_cancellation(
            conversation_id,
            turn_id,
            reason=payload.reason,
        )
    except RuntimeError as exc:
        raise HTTPException(status_code=404, detail=str(exc)) from exc
    return {"hosted_turn": _public_hosted_turn(hosted)}


# ---------------------------------------------------------------------------
# Studio group-chat completion: agent roster management, invite codes and
# membership, typing presence, message retraction, room summary/context
# settings, room workspace files, and room-scoped write approvals.  These
# routes share the room state file, ownership fencing, and the linked
# hosted-conversation transcript with the core room API above.
# ---------------------------------------------------------------------------

_ROOM_TYPING_TTL_MS = 6_000
_ROOM_INVITE_CODE_ALPHABET = "abcdefghjkmnpqrstuvwxyz23456789"
_ROOM_SUMMARY_FIELDS = ("profile", "provider", "model", "api_mode", "every_turns")
_ROOM_CONTEXT_FIELDS = ("trigger_tokens", "max_history_tokens", "tail_messages")
_ROOM_SETTINGS_FIELDS = (
    "allow_guest_agents",
    "guest_agent_approval",
    "max_guest_agents_per_member",
    "allow_remote_workspace_access",
)
_ROOM_MAX_LIST_ENTRIES = 2_000


def _generate_room_invite_code() -> str:
    return "".join(secrets.choice(_ROOM_INVITE_CODE_ALPHABET) for _ in range(10))


def _room_owner_member(room: dict[str, Any], owner_id: str) -> dict[str, Any]:
    now = int(time.time() * 1000)
    return {
        "id": f"member-owner-{owner_id}",
        "user_id": owner_id,
        "name": "Owner",
        "role": "owner",
        "joined_at": int(room.get("created_at") or now),
    }


def _room_members(room: dict[str, Any], owner_id: str) -> list[dict[str, Any]]:
    members = [m for m in (room.get("members") or []) if isinstance(m, dict)]
    if not any(str(m.get("user_id") or "") == owner_id for m in members):
        members.insert(0, _room_owner_member(room, owner_id))
    return members


def _room_is_member(room: dict[str, Any], owner_id: str) -> bool:
    return any(
        isinstance(m, dict) and str(m.get("user_id") or "") == owner_id
        for m in room.get("members") or []
    )


def _accessible_room_in_state(
    state: dict[str, Any],
    room_id: str,
    owner_id: str,
    account_generation: str,
) -> dict[str, Any]:
    """Owner OR invited-member room lookup with the same fencing as _owned_room_in_state."""

    try:
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
    except HTTPException as exc:
        if exc.status_code != 404:
            raise
        room = None
    if room is not None:
        if str(room.get("owner_id") or "") == owner_id or _room_is_member(room, owner_id):
            return room
    # Members reach rooms owned by another account: the invite code created a
    # durable membership entry. The CALLER's generation is their own active
    # fence; the room record carries the OWNER's era, which a member must
    # never be required to match — that comparison made every joined room
    # 404 for members of a different-generation owner.
    for candidate in state.get("rooms") or []:
        if not isinstance(candidate, dict) or candidate.get("id") != room_id:
            continue
        if not _room_is_member(candidate, owner_id):
            continue
        return candidate
    raise HTTPException(status_code=404, detail="Room not found")


def _room_agents_projection(room: dict[str, Any]) -> list[dict[str, Any]]:
    profiles = list(dict.fromkeys(room.get("profiles") or []))
    metadata: dict[str, dict[str, Any]] = {}
    for item in room.get("agents") or []:
        if isinstance(item, dict):
            key = str(item.get("profile") or "").strip()
            if key:
                metadata[key] = item
    try:
        known = {p["name"]: p for p in available_profiles()}
    except Exception:
        known = {}
    agents = []
    for profile in profiles:
        meta = metadata.get(profile) or {}
        info = known.get(profile) or {}
        agents.append(
            {
                "id": f"{room.get('id')}:profile:{profile}",
                "room_id": room.get("id"),
                "agent_id": profile,
                "agent": "hermes",
                "profile": profile,
                "provider": str(meta.get("provider") or info.get("provider") or ""),
                "model": str(meta.get("model") or info.get("model") or ""),
                "name": str(meta.get("name") or profile),
                "description": str(meta.get("description") or info.get("description") or ""),
                "avatar": str(meta.get("avatar") or ""),
                "connection_status": "online" if (profile in known or not known) else "offline",
            }
        )
    return agents


def _room_active_typing(room: dict[str, Any]) -> list[dict[str, Any]]:
    now = int(time.time() * 1000)
    typing = room.get("typing") if isinstance(room.get("typing"), dict) else {}
    active = []
    for member_key, record in list(typing.items()):
        if not isinstance(record, dict):
            continue
        expires_at = int(record.get("expires_at") or 0)
        if expires_at <= now:
            typing.pop(member_key, None)
            continue
        active.append(
            {
                "id": str(record.get("id") or member_key),
                "name": str(record.get("name") or member_key),
                "expires_at": expires_at,
            }
        )
    return active



_DELETION_TOMBSTONE_TTL_MS = 14 * 24 * 3600 * 1000
_DELETION_TOMBSTONE_MAX = 500


def _record_deletion_tombstone(
    single_state: dict[str, Any],
    conversation: dict[str, Any],
    *,
    now: Optional[int] = None,
) -> None:
    """Persist a bounded deletion tombstone for cross-device propagation.

    The delete_requested row is removed as soon as the deletion finalizes,
    which left other devices no window to observe it (they preserved their
    cached copies forever). These tombstones keep the id visible in the
    conversation list's `deleted` array for a TTL so every sync'ing device
    drops its copy.
    """
    entry = {
        "id": str(conversation.get("id") or "").strip(),
        "owner_id": str(conversation.get("owner_id") or "").strip(),
        "account_generation": str(conversation.get("account_generation") or "").strip(),
        "deleted_at": int(now if now is not None else time.time() * 1000),
    }
    if not entry["id"]:
        return
    tombstones = [
        item
        for item in (single_state.get("deletion_tombstones") or [])
        if isinstance(item, dict) and str(item.get("id") or "").strip()
    ]
    tombstones = [item for item in tombstones if item.get("id") != entry["id"]]
    tombstones.append(entry)
    tombstones.sort(key=lambda item: int(item.get("deleted_at") or 0), reverse=True)
    cutoff = int(time.time() * 1000) - _DELETION_TOMBSTONE_TTL_MS
    tombstones = [
        item
        for item in tombstones[: _DELETION_TOMBSTONE_MAX]
        if int(item.get("deleted_at") or 0) >= cutoff
    ]
    single_state["deletion_tombstones"] = tombstones


def _prune_deletion_tombstones(single_state: dict[str, Any]) -> bool:
    """Drop expired/over-cap tombstones; True when the list changed."""
    tombstones = [
        item
        for item in (single_state.get("deletion_tombstones") or [])
        if isinstance(item, dict)
    ]
    if not tombstones:
        return False
    cutoff = int(time.time() * 1000) - _DELETION_TOMBSTONE_TTL_MS
    kept = [
        item
        for item in tombstones
        if int(item.get("deleted_at") or 0) >= cutoff
    ][:_DELETION_TOMBSTONE_MAX]
    if len(kept) != len(tombstones):
        single_state["deletion_tombstones"] = kept
        return True
    return False


def _room_summary_state(room: dict[str, Any]) -> dict[str, Any]:
    summary = room.get("summary") if isinstance(room.get("summary"), dict) else {}
    now = int(time.time() * 1000)
    return {
        "room_id": str(room.get("id") or ""),
        "summary": str(summary.get("text") or ""),
        "summary_through_message_id": str(summary.get("through_message_id") or ""),
        "summary_through_message_timestamp": int(summary.get("through_timestamp") or 0),
        "summarized_turn_count": int(summary.get("turn_count") or 0),
        "status": str(summary.get("status") or "idle"),
        "version": int(summary.get("version") or 0),
        "updated_at": int(summary.get("updated_at") or 0),
        "last_error": summary.get("last_error") if summary.get("last_error") is not None else None,
        "server_time": now,
    }


def _room_workspace_root(room: dict[str, Any]) -> Path:
    conversation_id = str(room.get("conversation_id") or "")
    if not conversation_id:
        raise HTTPException(status_code=409, detail="Room workspace is not ready yet; retry")
    root = _contained_storage_path(conversation_files_root(conversation_id), "workspace")
    root.mkdir(parents=True, exist_ok=True)
    return root


def _room_workspace_child(room: dict[str, Any], relative: str, *, allow_root: bool = False) -> Path:
    root = _room_workspace_root(room)
    cleaned = str(relative or "").strip().replace("\\", "/").lstrip("/")
    parts = [part for part in cleaned.split("/") if part not in {"", ".", ".."}]
    if not parts:
        if allow_root:
            return root
        # The root itself is only addressable by read/list operations; a
        # resolved-to-root delete/rmtree must be refused, not interpreted as
        # "delete the whole workspace".
        raise HTTPException(status_code=400, detail="Workspace path is required")
    try:
        return _contained_storage_path(root, *parts)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail="Invalid workspace path") from exc


def _workspace_listing(target: Path) -> dict[str, Any]:
    entries = []
    try:
        children = sorted(target.iterdir(), key=lambda p: (p.is_file(), p.name.lower()))
    except OSError:
        children = []
    for child in children[:_ROOM_MAX_LIST_ENTRIES]:
        try:
            stat = child.stat()
        except OSError:
            continue
        entries.append(
            {
                "name": child.name,
                "path": child.name,
                "type": "directory" if child.is_dir() else "file",
                "size": stat.st_size if child.is_file() else 0,
                "modified_at": int(stat.st_mtime * 1000),
            }
        )
    return {"entries": entries, "truncated": len(children) > _ROOM_MAX_LIST_ENTRIES}


def _normalized_room_mentions(mentions: Any) -> list[dict[str, Any]]:
    normalized = []
    for item in mentions or []:
        if not isinstance(item, dict):
            continue
        kind = str(item.get("type") or "").strip().lower()
        if kind not in {"agent", "all"}:
            continue
        normalized.append(
            {
                "type": kind,
                "participant_id": str(item.get("participantId") or item.get("participant_id") or "").strip(),
                "display_name": str(item.get("displayName") or item.get("display_name") or "").strip(),
            }
        )
    return normalized


def _resolve_room_mention_profiles(
    room: dict[str, Any],
    mentions: Any,
    known_profiles: set[str],
) -> Optional[list[str]]:
    """Map structured mentions to room profiles; None keeps the default targeting."""

    normalized = _normalized_room_mentions(mentions)
    if not normalized:
        return None
    if any(item["type"] == "all" for item in normalized):
        return list(known_profiles)
    by_profile = {profile.lower(): profile for profile in known_profiles}
    by_name = {
        str(agent.get("name") or "").strip().lower(): str(agent.get("profile") or "")
        for agent in _room_agents_projection(room)
    }
    targets: list[str] = []
    for item in normalized:
        key = item["participant_id"].strip().lower()
        profile = by_profile.get(key) or by_name.get(key)
        if profile and profile not in targets:
            targets.append(profile)
    if not targets:
        # Unresolvable mentions must not silently drop the message: address
        # every member so the turn still runs, mirroring the @all fallback.
        return list(known_profiles)
    return targets


class RoomAgentBody(BaseModel):
    profile: str
    name: str = ""
    description: str = ""


class RoomAgentUpdateBody(BaseModel):
    profile: str = ""
    name: str = ""
    description: str = ""


class RoomConfigBody(BaseModel):
    name: str = ""
    workspace: str = ""
    summary: dict[str, Any] = Field(default_factory=dict)
    context: dict[str, Any] = Field(default_factory=dict)
    settings: dict[str, Any] = Field(default_factory=dict)


class RoomInviteCodeBody(BaseModel):
    invite_code: str = ""


class RoomJoinBody(BaseModel):
    invite_code: str = ""


class RoomTypingBody(BaseModel):
    state: str = "start"
    name: str = ""


class RoomSummaryBody(BaseModel):
    summary: str = ""


class RoomApprovalDecisionBody(BaseModel):
    profile: str = "default"
    expected_revision: int = Field(gt=0)
    decision: str
    payload_digest: str = ""


def _touch_room(room: dict[str, Any]) -> None:
    room["updated_at"] = int(time.time() * 1000)


def _room_detail_response(
    room: dict[str, Any],
    single_state: dict[str, Any],
    owner_id: str,
    offset: int = 0,
    limit: Optional[int] = None,
) -> dict[str, Any]:
    projection = _room_projection(
        room,
        single_state,
        summary=False,
        offset=offset,
        limit=limit,
    )
    projection["agents"] = _room_agents_projection(room)
    projection["members"] = _room_members(room, str(room.get("owner_id") or owner_id))
    projection["typing_users"] = _room_active_typing(room)
    projection["summary_state"] = _room_summary_state(room)
    return {
        "room": projection,
        "messages": projection.get("messages") or [],
        "agents": projection["agents"],
        "members": projection["members"],
        "total": projection.get("message_count", 0),
        "offset": projection.get("offset", offset),
        "limit": projection.get("limit", limit or 0),
        "has_more": projection.get("has_more", False),
        "typing_users": projection["typing_users"],
        "summary_state": projection["summary_state"],
    }


@router.get("/rooms/{room_id}/agents")
def list_room_agents(room_id: str, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _accessible_room_in_state(state, room_id, owner_id, account_generation)
        return {"agents": _room_agents_projection(room)}


@router.post("/rooms/{room_id}/agents")
def add_room_agent(room_id: str, payload: RoomAgentBody, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    profile = payload.profile.strip()
    if not profile:
        raise HTTPException(status_code=400, detail="profile is required")
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        if profile not in {item["name"] for item in available_profiles()}:
            raise HTTPException(status_code=404, detail=f"Unknown Hermes profile: {profile}")
        profiles = room.setdefault("profiles", [])
        if profile not in profiles:
            profiles.append(profile)
        agents = room.get("agents")
        if not isinstance(agents, list):
            agents = []
            room["agents"] = agents
        record = next(
            (
                item
                for item in agents
                if isinstance(item, dict) and str(item.get("profile") or "") == profile
            ),
            None,
        )
        if record is None:
            record = {"profile": profile, "name": "", "description": ""}
            agents.append(record)
        if payload.name.strip():
            record["name"] = payload.name.strip()[:120]
        if payload.description.strip():
            record["description"] = payload.description.strip()[:2_000]
        _touch_room(room)
        save_state(state)
        projection = _room_agents_projection(room)
    return {"agent": next((a for a in projection if a["profile"] == profile), {})}


@router.put("/rooms/{room_id}/agents/{agent_id}")
def update_room_agent(room_id: str, agent_id: str, payload: RoomAgentUpdateBody, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        profiles = list(room.get("profiles") or [])
        current = _agent_profile_from_identifier(agent_id, profiles)
        if current is None:
            raise HTTPException(status_code=404, detail="Room agent not found")
        new_profile = payload.profile.strip()
        if new_profile and new_profile != current:
            if new_profile not in {item["name"] for item in available_profiles()}:
                raise HTTPException(status_code=404, detail=f"Unknown Hermes profile: {new_profile}")
            if new_profile in profiles:
                raise HTTPException(
                    status_code=409,
                    detail=f"Room already contains profile {new_profile}",
                )
            profiles[profiles.index(current)] = new_profile
            room["profiles"] = profiles
            current = new_profile
        agents = room.get("agents")
        if not isinstance(agents, list):
            agents = []
            room["agents"] = agents
        record = next(
            (
                item
                for item in agents
                if isinstance(item, dict) and str(item.get("profile") or "") == current
            ),
            None,
        )
        if record is None:
            record = {"profile": current, "name": "", "description": ""}
            agents.append(record)
        if payload.name.strip():
            record["name"] = payload.name.strip()[:120]
        if payload.description.strip():
            record["description"] = payload.description.strip()[:2_000]
        _touch_room(room)
        save_state(state)
        agents_projection = _room_agents_projection(room)
    return {
        "agent": next((a for a in agents_projection if a["profile"] == current), {}),
        "agents": agents_projection,
        "members": _room_members(room, owner_id),
    }


def _agent_profile_from_identifier(agent_id: str, profiles: list[str]) -> Optional[str]:
    cleaned = str(agent_id or "").strip()
    for profile in profiles:
        if cleaned in {profile, f"profile:{profile}"} or cleaned.endswith(f":profile:{profile}"):
            return profile
    lowered = cleaned.lower()
    for profile in profiles:
        if profile.lower() == lowered:
            return profile
    return None


@router.delete("/rooms/{room_id}/agents/{agent_id}")
def remove_room_agent(room_id: str, agent_id: str, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        profiles = list(room.get("profiles") or [])
        current = _agent_profile_from_identifier(agent_id, profiles)
        if current is None:
            raise HTTPException(status_code=404, detail="Room agent not found")
        if len(profiles) <= 1:
            raise HTTPException(status_code=409, detail="A room must keep at least one agent")
        profiles.remove(current)
        room["profiles"] = profiles
        agents = room.get("agents")
        if isinstance(agents, list):
            room["agents"] = [
                item
                for item in agents
                if not (isinstance(item, dict) and str(item.get("profile") or "") == current)
            ]
        _touch_room(room)
        save_state(state)
        agents_projection = _room_agents_projection(room)
    return {
        "success": True,
        "agents": agents_projection,
        "members": _room_members(room, owner_id),
    }


@router.put("/rooms/{room_id}")
def update_room_config(room_id: str, payload: RoomConfigBody, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        if payload.name.strip():
            room["name"] = payload.name.strip()[:200]
        if payload.workspace.strip():
            room["workspace"] = payload.workspace.strip()[:500]
        summary_config = dict(room.get("summary_config") or {})
        for field in _ROOM_SUMMARY_FIELDS:
            if field in payload.summary:
                summary_config[field] = payload.summary[field]
        room["summary_config"] = summary_config
        context_config = dict(room.get("context_config") or {})
        for field in _ROOM_CONTEXT_FIELDS:
            if field in payload.context:
                try:
                    context_config[field] = max(0, int(payload.context[field]))
                except (TypeError, ValueError):
                    continue
        room["context_config"] = context_config
        settings = dict(room.get("settings") or {})
        for field in _ROOM_SETTINGS_FIELDS:
            if field in payload.settings:
                settings[field] = payload.settings[field]
        room["settings"] = settings
        _touch_room(room)
        save_state(state)
        single_state = load_single_state()
        response = _room_detail_response(room, single_state, owner_id)
        conversation_id = str(room.get("conversation_id") or "")
    _notify_hosted_update(conversation_id)
    return response


@router.post("/rooms/{room_id}/invite-code")
def rotate_room_invite_code(room_id: str, payload: RoomInviteCodeBody, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        requested = payload.invite_code.strip()
        code = requested[:64] if requested else _generate_room_invite_code()
        existing_codes = {
            str(item.get("invite_code") or "")
            for item in state.get("rooms") or []
            if isinstance(item, dict) and item.get("id") != room_id
        }
        if requested and code in existing_codes:
            raise HTTPException(status_code=409, detail="Invite code is already used by another room")
        if not requested:
            # Generated codes must stay unique across every room in the file.
            existing = {
                str(item.get("invite_code") or "")
                for item in state.get("rooms") or []
                if isinstance(item, dict)
            }
            while code in existing:
                code = _generate_room_invite_code()
        room["invite_code"] = code
        _touch_room(room)
        save_state(state)
    return {"success": True, "invite_code": code}


@router.post("/rooms/join")
def join_room_by_code(payload: RoomJoinBody, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    code = payload.invite_code.strip()
    if not code:
        raise HTTPException(status_code=400, detail="invite_code is required")
    with _STATE_LOCK:
        state = load_state()
        room = next(
            (
                item
                for item in state.get("rooms") or []
                if isinstance(item, dict) and str(item.get("invite_code") or "") == code
            ),
            None,
        )
        if not isinstance(room, dict):
            raise HTTPException(status_code=404, detail="Invite code not found")
        room_owner = str(room.get("owner_id") or "").strip()
        if room_owner == owner_id or _room_is_member(room, owner_id):
            _touch_room(room)
            save_state(state)
        else:
            members = room.setdefault("members", [])
            members.append(
                {
                    "id": f"member-{uuid.uuid4().hex[:10]}",
                    "user_id": owner_id,
                    "name": "Member",
                    "role": "member",
                    "joined_at": int(time.time() * 1000),
                }
            )
            _touch_room(room)
            save_state(state)
        single_state = load_single_state()
        response = _room_detail_response(room, single_state, room_owner)
        conversation_id = str(room.get("conversation_id") or "")
    _notify_hosted_update(conversation_id)
    return response


@router.delete("/rooms/{room_id}/members/{member_user_id}")
def remove_room_member(room_id: str, member_user_id: str, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        target = str(member_user_id or "").strip()
        if not target or target == str(room.get("owner_id") or ""):
            raise HTTPException(status_code=409, detail="The room owner cannot be removed")
        members = [m for m in (room.get("members") or []) if isinstance(m, dict)]
        remaining = [m for m in members if str(m.get("user_id") or "") != target]
        if len(remaining) == len(members):
            raise HTTPException(status_code=404, detail="Room member not found")
        room["members"] = remaining
        _touch_room(room)
        save_state(state)
        agents_projection = _room_agents_projection(room)
        conversation_id = str(room.get("conversation_id") or "")
    _notify_hosted_update(conversation_id)
    return {
        "success": True,
        "agents": agents_projection,
        "members": _room_members(room, owner_id),
    }


@router.delete("/rooms/{room_id}/messages/{message_id}")
def retract_room_message(room_id: str, message_id: str, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _accessible_room_in_state(state, room_id, owner_id, account_generation)
        conversation_id = str(room.get("conversation_id") or "")
        if not conversation_id:
            raise HTTPException(status_code=409, detail="Room transcript is not ready yet; retry")
        room_owner = str(room.get("owner_id") or owner_id)
        single_state = load_single_state()
        conversation = next(
            (
                item
                for item in single_state.get("conversations") or []
                if isinstance(item, dict) and str(item.get("id") or "") == conversation_id
            ),
            None,
        )
        if not isinstance(conversation, dict):
            raise HTTPException(status_code=404, detail="Message not found")
        message = next(
            (
                item
                for item in conversation.get("messages") or []
                if isinstance(item, dict) and str(item.get("id") or "") == str(message_id)
            ),
            None,
        )
        if not isinstance(message, dict):
            # Older tails may live in the hydrated sidecar.
            hydrated = _hydrate_conversation_history(conversation)
            message = next(
                (
                    item
                    for item in hydrated.get("messages") or []
                    if isinstance(item, dict) and str(item.get("id") or "") == str(message_id)
                ),
                None,
            )
            if isinstance(message, dict):
                conversation = hydrated
        if not isinstance(message, dict):
            raise HTTPException(status_code=404, detail="Message not found")
        meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
        sender = str(meta.get("sender_id") or "")
        is_own = str(message.get("role") or "") == "user" and (
            sender == owner_id
            or (not sender and room_owner == owner_id)
        )
        is_owner = room_owner == owner_id
        if not (is_own or is_owner):
            raise HTTPException(status_code=403, detail="Only the sender or room owner can retract")
        if meta.get("retracted"):
            save_single_state(single_state)
            return {"ok": True, "retracted": True, "replayed": True}
        message["content"] = "[已撤回]"
        message["meta"] = {**meta, "retracted": True, "retracted_at": int(time.time() * 1000)}
        conversation["updated_at"] = int(time.time() * 1000)
        save_single_state(single_state)
    _notify_hosted_update(conversation_id)
    return {"ok": True, "retracted": True, "replayed": False}


@router.post("/rooms/{room_id}/typing")
def set_room_typing(room_id: str, payload: RoomTypingBody, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    conversation_id = ""
    with _STATE_LOCK:
        state = load_state()
        room = _accessible_room_in_state(state, room_id, owner_id, account_generation)
        conversation_id = str(room.get("conversation_id") or "")
        typing = room.get("typing")
        if not isinstance(typing, dict):
            typing = {}
            room["typing"] = typing
        member_key = owner_id
        if str(payload.state or "").strip().lower() == "stop":
            typing.pop(member_key, None)
        else:
            display = payload.name.strip()[:120] or "Member"
            typing[member_key] = {
                "id": member_key,
                "name": display,
                "expires_at": int(time.time() * 1000) + _ROOM_TYPING_TTL_MS,
            }
        _touch_room(room)
        save_state(state)
    if conversation_id:
        # Watchers on the hosted-event stream re-read the room projection, so
        # typing presence reaches every online member without a poll tick.
        _notify_hosted_update(conversation_id)
    return {"ok": True}



_ROOM_SUMMARY_MIN_EVERY_TURNS = 1
_ROOM_SUMMARY_DEFAULT_EVERY_TURNS = 20
_ROOM_SUMMARY_TRANSCRIPT_TAIL = 40
_ROOM_SUMMARY_ATTEMPT_BACKOFF_MS = 60_000
_ROOM_SUMMARY_STALE_LEASE_MS = 10 * 60_000
_ROOM_SUMMARY_THREADS: dict[str, threading.Thread] = {}
_ROOM_SUMMARY_THREADS_LOCK = threading.Lock()


def _room_terminal_turn_count(conversation: Optional[dict[str, Any]]) -> int:
    """Number of hosted turns that have reached a terminal state."""
    if not isinstance(conversation, dict):
        return 0
    return sum(
        1
        for run in (conversation.get("hosted_turns") or {}).values()
        if isinstance(run, dict)
        and str(run.get("status") or "queued") in _HOSTED_TERMINAL_STATUSES
    )


def _room_summary_due(
    room: dict[str, Any],
    conversation: Optional[dict[str, Any]],
) -> bool:
    config = room.get("summary_config") if isinstance(room.get("summary_config"), dict) else {}
    profile = str(config.get("profile") or "").strip()
    if not profile:
        return False
    try:
        every = max(
            _ROOM_SUMMARY_MIN_EVERY_TURNS,
            int(config.get("every_turns") or _ROOM_SUMMARY_DEFAULT_EVERY_TURNS),
        )
    except (TypeError, ValueError):
        every = _ROOM_SUMMARY_DEFAULT_EVERY_TURNS
    summary = room.get("summary") if isinstance(room.get("summary"), dict) else {}
    status = str(summary.get("status") or "idle")
    if status == "summarizing":
        lease_started = int(summary.get("lease_started_at") or 0)
        if lease_started and int(time.time() * 1000) - lease_started < _ROOM_SUMMARY_STALE_LEASE_MS:
            return False
    last_attempt = int(summary.get("last_attempt_at") or 0)
    if last_attempt and int(time.time() * 1000) - last_attempt < _ROOM_SUMMARY_ATTEMPT_BACKOFF_MS:
        return False
    terminal_now = _room_terminal_turn_count(conversation)
    anchor = int(summary.get("turn_count") or 0)
    return terminal_now - anchor >= every


def _room_summary_prompt(room: dict[str, Any], conversation: dict[str, Any]) -> str:
    messages = [
        item
        for item in (conversation.get("messages") or [])
        if isinstance(item, dict)
    ]
    tail = messages[-_ROOM_SUMMARY_TRANSCRIPT_TAIL:]
    lines = []
    for message in tail:
        role = "User" if str(message.get("role") or "") == "user" else "Agent"
        name = str(message.get("name") or "").strip()
        content = str(message.get("content") or "").strip()
        if not content:
            continue
        lines.append(f"[{role}{':' + name if name and role == 'Agent' else ''}] {content[:1200]}")
    transcript = "\n".join(lines) or "(no messages yet)"
    return (
        "You are the summarizer for a team chat room. Summarize the recent "
        "conversation below into a concise rolling summary in the conversation "
        "language: key decisions, current task states, open questions, and "
        "each member's latest responsibility. Keep it under 2500 characters, "
        "plain text, no headings.\n\n"
        f"Room: {str(room.get('name') or '')}\n\n{transcript}"
    )


def _summarize_room_async(
    room_id: str,
    conversation_id: str,
    owner_id: str,
    account_generation: str,
) -> None:
    """Single-flight background summarizer; result persists on room.summary."""

    with _ROOM_SUMMARY_THREADS_LOCK:
        existing = _ROOM_SUMMARY_THREADS.get(room_id)
        if existing is not None and existing.is_alive():
            return

        def worker() -> None:
            try:
                profile = ""
                prompt = ""
                with _STATE_LOCK:
                    state = load_state()
                    room = _owned_room_in_state(
                        state, room_id, owner_id, account_generation
                    )
                    single_state = load_single_state()
                    conversation = next(
                        (
                            item
                            for item in single_state.get("conversations") or []
                            if isinstance(item, dict)
                            and str(item.get("id") or "") == conversation_id
                        ),
                        None,
                    )
                    if not isinstance(conversation, dict) or not _room_summary_due(
                        room, conversation
                    ):
                        return
                    config = room.get("summary_config") or {}
                    profile = str(config.get("profile") or "").strip()
                    if not profile:
                        return
                    prompt = _room_summary_prompt(room, conversation)
                    summary = room.get("summary")
                    if not isinstance(summary, dict):
                        summary = {}
                        room["summary"] = summary
                    summary["status"] = "summarizing"
                    summary["lease_started_at"] = int(time.time() * 1000)
                    summary["last_attempt_at"] = int(time.time() * 1000)
                    save_state(state)

                text = run_single_turn(profile, prompt)
                clean = str(text or "").strip()
                if not clean:
                    raise RuntimeError("summarizer returned empty output")

                with _STATE_LOCK:
                    state = load_state()
                    room = _owned_room_in_state(
                        state, room_id, owner_id, account_generation
                    )
                    single_state = load_single_state()
                    conversation = next(
                        (
                            item
                            for item in single_state.get("conversations") or []
                            if isinstance(item, dict)
                            and str(item.get("id") or "") == conversation_id
                        ),
                        None,
                    )
                    summary = room.get("summary")
                    if not isinstance(summary, dict):
                        summary = {}
                        room["summary"] = summary
                    summary.update(
                        {
                            "text": clean[:20_000],
                            "status": "success",
                            "version": int(summary.get("version") or 0) + 1,
                            "updated_at": int(time.time() * 1000),
                            "last_error": None,
                            "turn_count": _room_terminal_turn_count(conversation),
                            "through_message_id": "",
                        }
                    )
                    summary.pop("lease_started_at", None)
                    _touch_room(room)
                    save_state(state)
                _notify_hosted_update(conversation_id)
            except Exception as exc:
                try:
                    with _STATE_LOCK:
                        state = load_state()
                        # Lenient by-id lookup: the ownership fence may have
                        # legitimately changed mid-run (that 404 was the
                        # original exception); still verify the owner before
                        # recording so a re-registered account's room is never
                        # touched by the previous era's summarizer.
                        room = next(
                            (
                                item
                                for item in state.get("rooms") or []
                                if isinstance(item, dict)
                                and item.get("id") == room_id
                                and str(item.get("owner_id") or "").strip() == owner_id
                            ),
                            None,
                        )
                        if room is None:
                            return
                        summary = room.get("summary")
                        if not isinstance(summary, dict):
                            summary = {}
                            room["summary"] = summary
                        summary["status"] = "failed"
                        summary["last_error"] = str(exc)[:1000]
                        summary["updated_at"] = int(time.time() * 1000)
                        summary.pop("lease_started_at", None)
                        save_state(state)
                except Exception:
                    pass
            finally:
                with _ROOM_SUMMARY_THREADS_LOCK:
                    if _ROOM_SUMMARY_THREADS.get(room_id) is threading.current_thread():
                        _ROOM_SUMMARY_THREADS.pop(room_id, None)

        thread = threading.Thread(
            target=worker,
            name=f"hermes-room-summary-{room_id}",
            daemon=True,
        )
        _ROOM_SUMMARY_THREADS[room_id] = thread
    thread.start()


@router.get("/rooms/{room_id}/summary")
def get_room_summary(room_id: str, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    conversation_id = ""
    due = False
    with _STATE_LOCK:
        state = load_state()
        room = _accessible_room_in_state(state, room_id, owner_id, account_generation)
        conversation_id = str(room.get("conversation_id") or "")
        if conversation_id:
            single_state = load_single_state()
            conversation = next(
                (
                    item
                    for item in single_state.get("conversations") or []
                    if isinstance(item, dict)
                    and str(item.get("id") or "") == conversation_id
                ),
                None,
            )
            due = _room_summary_due(room, conversation)
            summary = _room_summary_state(room)
            config = dict(room.get("summary_config") or {})
        else:
            summary = _room_summary_state(room)
            config = dict(room.get("summary_config") or {})
    if due and conversation_id:
        # The client polls this endpoint; crossing the every_turns threshold
        # here dispatches the single-flight background summarizer.
        _summarize_room_async(
            room_id,
            conversation_id,
            str(room.get("owner_id") or owner_id),
            account_generation,
        )
    return {
        "summary": summary,
        "anchor": None,
        "config": config,
    }


@router.put("/rooms/{room_id}/summary")
def update_room_summary(room_id: str, payload: RoomSummaryBody, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        summary = room.get("summary")
        if not isinstance(summary, dict):
            summary = {}
            room["summary"] = summary
        summary.update(
            {
                "text": payload.summary[:20_000],
                "status": "success",
                "version": int(summary.get("version") or 0) + 1,
                "updated_at": int(time.time() * 1000),
                "last_error": None,
            }
        )
        _touch_room(room)
        save_state(state)
    return {"summary": _room_summary_state(room)}


@router.post("/rooms/{room_id}/clear")
def clear_room_context(room_id: str, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    conversation_id = ""
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        conversation_id = str(room.get("conversation_id") or "")
        if conversation_id:
            single_state = load_single_state()
            conversation = next(
                (
                    item
                    for item in single_state.get("conversations") or []
                    if isinstance(item, dict) and str(item.get("id") or "") == conversation_id
                ),
                None,
            )
            if isinstance(conversation, dict):
                active_turns = [
                    turn_id
                    for turn_id, run in (conversation.get("hosted_turns") or {}).items()
                    if isinstance(run, dict)
                    and str(run.get("status") or "queued") not in _HOSTED_TERMINAL_STATUSES
                ]
                if active_turns:
                    # Plain-string detail: the iOS error surface renders
                    # string details verbatim and drops structured objects.
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            "Cancel or wait for the running turn before clearing. "
                            f"Active turns: {', '.join(active_turns[:10])}"
                        ),
                    )
                conversation["messages"] = []
                conversation["session_entries"] = []
                conversation["session_entry_cursor"] = 0
                conversation["session_entry_leaf_id"] = ""
                conversation["history_message_count"] = 0
                conversation["history_last_message"] = None
                conversation["history_session_entry_count"] = 0
                conversation["history_complete"] = True
                conversation["updated_at"] = int(time.time() * 1000)
                save_single_state(single_state)
            # The retained history sidecar is the durable transcript: without
            # removing it, the very next detail read re-hydrates everything
            # the caller just asked to clear.
            sidecar = _conversation_history_path(conversation_id)
            if sidecar is not None:
                try:
                    sidecar.unlink()
                except FileNotFoundError:
                    pass
                except OSError as exc:
                    raise HTTPException(
                        status_code=503,
                        detail={
                            "reason": "room_clear_pending",
                            "message": "Room history clear is pending; retry.",
                        },
                    ) from exc
        room["mailbox"] = []
        _touch_room(room)
        save_state(state)
    if conversation_id:
        _notify_hosted_update(conversation_id)
    return {"success": True}


def _room_workspace_read_allowed(room: dict[str, Any], owner_id: str) -> bool:
    if str(room.get("owner_id") or "") == owner_id:
        return True
    settings = room.get("settings") if isinstance(room.get("settings"), dict) else {}
    return bool(int(settings.get("allow_remote_workspace_access") or 0))


@router.get("/rooms/{room_id}/workspace/files")
def list_room_workspace_files(room_id: str, request: Request, path: str = ""):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _accessible_room_in_state(state, room_id, owner_id, account_generation)
        if not _room_workspace_read_allowed(room, owner_id):
            raise HTTPException(status_code=403, detail="Room workspace access is not enabled for members")
        target = _room_workspace_child(room, path, allow_root=True)
    if not target.is_dir():
        raise HTTPException(status_code=404, detail="Workspace path not found")
    return _workspace_listing(target)


@router.get("/rooms/{room_id}/workspace/file")
def read_room_workspace_file(room_id: str, request: Request, path: str = ""):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _accessible_room_in_state(state, room_id, owner_id, account_generation)
        if not _room_workspace_read_allowed(room, owner_id):
            raise HTTPException(status_code=403, detail="Room workspace access is not enabled for members")
        target = _room_workspace_child(room, path)
    if not target.is_file():
        raise HTTPException(status_code=404, detail="Workspace file not found")
    try:
        content = target.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        raise HTTPException(status_code=422, detail="Workspace file is not readable text") from exc
    return {
        "path": str(path),
        "name": target.name,
        "content": content,
        "size": len(content.encode("utf-8")),
        "modified_at": int(target.stat().st_mtime * 1000),
    }


class RoomWorkspaceWriteBody(BaseModel):
    content: str = ""
    path: str = ""


class RoomWorkspaceTwoPathBody(BaseModel):
    old_path: str = ""
    new_path: str = ""
    source_path: str = ""
    destination_path: str = ""


@router.put("/rooms/{room_id}/workspace/file")
def write_room_workspace_file(room_id: str, payload: RoomWorkspaceWriteBody, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    if len(payload.content.encode("utf-8")) > 2_000_000:
        raise HTTPException(status_code=413, detail="Workspace file is too large")
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        # Resolve + validate containment under the lock; the file IO runs on
        # the immutable per-conversation workspace root, outside the lock
        # (_STATE_LOCK also holds the cross-process lifecycle OS lock).
        target = _room_workspace_child(room, payload.path)
    target.parent.mkdir(parents=True, exist_ok=True)
    tmp = target.with_name(target.name + ".tmp-" + uuid.uuid4().hex[:8])
    tmp.write_text(payload.content, encoding="utf-8")
    os.replace(tmp, target)
    return {"ok": True, "path": str(payload.path)}


@router.post("/rooms/{room_id}/workspace/file")
def mkdir_room_workspace_path(room_id: str, payload: RoomWorkspaceWriteBody, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        target = _room_workspace_child(room, payload.path)
    target.mkdir(parents=True, exist_ok=True)
    return {"ok": True, "path": str(payload.path)}


@router.delete("/rooms/{room_id}/workspace/file")
def delete_room_workspace_path(room_id: str, request: Request, path: str = "", recursive: bool = False):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        target = _room_workspace_child(room, path)
    if not target.exists():
        raise HTTPException(status_code=404, detail="Workspace path not found")
    try:
        if target.is_dir():
            if recursive:
                shutil.rmtree(target)
            else:
                target.rmdir()
        else:
            target.unlink()
    except FileNotFoundError as exc:
        # A concurrent delete won the race once the state lock was released.
        raise HTTPException(status_code=404, detail="Workspace path not found") from exc
    return {"ok": True}


@router.post("/rooms/{room_id}/workspace/rename")
def rename_room_workspace_path(room_id: str, payload: RoomWorkspaceTwoPathBody, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        source = _room_workspace_child(room, payload.old_path)
        destination = _room_workspace_child(room, payload.new_path)
    if not source.exists():
        raise HTTPException(status_code=404, detail="Workspace path not found")
    try:
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.move(str(source), str(destination))
    except FileNotFoundError as exc:
        raise HTTPException(status_code=404, detail="Workspace path not found") from exc
    return {"ok": True}


@router.post("/rooms/{room_id}/workspace/copy")
def copy_room_workspace_path(room_id: str, payload: RoomWorkspaceTwoPathBody, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        source = _room_workspace_child(room, payload.source_path or payload.old_path)
        destination = _room_workspace_child(room, payload.destination_path or payload.new_path)
    if not source.exists():
        raise HTTPException(status_code=404, detail="Workspace path not found")
    destination.parent.mkdir(parents=True, exist_ok=True)
    if source.is_dir():
        shutil.copytree(source, destination, dirs_exist_ok=True)
    else:
        shutil.copy2(source, destination)
    return {"ok": True}


@router.get("/rooms/{room_id}/approvals")
def list_room_approvals(room_id: str, request: Request):
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        # Owner-only: the pending write-approval store belongs to the host
        # ACCOUNT, not to the room. A joined member enumerating or deciding
        # those records was a confused-deputy onto the host's memory/skills.
        room = _owned_room_in_state(state, room_id, owner_id, account_generation)
        profiles = list(dict.fromkeys(room.get("profiles") or [])) or ["default"]
    approvals: list[dict[str, Any]] = []
    for profile in profiles:
        normalized, _home, store = _mobile_approval_store(profile)
        try:
            approvals.extend(
                store.list(
                    owner_id=owner_id,
                    profile=normalized,
                    states=("pending",),
                    limit=50,
                )
            )
        except Exception:
            continue
    return {"approvals": approvals}


@router.post("/rooms/{room_id}/approvals/{approval_id}")
def decide_room_approval(room_id: str, approval_id: str, payload: RoomApprovalDecisionBody, request: Request):
    from hermes_cli.account_write_approvals import (
        ApprovalConflict,
        ApprovalPayloadMismatch,
    )

    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_state()
        # Owner-only, mirroring list_room_approvals.
        _owned_room_in_state(state, room_id, owner_id, account_generation)
    normalized, _home, store = _mobile_approval_store(payload.profile)
    try:
        record = store.claim_decision(
            owner_id=owner_id,
            profile=normalized,
            approval_id=approval_id,
            expected_revision=payload.expected_revision,
            decision=payload.decision,
            decision_by=owner_id,
            idempotency_key=f"room:{room_id}:{approval_id}:{payload.decision}:{payload.expected_revision}",
            payload_digest=payload.payload_digest,
        )
    except ApprovalPayloadMismatch as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except ApprovalConflict as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    if payload.decision.strip().lower() == "reject":
        return {"approval": record}
    if not record.get("_claim_acquired"):
        return {"approval": record}
    try:
        record = _finish_mobile_write_approval_claim(
            profile=normalized,
            store=store,
            record=record,
        )
    except ApprovalConflict as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    return {"approval": record}


def _profile_runner_result_error(result: Any) -> str:
    text = _structured_text(result)
    if not text:
        return ""
    try:
        data = json.loads(text)
    except (TypeError, ValueError):
        data = None
    if isinstance(data, dict):
        if data.get("error"):
            return _structured_text(data.get("error"))
        if data.get("success") is False:
            return _structured_text(data.get("message") or text)
    if re.match(r"^(?:error|failed|exception)\s*[:：]", text, re.IGNORECASE):
        return text
    return ""


def _discover_profile_toolsets(
    config: dict[str, Any],
    capability_hints: Optional[list[str]] = None,
    *,
    allow_tools: bool = True,
) -> list[str]:
    """Connect only route-selected MCPs before taking the hosted tool snapshot."""

    if not allow_tools:
        return []

    backend = _backend_api()
    hints = [str(item) for item in (capability_hints or []) if str(item).strip()]
    _refresh_mcp_provider_catalog(hints)
    configured = config.get("mcp_servers") if isinstance(config, dict) else {}
    configured = configured if isinstance(configured, dict) else {}
    full_static = str(os.environ.get("HERMES_FULL_TOOL_DEFINITIONS") or "").strip().lower() in {
        "1", "true", "yes", "on"
    }
    if full_static:
        # Match the official 0.19 lazy path: register every cached/static MCP
        # schema into the agent snapshot, but do not connect or discover any
        # service here. A registered handler starts its service only when the
        # model actually calls that tool; the supervisor then reaps it after
        # its configured idle window.
        from tools.mcp_tool import register_mcp_servers

        register_mcp_servers({
            name: {**server, "lazy": True}
            for name, server in configured.items()
            if isinstance(server, dict)
        })
        selected = {
            str(name)
            for name, server in configured.items()
            if isinstance(server, dict)
            and str(name).strip()
            and str(server.get("enabled", True)).strip().lower()
            not in {"0", "false", "no", "off"}
        }
        live_selected = set(selected)
    else:
        selected = backend.select_mcp_servers_for_capabilities(configured, hints)
        backend.discover_mcp_tools(capability_hints=hints)
        live_selected = {
            snapshot.name
            for snapshot in backend.get_mcp_availability()
            if (snapshot.live or getattr(snapshot, "state", "") == "ready")
            and snapshot.registered_tools
            and snapshot.name in selected
        }
    for selected_name in sorted(live_selected):
        _observe_runtime_provider(
            provider_id=_runtime_provider_id("mcp", selected_name),
            interface_key=f"mcp:{selected_name}",
            health="healthy",
            metadata={"selected": True, "capability_hints": hints},
        )
    base_toolsets = set(
        backend._get_platform_tools(
            config,
            "cli",
            include_default_mcp_servers=False,
        )
    ) - backend.enabled_mcp_server_names(config)
    # The chat plan is first-class product state. The todo tool is local,
    # credential-free, and its schema already limits use to multi-step work.
    base_toolsets.add("todo")
    return sorted(base_toolsets | live_selected)


def _profile_event_runner_main() -> int:
    """Child-process entrypoint that emits only structured Hermes JSONL events."""
    real_stdout = sys.stdout
    emit_lock = threading.Lock()
    agent_ref: list[Any] = [None]
    last_model_witness_ref = ""

    def emit(event_type: str, payload: Optional[dict[str, Any]] = None) -> None:
        nonlocal last_model_witness_ref
        current_agent = agent_ref[0]
        if current_agent is not None and event_type != "provider.registered":
            current_provider = str(getattr(current_agent, "provider", "") or "").strip()
            current_model = str(getattr(current_agent, "model", "") or "").strip()
            if current_provider:
                current_witness = _observe_runtime_provider(
                    provider_id=_runtime_provider_id(
                        "model",
                        f"{current_provider}:{current_model or 'default'}",
                    ),
                    interface_key="model:hosted",
                    health="healthy",
                    metadata={
                        "provider": current_provider,
                        "model": current_model,
                    },
                )
                current_ref = _provider_witness_ref(current_witness)
                if current_ref and current_ref != last_model_witness_ref:
                    last_model_witness_ref = current_ref
                    witness_event = {
                        "type": "provider.registered",
                        "payload": current_witness or {},
                    }
                    with emit_lock:
                        real_stdout.write(
                            json.dumps(
                                witness_event,
                                ensure_ascii=False,
                                separators=(",", ":"),
                                default=str,
                            )
                            + "\n"
                        )
                        real_stdout.flush()
        event = {"type": event_type, "payload": payload or {}}
        line = json.dumps(event, ensure_ascii=False, separators=(",", ":"), default=str)
        with emit_lock:
            real_stdout.write(line + "\n")
            real_stdout.flush()

    try:
        request_payload = json.loads(sys.stdin.read() or "{}")
        prompt = _structured_text(request_payload.get("prompt"))
        runner_action = _structured_text(
            request_payload.get("action") or "chat"
        ).strip().lower()
        focus_topic = _structured_text(request_payload.get("focus_topic")).strip()
        capability_hints = [
            str(item)
            for item in request_payload.get("capability_hints") or []
            if str(item).strip()
        ]
        allow_tools = _coerce_flag(request_payload.get("allow_tools"), default=True)
        requested_session_id = _structured_text(
            request_payload.get("session_id")
        ).strip()
        if runner_action not in {"chat", "compress"}:
            raise ValueError("unsupported profile runner action")
        if runner_action == "chat" and not prompt:
            raise ValueError("任务内容为空")
        if runner_action == "compress" and not requested_session_id:
            raise ValueError("session_id is required for compression")

        os.environ["HERMES_YOLO_MODE"] = "1"
        os.environ["HERMES_ACCEPT_HOOKS"] = "1"
        from hermes_runtime.config import load_config
        from hermes_cli.env_loader import load_hermes_dotenv
        from hermes_cli.fallback_config import get_fallback_chain
        from hermes_cli.runtime_provider import resolve_runtime_provider
        from hermes_runtime.session_context import declare_stateless_channel
        from hermes_state import SessionDB
        from run_agent import AIAgent

        # This process exits as soon as the hosted turn finishes and therefore
        # has no channel capable of delivering a detached subagent completion.
        # Force delegate_task onto its synchronous path before AIAgent snapshots
        # runtime capabilities, otherwise background child results are lost.
        declare_stateless_channel()

        load_hermes_dotenv(hermes_home=os.environ.get("HERMES_HOME"))
        cfg = load_config()
        # This runner is a fresh process for a hosted chat turn. MCP names in
        # enabled_toolsets are only registry aliases; discovery must connect
        # and register their schemas before AIAgent snapshots its tool list.
        enabled_toolsets = _discover_profile_toolsets(
            cfg,
            capability_hints,
            allow_tools=allow_tools,
        )
        backend = _backend_api()
        selected_mcp_names = set() if not allow_tools else set(
            backend.select_mcp_servers_for_capabilities(
                cfg.get("mcp_servers") or {},
                capability_hints,
            )
        )
        mcp_availability = [
            snapshot.as_dict()
            for snapshot in backend.get_mcp_availability()
            if snapshot.name in selected_mcp_names
        ]
        for snapshot in mcp_availability:
            mcp_name = str(snapshot.get("name") or "").strip()
            if not mcp_name:
                continue
            mcp_witness = _observe_runtime_provider(
                provider_id=_runtime_provider_id("mcp", mcp_name),
                interface_key=f"mcp:{mcp_name}",
                health=(
                    "healthy"
                    if bool(snapshot.get("live"))
                    or str(snapshot.get("state") or "").lower() in {"ready", "connected"}
                    else str(snapshot.get("state") or "unknown")
                ),
                metadata={
                    "mcp_name": mcp_name,
                    "registered_tools": list(snapshot.get("registered_tools") or ())[:100],
                },
            )
            if mcp_witness:
                emit("provider.registered", mcp_witness)
        managed_mcp_servers = sorted(
            name
            for name, server in (cfg.get("mcp_servers") or {}).items()
            if isinstance(server, dict)
            and server.get("enabled", True) is not False
            and name in enabled_toolsets
        )
        if managed_mcp_servers and runner_action == "chat":
            prompt = (
                f"{prompt}\n\nRuntime MCP capabilities currently connected: "
                f"{', '.join(managed_mcp_servers)}. When the user needs current "
                "iPhone, Apple Watch, location, health, weather, calendar, reminder, "
                "or device data, call the matching mcp__ tool before answering. "
                "Do not claim these MCPs are absent unless the matching tool call "
                "itself returns an availability error."
            )
        model_cfg = cfg.get("model") or {}
        if isinstance(model_cfg, str):
            model = model_cfg
            provider = None
        else:
            model = str(model_cfg.get("default") or model_cfg.get("model") or "")
            provider = str(model_cfg.get("provider") or "").strip() or None
        runtime = resolve_runtime_provider(
            requested=provider,
            target_model=model or None,
        )
        model_provider_id = _runtime_provider_id(
            "model",
            f"{str(getattr(runtime, 'provider', None) or provider or 'default')}:{model or 'default'}",
        )
        model_witness = _observe_runtime_provider(
            provider_id=model_provider_id,
            interface_key="model:hosted",
            health="healthy",
            metadata={
                "provider": str(getattr(runtime, "provider", None) or provider or "default"),
                "model": model or "",
                "generation": str(request_payload.get("account_generation") or ""),
            },
        )
        if model_witness:
            last_model_witness_ref = _provider_witness_ref(model_witness)
            emit("provider.registered", model_witness)
        fallback = get_fallback_chain(cfg)
        tool_started_at: dict[str, float] = {}

        def tool_start(tool_id: str, name: str, args: Any) -> None:
            tool_started_at[str(tool_id)] = time.monotonic()
            emit(
                "tool.start",
                {
                    "tool_id": str(tool_id or ""),
                    "name": str(name or "工具调用"),
                    "args": args,
                    "started_at": int(time.time() * 1000),
                },
            )

        def tool_complete(tool_id: str, name: str, args: Any, result: Any) -> None:
            started = tool_started_at.pop(str(tool_id), time.monotonic())
            error = _profile_runner_result_error(result)
            emit(
                "tool.complete",
                {
                    "tool_id": str(tool_id or ""),
                    "name": str(name or "工具调用"),
                    "args": args,
                    "result_text": _structured_text(result),
                    "error": error,
                    "duration_s": max(0.0, time.monotonic() - started),
                    "ended_at": int(time.time() * 1000),
                },
            )

        def tool_progress(
            event_type: str,
            name: Optional[str] = None,
            preview: Optional[str] = None,
            args: Any = None,
            **kwargs: Any,
        ) -> None:
            if event_type in {"tool.started", "tool.completed", "_thinking"}:
                return
            if event_type == "reasoning.available":
                # This fallback is assistant content, not a distinct thought.
                # Genuine reasoning is emitted by the dedicated callbacks.
                return
            if event_type.startswith("subagent.") or event_type == "subagent_progress":
                normalized_type = (
                    "subagent.progress"
                    if event_type == "subagent_progress"
                    else event_type
                )
                emit(
                    normalized_type,
                    {
                        "name": name or kwargs.get("model") or "子 Agent",
                        "preview": preview or "",
                        "args": args,
                        **kwargs,
                    },
                )
                return
            emit(
                "tool.progress",
                {
                    "name": name or "工具调用",
                    "preview": preview or "",
                    "args": args,
                    "event": event_type,
                },
            )

        def status_update(kind: Any, text: Any = None) -> None:
            event = _profile_status_event(kind, text)
            if event is not None:
                emit(event["type"], event["payload"])

        session_db = SessionDB()
        resolved_session_id = ""
        conversation_history: list[dict[str, Any]] = []
        if requested_session_id:
            resolved_session_id = str(
                session_db.resolve_resume_session_id(requested_session_id) or ""
            ).strip()
            if resolved_session_id and session_db.get_session(resolved_session_id):
                conversation_history = [
                    message
                    for message in session_db.get_messages_as_conversation(
                        resolved_session_id
                    )
                    if message.get("role") != "session_meta"
                ]
                session_db._conn.execute(
                    "UPDATE sessions SET ended_at = NULL, end_reason = NULL WHERE id = ?",
                    (resolved_session_id,),
                )
                session_db._conn.commit()
            else:
                resolved_session_id = ""
        agent = AIAgent(
            api_key=runtime.get("api_key"),
            base_url=runtime.get("base_url"),
            provider=runtime.get("provider"),
            api_mode=runtime.get("api_mode"),
            model=model,
            max_iterations=45,
            enabled_toolsets=enabled_toolsets,
            quiet_mode=True,
            platform="cli",
            session_db=session_db,
            session_id=resolved_session_id or None,
            credential_pool=runtime.get("credential_pool"),
            fallback_model=fallback or None,
            stream_delta_callback=lambda text: (
                emit("message.delta", {"text": text}) if text is not None else None
            ),
            reasoning_callback=lambda text: emit("reasoning.delta", {"text": text}),
            tool_start_callback=tool_start,
            tool_complete_callback=tool_complete,
            tool_progress_callback=tool_progress,
            tool_gen_callback=lambda name: emit(
                "tool.generating", {"name": str(name or "工具调用")}
            ),
            status_callback=status_update,
            event_callback=lambda event_type, payload: emit(
                str(event_type or ""),
                dict(payload) if isinstance(payload, dict) else {},
            ),
        )
        agent_ref[0] = agent
        # The hosted child owns the model retry loop. Keeping this inside the
        # child preserves one session and prevents the outer workflow from
        # replaying a prompt or repeating a tool side effect.
        try:
            agent._api_max_retries = max(
                1,
                min(
                    _HOSTED_CHAT_API_ATTEMPTS,
                    int(
                        os.environ.get(
                            "HERMES_API_MAX_RETRIES",
                            str(_HOSTED_CHAT_API_ATTEMPTS),
                        )
                    ),
                ),
            )
        except (TypeError, ValueError):
            agent._api_max_retries = _HOSTED_CHAT_API_ATTEMPTS
        agent._api_retry_delay_seconds = _HOSTED_CHAT_API_RETRY_DELAY_SECONDS
        agent._api_retry_client_errors = True
        agent._api_retry_status_live = True
        if resolved_session_id:
            agent._session_db_created = True
        agent.suppress_status_output = True
        emit(
            "session.info",
            {
                "session_id": str(getattr(agent, "session_id", "") or ""),
                "model": str(getattr(agent, "model", model) or model),
                "provider": str(
                    getattr(agent, "provider", runtime.get("provider"))
                    or runtime.get("provider")
                    or ""
                ),
                "mcp_availability": mcp_availability,
            },
        )
        emit(
            "request.accepted",
            {
                "session_id": str(getattr(agent, "session_id", "") or ""),
                "model": str(getattr(agent, "model", model) or model),
                "provider": str(
                    getattr(agent, "provider", runtime.get("provider"))
                    or runtime.get("provider")
                    or ""
                ),
            },
        )
        if runner_action == "compress":
            if not resolved_session_id:
                raise ValueError("session was not found")
            if len(conversation_history) < 4:
                raise ValueError("not enough conversation to compress")
            if not bool(getattr(agent, "compression_enabled", False)):
                raise ValueError("compression is disabled for this profile")
            from agent.model_metadata import estimate_request_tokens_rough

            approx_tokens = estimate_request_tokens_rough(
                conversation_history,
                system_prompt=getattr(agent, "_cached_system_prompt", "") or "",
                tools=getattr(agent, "tools", None) or None,
            )
            with open(os.devnull, "w", encoding="utf-8") as devnull:
                with redirect_stdout(devnull), redirect_stderr(devnull):
                    compressed, _ = agent._compress_context(
                        conversation_history,
                        None,
                        approx_tokens=approx_tokens,
                        focus_topic=focus_topic or None,
                        force=True,
                    )
                    if (
                        getattr(agent, "session_id", None)
                        and agent.session_id != resolved_session_id
                    ):
                        agent._flush_messages_to_session_db(compressed, None)
            new_session_id = str(getattr(agent, "session_id", "") or "").strip()
            if not new_session_id or new_session_id == resolved_session_id:
                raise RuntimeError("compression did not create a continuation session")
            emit(
                "message.complete",
                {
                    "text": "Context compression completed",
                    "status": "completed",
                    "session_id": new_session_id,
                    "previous_session_id": resolved_session_id,
                    "message_count": len(compressed),
                    "previous_message_count": len(conversation_history),
                },
            )
            return 0
        with open(os.devnull, "w", encoding="utf-8") as devnull:
            with redirect_stdout(devnull), redirect_stderr(devnull):
                result = agent.run_conversation(
                    prompt,
                    conversation_history=conversation_history,
                )
        final_response = _structured_text(result.get("final_response"))
        status = "error" if result.get("failed") else "completed"
        emit(
            "message.complete",
            {
                "text": final_response,
                "status": status,
                "session_id": _structured_text(result.get("session_id")),
            },
        )
        return 0 if final_response and status == "completed" else 1
    except BaseException as exc:
        emit(
            "error",
            {
                "message": sanitize_runtime_error(exc),
                "transient": _is_transient_runtime_error(exc),
            },
        )
        return 1


_FILE_LIBRARY: CloudFileLibrary | None = None
_ARTIFACT_INTENT_RECOVERY_RUNNING = False


def _artifact_intent_has_active_claim(
    hosted: dict[str, Any],
    remote: Any,
    intent: dict[str, Any],
    *,
    now: int,
) -> bool:
    if not isinstance(remote, dict):
        return False
    claim_token = str(remote.get("claim_token") or "")
    expected_digest = str(intent.get("claim_sha256") or "")
    connector_id = str(
        intent.get("connector_id") or remote.get("lease_owner") or ""
    )
    if not claim_token or not expected_digest or not connector_id:
        return False
    actual_digest = hashlib.sha256(claim_token.encode("utf-8")).hexdigest()
    if not hmac.compare_digest(actual_digest, expected_digest):
        return False
    try:
        _require_active_remote_artifact_claim(
            hosted,
            remote,
            connector_id=connector_id,
            claim_token=claim_token,
            now=now,
        )
    except HTTPException:
        return False
    return True


def _recover_connector_artifact_upload_intents(
    library: CloudFileLibrary,
) -> None:
    """Finish or roll back connector artifact publication after a crash."""

    global _ARTIFACT_INTENT_RECOVERY_RUNNING
    if _ARTIFACT_INTENT_RECOVERY_RUNNING:
        return
    _ARTIFACT_INTENT_RECOVERY_RUNNING = True
    changed_conversations: set[str] = set()
    try:
        with _STATE_LOCK:
            state = load_single_state()
            now = int(time.time() * 1000)
            changed = False
            for conversation in state.get("conversations") or []:
                if not isinstance(conversation, dict):
                    continue
                owner_id = str(conversation.get("owner_id") or LOCAL_OWNER_ID)
                for hosted in (conversation.get("hosted_turns") or {}).values():
                    if not isinstance(hosted, dict):
                        continue
                    intents = hosted.get("artifact_upload_intents")
                    if not isinstance(intents, dict) or not intents:
                        continue
                    for intent_id, intent in list(intents.items()):
                        if not isinstance(intent, dict):
                            intents.pop(intent_id, None)
                            changed = True
                            continue
                        account_generation = str(
                            intent.get("account_generation")
                            or hosted.get("account_generation")
                            or conversation.get("account_generation")
                            or ""
                        ).strip()
                        if not account_generation:
                            intents.pop(intent_id, None)
                            changed = True
                            continue
                        origin_key = str(intent.get("origin_key") or "")
                        record = (
                            library.get_file_by_origin(
                                owner_id,
                                origin_key,
                                account_generation=account_generation,
                            )
                            if origin_key
                            else None
                        )
                        file_id = str((record or {}).get("id") or intent.get("file_id") or "")
                        remote_id = str(intent.get("remote_run_id") or "")
                        role_key = str(intent.get("role_key") or "")
                        remote = (
                            (hosted.get("remote_runs") or {}).get(role_key)
                            if role_key
                            else None
                        )
                        if not isinstance(remote, dict) or str(remote.get("id") or "") != remote_id:
                            remote = next(
                                (
                                    item
                                    for item in (hosted.get("remote_runs") or {}).values()
                                    if isinstance(item, dict)
                                    and str(item.get("id") or "") == remote_id
                                ),
                                None,
                            )
                        boundary_matches = all(
                            not candidate or candidate == account_generation
                            for candidate in (
                                str(conversation.get("account_generation") or "").strip(),
                                str(hosted.get("account_generation") or "").strip(),
                                (
                                    str(remote.get("account_generation") or "").strip()
                                    if isinstance(remote, dict)
                                    else ""
                                ),
                            )
                        )
                        artifact_linked = bool(
                            record
                            and isinstance(remote, dict)
                            and any(
                                isinstance(item, dict)
                                and str(item.get("id") or "") == file_id
                                for item in remote.get("artifacts") or []
                            )
                        )
                        message_linked = any(
                            isinstance(message, dict)
                            and isinstance(message.get("meta"), dict)
                            and str(message["meta"].get("message_key") or "")
                            == f"{remote_id}:artifact:{file_id}"
                            for message in conversation.get("messages") or []
                        )
                        claim_active = boundary_matches and _artifact_intent_has_active_claim(
                            hosted,
                            remote,
                            intent,
                            now=now,
                        )
                        publication_finished = bool(
                            record is not None
                            and str(record.get("status") or "") == "available"
                            and isinstance(remote, dict)
                            and (artifact_linked or message_linked)
                            and boundary_matches
                        )
                        if record is not None and (
                            publication_finished
                            or (claim_active and (artifact_linked or message_linked))
                        ):
                            published = library.publish_file(
                                owner_id,
                                file_id,
                                account_generation=account_generation,
                            )
                            attachment = _library_attachment(published)
                            if isinstance(remote, dict) and not artifact_linked:
                                remote.setdefault("artifacts", []).append(attachment)
                            if not message_linked:
                                _append_message(
                                    conversation,
                                    role="assistant",
                                    name=str(intent.get("profile") or "worker"),
                                    content=f"已收到交付文件：{intent.get('filename') or published.get('name')}",
                                    status="completed",
                                    kind="message",
                                    meta={
                                        "role_stage": f"{intent.get('role_stage') or 'worker'}.artifact",
                                        "phase": "milestone",
                                        "message_key": f"{remote_id}:artifact:{file_id}",
                                        "runtime_turn_id": str(hosted.get("turn_id") or ""),
                                        "profile": str(intent.get("profile") or "worker"),
                                        "attachments": [attachment],
                                        "collapse_activities": True,
                                        "final_report": False,
                                    },
                                )
                        else:
                            if (
                                isinstance(remote, dict)
                                and file_id
                                and _coerce_flag(intent.get("artifact_link_added"))
                            ):
                                remote["artifacts"] = [
                                    item
                                    for item in remote.get("artifacts") or []
                                    if not (
                                        isinstance(item, dict)
                                        and str(item.get("id") or "") == file_id
                                    )
                                ]
                            if file_id and _coerce_flag(intent.get("message_added")):
                                message_key = f"{remote_id}:artifact:{file_id}"
                                _rewrite_conversation_history_messages(
                                    str(conversation.get("id") or ""),
                                    lambda history_messages, key=message_key: [
                                        message
                                        for message in history_messages
                                        if not (
                                            isinstance(message.get("meta"), dict)
                                            and str(message["meta"].get("message_key") or "") == key
                                        )
                                    ],
                                )
                                conversation["messages"] = [
                                    message
                                    for message in conversation.get("messages") or []
                                    if not (
                                        isinstance(message, dict)
                                        and isinstance(message.get("meta"), dict)
                                        and str(message["meta"].get("message_key") or "")
                                        == message_key
                                    )
                                ]
                            elif file_id and isinstance(intent.get("previous_message"), dict):
                                message_key = f"{remote_id}:artifact:{file_id}"
                                messages = conversation.get("messages") or []
                                previous_message = deepcopy(intent["previous_message"])
                                restore_index = int(
                                    intent.get("previous_message_index") or -1
                                )

                                def restore_history_message(
                                    history_messages: list[dict[str, Any]],
                                    key: str = message_key,
                                    replacement: dict[str, Any] = previous_message,
                                    index: int = restore_index,
                                ) -> list[dict[str, Any]]:
                                    current_index = next(
                                        (
                                            candidate_index
                                            for candidate_index, candidate in enumerate(history_messages)
                                            if isinstance(candidate.get("meta"), dict)
                                            and str(candidate["meta"].get("message_key") or "") == key
                                        ),
                                        -1,
                                    )
                                    if current_index >= 0:
                                        history_messages[current_index] = deepcopy(replacement)
                                    else:
                                        history_messages.insert(
                                            max(0, min(index, len(history_messages))),
                                            deepcopy(replacement),
                                        )
                                    return history_messages

                                _rewrite_conversation_history_messages(
                                    str(conversation.get("id") or ""),
                                    restore_history_message,
                                )
                                current_index = next(
                                    (
                                        index
                                        for index, message in enumerate(messages)
                                        if isinstance(message, dict)
                                        and isinstance(message.get("meta"), dict)
                                        and str(message["meta"].get("message_key") or "")
                                        == message_key
                                    ),
                                    -1,
                                )
                                if current_index >= 0:
                                    messages[current_index] = previous_message
                                else:
                                    messages.insert(
                                        max(0, min(restore_index, len(messages))),
                                        previous_message,
                                    )
                            previous_file_record = intent.get("previous_file_record")
                            if isinstance(previous_file_record, dict):
                                library.restore_file_record(previous_file_record)
                            elif record is not None:
                                library.delete_file(
                                    owner_id,
                                    file_id,
                                    account_generation=account_generation,
                                )
                        intents.pop(intent_id, None)
                        changed = True
                        changed_conversations.add(str(conversation.get("id") or ""))
                    if not intents:
                        hosted.pop("artifact_upload_intents", None)
            if changed:
                save_single_state(state)
    finally:
        _ARTIFACT_INTENT_RECOVERY_RUNNING = False
    for conversation_id in changed_conversations:
        _notify_hosted_update(conversation_id)


def _file_library() -> CloudFileLibrary:
    global _FILE_LIBRARY
    expected_root = (
        Path(get_hermes_home())
        / "collaboration"
        / "account-files"
    )
    if _FILE_LIBRARY is None or _FILE_LIBRARY.root != expected_root:
        _FILE_LIBRARY = CloudFileLibrary(expected_root)
    _recover_connector_artifact_upload_intents(_FILE_LIBRARY)
    return _FILE_LIBRARY


def _owned_conversation(
    request: Request,
    conversation_id: str,
) -> tuple[str, dict[str, Any]]:
    """Bind legacy conversations on first file access and enforce ownership."""

    owner_id = owner_id_from_request(request)
    _account_generation_for_request(request, owner_id)
    with _STATE_LOCK:
        state = load_single_state()
        conversation, claimed = _owned_conversation_in_state(
            state,
            conversation_id,
            owner_id,
        )
        if claimed:
            save_single_state(state)
    return owner_id, conversation


def _sync_conversation_files(
    owner_id: str,
    conversation: dict[str, Any],
    uploads_dir: Path | None = None,
    outputs_dir: Path | None = None,
    *,
    account_generation: str = "",
    strict: bool = False,
) -> None:
    conversation_id = str(conversation.get("id") or "").strip()
    if not conversation_id:
        return
    profile = str(conversation.get("profile") or "").strip()
    generation = str(
        account_generation
        or conversation.get("account_generation")
        or ""
    ).strip()
    if not generation:
        raise ValueError("conversation account_generation is required")
    uploads = uploads_dir or _conversation_file_dir(conversation_id, "uploads")
    outputs = outputs_dir or _conversation_file_dir(conversation_id, "outputs")
    library = _file_library()
    sync_options = {"strict": True} if strict else {}
    library.sync_directory(
        owner_id,
        uploads,
        account_generation=generation,
        source="user_upload",
        conversation_id=conversation_id,
        profile=profile,
        origin_prefix=f"conversation:{conversation_id}:uploads",
        **sync_options,
    )
    library.sync_directory(
        owner_id,
        outputs,
        account_generation=generation,
        source="model_output",
        conversation_id=conversation_id,
        profile=profile,
        origin_prefix=f"conversation:{conversation_id}:outputs",
        **sync_options,
    )


def _sync_account_conversations(
    owner_id: str,
    account_generation: str = "",
    *,
    strict: bool = False,
) -> None:
    """Migrate explicitly bound legacy conversations and discover outputs."""

    generation = str(
        account_generation or _account_generation_for_owner(owner_id)
    ).strip()
    with _STATE_LOCK:
        state = load_single_state()
        conversations: list[dict[str, Any]] = []
        changed = False
        for conversation in state.get("conversations") or []:
            existing_owner = str(conversation.get("owner_id") or "").strip()
            if conversation.get("delete_requested"):
                continue
            if existing_owner != owner_id and not _legacy_owner_claim_allowed(
                existing_owner,
                owner_id,
            ):
                continue
            if existing_owner != owner_id:
                conversation["owner_id"] = owner_id
                changed = True
            stored_generation = str(
                conversation.get("account_generation") or ""
            ).strip()
            if stored_generation and stored_generation != generation:
                continue
            if not stored_generation:
                conversation["account_generation"] = generation
                changed = True
            conversations.append(conversation)
        if changed:
            save_single_state(state)
    for conversation in conversations:
        _sync_conversation_files(
            owner_id,
            conversation,
            account_generation=generation,
            strict=strict,
        )


def _account_file_migration_marker(
    owner_id: str,
    account_generation: str = "",
) -> Path:
    generation = str(
        account_generation or _account_generation_for_owner(owner_id)
    ).strip()
    owner_hash = hashlib.sha256(
        f"{owner_id}\x00{generation}".encode("utf-8")
    ).hexdigest()[:32]
    return (
        _file_library().root
        / "migrations"
        / f"{_ACCOUNT_FILE_MIGRATION_VERSION}-{owner_hash}.done"
    )


def _migrate_account_conversation_files_once(
    owner_id: str,
    account_generation: str = "",
) -> None:
    """Index pre-library conversation files once for the account that claims them."""

    generation = str(
        account_generation or _account_generation_for_owner(owner_id)
    ).strip()
    marker = _account_file_migration_marker(owner_id, generation)
    if marker.is_file():
        return
    with _ACCOUNT_FILE_MIGRATION_LOCK:
        if marker.is_file():
            return
        _sync_account_conversations(owner_id, generation, strict=True)
        marker.parent.mkdir(parents=True, exist_ok=True)
        temporary = marker.with_name(f".{marker.name}.{uuid.uuid4().hex}.tmp")
        try:
            with temporary.open("x", encoding="utf-8", newline="\n") as handle:
                os.chmod(temporary, 0o600)
                handle.write(f"{int(time.time() * 1000)}\n")
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, marker)
        finally:
            temporary.unlink(missing_ok=True)


def _library_attachment(record: dict[str, Any]) -> dict[str, Any]:
    file_id = str(record.get("id") or "")
    source = str(record.get("source") or "")
    return {
        key: record.get(key)
        for key in (
            "id",
            "name",
            "sha256",
            "mime_type",
            "extension",
            "file_type",
            "size",
            "source",
            "status",
            "conversation_id",
            "message_id",
            "turn_id",
            "profile",
            "error",
            "created_at",
            "updated_at",
            "available_at",
        )
    } | {
        "bucket": "outputs" if source == "model_output" else "uploads",
        "download_url": f"/api/plugins/collaboration/files/{quote(file_id, safe='')}/download",
    }


def _conversation_library_attachments(
    owner_id: str,
    conversation_id: str,
    *,
    account_generation: str,
) -> list[dict[str, Any]]:
    library = _file_library()
    records: list[dict[str, Any]] = []
    offset = 0
    while True:
        page, total = library.list_files(
            owner_id,
            account_generation=account_generation,
            conversation_id=conversation_id,
            limit=200,
            offset=offset,
        )
        records.extend(page)
        offset += len(page)
        if not page or offset >= total:
            break
    return [_library_attachment(record) for record in records]


def _attachment_file_ids(meta: Any) -> list[str]:
    if not isinstance(meta, dict):
        return []
    attachments = meta.get("attachments")
    if not isinstance(attachments, list):
        return []
    return [
        str(attachment.get("id") or "").strip()
        for attachment in attachments
        if isinstance(attachment, dict)
        and str(attachment.get("id") or "").startswith("file_")
    ]


class RegisterArtifactBody(BaseModel):
    relative_path: str = ""
    name: str = ""
    artifact_id: str = ""
    status: str = "available"
    mime_type: str = ""
    message_id: str = ""
    turn_id: str = ""
    profile: str = ""
    error: str = ""


class MobileManagedInstallationBody(BaseModel):
    kind: str
    identifier: str
    profile: str = "default"
    request_id: str = ""
    scope: str = "auto"
    locality: str = "portable"
    targets: list[str] = []
    project_name: str = ""
    source_ref: str = ""


class MobileManagedInstallationRollbackBody(BaseModel):
    request_id: str = ""


@router.post("/single/conversations/{conversation_id}/artifacts")
def register_conversation_artifact(
    conversation_id: str,
    payload: RegisterArtifactBody,
    request: Request,
):
    """Reserve, publish, or fail a model-created file in ``outputs``."""

    owner_id, conversation = _owned_conversation(request, conversation_id)
    account_generation = _account_generation_for_request(request, owner_id)
    output_root = _conversation_file_dir(conversation_id, "outputs").resolve()
    relative_path = payload.relative_path.strip().replace("\\", "/")
    target = (output_root / relative_path).resolve() if relative_path else None
    if target is not None and not target.is_relative_to(output_root):
        raise HTTPException(status_code=403, detail="Artifact path escapes outputs")
    name = payload.name.strip() or (target.name if target is not None else "")
    profile = payload.profile.strip() or str(conversation.get("profile") or "")
    origin_key = (
        f"conversation:{conversation_id}:outputs:{relative_path}"
        if relative_path
        else ""
    )
    artifact_status = payload.status.strip().lower()
    if artifact_status not in {"uploading", "available", "failed"}:
        raise HTTPException(
            status_code=422,
            detail="Artifact status must be uploading, available, or failed",
        )
    library = _file_library()
    try:
        if artifact_status == "available":
            if target is None or not target.is_file():
                raise HTTPException(status_code=404, detail="Artifact file not found")
            record = library.ingest_file(
                owner_id,
                target,
                account_generation=account_generation,
                name=name,
                source="model_output",
                conversation_id=conversation_id,
                message_id=payload.message_id,
                turn_id=payload.turn_id,
                profile=profile,
                origin_key=origin_key,
                mime_type=payload.mime_type,
                file_id=payload.artifact_id,
                allowed_roots=[output_root],
            )
        else:
            if payload.artifact_id:
                record = library.get_file(
                    owner_id,
                    payload.artifact_id,
                    account_generation=account_generation,
                )
                if record is None:
                    raise KeyError(payload.artifact_id)
            else:
                record = library.reserve_file(
                    owner_id,
                    account_generation=account_generation,
                    name=name,
                    source="model_output",
                    conversation_id=conversation_id,
                    message_id=payload.message_id,
                    turn_id=payload.turn_id,
                    profile=profile,
                    origin_key=origin_key,
                    mime_type=payload.mime_type,
                )
            record = library.set_status(
                owner_id,
                str(record["id"]),
                artifact_status,
                account_generation=account_generation,
                error=payload.error,
            )
    except KeyError as exc:
        raise HTTPException(status_code=404, detail="Artifact not found") from exc
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return {"file": _library_attachment(record)}


@router.post("/files")
async def upload_account_file(request: Request):
    """Upload a durable user-owned file without requiring a chat first."""

    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    try:
        filename = safe_attachment_name(
            unquote(request.headers.get("x-filename", ""))
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    upload_id = str(request.headers.get("x-upload-id") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9._:-]{8,256}", upload_id):
        raise HTTPException(status_code=422, detail="Invalid X-Upload-ID")
    expected_bytes, expected_sha = _attachment_upload_contract(request)
    incoming = _file_library().root / "incoming"
    incoming.mkdir(parents=True, exist_ok=True)
    temp = incoming / f".{uuid.uuid4().hex}.upload"
    total = 0
    try:
        with temp.open("wb") as handle:
            async for chunk in request.stream():
                if not chunk:
                    continue
                total += len(chunk)
                if total > _MAX_ATTACHMENT_BYTES:
                    raise HTTPException(status_code=413, detail="文件不能超过 64 MB")
                handle.write(chunk)
        if expected_bytes is not None and total != expected_bytes:
            raise HTTPException(status_code=400, detail="Content-Length does not match request body")
        actual_sha = _sha256_path(temp)
        if expected_sha and actual_sha != expected_sha:
            raise HTTPException(status_code=422, detail="X-Content-SHA256 does not match request body")
        origin_key = f"account-upload:{upload_id}"
        existing = _file_library().get_file_by_origin(
            owner_id,
            origin_key,
            account_generation=account_generation,
        )
        if (
            existing is not None
            and existing.get("status") == "available"
            and str(existing.get("sha256") or "") != actual_sha
        ):
            raise HTTPException(
                status_code=409,
                detail="X-Upload-ID was already used with different content",
            )
        record = _file_library().ingest_file(
            owner_id,
            temp,
            account_generation=account_generation,
            name=filename,
            source="user_upload",
            origin_key=origin_key,
            mime_type=request.headers.get("content-type", ""),
            allowed_roots=[incoming],
        )
    except (FileExistsError, BlockingIOError) as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except PermissionError as exc:
        raise HTTPException(status_code=410, detail="Account was deleted") from exc
    finally:
        temp.unlink(missing_ok=True)
    if record is None:
        raise HTTPException(status_code=500, detail="File upload was not persisted")
    return {"file": _library_attachment(record)}


@router.get("/files")
def list_account_files(
    request: Request,
    q: str = "",
    date_from: str = "",
    date_to: str = "",
    source: str = "",
    file_type: str = "",
    status: str = "",
    filter_contract: str = "",
    limit: int = 100,
    offset: int = 0,
):
    if filter_contract and filter_contract != _TOOL_OUTPUT_FILTER_CONTRACT:
        raise HTTPException(status_code=422, detail="unsupported account-files filter contract")
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    try:
        start_ms = parse_date_filter(date_from)
        end_ms = parse_date_filter(date_to, end_of_day=True)
        requested_type = file_type or request.query_params.get("type", "")
        records, total = _file_library().list_files(
            owner_id,
            account_generation=account_generation,
            keyword=q,
            date_from=start_ms,
            date_to=end_ms,
            source=source,
            file_type=requested_type,
            status=status,
            account_files_contract=filter_contract == _TOOL_OUTPUT_FILTER_CONTRACT,
            limit=limit,
            offset=offset,
        )
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    response = {
        "files": [_library_attachment(record) for record in records],
        "total": total,
        "limit": max(1, min(limit, 200)),
        "offset": max(0, offset),
    }
    if filter_contract:
        response["filter_contract"] = _TOOL_OUTPUT_FILTER_CONTRACT
    return response


_TOOL_OUTPUT_FILTER_CONTRACT = "account-files-v1"


@router.get("/tool-output-artifacts")
def list_tool_output_artifacts(
    request: Request,
    q: str = "",
    date_from: str = "",
    date_to: str = "",
    filter_contract: str = "",
    limit: int = 100,
    offset: int = 0,
):
    if limit < 1 or limit > 1000:
        raise HTTPException(status_code=422, detail="limit must be between 1 and 1000")
    if offset < 0:
        raise HTTPException(status_code=422, detail="offset must be non-negative")
    if filter_contract and filter_contract != _TOOL_OUTPUT_FILTER_CONTRACT:
        raise HTTPException(status_code=422, detail="unsupported tool-output filter contract")
    store = EncryptedToolArtifactStore(Path(get_hermes_home()))
    owner_id = owner_id_from_request(request)
    account_generation = _account_generation_for_request(request, owner_id)
    try:
        start_ms = parse_date_filter(date_from)
        end_ms = parse_date_filter(date_to, end_of_day=True)
        artifacts = store.list_owner(
            owner_id,
            account_generation=account_generation,
            q=q,
            date_from=start_ms,
            date_to=end_ms,
            limit=limit,
            offset=offset,
        )
        total = store.count_owner(
            owner_id,
            account_generation=account_generation,
            q=q,
            date_from=start_ms,
            date_to=end_ms,
        )
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    return {
        "artifacts": artifacts,
        "total": total,
        "limit": limit,
        "offset": offset,
        "filter_contract": _TOOL_OUTPUT_FILTER_CONTRACT,
    }


